WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[11922] = { title = "Torch Tossing", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nTake these torches and run near the bonfire.  You'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers before the time limit, then come back here... for your next lesson.", objectives = "Win the torch tossing game, then speak with the Master Flame Eater.", progress = "Quick!  There's no time to waste!", completion = "Well done!  You'll be a fire juggler faster than the fuse on a ground flower!  Now gird yourself!  The next test is when things really heat up..." }
WordHunterWoW_QuestEN[11923] = { title = "Torch Catching", description = "Now that you can throw a torch, let's see if you can catch one!\n\nTake this stack of unlit torches.  Go to the bonfire and throw a torch high into the air.  Catch it before it hits the ground... then throw it back up!  Catch four then come back to me.\n\nCareful! They're dangerous if they hit the ground! Good luck!", objectives = "Catch 4 torches in a row, then speak with the Master Flame Eater.", progress = "Torch catching is a lot of fun, don't you think?  But have care!  You don't want to get singed!", completion = "Did you get burned?  If you did, then maybe you'll think twice before playing with fire...\n\nJust kidding!  Well done!  It's official.  You're a bona fide fire juggler.  Now get out there and have some fun!" }
WordHunterWoW_QuestEN[11924] = { title = "More Torch Catching", description = "Torch catching sure keeps you on your toes.  Think you can keep it up for a long time?\n\nLet's see...", objectives = "Catch 10 torches then speak with the Master Fire Eater.", progress = "Torch catching is a lot of fun, don't you think?  But have care!  You don't want to get singed!", completion = "How's that arm doing, <name>?  You looked great out there.  A real juggling master!" }
WordHunterWoW_QuestEN[11925] = { title = "More Torch Catching", description = "Torch catching sure keeps you on your toes.  Think you can keep it up for a long time?\n\nLet's see...", objectives = "Catch 10 torches then speak with the Master Flame Eater.", progress = "Torch catching is a lot of fun, don't you think?  But have care!  You don't want to get singed!", completion = "How's that arm doing, <name>?  You looked great out there.  A real juggling master!" }
WordHunterWoW_QuestEN[11926] = { title = "More Torch Tossing", description = "Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...\n\nYou know the rules: toss torches at the marked braziers.  This time, however, you have a little more time and a LOT more braziers to hit.\n\nReady?", objectives = "Win the torch tossing game, then speak with the Master Flame Eater.", completion = "Wow, you did it!  You are great!  Maybe next year you can apply for a job at the festival!" }
WordHunterWoW_QuestEN[11927] = { title = "Word on the Street", description = "Hey, {name}.  There's a girl in the inn that's asking about you.  Her name's Leryssa.\n\nI don't think she knows you, but she said she needed your help.  She sounded really desperate.", objectives = "Find Leryssa at the inn in Valiance Keep.", completion = "Thank you for coming to see me.  I didn't know who else to contact." }
WordHunterWoW_QuestEN[11928] = { title = "Farshire", description = "My lads should be able to take it from here, {name}.  Valiance Keep is built to take a beating far worse than this.  I worry about our farmlands and mine in Farshire, however.\n\nWe sent a full detachment to protect our mining operations right before the invasion - they should be able to defend the civilians.\n\nGerald Green's in charge of the villagers there. There's a passage out of the northern wall out of Valiance Keep; it'll take you straight to him.  See what you can do to help them.", objectives = "Travel to Farshire in Borean Tundra and speak to Gerald Green.", completion = "You're here to help?  You're just in time then!" }
WordHunterWoW_QuestEN[11929] = { title = "The Fall of Taunka'le Village", description = "We are lost, {name}. This place has been our home for many generations, but it is no longer safe. There remains only death... Death and a memory of what used to be.\n\nI have called for the evacuation of Taunka'le. All remaining taunka must leave at once and make their way to our capital city, Icemist, located in the Dragonblight.\n\n<Wintergale points east.>\n\nYou must help get my people to safety, {name}. Mother Tauranook awaits you at the village gates. Hurry! The Scourge closes in from all sides!", objectives = "Speak to Mother Tauranook outside the gates of Taunka'le Village.", completion = "<Mother Tauranook wipes her tears away.>\n\nThere was once a time when I could walk across this tundra and the snow would fill my view for as far as I could see.\n\nBut the snow has left us - signaling that our time here has come to an end. We leave behind Taunka'le Village and the Borean Tundra with many happy memories...\n\n<Mother Tauranook whimpers.>\n\nPerhaps the future will welcome our return - along with the snow." }
WordHunterWoW_QuestEN[11930] = { title = "Across Transborea", description = "The path across Transborea, to the east, is the only way to reach the Dragonblight. Many perils await you as you make your journey across the tundra. Beware the Scourge and its influence upon the beasts of the land. Rumors have started to spread about our very own taunka brothers and sisters rising from the dead and attacking caravans on their way to the Dragonblight! Defend your caravan and get the evacuees to safety!\n\nWartook Iceborn waits for you across the bridge leading into the Dragonblight.", objectives = "Escort the Taunka'le Evacuees across Transborea to Wartook Iceborn on the border of the Dragonblight.", progress = "It's gone. It's all gone.", completion = "<Wartook looks upon you grimly.>\n\nIcemist is no more..." }
WordHunterWoW_QuestEN[11931] = { title = "Cracking the Code", description = "I sense a distinct peculiarity in the drakes here but the meaning of the runes that cover their bodies still eludes me.\n\nWithout a codex, it will take more time than we can afford for me to interpret them.\n\nNot far from here is a Kirin Tor traitor, Caleras, who is likely to have a copy of the tome I require. His underlings hold the runes I will need for my translation.\n\nHurry, mortal. Malygos gains strength with every passing moment.", objectives = "Raelorasz at the Transitus Shield wants you to get the Azure Codex from Inquisitor Caleras and collect 3 Shimmering Runes from his Coldarra Spellbinders.", progress = "Hurry, mortal.\n\nMalygos gains strength with every passing moment.", completion = "You have done well, <race>.\n\nLet us hope for a clue that we can use against Malygos." }
WordHunterWoW_QuestEN[11932] = { title = "Cowards and Fools", description = "Listen, {name}.  No offense, but the operation they put Thassarian in charge of was pure suicide.\n\nA handful of our men were to launch an attack on the biggest Scourge presence in the area.  Call me crazy, but storming a Scourge ziggurat outside a plagued Nerubian city with a dozen men ain't my idea of fun.\n\nIf you're still interested in finding Thassarian, we were supposed to arrange for passage east with a tuskarr by the name of Ataika in Kaskala to the northeast.  Good luck with your fool's errand.", objectives = "Speak to Ataika in Kaskala, northeast of Valiance Keep.", completion = "I remember the man you speak of.  He bore the marks of Karkut.\n\nMay Karkut protect our fallen." }
WordHunterWoW_QuestEN[11933] = { title = "Stealing the Exodar's Flame", description = "This flame, stolen from the heart of the Exodar itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", objectives = "Return the Flame of the Exodar to the Festival Talespinner.", progress = "You're practically glowing, <race>. What do you have there?", completion = "This fire seems new... Yet, you say it came from the Exodar? Fascinating! To make your way into that ship...  Of course, I'll pay you for this. If you find anything else like this, be sure to speak with me again." }
WordHunterWoW_QuestEN[11934] = { title = "Unlocking Your Potential [PH]", description = "Today you unlock a page in your spellbook, one you may not have realized it was there.  Bring me something, and I'll open it up for you.You will receive:", objectives = "Bring this dude some stuff." }
WordHunterWoW_QuestEN[11935] = { title = "Stealing Silvermoon's Flame", description = "This flame, stolen from Silvermoon, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", objectives = "Return the Flame of Silvermoon to the Festival Loremaster.", progress = "You're practically glowing, <race>. What do you have there?", completion = "What a glorious fire! You received this from Silvermoon, you say? Unbelievable! With the flames of all four cities, who knows what we could accomplish?" }
WordHunterWoW_QuestEN[11936] = { title = "Hatching a Plan", description = "Our goals here are simple. We are to remain hidden from Malygos, observe his brood, and thwart his efforts wherever possible. To that end, I have a task for you.\n\nThe blues are laying their eggs at the base of the Nexus. Exposure to so much arcane energy will surely make them hatch sooner, and there's no telling what effect it will have on their spawn.\n\nI don't intend to find out. Slay the local wyrmkin and use their frozen axes to break the eggs.", objectives = "Raelorasz at the Transitus Shield wants you to kill Coldarra Wyrmkin and use their frozen axes to break 5 blue dragon eggs.", progress = "Have you destroyed the blues' eggs, <class>?", completion = "It pains me to order the destruction of dragon eggs, enemy or no.\n\nMay the ends of this war justify the means...." }
WordHunterWoW_QuestEN[11937] = { title = "FLAG - all torch return quests are complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[11938] = { title = "Buying Some Time", description = "Now that we have this phylactery, I shouldn't have any problems getting the information I need.  It won't take long for the Scourge in the Temple City to notice something's up, however.\n\nI won't be able to fend off a full scale attack here.  Or maybe I would... but I'd rather not find out.\n\nI want you to head down there and inflict some casualties.  Hopefully they'll be distracted long enough for these two to spill their guts... figuratively, of course.  Take Lurid with you, he might be of aid.", objectives = "Thassarian at the Wailing Ziggurat in Borean Tundra wants you to inflict 20 casualties against the Scourge inside the Temple City of En'kilah. Use Lurid's Bones if you need assistance.", progress = "Is it done?", completion = "That should buy us some time.  Isidorus has been cooperative, but I really needed that alone time with the lich." }
WordHunterWoW_QuestEN[11939] = { title = "?????", description = "[PH]Quest to close this questline - summon and kill a mature drake (Elite?) - Fight a drake in the dungeon?", objectives = "" }
WordHunterWoW_QuestEN[11940] = { title = "Drake Hunt", description = "I need more drake hatchlings to continue researching the runes covering their bodies.\n\nThey can be found around the northwest edge of the valley....\n\n<Raelorasz pokes his hand with a spear and coats the tip with his blood.>\n\nTake this and use it on one of them. Wait for it to become subdued, then bring it here to me before it expires.", objectives = "Raelorasz wants you to use the Blood-tipped Spear to subdue a Nexus Drake Hatchling and return it to him at the Transitus Shield.", completion = "The fate of these young drakes need not burden your conscience, <race>. Malygos alone is accountable for this.\n\nI am working ceaselessly to discover the secrets of these runes.\n\nRest assured, we shall take no more lives than we must." }
WordHunterWoW_QuestEN[11941] = { title = "Puzzling...", description = "Something about this scrap of metal prevents you from casting it aside.\n\nPerhaps Raelorasz might be able to shed some light on its purpose.", objectives = "Bring the Scintillating Fragment to Raelorasz at the Transitus Shield.", progress = "What have you found, <class>?", completion = "It was wise of you to bring this to me, <name>.\n\n\n\nIf you truly desire to contribute to our efforts, no matter the risk, I shall share with you its meaning." }
WordHunterWoW_QuestEN[11942] = { title = "Words of Power", description = "The lich has spoken, {name}.  The high priests of En'kilah hold the secret to entering Naxxanar.\n\nGo to the Spire of Blood, the Spire of Pain and the Spire of Decay and slay each of the priests.\n\nReturn once you've obtained the three scrolls.", objectives = "Thassarian at the Wailing Ziggurat wants you to go to the Temple City of En'kilah and retrieve High Priest Talet-Kha's Scroll from the Spire of Pain, High Priest Naferset's Scroll from the Spire of Decay and High Priest Andorath's Scroll at the Spire of Blood.", progress = "Taking your time, are you?  I don't know how much longer I can keep this lich restrained.", completion = "Excellent work, <name>.  Now for one last bit of information." }
WordHunterWoW_QuestEN[11943] = { title = "The Cell", description = "You've discovered a fragment of a special prison, {name}.\n\nMalygos' minions use similar prisons to hold their captured mages and other arcane entities, but this prison was constructed to hold something... stronger.\n\nIn hopes that the enemy of our enemy will prove to be a friend, you must search for the prison's remaining fragments.\n\nThey are likely to be in the possession of Malygos' most trusted underlings.", objectives = "Raelorasz at the Transitus Shield wants you to obtain the Prison Casing from General Cerulean and the Energy Core from Warbringer Goredrak.", progress = "Have you discovered any other pieces to the prison?", completion = "<The pieces you've collected begin to glow brightly in Raelorasz' hands.>\n\nIt is done.\n\nI sense a strong presence within this prison. Let us hope it proves to be an ally." }
WordHunterWoW_QuestEN[11944] = { title = "Surrounded!", description = "Our situation is nearly hopeless.  We were ordered to take the Wailing Ziggurat with a handful of men.\n\nWe'll be lucky if we can hold this position against the Scourge.  We're outnumbered, injured and have no escape route.\n\nIf you can take some of the pressure off of us, we might be able to solidify our position.  Kill some of the undead circling the structure - we'll hold off their advance.", objectives = "Corporal Venn at Death's Stand wants you to slay 7 Ziggurat Defenders.", completion = "That should buy us some time, <name>.  We'll hope against hope for reinforcements from Valiance Keep." }
WordHunterWoW_QuestEN[11945] = { title = "Preparing for the Worst", description = "Dark times are upon us.  Karkut's spirit walks the earth and gathers the spirits of dead tuskarr.\n\nThe sons of the mist have taken many of our brethren.  Soon dear Kaskala will be reduced to ashes.\n\nThere is hope yet.  Not for us perhaps, but we've sent our families to Unu'pe.  We fight here so there may be a future for them.\n\nThey will need supplies or they will starve.  There's not enough food in Unu'pe.  Salvage any supplies before it's too late for our families.", objectives = "Utaik wants you to gather 8 Kaskala Supplies in Kaskala.", progress = "Have you succeeded, <name>?  Our relatives in Unu'pe are depending on your efforts.", completion = "I thank you, <name>.  These supplies will feed our cousins and children.  Even if Kaskala falls, our tribes must carry on." }
WordHunterWoW_QuestEN[11946] = { title = "Keristrasza", description = "I am... free?\n\nI was destined to spend an eternity roaming an empty abyss, and now am saved? You cannot fathom my gratitude, mortal.\n\nWhen I refused to bend to his will Malygos bound me to that prison, then shattered it and scattered the pieces. Should I live one hundred of your lifetimes, I shall not forget this kindness.\n\nPerhaps, in time, I will find ways to repay you. For now, though, we must focus our attention on Malygos. I am weak, and there is much to be done.\n\nI need your help, {name}.", objectives = "Use the Augmented Arcane Prison to summon and speak to Keristrasza.\n\nProvided item:", completion = "We cannot wait for me to regain my strength.\n\nI must rely on you to make our preparations...." }
WordHunterWoW_QuestEN[11947] = { title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nThere is a camp located in the shadow of Ethel Rethor within northwestern Desolace. There, they use ice stones to communicate with the elementals, as they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", objectives = "Slay the Hailstone Lieutenant summoned from the Ice Stone located at Ethel Rethor in Desolace, then return to the Earthen Ring Elder in a capital city.", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do." }
WordHunterWoW_QuestEN[11948] = { title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nNeptulon has long had a base of operations on an island in western Stranglethorn. There, the Twilight Cult has set up ice stones to communicate with the Tidehunter's realm, much like they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", objectives = "Slay the Chillwind Lieutenant summoned from the Ice Stone located on the water elemental's island in western Stranglethorn Vale, then return to the Earthen Ring Elder in a capital city.", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do." }
WordHunterWoW_QuestEN[11949] = { title = "Not Without a Fight!", description = "Kaskala is a sacred place for us, {race}.  Our ancestors were guided here by the spirit of Tayutka herself.\n\nNow these foul creatures attack us from the mists without any provocation.\n\nWe will show them that our spears are not merely for whaling.  Fight alongside us, friend.  Perhaps my people might repay you some time in the future.", objectives = "Ataika wants you to slay 12 Kvaldir Raiders in Kaskala.", completion = "I thank you, <name>.  I will be deeply in your debt if we ever make it out of here alive." }
WordHunterWoW_QuestEN[11950] = { title = "Muahit's Wisdom", description = "Listen, {name}.  Warriors like me are replaceable.  If I fall, my brothers and cousins will pick up my spear and fight.\n\nMy people cannot survive without wise elders.  Stubborn Muahit, our most venerable shaman, refuses to leave the altar to Tayutka in the central island.  We would suffer a significant loss if he was slain by these monsters.\n\nYou are an outsider, maybe he'll listen to you.  Show him reason... ask him to flee to the safety of Unu'pe before it's too late.", objectives = "Find Elder Muahit in Kaskala.", completion = "Ataika sent you, didn't he?  I am not to be swayed.\n\nAll is not lost.  The spirits are still with us." }
WordHunterWoW_QuestEN[11951] = { title = "Bait and Switch", description = "During my captivity I was able to learn much about Malygos. Fate now allows us to use this knowledge against him.\n\nThere is a great blue dragon, Saragosa, who circles high above the Nexus. She serves both as the aspect's guardian and as his consort. If any serious threats arise, she alerts her master of the danger.\n\nI suffered greatly at the hand of Saragosa during my captivity, and now her time to die has come. First, however, we must fashion the perfect bait....", objectives = "Keristrasza has asked you to collect 10 Crystalized Mana Shards from around Coldarra.\n\nIf you lose your Augmented Arcane Prison, speak to Raelorasz at the Transitus Shield.", progress = "Have you gathered the mana shards I require?", completion = "Thank you, <name>.\n\nI am drained from the effects of my confinement and my strength is returning ever so slowly.\n\nI shall use the power from these crystals wisely. They are a byproduct of Malygos' malevolent schemes. With luck, they will play a part in his undoing." }
WordHunterWoW_QuestEN[11952] = { title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nFirewatch Ridge in Searing Gorge is an established bastion of Twilight Cult activity. Recently, they have been using ice stones in the cave to communicate with the Tidehunter's realm, much like they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", objectives = "Slay the Frigid Lieutenant summoned from the Ice Stone located in the cave underneath Firewatch Ridge in the northwest of Searing Gorge, then return to the Earthen Ring Elder in a capital city.", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do." }
WordHunterWoW_QuestEN[11953] = { title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nSilithus is the Azerothian base of the Twilight Cult. In the north, they have been using new ice stones to communicate with the Tidehunter's realm. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", objectives = "Slay the Glacial Lieutenant summoned from the Ice Stone located at Twilight's Run in northern Silithus, then return to the Earthen Ring Elder in a capital city.", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do." }
WordHunterWoW_QuestEN[11954] = { title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nIn order to ensure Ahune's success, the cult has established a base near the Dark Portal itself in Draenor. They use ice stones to coordinate the frost lord's arrival. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's templar protectors and destroy it. Perhaps this forestalling action will be enough...", objectives = "Slay the Glacial Templar summoned from the Ice Stone located near the Dark Portal in Hellfire Peninsula, then return to the Earthen Ring Elder in a capital city.", progress = "You have returned victorious?", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do." }
WordHunterWoW_QuestEN[11955] = { title = "Ahune, the Frost Lord", description = "I believe you are strong enough for the ultimate task set before us.\n\nWe cannot allow the plot between the Twilight Cult and the naga heretics of Neptulon to come to fruition. For the sake of Azeroth and all life upon it, we must act. Our path is clear. You must journey to the Slave Pens deep within Coilfang Reservoir and meet with our shaman there. Go, and quickly!", objectives = "Travel to the Slave Pens in Coilfang Reservoir within Zangarmarsh and speak with Numa Cloudsister.I believe you are strong enough for the ultimate task set before us.\n\nWe cannot allow the plot between the Twilight Cult and the naga heretics of Neptulon to come to fruition. For the sake of Azeroth and all life upon it, we must act. Our path is clear. You must journey to the Slave Pens deep within Coilfang Reservoir and meet with our shaman there. Go, and quickly!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[11956] = { title = "Finding the Phylactery", description = "No time for small talk, {name}.  I was sent on what was to be a suicide mission to take this ziggurat.  I've accomplished my duty as a soldier, now is the time to get some answers.\n\nThis lich has knowledge I seek, yet I cannot inflict pain to his physical body to obtain that knowledge.\n\nThe lich stored his soul in a phylactery, and while it remains hidden, I won't be able to pry the information from him.\n\nReturn to the camp and take my horse, Dusk, she will lead you to the phylactery.  Bring it to me.", objectives = "Go to Death's Stand and ride Dusk to the location of Tanathal's Phylactery. Obtain it and bring it back to Thassarian inside the Wailing Ziggurat.", progress = "You're back, <name>.  Did you get the phylactery?", completion = "Just in time, <name>.  Pinning down a lich is not as easy as it looks." }
WordHunterWoW_QuestEN[11957] = { title = "Saragosa's End", description = "Using the mana crystals you provided, I have created this Power Focus.\n\nSaragosa is a glutton. She will be unable to resist its lure. Inside it lie magics that will greatly diminish her power. Let us hope she does not see through my ruse....\n\nPrepare yourself, {name}, and speak to me again when you are ready to face Saragosa.\n", objectives = "Keristrasza wants you to use the Power Focus to lure Saragosa, and then defeat her.", progress = "Saragosa must not be allowed to live!", completion = "This world is a better place now that Saragosa is no more, but our work is not yet finished.\n\nThe time has come to strike at Malygos himself!" }
WordHunterWoW_QuestEN[11958] = { title = "Let Nothing Go To Waste", description = "The wolvar have always been our natural enemies. But the incursion of your peoples into the Great Dragonblight has forced them into a small space upon the glade to the north.\n\nCombined with the land's upheaval this morning, they have become even more aggressive than ever before. They have made several raids upon our goods... things that we'll need if we are to survive the trek from our home here.\n\nAs a sign of good faith and friendship, retrieve our goods from the Snowfall Glade wolvar.", objectives = "Retrieve 6 Stolen Moa'ki Goods from the wolvar. Return them to Elder Ko'nani at Moa'ki Harbor.", progress = "The natural balance has been tipped over and over of late.\n\nI hope that you will be able to help us survive the upheaval of our way of life.", completion = "I will not say that I am pleased to ask you to do such things on our behalf. It is all we can do to prepare quickly for our departure, though we know not yet where we go.\n\nMy sorcerers tell me that you are here to save the land from He Who Walks in Shadow.\n\nI trust that you will save the peoples of the land as well." }
WordHunterWoW_QuestEN[11959] = { title = "Slay Loguhn", description = "Already it goes from bad to worse. There is only one course to take... regrettably, Loguhn must die!\n\nHe's the alpha male of the Snowfall Glade tribe and one mean wolvar. But it's the only way to get a short break from their attacks and stealing forays.\n\nYou will find the \"Render of Flesh\" in front of his hovel upon the northern rise of the glade. It's larger than the others and hard to miss. Kill him and smear his blood upon yourself, both to show your dominance and respect.", objectives = "Smear the Blood of Loguhn upon yourself and then return to Elder Ko'nani at Moa'ki Harbor.", completion = "Loguhn's honorable sacrifice at your hands is exactly what my people need. Now we will make the most of the wolvar in-fighting for his place.\n\nIt will have to be enough." }
WordHunterWoW_QuestEN[11960] = { title = "Planning for the Future", description = "We must move decisively against the wolvar if we're to have a chance of survival. However, I worry that in our zeal, too many of them will be slain.\n\nThe Snowfall Glade wolvar have as much right to exist as do we. You and I will see to it that they get that chance.\n\nIf Elder Ko'nani hasn't asked you already, he will ask you to deal with them.  While you're upon the glade to the north, I'd like you to bag up their pups and bring them back to me.", objectives = "Collect 12 Snowfall Glade Pups. Deliver them to Trapper Mau'i at Moa'ki Harbor.", progress = "How many pups could you have possibly saved in so short a time?", completion = "Well, I guess you saved plenty of them. Thank you, <race>.\n\nNow the wolvar will have a chance of surviving along with us. If we survive at all, that is.\n\nDo you think that you could return tomorrow so that we can save more of the pups?" }
WordHunterWoW_QuestEN[11961] = { title = "Spirits Watch Over Us", description = "Powerful spirits watch over my tribe -- Kaskala will not be lost.\n\nIssliruk will give us courage, Tayutka will make sure our survivors always have food and shelter and Karkut will watch over the fallen so they do not lose their way.\n\nIssliruk's guidance is the one we need the most right now.  I asked my nephew, Iruk, to bring me Issliruk's totem, but the Kvaldir's spears struck him down and his body fell into the waters to the north.  Bring me the totem, {name}.  Don't let my nephew's death be in vain.", objectives = "Elder Muahit at Njord's Breath Bay wants you to find Iruk's corpse in the water and retrieve Issliruk's totem.", progress = "The totem, <race>.  Do you have it?", completion = "Can you feel Issliruk's presence, <name>?  He does not want his children to perish at the hand of the mist-walkers." }
WordHunterWoW_QuestEN[11962] = { title = "One Last Delivery", description = "That's it then.  With the last of the ore you salvaged we now have enough to send to Valiance Keep.\n\nIf Farshire is wiped off the face of Azeroth, then at least let us be remembered as the first ones to defend our land and the last ones to give up.\n\nTake this ore to Hilda Stoneforge - she is a good friend of mine.  Tell her to make some good weapons with this ore.  We'll need plenty of them in the days to come.", objectives = "Deliver the Crate of Farshire Ore to Hilda Stoneforge in Valiance Keep.", progress = "What do you have there?", completion = "Ore from Farshire?  We weren't scheduled for a shipment just yet.  Is something wrong?" }
WordHunterWoW_QuestEN[11963] = { title = "Weapons for Farshire", description = "Farshire is overrun and all that Gerald can think of is to get me my ore shipment?  I swear that man has as much heart as any of our soldiers on the frontlines.\n\nWe cannot let the civilians lose their lands if they're willing to fight for them.  We might not have the troops to spare, but we can send them weapons.\n\nThese were earmarked for new recruits, but I'll be able to cover those with the ore you've brought me.  Send word to Gerald that weapons are on the way.", objectives = "Return to Gerald Green in Farshire.", completion = "Hilda's sending us weapons?  That's excellent news, <name>.  I was about ready to tell the lads to pack things up." }
WordHunterWoW_QuestEN[11964] = { title = "Incense for the Summer Scorchlings", description = "Did you know that our festival fires burn in every land with an Alliance settlement? Flame Wardens tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue.\n\nWith each Flame Warden is a summer scorchling -- an emissary to the elemental spirits of fire.\n\nWould you like to honor a scorchling, {name}?  Take this summer incense and bring it to any summer scorchling.  Appease the little fire spirit, and it may reward you.", objectives = "The Festival Loremaster wants you to take Summer Incense to a Summer Scorchling outside any Alliance settlement.", progress = "A fiery salutations to you, honored <class>.  Welcome to this hallowed ground of the Midsummer Fire Festival.", completion = "Ah, and what is this?  Such a delightful aroma!  I am sure it will burn with a flame pure and bright!\n\nTake this blossom, <name>.  Take it, and leave me be... I must attend to this precious fuel..." }
WordHunterWoW_QuestEN[11965] = { title = "Call to Arms!", description = "Farshire has a fighting chance now, {name}.  That's all we could've asked for and you've made it possible.\n\nAll we need now is a rallying point.  I'll have my men deliver the weapons to our town hall.  Go and ring the town hall bell so any survivors know to rally there.\n\nIt's time to show the Scourge what we're made of.", objectives = "Go to the town hall building in Farshire and ring the bell inside of it.", completion = "Thanks once again for aiding us, <name>.  The people of Farshire will always remember you." }
WordHunterWoW_QuestEN[11966] = { title = "Incense for the Festival Scorchlings", description = "Did you know that our festival fires burn in every land with a Horde settlement? Flame Keepers tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue.\n\nWith each Flame Keeper is a festival scorchling -- an emissary to the elemental spirits of fire.\n\nWould you like to honor a scorchling, {name}?  Take this summer incense and bring it to any festival scorchling.  Appease the little fire spirit, and it may reward you.", objectives = "The Festival Talespinner wants you to take Summer Incense to a Festival Scorchling outside any Horde settlement.", progress = "A fiery salutations to you, honored <class>.  Welcome to this hallowed ground of the Midsummer Fire Festival.", completion = "Ah, and what is this?  Such a delightful aroma!  I am sure it will burn with a flame pure and bright!\n\nTake this blossom, <name>.  Take it, and leave me be... I must attend to this precious fuel..." }
WordHunterWoW_QuestEN[11967] = { title = "Mustering the Reds", description = "Malygos is certainly aware that something is amiss.\n\nI know him. His focus is fragmented. I am confident that I can lure him from the safety of his realm when he learns what has become of his precious Saragosa.\n\nTake me to Raelorasz at once, {name}. He must rouse every dragon he commands to face Malygos.", objectives = "Keristrasza has asked you to bring her to Raelorasz at the Transitus Shield.", progress = "You have news for me, <name>?", completion = "Word of Keristrasza's rescue has reached my ears. You are to be commended.\n\nI am eager to speak with her again." }
WordHunterWoW_QuestEN[11968] = { title = "The Tides Turn", description = "The spirits have heard our cry for help, {name}.  It's a sign that Kaskala might yet be saved.\n\nTake advantage of the confusion the weather has created and slay the Kvaldir leader.  Your actions will sway the battle in our favor, I am sure of it.", objectives = "Elder Muahit wants you to kill Heigarr the Horrible in Njord's Breath Bay.", progress = "Have you done what I asked of you, <name>?", completion = "You've done us a great favor, <race>.  The fight is not yet won, but my people now have a chance." }
WordHunterWoW_QuestEN[11969] = { title = "Springing the Trap", description = "We owe this opportunity in great part to your efforts, {name}.\n\nIt is only fitting that you initiate the attack on Malygos.\n\nTake this spark and use it to light the signal fire northwest of the Nexus. Keristrasza will direct you from there.", objectives = "Raelorasz wants you to use Raelorasz' Spark at the signal fire in Coldarra.", progress = "Did you meet with Keristrasza?", completion = "We have dealt a blow to Malygos, but it has come at a high price." }
WordHunterWoW_QuestEN[11970] = { title = "The Master of Summer Lore", description = "There should be no mistake, the festival is a time for fun and laughter! However it is important that you understand the origins of this holiday. Education should be sought out and savored! .\n\nThe Festival Loremaster in the Alliance capitals can guide your way. Go now and learn!", objectives = "Speak to the Festival Loremaster in any Alliance capital.", completion = "I'll be happy to tell you what I know." }
WordHunterWoW_QuestEN[11971] = { title = "The Spinner of Summer Tales", description = "Let there be no mistake, the festival is a time for fun and laughter! However it's important that you understand the origins of this holiday. Education should be sought out and savored! .\n\nThe Festival Talespinner in the Horde capitals can guide your way. Go now and learn.", objectives = "Speak to the Festival Talespinner in any Horde capital.", completion = "I'd be happy to tell you what I know." }
WordHunterWoW_QuestEN[11972] = { title = "Shards of Ahune", description = "These shards pulse with foreboding. Do they hold the last essence of the Frost Lord?", objectives = "Bring the Ice Shards to Luma Skymother.", progress = "Greetings, <name>.  You look worried, but you shoud rejoice.  The Frost Lord is defeated!", completion = "Yes, these shards hold the final essence of the Frost Lord in this land.  We will dispose of them and banish Ahune to the nether regions of cold.\n\nThank you, <name>.  Your name will echo in the chants of the Earthen Ring for days without end.  Please honor us by accepting this vestige, a symbol of your kinship with warmth and light." }
WordHunterWoW_QuestEN[11973] = { title = "Prisoner of War", description = "Malygos has taken Keristrasza to serve as his consort!\n\nWe cannot allow this to come to pass.\n\nYou must do whatever it takes to spare her such a fate, {race}.", objectives = "Warmage Kaitlyn wants you to free Keristrasza.", progress = "Were you able to free her from her bonds?", completion = "So, it is done then....\n\nOur kind shall never forget the sacrifice Keristrasza has made for this cause." }
WordHunterWoW_QuestEN[11975] = { title = "Now, When I Grow Up...", description = "Maybe I already asked you this, but when you were my age did you know that you wanted to be a {class} when you grew up?\n\nI'm not sure what I want to be.  Maybe a mage or a warlock or a Blood Knight, like I said before?  Or maybe... A rock star!!  Like Sig Nicious, the blood elf, in the Tauren Chieftains!\n\nI heard that when they aren't touring, they hang out in Silvermoon City!  They just sit on a balcony in the Walk of Elders waiting for people to stop by.\n\nPlease take me there.  Please!", objectives = "Take your orphan, Salandria, to see the Elite Tauren Chieftain in Silvermoon City's Walk of Elders. Make sure to call for her if she is not present when you arrive.", progress = "Elite Tauren Chieftain are the coolest!", completion = "Did you see that?  They were cheering for me!!\n\nNow I know how they feel when they are up on stage singing!  I felt the power and the energy!\n\nJust like they say in their song!\n\nMy mind is made up, I am going to be a rock star when I grow up!" }
WordHunterWoW_QuestEN[11976] = { title = "Ice Shards", description = "These shards pulse with foreboding.  Do they hold the last essence of the Frost Lord?You will receive:", objectives = "Bring the Ice Shards to Luma Skymother." }
WordHunterWoW_QuestEN[11977] = { title = "A Tauren Among Taunka", description = "<Wartook points northeast.>\n\nShe is quite kind, you know. If it were not for your emissary, the surviving refugees may have given up hope. While she may not be taunka by birthright, the tribe has taken to her as a village elder for the time being.\n\nIf you are who I think you are, please go and pay Emissary Brighthoof a visit inside the refugee camp. She has been waiting for you.", objectives = "Seek out Emissary Brighthoof at the Westwind Refugee Camp.", completion = "What you see here is all that remains of the taunka from the Borean Tundra and the Dragonblight. They are a broken people... battered and brought to the brink of extinction by the Scourge.\n\n<Brighthoof shakes her head.>\n\nOnly the Horde can save them now. Only the Horde can mend their broken spirits. We will nurse them back to full health and they will in turn strengthen the Horde in Northrend." }
WordHunterWoW_QuestEN[11978] = { title = "Into the Fold", description = "Before we can officially bring these taunka into the Horde we must recover our armaments from the Anub'ar Nerubians that infest the nearby woods. The armaments were lost when a caravan from Agmar's Hammer was ambushed by the Scourge late last night.\n\nVenture out into the woods to the east of Westwind Refugee Camp and recover those armaments, {race}.", objectives = "Emissary Brighthoof at the Westwind Refugee Camp in the Dragonblight wants you to recover 10 Horde Armaments.", progress = "Without armor and weapons our newest members will be defenseless in their trek to Agmar's Hammer.", completion = "This is exactly what we need, <name>! Brandishing Horde arms will lift their spirits and give them the protection they need against the Scourge.\n\nAre you prepared for the ceremony of initiation?\n\n\n\nYou will be the one to admit our new allies into the Horde." }
WordHunterWoW_QuestEN[11979] = { title = "The Taunka and the Tauren", description = "The Scourge have seized control of the capital city of the taunka, Icemist Village! All living taunka that escaped the massacre are being held in protective custody at the Westwind Refugee Camp on the western border of Dragonblight.\n\nLord Hellscream believes that the taunka must join the Horde if they are to survive and has sent a tauren emissary to Westwind to bolster our relationship with the winter tauren. Travel to Westwind Refugee Camp and seek out Emissary Brighthoof. You will assist her.", objectives = "Seek out Emissary Brighthoof at the Westwind Refugee Camp.", completion = "What you see here is all that remains of the taunka from the Borean Tundra and the Dragonblight. They are a broken people... battered and brought to the brink of extinction.\n\n<Brighthoof shakes her head.>\n\nOnly the Horde can save them now. Only the Horde can mend their broken spirits. We will nurse them back to full health and they will in turn strengthen the Horde in Northrend." }
WordHunterWoW_QuestEN[11980] = { title = "Pride of the Horde", description = "I was one of the guards chosen to escort the caravan carrying the armament shipment to this camp. The attack came fast and without warning. We fought and killed dozens of the beasts, but in the end there were simply too many. Tor'zin and I barely made it out alive...\n\nIf not for our injuries we would be out in the woods hunting down those fiends ourselves. Will you help us regain our lost pride? Search the woods east of here for Anub'ar Nerubians and kill them! For the Horde!", objectives = "Blood Guard Roh'kill at the Westwind Refugee Camp in the Dragonblight wants you to slay 15 Anub'ar Ambushers.", completion = "<Roh'kill salutes you.>\n\nYou have preserved our honor, <name>. Tor'zin and I both thank you for this selfless act!" }
WordHunterWoW_QuestEN[11981] = { title = "Find Kurun!", description = "The Earthen warrior's stone surface is covered with cracks and gouges. Although it is incapable of bleeding, you can sense that the warrior is near death.\n\nA low, hoarse voice escapes from the dying warrior's mouth.\n\n\"Find... Kurun... you must find... Kurun.\"\n\nIt looks at you helplessly as you ask for any clues as to who or what Kurun might be.\n\n\"Our... leader... he stands on the... hill overlooking Thor Modan... commands us. Please... tell him... we cannot take... the city... \"", objectives = "Speak with Kurun on the hill overlooking Thor Modan.", completion = "<You tell Kurun about the message given to you by the fallen Earthen.>\n\nThey fight bravely, but he is right. We will not overcome the iron dwarves of Thor Modan without help. My giants and the Earthen have long struggled against iron's evil, but our forces are not numerous enough to win the battle for Thor Modan. Will you aid us?" }
WordHunterWoW_QuestEN[11982] = { title = "Raining Down Destruction", description = "Beneath us is iron's ancient bastion, Thor Modan. Thousands of years ago, the stone giants tore the land asunder, collapsing part of the city and exposing much of the rest.\n\nEven now, the iron dwarves attempt to reclaim their old capital, but we will not permit it. My giants fill the trench with boulders and debris, hoping to seal it off and kill the servants of iron as they work. Take up the boulders you see near the trench to the northeast, and help us put an end to their efforts.", objectives = "Kurun on the hill overlooking Thor Modan wants you to disrupt the iron dwarves' work by throwing boulders into the exposed area of Thor Modan.", progress = "What have you to report?", completion = "As quickly as we're able to fill the trench, the iron dwarves keep clearing it. Our assault from above will not take the city alone. You must aid the earthen fighting in the plaza below." }
WordHunterWoW_QuestEN[11983] = { title = "Blood Oath of the Horde", description = "They are ready, {name}. These taunka will all willingly join the Horde and give all that they have to see the Scourge driven from this world.\n\n<Brighthoof hands you a scroll bearing the insignia of the Horde.>\n\nWithin this scroll you will find the blood oath of the Horde. Tradition dictates that our new taunka brothers and sisters utter the sacred words herein.\n\nTake the scroll and swear the taunka into the Horde, commander. Return the scroll to me when you have completed your duty.", objectives = "Speak to the taunka at Westwind Refugee Camp and make 5 of them pledge their allegiance to the Horde.\n\nReturn the Blood Oath of the Horde to Emissary Brighthoof once you have completed this task.", progress = "They will strengthen the Horde, commander.", completion = "Thank you for doing this, Commander <name>. They had nothing left. You have given them purpose and with purpose comes hope... Hope for a new tomorrow... for a new life." }
WordHunterWoW_QuestEN[11984] = { title = "Filling the Cages", description = "'Ol Budd's seen better days.\n\nEver since our stay in Ghostlands he's been useless to us. We've had to find ways to make it on our own, and today that means sellin' trolls to the highest bidder.\n\nFortunately, we've recently found a use for Budd. Something about his condition allows him to mingle with the local trolls, so we taught him a little game that's turned us a tidy profit.\n\nSee for yourself. Talk to Budd, take him southwest to Drak'Zin Ruins and use this cage as soon as he tags a troll.", objectives = "Samir at Granite Springs wants you to use the Bounty Hunter's Cage on a drakkari troll that's been stunned by Budd.", progress = "Have you managed to cage an ice troll?", completion = "Great work, <class>. Looks like we'll be keepin' Budd around a little longer.\n\nWe'll have your cage picked up right away. Here's your share of the bounty.\n\nOh, and welcome to the camp. Stick around and I'm sure we'll find a use for ya...." }
WordHunterWoW_QuestEN[11985] = { title = "Into the Breach", description = "If we can't overcome the defenders inside Thor Modan, the iron dwarves can hold out forever. The Earthen are bravely taking on the constructs built by the sons of iron, but they cannot break into the city.\n\nThe tunnels narrow too quickly for my fellow giants to be of use, so our options are few. Would you be willing to venture into the city and kill the dwarf commanding the resistance?", objectives = "Kurun on the hill overlooking Thor Modan wants you to kill Iron Thane Argrum.", progress = "Were you able to kill the commander?", completion = "Well done, <name>. The loss of the iron dwarf commander should be enough to break the remaining defenders. The Earthen should be able to deal with the survivors." }
WordHunterWoW_QuestEN[11986] = { title = "The Damaged Journal", description = "This battered, mud-stained journal has seen better days. Leafing through the pages, you discover dozens of notes, diagrams, and maps.\n\nThe author's handwriting seems vaguely familiar, but you're unable to place it until you discover an entry signed with the name of Brann Bronzebeard.\n\nThe back half of the book, containing the most recent entries, has been torn away. Pages litter the battlefield, and it will be impossible to know what Brann discovered here until the book is whole again.", objectives = "Recover 8 Missing Journal Pages, combine them with the Incomplete Journal, and return the completed journal to Torthen Deepdig at the Westfall Brigade Encampment.", progress = "What's that you have there?", completion = "You found Brann's journal? Incredible! The league hasn't gotten a report from him in some time, and we began to fear he may have been captured or killed. What did he discover inside Thor Modan?" }
WordHunterWoW_QuestEN[11987] = { title = "zzOLDFortune Card: Silver", description = "", objectives = "You will be able to choose one of these rewards:" }
WordHunterWoW_QuestEN[11988] = { title = "The Runic Keystone", description = "Brann's journal mentions that he used a runic keystone to illuminate the important runes on the plate he discovered. Without the keystone, the plate's contents would be little better than gibberish.\n\nAt the end of Brann's last entry, he describes the iron dwarf defenders seizing the keystone from him, shattering it, and dividing it among themselves. Before we can decipher the runed plate, we must hunt down the fragments. Any of the dwarves within Thor Modan or the buildings around it may carry fragments.", objectives = "Bring 5 Runic Keystone Fragments to Torthen Deepdig at the Westfall Brigade Encampment.", progress = "Do you have enough of the fragments to reconstruct the keystone?", completion = "<Torthen works quickly to assemble the fragments you retrieved.>\n\nThis is incomplete, but it should still allow us to get most of the information from the plate." }
WordHunterWoW_QuestEN[11989] = { title = "Truce?", description = "Watch yerself, mon.\n\nDrakuru shrunk more {race} heads than I can remember - and even if I could remember, I couldn't count that high. Lucky for you I be stuck in dis cage or I'd be addin' one more to da list.\n\nBut things bein' what they are, mebbe we be puttin' our differences aside fer a time, eh?\n\nDrakuru know things, mon. Things that will aid you in your struggle here.\n\n<Drakuru cuts the palm of his hand on one of his tusks and extends it through the cage.>\n\nSo, what you say, mon... truce?", objectives = "Drakuru at Granite Springs wants you to use the Dull Carving Knife near his cage and then speak to him.", progress = "Good choice, mon. You won't be livin' to regret it....", completion = "There!\n\nNow we be connected by blood, mon. A true bond we be havin'.\n\nYou lissen carefully to Drakuru, <race>. There be much to do." }
WordHunterWoW_QuestEN[11990] = { title = "Vial of Visions", description = "First things first, mon. There be some preparatory work that need doin'.\n\nNo tellin' how long dey gunna keep me here. Ya be needin' a powerful elixir so we can be keepin' in touch.\n\nLucky for you, I know just the thing! And the ingredients all be close by.\n\nI need a vial from the pretty little troll over there, some waterweed from the lake just north of here, and a few haze leaves found around the camp here.\n\nHurry now, mon, before dey be haulin' me away.", objectives = "Drakuru at Granite Springs wants you to bring him a Crystal Vial, a Waterweed Frond, and 3 Haze Leaves.", progress = "You got da stuff, mon?", completion = "<Drakuru takes the ingredients and deftly combines them in the vial.>\n\nThis should do it, mon. Now it be time to get to work." }
WordHunterWoW_QuestEN[11991] = { title = "Subject to Interpretation", description = "A legendary set of artifacts, lost for thousands of years, were created to make Drak'Tharon Keep impervious.\n\nMost think they be myth, but Drakuru knows better, mon!\n\nI nearly discovered where one be, but got captured while interpreting hieroglyphs. Ya gotta summon my soul back dere so I can finish readin' em!\n\nUse my elixir at da brazier on Drak'Zin Ruins, southwest of here. You'll hafta mix in da frozen mojo my bruddas be holdin'. I hate ta see my bruddas fall, but it be for the greater good.\n", objectives = "Drakuru wants you to get 5 Frozen Mojo from the Drakkari Trolls at the Ruins of Drak'Zin and then use the elixir at Drakuru's Brazier there.", completion = "Ahh, yes. Ya done good, mon.\n\nI be readin' the walls just fine from here...." }
WordHunterWoW_QuestEN[11992] = { title = "Navigation Charts (Deprecated)", description = "You've uncovered the first part of a navigation chart drawn on flayed dragonskin.  If you could complete it you'd be able to find the kvaldir's future plans of attack.\n\nOther mariners in Riplash might have the missing charts on them.  Karuk would be interested in the information they contain.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Obtain the missing parts of the Skadir Navigational Chart and bring it to Karuk in Riplash Stand." }
WordHunterWoW_QuestEN[11993] = { title = "The Runic Prophecies", description = "We've no time to lose! Now that we've reassembled the runic keystone -- well, most of it -- we can decipher the contents of those very same runic plates Brann was working on before he fled.\n\nWe have no way of knowing if he managed to read the contents of all three plates, but we'll have to assume he got enough information to determine his next destination.\n\nStand before each of the plates and use the keystone to determine the contents of each. Brann may be counting on us!", objectives = "Torthen Deepdig at the Westfall Brigade Encampment wants you to decipher the three Rune Plates.", completion = "<Torthen listens as you recount the contents of the runic plates.>\n\nBy Madoran's hammer, he's discovered a whole new titan city!\n\n'The cradle of stone and iron.'\n\n'Ulduar nestled in the storm.'\n\nWhat d'you suppose that means? Could it be where we come from, after all these years?\n\nWe have to follow him! We have to find him!" }
WordHunterWoW_QuestEN[11994] = { title = "Juno's Flag Tester", description = "", objectives = "" }
WordHunterWoW_QuestEN[11995] = { title = "Your Presence is Required at Stars' Rest", description = "{class}, I know these tuskarr will ask you to do many favors for them, but you must get to Stars' Rest with all due haste!\n\nThe upheaval in the land this morning is sure to have broader repercussions than just inconveniencing the natives.\n\nStars' Rest is westward past the intersection of the road leading north out of the harbor. There is an archmage there named Modera. She will be expecting you.", objectives = "Speak with the Image of Archmage Modera at Stars' Rest.", completion = "I've been expecting you, <class>. We have much work to do, you and I." }
WordHunterWoW_QuestEN[11996] = { title = "Your Presence is Required at Agmar's Hammer", description = "{class}, I know these tuskarr will ask you to do many favors for them, but you must get to Agmar's Hammer with all due haste!\n\nThe upheaval in the land this morning is sure to have broader repercussions than just inconveniencing the natives.\n\nThe Hammer is westward past the intersection of the road leading north out of the harbor. Archmage Aethas Sunreaver himself will be expecting you!", objectives = "Speak with the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", completion = "What took you so long? Time waits only for Aspects, <race>.\n\nWe have much work to do, you and I." }
WordHunterWoW_QuestEN[11997] = { title = "The Frozen Flame", description = "It is time we make our move, {name}. I can conjure a portal that will take you directly inside but it will take some time before I can make another and join you.\n\nThe Lich King will no doubt sense the magic of your arrival so you will need to move fast to locate Felo'melorn and secure it.\n\nIf Lyandra has the blade with her then I fear she may not relinquish it easily. Be prepared for anything, {name}.", objectives = "Obtain Felo'melorn from Lyandra Sunstrider in Icecrown Citadel.", completion = "Felo'melorn... I can barely believe that such great power is locked within a blade as beautiful as this!\n\nWith this weapon in your hands, the Legion will surely fall!" }
WordHunterWoW_QuestEN[11998] = { title = "Softening the Blow", description = "Our best bet for moving our forces quickly to Icecrown Glacier lies with the network of tunnels beneath the ancient iron dwarf city of Thor Modan.\n\nBrugar Stoneshear and his Explorers' League boys aren't going to be happy, but orders are orders.\n\nThe news might go over better if you brought him a cask of that moonshine sold by that trapper, Hugh Glass, down at Redwood Trading Post, southeast of here along the tree line.\n\nMan's not right in the head, but you won't find better moonshine out here.", objectives = "Bring Brugar Stoneshear at the Westfall Brigade Encampment a cask of Howlin' Good Moonshine.", progress = "What's that you have there?", completion = "Let me get this straight -- a <race> I don't know brings me a cask of the finest booze in this miserable forest. Ok, then, what are you after?" }
WordHunterWoW_QuestEN[11999] = { title = "Rifle the Bodies", description = "The Moonrest Gardens to the southwest were the final resting place of a group of Highborne elves. It was also a ley line nexus.\n\nThe blue dragonflight used a magical device they call a surge needle to destroy that nexus, freeing the power to redirect at their will.\n\nI want more information and you are going to get it for me!\n\nAfter the land was destroyed at the ruins, the ghosts of the Highborne rose up and decimated half of the mage hunters there. Go rifle their corpses for clues.", objectives = "Find the Moonrest Gardens Plans and return them to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", progress = "You have returned.  What did you uncover?", completion = "Curious, they seek an accord with the Ethereum. The ethereals could prove a powerful ally for Malygos and his madness.\n\nThis will not do!" }
WordHunterWoW_QuestEN[12000] = { title = "Rifle the Bodies", description = "The Moonrest Gardens to the southwest were the final resting place of a noble group of Highborne elves. It was also a powerful ley line nexus.\n\nThe blue dragonflight used a magical device they call a surge needle to destroy that nexus, freeing the power to redirect at their will.\n\nI need more information and I hope that you will get it for me.\n\nAfter the upheaval at the ruins, the ghosts of the Highborne rose up and decimated half of the mage hunters present. Go rifle their corpses for clues.", objectives = "Find the Moonrest Gardens Plans and return them to the Image of Archmage Modera at Stars' Rest.", progress = "You have returned.  What did you uncover?", completion = "Curious, they seek an accord with the Ethereum. The ethereals could prove a powerful ally for Malygos and his madness.\n\nThis will not do!" }
WordHunterWoW_QuestEN[12001] = { title = "zzOLDHunting Tarot: Lesser Beasts", description = "Staring into the card, the image blurs until you see yourself standing covered in the furs from many wolves and bears.  You can only assume this is your destiny should you invoke the tarot's power.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 12 Torn Hides and then summon the Huntsman with the Hunting Tarot. The Torn Hides can only be gathered from beasts of level 5 or higher." }
WordHunterWoW_QuestEN[12002] = { title = "Brothers in Battle", description = "I hope Gryan knows I withdrew my men from Thor Modan when the battle began. There's no way we can excavate anything until that place settles down.\n\nYou seem like a brave sort, though, and you have Stoutmantle's trust.\n\nThor Modan is just to the northeast of us and the battle still rages between our Earthen brothers and the creations of those accursed iron dwarves. Help our brethren to even the odds and I'll start figuring out how we're going to accomplish this survey of Thor Modan.", objectives = "Kill 10 Runic Battle Golems and return to Brugar Stoneshear at the Westfall Brigade Encampment.", completion = "<Brugar listens to your report.>\n\nIt sounds like things may be calming down there a bit. We'll start looking for entrances to the iron dwarves' tunnel system." }
WordHunterWoW_QuestEN[12003] = { title = "Uncovering the Tunnels", description = "The first place we'll search for entrances to the Thor Modan tunnel system will be the outlying buildings.\n\nAs I left the site with my men, it looked like the iron dwarf defenders were taking refuge inside the buildings. Be careful as you explore them.\n\nAny tunnel entrances are likely to be toward the back of the buildings. I'm not sure what Stoutmantle thinks we're going to find down there, but I doubt the iron dwarves will make the search easy.", objectives = "Brugar Stoneshear at the Westfall Brigade Encampment wants you to explore the North Building, the East Building, and the South Building of Thor Modan.", completion = "<Brugar utters a stream of foul dwarven words.>\n\nNo entrances? None?\n\nNo, of course it couldn't be that easy. Well, I suppose there's no avoiding a foray into the city proper. My boys'll never get back to their real work." }
WordHunterWoW_QuestEN[12004] = { title = "Prevent the Accord", description = "We need to kill two birds with one stone here, {class}. You're the stone.\n\nOur two birds are Wind Trader Mu'fah and Goramosh. They should be somewhere in the western half of the Moonrest Gardens. Most likely they're in the larger two-story building overlooking the pit.\n\nI require proof of their demise, if you would be so kind.", objectives = "Deliver Wind Trader Mu'fah's Remains and the Scales of Goramosh to the Image of Archmage Modera at Stars' Rest.", progress = "Have you prevented the accord between the blue dragonflight and the Ethereum?", completion = "Unfortunate that Goramosh indicated the accord had already been reached.\n\nNonetheless, that's two less worms we'll have to worry about. Let us get to more important business." }
WordHunterWoW_QuestEN[12005] = { title = "Prevent the Accord", description = "We need to kill two birds with one stone here, {class}. You're the stone.\n\nOur two birds are Wind Trader Mu'fah and Goramosh. They should be somewhere in the western half of the Moonrest Gardens. Most likely they're in the larger two-story building overlooking the pit.\n\nI require proof of their demise, if you would be so kind.", objectives = "Deliver Wind Trader Mu'fah's Remains and the Scales of Goramosh to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", progress = "Have you prevented the accord between the blue dragonflight and the Ethereum?", completion = "That's alright, <class>, just put them down on the ground there in front of Agmar's throne.\n\n\n\nUnfortunate that Goramosh indicated the accord had already been reached.\n\nNonetheless, that's two less worms we'll have to worry about. Let us get on to more important business." }
WordHunterWoW_QuestEN[12006] = { title = "Avenge this Atrocity!", description = "These so-called mage hunters came here and destroyed our resting place.\n\nAvenge us, or I will see to it that your base of operations is overrun with the spirits of the dead!", objectives = "Kill any combination of 15 Dragonblight Mage Hunters, Moonrest Stalkers, Surge Needle Sorcerers, and Focus Wizards. After you have done that, return to Ethenial Moonshadow at Moonrest Gardens.", progress = "Somehow I sense that you haven't quite killed enough of these defilers!", completion = "Very well, you have satisfied my request if nothing more.\n\nThank you, <race>." }
WordHunterWoW_QuestEN[12007] = { title = "Sacrifices Must be Made", description = "I've got it, mon!\n\nTo da north, on da Ziggurat at Zeb'Halak be a stone head with ruby eyes. One o' dem be da Eye of the Prophets! Bring it to the brazier there and drink my elixir.\n\nAgain, ya be needing some mojo for my elixir to work - dis time from da warlord, Zim'bo. He be hidin' in one of da huts in Zeb'Halak.\n\nIt be a shame to kill Zim'bo, mon, but he swore da blood oath to defend Drak'Tharon and he done failed. Now at least his mojo be helpin' us to reclaim Drak'Tharon.", objectives = "Drakuru wants you to bring the Eye of the Prophets to him at Drakuru's Brazier in Zeb'Halak.\n\nYou will need to collect Zim'bo's Mojo to use Drakuru's Elixir there.", progress = "You get da Eye of the Prophets, mon?", completion = "Dis be it, mon!\n\nIt be even more precious than I hoped. Dis be sure to bring mah people hope in dese dark times.\n\nNo time to waste, now. Let's be seein' where da next artifact be hidin'." }
WordHunterWoW_QuestEN[12008] = { title = "Agmar's Hammer", description = "Directly east of this refugee camp stands Agmar's Hammer - testament to the Hordes' power in the Dragonblight.\n\nWhile I have no doubt that our Horde brothers and sisters are already seeing the result of your efforts to bring the taunka into the Horde, I want you to deliver news of your success to Overlord Agmar in person.\n\nGo now, {name}! Race the winds! East to Agmar's Hammer!\n", objectives = "Travel to Agmar's Hammer in the Dragonblight and speak to Overlord Agmar.", completion = "While you have undoubtedly championed the cause of the Horde elsewhere, many more have been working towards expanding our grasp deeper into Northrend. Even now we have forces establishing bases in the frozen reaches of this desolate wasteland.\n\nWe surround the Scourge on all sides. Victory nears as our armies amass at the foot of the Wrathgate, Angrathar. Soon we will tear down the gate and breach Icecrown.\n\nBut there is much work left to be done...\n\nFirst we stop the Nerubians!" }
WordHunterWoW_QuestEN[12009] = { title = "Tua'kea's Crab Traps", description = "With all of the troubles, I've lost my assistants. I was wondering if maybe you could help me?\n\nI have many crab traps under the waves of the harbor. Will you retrieve them for me? I'm too old for that sort of thing and the waters can be very dangerous.\n\nPlease, take this bladder. It will help you to breathe while you're down there.", objectives = "Collect 8 of Tua'kea's Crab Traps and return them to him at Moa'ki Harbor.", progress = "How many crabs did you manage to retrieve?", completion = "I'm a simple trapper. The world has turned upside-down all of a sudden. It doesn't make sense.\n\nI hope that you'll be able to set it right again." }
WordHunterWoW_QuestEN[12010] = { title = "The Fate of Orlond", description = "When we began excavating the city, I sent Surveyor Orlond to check the stability of the tunnels in Thor Modan. I didn't see him escape when we withdrew at the beginning of the battle, and I worry he may still be trapped inside the city.\n\nIf we're going to get an army through Thor Modan, we'll need the information he was collecting. Stoutmantle and his superiors would have my hide if the tunnels collapsed on one of their brigades!", objectives = "Locate Surveyor Orlond within Thor Modan.", completion = "A quick examination of the body reveals that the surveyor has been dead for some time. Looking through his pack, you stumble upon Orlond's handwritten notes." }
WordHunterWoW_QuestEN[12011] = { title = "Signs of Big Watery Trouble", description = "This crab trap appears to have been destroyed by something much larger than the nearby circling sharks.\n\nPerhaps Tua'kea, the fisherman at Moa'ki Harbor, should be told about this?", objectives = "Inform Tua'kea at Moa'ki Harbor about the wrecked crab trap.", completion = "That's not the news I wanted to hear, <race>.\n\nNo, no... it's good that you told me, but I fear my old nemesis has returned to these waters." }
WordHunterWoW_QuestEN[12012] = { title = "Inform the Elder", description = "This information must be spread to the entirety of the Earthen Ring. I'm not certain how to proceed, but the elder who set you on this task in the first place may. Please, return to the elder and seek the next course of action - we must do something!", objectives = "Travel to a capital city and speak to the Earthen Ring Elder.", completion = "This is grave news indeed. We must do everything in our power to stop this war from coming to pass." }
WordHunterWoW_QuestEN[12013] = { title = "End Arcanimus", description = "There is one last thing that I would have you do, {name} the {race}. I would have you destroy Arcanimus!\n\nThe sorcerers to the west used that giant device in the sky to bore a massive pit into our resting place. When they did that, they unleashed a monstrosity!\n\nI would not care if it were only a concern for mortals, but Arcanimus feeds upon the spirits of the dead.\n\nYou will put an end to it now!", objectives = "Destroy Arcanimus and then return to Ethenial Moonshadow at Moonrest Gardens.", progress = "Do you think me a fool? Arcanimus is still eating the souls of my brothers and sisters, <class>!", completion = "You have my deepest gratitude, <name>.\n\nIf you haven't already, you should alert your betters to the danger that the blue dragonflight has unleashed. By blowing apart the ley line anchor underneath the gardens, they threaten to destroy us all!" }
WordHunterWoW_QuestEN[12014] = { title = "Steady as a Rock?", description = "Orlond's notes indicate that he brought a piece of equipment called a portable seismograph with him, but the device is nowhere to be seen.\n\nThe survey log shows that Orlond completed all his readings in the Thor Modan tunnel, save one labeled the 'east end of the exposed tunnel.'\n\nThe last entry in the log indicates Orlond tried to take refuge in the water and was attacked by subterranean threshers. They might've taken his equipment.You'll need to recover it before you can take the last reading.", objectives = "Retrieve the Portable Seismograph and use it to take stability readings in Thor Modan, then return to Brugar Stoneshear at the Westfall Brigade Encampment.", progress = "What did you find?", completion = "<Brugar looks over the report.>\n\nThis isn't good at all. Even if we could excavate the tunnels behind the blockage, there's no guarantee they wouldn't collapse again. It looks like some of these areas haven't been used in generations. We'll have to give Captain Gryan the bad news." }
WordHunterWoW_QuestEN[12015] = { title = "Test Quest for Craig", description = "klajsdklajlsdUpon completion of this quest you will gain:", objectives = "Craig Amai at wherever wants you to bring him 5 whatevers." }
WordHunterWoW_QuestEN[12016] = { title = "The Bait", description = "I'm sure of it... our ancient aquatic nemesis, Tu'u'gwar, \"He Who Plays With Food\", has returned. We must lay a trap for him, you and I.\n\nIf Tu'u'gwar has one weakness it's his stomach. There's one meat for certain that he'd never be able to pass up.\n\n\"Two Huge Pincers\", the mother of all crabs, Kili'ua, paces upon her island out in the waters to the southwest. You must pay her a visit and return with her meat.", objectives = "Obtain The Flesh of \"Two Huge Pincers\" and deliver it to Tua'kea at Moa'ki Harbor.", progress = "You return with the succulent flesh of Kili'ua?", completion = "You were able to slay Kili'ua... perhaps you'll be able to do the same to Tu'u'gwar.\n\nPerhaps not." }
WordHunterWoW_QuestEN[12017] = { title = "Meat on the Hook", description = "The time has come my friend: Tu'u'gwar must be dealt with!\n\nI've prepped the meat so that the beast is sure to come once you bait the hook I have out in the water. Just follow the fishing line here down to it.\n\nWhatever you do, don't let Tu'u'gwar swallow you whole, {name}!", objectives = "Slay Tu'u'gwar and then return to Tua'kea at Moa'ki Harbor.", progress = "I thought I might have spotted some thrashing... is Tu'u'gwar dead?", completion = "We shall rejoice at your success, my young friend! There's blood in the water and it is our enemy's!\n\nYou have the eternal gratitude of this old fisherman, and most certainly of all the Kalu'ak once I spread the word!\n\nHere now, I insist, take something as a reward, please." }
WordHunterWoW_QuestEN[12018] = { title = "Sweet Revenge", description = "You there... you look the fighting type.  I want some sweet Revenge on the Scourge that killed my family.  Go get me 2 Stone Hunks O' Gargoyle so that I can throw them on the ground and stomp on them violently until they are mashed into itty bitty pebbly bits. \n\nYes. Go. Kill.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Obtain 2 Stone Hunks O' Gargoyle from Carrion Gargoyles in the Eastern Carrion Fields. Return to Lord Bevis when the task is complete." }
WordHunterWoW_QuestEN[12019] = { title = "Last Rites", description = "I served Arthas in death, because I had no choice.  He had control over my will and my body.  The Cult of the Damned serves Arthas in life... willingly.\n\nNow that we know the words of power to enter Naxxanar we can put an end to the cultist blight.  Go to En'kilah and look for the teleportation orb beneath the floating citadel.\n\nWork your way up and meet me at the top.  Arm yourself with what courage you can, we might not make it out of this alive.", objectives = "Go to the Temple City of En'kilah and find the teleportation orb beneath the floating Scourge citadel of Naxxanar. Use it to reach the top and help Thassarian there.", progress = "Hail, <name>.", completion = "You did well, <name>.  I was hoping to leave my sister out of all this.  Thanks to you she is alive and well.\n\nMy obligations to my king and my army have been fulfilled.  It is clear I'm not welcome among my comrades anymore.  I will have to find my own way, fighting no wars but my own and following no orders but my heart's.\n\nPerhaps we shall meet again, <class>.  Until then, take this as a token of my gratitude." }
WordHunterWoW_QuestEN[12020] = { title = "This One Time, When I Was Drunk...", description = "The Dark Irons took a beating!  As they rushed back to the Grim Guzzler, a portion of their transport fell off.  More importantly, you managed to keep the camp safe... today.\n\nHead over to Boxey and explain your heroic triumph over the Dark Iron dwarves.", objectives = "Talk to Boxey Boltspinner in the Brewfest camp.", completion = "So you managed to stop the Dark Irons... While drunk too?  That, <class>, is truly the spirit of Brewfest!  I guess in keeping with the spirit of Brewfest you want your prize tokens.\n\nThanks for your help, <name>.  Enjoy the rest of Brewfest." }
WordHunterWoW_QuestEN[12021] = { title = "A Letter Home", description = "This letter appears to be addressed to a resident of Stormwind from one of the late Villagers in the Carrion Fields.  Perhaps one of the surviving residents in the Eastern camp would be interested in forwarding it to its intended recipient.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring the letter home to Lady Alustra in the Eastern Carrion Fields.This letter appears to be addressed to a resident of Stormwind from one of the late Villagers in the Carrion Fields. Perhaps one of the surviving residents in the Eastern camp would be interested in forwarding it to its intended recipient.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[12022] = { title = "Chug and Chuck!", description = "Hey there! You look like you can handle your brew.\n\nBut can you handle your brew mug?\n\nWe like to keep things lively around camp, and nothing says fun like a good old-fashioned mug toss!\n\nThink you've got the aim to hit S.T.O.U.T.? Just grab a sampler, take a sip, and see if you can land a hit. It's trickier than it looks, but that's half the fun. Step right up and give it a shot!", objectives = "Use the Alcohol-Free Brewfest Sampler to hit S.T.O.U.T. 5 times.", progress = "Toss one back, then toss one forward. S.T.O.U.T. can take the abuse, it's why I built him.", completion = "Do you know what that was?  Gnomish engineering at its finest!  S.T.O.U.T. took the abuse like a champ!\n\nI think you're ready now to take on the Dark Irons if they show up again." }
WordHunterWoW_QuestEN[12023] = { title = "Sweeter Revenge", description = "Satisfyingly crunchy.  Now... you... <race> thing... there's an Abomination wandering the hillside to the south.  Go kill it.  Kill it good.You will receive:", objectives = "Kill the Abomination on the hillside in Eastern Carrion Fields. Return to Lord Bevis once the slaughter is complete." }
WordHunterWoW_QuestEN[12024] = { title = "Recording the Fallen", description = "Thank you for coming <name>.  We haven't recieved any word from Wintergarde Keep.  I'm sure they're still battling the Scourge, but I can believe they left us alone to this slaughter.  \n\nWe need to gather the names of the dead so that we can notify their families.  When the Alliance Military brought us here, we all filled out Settlement Documentation and were required to keep it on our persons.  \n\nGo sift through the corpses and bring me any Documents that you find so that I can start a list of the names.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Search the skeletons in the Carrion Fields for Alliance Settlement Documents." }
WordHunterWoW_QuestEN[12025] = { title = "A Scarlet Among Us", description = "It's good to see that you were not ravaged by the Scourge as well.  Perhaps you'd be willing to lend a hand.  \n\nThe Scarlet Crusade has taken up a post to the north with the obvious intent of battling the Scourge.  The thing that bothers me is that they were building before we were attacked - they must have known something.  \n\nI need to know if one of our Villagers was involved.  Search for evidence on those of us that were brought back as ghouls.  If you find anything, bring it to me.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Search for evidence of the Scarlet Crusade on the freshly risen Carrion Ghouls in the Eastern Carrion Fields. Return to Lady Alustra with anything you find." }
WordHunterWoW_QuestEN[12026] = { title = "The Damaged Journal", description = "This battered, mud-stained journal has seen better days. Leafing through the pages, you discover dozens of notes, diagrams, and maps in the dwarven language.\n\nThe only text you're able to decipher is the name of Brann Bronzebeard scrawled at the end of one of the entries.\n\nThe back half of the book, containing the most recent entries, has been torn away. Someone thought the notes important enough to attempt to destroy them. Perhaps gathering the missing pages from the battlefield will yield some clues.", objectives = "Recover 8 Missing Journal Pages, combine them with the Incomplete Journal, and return the completed journal to Sage Paluna at Camp Oneqwah.", progress = "What's that you have there?", completion = "Who is this Brann Bronzebeard? The iron dwarves found no reason to treat with him, but I have no idea why we'd be interested in his writings." }
WordHunterWoW_QuestEN[12027] = { title = "Mr. Floppy's Perilous Adventure", description = "Excuse me, Mister, do you know the way back to the soldiers' camp?\n\nMr. Floppy and I decided to go for a walk in the woods, and my brother Walter was gonna come with us, but then he had squire things to do.\n\nSo Mr. Floppy and I went by ourselves, but we got lost, and there were a whole bunch of hungry wolves, but we found this tower.\n\nThe wolves went away, but we're still lost.\n\nI asked Mr. Floppy, and he doesn't know the way back. Would you help us? Please?", objectives = "Help Emily and Mr. Floppy get back to the Westfall Brigade Encampment, then speak to Squire Walter.", completion = "Thank goodness you found Emmy! When she left without me, I was worried she'd get lost.\n\nI'm glad to see Mr. Floppy's back safe and sound, too." }
WordHunterWoW_QuestEN[12028] = { title = "Spiritual Insight", description = "{race}, we have not heard from our people at Indu'le Village since the ground shook and was torn apart!\n\nHave you ever been upon a vision quest? You've bested Loguhn, so you must be capable.\n\nI will give you a special incense to sprinkle into my brazier. Breathe deep from its vapors and your spirit will be sent aloft to view what has transpired at Indu'le.\n\nAs your spirit soars, I will be able to look through your eyes.", objectives = "Speak with Toalu'u the Mystic at Moa'ki Harbor after you have attained your spiritual insight.", progress = "What do you think?", completion = "Ghosts and gibbering madness? This cannot be!\n\nWe must seek further guidance." }
WordHunterWoW_QuestEN[12029] = { title = "Seared Scourge", description = "<Hic>... gotta burn these corpshes 'fore they shtart walkin' around again.\n\nPoppa always said, only thing worshe than havin' to kill a troll is havin' ta kill a troll twice.\n\nSay,<hic>... shpeakin' of Scourge, we can't get into tha' troll keep up north 'til we get them trolls thinned out a bit.\n\nHow 'bout ya take shome o my grog here and put them bashtards outta their misery?", objectives = "Mack at Granite Springs wants you to use his grog to burn 20 Famished Scourge Trolls at Drak'Tharon.", completion = "Well done!\n\n<Mack laughs hysterically for a moment.>\n\nAww, come on now. That was funny...<hic>." }
WordHunterWoW_QuestEN[12030] = { title = "Elder Mana'loa", description = "My people....\n\n<The mystic is on the verge of breaking down.>\n\nWhile your spirit was flying through the village, I sensed that Elder Mana'loa took notice of you. {name}, he wishes to speak with you. The stone elders are revered by us as fonts of ancient wisdom.\n\nThe elder must want to help. Seek him in the northwest corner of the village.", objectives = "Speak with the statue, Elder Mana'loa, at Indu'le Village.", completion = "I've been expecting you, <race>. I saw your spirit fly by and sensed the mystic watching behind your eyes.\n\nYour fate and that of the Kalu'ak are now tied together." }
WordHunterWoW_QuestEN[12031] = { title = "Freedom for the Lingering", description = "The sacred ground of the elves to the west has been torn asunder. Now their magic is moving through the land causing ruin where it flows.\n\nThe souls of the Kalu'ak are in danger as the blue dragons forces attempt to control the magic.\n\nThe power came up through the lake, instantly slaying most in the village. Those that survived were driven insane.\n\n{name}, you must release these spirits so that they may move on. Leave the deranged living alone; they may yet regain their sanity in time.", objectives = "Put to rest any combination of 15 Indu'le Fishermen, Mystics and Warriors, then return to Elder Mana'loa at Indu'le Village.", progress = "<Elder Mana'loa looks through you, sensing that you have not yet completed his task.>", completion = "Not the most pleasant task, but necessary and merciful.\n\nAnd now there is something else that you are destined to do for the Kalu'ak." }
WordHunterWoW_QuestEN[12032] = { title = "Conversing With the Depths", description = "The watery goddess, Oacha'noa, must be consulted; only she will know what the destiny of the Kalu'ak is to be. And only The Pearl of the Depths can call her forth from the murky nether.\n\nOff the coast to the southwest rises The Briny Pinnacle. Atop it sits the altar upon which the pearl rests.\n\nCommune at the altar and Oacha'noa is certain to hear your call. Do as she says lest you incur her wrath and bring ruin upon all of the tuskarr.\n\nShould you survive, return to the mystic.", objectives = "Commune with The Pearl of the Depths and do as the sea-goddess Oacha'noa instructs.\n\nShould you survive the ordeal, return to Toalu'u the Mystic at Moa'ki Harbor.", completion = "You spoke with Oacha'noa?!\n\nIf it is her will that we stand with your people then so be it. Elder Ko'nani will accept this as our destiny, for weal or woe.\n\nMy people believe that all souls are one with the magic of the world. We must oppose the blue dragon attempts to control the magic or we are all doomed!\n\nI never thought that a <race> would be the champion of the Kalu'ak, but you have proven me wrong. On behalf of my people, I give you thanks, <name>.\n\nMay the gods smile upon you and keep you safe." }
WordHunterWoW_QuestEN[12033] = { title = "Message from the West", description = "<Torvus shakes your hand, giving you a letter in the process.>\n\n<Torvus speaks under his breath.>\n\nJust play along, {name}.\n\nIt is good to see you here, soldier! Lord Hellscream has undoubtedly sent his strongest warriors to Lord Agmar!\n\n<Torvus speaks under his breath.>\n\nRead it and then destroy it in the fire pot next to me.", objectives = "Read the Letter from Saurfang and then destroy it.\n\nSpeak to Messenger Torvus once you have completed this task.", completion = "<Torvus nods at you.>\n\nSo we are understood? I will return to my lord and tell him that you have accepted." }
WordHunterWoW_QuestEN[12034] = { title = "Victory Nears...", description = "There remain only two primary threats that stand in our way. One is the dread citadel of Naxxramas, far to the east, above the Alliance fortress of Wintergarde and the other is the Pit of Narjun, exit point for the undead armies of Azjol'Nerub. It is from the Pit of Narjun that the Anub'ar Nerubians assaulted and ultimately razed the taunka village of Icemist.\n\nWe will destroy the Anub'ar and close off the Pit of Narjun.\n\nReport to Senior Sergeant Juktok for your mission orders.", objectives = "Speak to Senior Sergeant Juktok at Agmar's Hammer.", completion = "By land and by air, that's how we will end the Anub'ar threat." }
WordHunterWoW_QuestEN[12035] = { title = "Repurposed Technology", description = "Ok, I've got it!  The rewiring is a little complicated, but nothing a clever {class} like you can't handle.\n\nTake my tools and put some of the harvest collectors out of commission.  Once they're down use the tools to plug all the red wires into the blue sockets.  That'll make them go into self-defense mode.  Hurry, {name}.  Before long there won't be anything left to save.", objectives = "Jeremiah Hawning at Farshire wants you to destroy 5 Harvest Collectors and then use Jeremiah's Tools to rewire them.", progress = "You done yet, <name>?", completion = "Nice job!  I finally feel useful again... and that's sayin' something." }
WordHunterWoW_QuestEN[12036] = { title = "From the Depths of Azjol-Nerub", description = "The undead Nerubians that attacked Icemist Village came from a gigantic sinkhole known as the Pit of Narjun. If left alone, those fiends will no doubt flank our forces at the Wrathgate and end our march to victory.\n\nI need eyes on the ground, {name}. You are to head west and investigate the Pit of Narjun. We need to locate their primary exit point and seal it off! Find me that location.\n", objectives = "Explore the Pit of Narjun and return with your findings to Senior Sergeant Juktok at Agmar's Hammer.", completion = "That damned sinkhole must be directly connected to Azjol-Nerub. This is worse than I thought.\n\n<Juktok pauses to think for a moment.>\n\nSeek and destroy... That'll be the next course of action." }
WordHunterWoW_QuestEN[12037] = { title = "Search and Rescue", description = "Orcs... they just don't lissen <hic>. Know what I mean, {race}?\n\nKurzel's been with us fer years. You'd think she'd get a feel fer how we do things by now. Lure the fools in fer the dangerous work, then reap the rewards when it's safe. What's so hard to understand?\n\nNot her though... she goes off and takes matters into her own hands. Probably dead by now, but I'd feel horrible if we didn't follow after her, and I'm in no shape to do it myself <hic>.\n\nSo whatdya say, pal?", objectives = "Mack at Granite Springs wants you to go into Drak'Tharon and find out what became of Kurzel.", completion = "I knew it!\n\nEven my going missing wasn't enough to get those spineless weasels to come in here after me.\n\nWell, they sent you. I suppose that's something....\n\nHere, take this. I'd rather it go to you than to those dimwits back at the camp." }
WordHunterWoW_QuestEN[12038] = { title = "Seared Scourge", description = "Whatcha waitin' fer, {class}? Them shcourged trolls ain't gunna kill themselves!\n\nYou know the drill. Git up ta Drak'Tharon up north... Take some o thish here grog and hurl it at 'em from a distance...<hic>.  Then jusht sit back an' watch 'em burn.", objectives = "Mack at Granite Springs wants you to use his grog to burn 30 Famished Scourge Trolls.", completion = "Well done!\n\n<Mack laughs hysterically for a moment.>\n\nAww, come on now. That was funny...hic." }
WordHunterWoW_QuestEN[12039] = { title = "Black Blood of Yogg-Saron", description = "Angrathar, the Wrathgate... I watched as the metal holding the gate together pulsed and undulated as if it were alive! In 50 years I've never seen metal \"breathe.\"\n\nOnly ones who knew anything about it were the tuskarr. They called it the \"Black Blood of Yogg-Saron\" and told me to keep my distance.\n\nThere's a sinkhole outside Icemist Village to the west called the Pit of Narjun. I've heard of these sinkholes being rich with this strange ore. If you head that way, could you try and get me some samples?", objectives = "Borus Ironbender at Agmar's Hammer in the Dragonblight wants you to recover 10 Black Blood of Yogg-Saron Samples.", progress = "What's life without risks?", completion = "It's so light... As if it weighs nothing at all! I'll need time to analyze the metal and see if I can do anything with it! Tests! I need to run tests!\n\nI'll keep in contact, <name>. If anything comes of this, you'll be the first to know." }
WordHunterWoW_QuestEN[12040] = { title = "An Enemy in Arthas", description = "We are in the midst of a civil war. At the heart of this world the last living members of my species defend themselves against total annihilation. The Lich King seeks to rule the kingdom of Azjol-Nerub at any cost. Those that do not acquiesce are branded enemies of the Scourge and marked for death.\n\nIn Arthas we both have an enemy...\n\nJoin our cause and rid this place of the taint of Anub'ar! Let Anub'arak himself hear the anguish of their death cries!", objectives = "Kilix the Unraveler at the Pit of Narjun in the Dragonblight has asked that you slay 6 Anub'ar Underlords.", progress = "The Azjol Empire will rise again!", completion = "There are thousands more and they spill out from every dark crevice in Northrend. Alone you stand no chance, but together... Maybe..." }
WordHunterWoW_QuestEN[12041] = { title = "The Lost Empire", description = "You have proven that you are willing to assist the Azjol Empire in its time of need and as such the Azjol Empire will assist the Horde.\n\nTake this scroll back to your leader. It documents the strengths and weaknesses of the Nerubians attacking Icemist Village. Consider it a gesture of good faith - a willingness to help your people. Use the knowledge on those pages to crush the Anub'ar and you will have done a service for us all.\n\nFarewell, {race}.\n", objectives = "Deliver Kilix's Battle Plan to Overlord Agmar at Agmar's Hammer to the east.", progress = "What have you got there?", completion = "<Overlord Agmar looks over the document.>\n\nIs this what I think it is? With the information contained within these pages we will CRUSH the Anub'ar assault!\n\nYou have done well to bring this document to me, <name>. Perhaps you will be allowed to watch or even participate in the final battle at Angrathar! LOK'TAR!" }
WordHunterWoW_QuestEN[12042] = { title = "Heart of the Ancients", description = "Secrets of da ages, be revealed to me now!\n\n<Drakuru peers through the Eye of the Prophets.>\n\nAhh, great be mah destiny, {name}. You be lucky ta know me....\n\nThere! I be seein' it, mon. The Heart of the Ancients. Dis be too easy!\n\nYou gunna find da heart lyin' near da corpse of a goblin east of here. He be up in a chamber, near a river of broken trees.\n\nHurry, mon, before someone else be findin' it!", objectives = "Drakuru wants you to go to the uppermost chamber at Blue Sky Logging Ground and find the Heart of the Ancients.", completion = "This unfortunate goblin must have unearthed the Heart of the Ancients during his excavations in the region.\n\nIt's doubtless that he had no clue as to its nature.\n\nYou determine that it must have been overlooked in the chaos sweeping through the area." }
WordHunterWoW_QuestEN[12043] = { title = "Nozzlerust Defense", description = "You, {class}!  These undead south of us are being a constant nuisance to our work.  Go clear them out, will ya?", objectives = "Kill 12 Wastes Diggers and 1 Wastes Taskmaster at the digs surrounding Galakrond's Rest. Return to Narf at Nozzlerust Post when the task is complete.", completion = "Oh!  Yeah, the undead.  Here's your coin, bugger off." }
WordHunterWoW_QuestEN[12044] = { title = "Stocking Up", description = "Hello hello!  The Scourge to the south are digging up some ancient dragon thing.  I could care less why they're doing it, but they're pulling cartloads of composite ore in the process.\n\nGo lift me a bunch of that ore.  That stuff should yield a pretty penny for all the weapons the Horde are crafting.\n", objectives = "Gather 8 bundles of Composite Ore from the digs surrounding Galakrond's Rest and bring them to Xink at Nozzlerust Post.", progress = "Did you get the ore?  My carrier will be back shortly - we need to get this shipment out while the fight's still going!", completion = "Hah!  That's quite a load!  Your back feeling alright?" }
WordHunterWoW_QuestEN[12045] = { title = "Shaved Ice", description = "I've never seen you before... are you new to the Vice?  Glad to have you.  I could always use some more hands.\n\nYou get the materials, I'll finish my machine, then we can sell it to those commander types and all go home rich.\n\nI actually have most of the primary components, so I just need some of the materials for the weapon itself.  Narf said that jagged ice shards from those elementals to the north would make perfect shrapnel for my bombs - go nab some, will ya?\n", objectives = "Collect 4 Ice Shard Clusters from Ice Elementals in the north and bring them to Zivlix at Nozzlerust Post.", progress = "Do you have the shards?  I'm almost finished with the main refrigeration unit.", completion = "Excellent!  They're even sharper than I expected them to be.  I'll pack them in the snow until the bomb is ready.\n\nLet's see... what next..." }
WordHunterWoW_QuestEN[12046] = { title = "Soft Packaging", description = "I need some new packaging for the shrapnel bombs.  All the stuff I have is too hard and the shrapnel doesn't spread when it bursts.  \n\nWhat we need is some really thin animal hide.  Those jormungar tunnelers to the west might work... or perhaps the condors sifting through the dragon bones.  Go get me whatever you can find.\n", objectives = "Collect 12 Thin Animal Hides from the Jormungar Tunnelers or the Dragonbone Condors near Nozzlerust Post. Once you've located the hides, return them to Zivlix.", progress = "How goes the hunt?  Do you have my hides?", completion = "Good... good... these should do fine.  The shrapnel bombs are almost finished. \n\nWait... what happened to my ice shards?  Narf told me shards from those elementals should be enchanted, but they're melting just like the ones hanging from Narf's grumpy chin!" }
WordHunterWoW_QuestEN[12047] = { title = "Something That Doesn't Melt", description = "No no no! Those ice shards didn't work at all! They'll melt before they even do any damage. That's the last time I'll trust Narf's word on materials. This means we need something else entirely for the shrapnel.\n\nI know! I'm brilliant. Bone splinters.\n\nThere are some bones all around here that the jormungar have been gnawing on pretty thoroughly. Go check them out and see if you can find me some splintered bone that I can use.", objectives = "Search the dragon bones east of Nozzlerust Post for 12 Splintered Bone Chunks.", progress = "Were there any splinters to be found?", completion = "Excellent!  That should be the last thing I need to test out the new bombs.  Just a moment and I'll try this out!" }
WordHunterWoW_QuestEN[12048] = { title = "Scourge Armaments", description = "I can't make a damned thing out of this ore. It simply will not hold together! Despite my best efforts the Scourge metal will not bend!\n\nPerhaps if I had some samples of some forged Scourge armaments I might be able to reverse engineer the process by which the items are created.\n\nIcemist Village is crawling with armored Scourge Nerubians. Go there and get me some Scourge armaments! With your help I might actually succeed in creating something from this ore.\n\nYou'll find Icemist to the west.", objectives = "Borus Ironbender at Agmar's Hammer in the Dragonblight wants you to bring him 8 Scourge Armaments.", progress = "<Borus throws his tools down.>\n\nThese are useless!", completion = "These are in excellent condition, <name>. I'll get to work right away. If anything comes of this, you will be the first to know!" }
WordHunterWoW_QuestEN[12049] = { title = "Hard to Swallow", description = "Those troops are sure to be needin' a hefty supply of food in their bellies.\n\nI'll let you in on a little secret that a squeamish {race} like you would never know... those jormungar worms taste just like chicken.\n\nGo provoke one of those giant hulking jormungar to the east.  You're not likely to be able to kill one straight out, so just toss this down its throat when it opens its mouth wide.  Bring me back as many of the slabs of meat as you can tote.", objectives = "Battle a Hulking Jormungar east of Nozzlerust Post until it opens its mouth, then throw a Potent Explosive Charge into its throat. After it explodes, collect 6 slabs of Seared Jormungar Meat off of the ground and bring them back to Xink.", progress = "Did ya get it all?  You certainly stink of it.", completion = "Ha ha!  One of those meat slabs landed clear over here!  Nice work there!" }
WordHunterWoW_QuestEN[12050] = { title = "Lumber Hack", description = "Next up, we need to haul in some lumber for all the towers the Alliance are building.  There are some thin trees to the south, but the trees the harpies are nesting in to the north look much more fit for structures.\n\nTake this.  When you get to the harpy nesting area, use the control and one of my Shredders should come to you.  Gather as much lumber as it can carry.  The harpies are sure to disagree with you chopping down their homes - just deal with them as necessary.\n\nHop to it!", objectives = "Use Xink's Shredder Control Device to call a Shredder once you reach the Harpy Nesting Grounds in the North. Gather 50 Bundles of Lumber from the trees in the area, and then return to Xink at Nozzlerust Post.\n\nShould you lose Xink's Shredder Control Device, speak to Xink at Nozzlerust Post to obtain a new one.", progress = "Where's that carrier?  Hope the Jormungar didn't get him.  He was carrying a good sized load that time.", completion = "If a tree falls in the forest, and you can't hear it through the saw blade, does it really make a sound?" }
WordHunterWoW_QuestEN[12051] = { title = "Rustling Some Feathers", description = "Those harpies have slowed our profits long enough!  Kill them all.", objectives = "Kill 20 Harpies Northwest of Nozzlerust Post for Narf at Nozzlerust Post." }
WordHunterWoW_QuestEN[12052] = { title = "Harp on This!", description = "{class}, did you see that? That's the harpy that's been leading the attack on our shipments to the gate! I've seen her in the back of Coldwind Heights before.\n\n Those harpies have slowed our profits long enough! Kill them all.", objectives = "Kill the Mistress of the Coldwind and 15 Coldwind harpies in the mountains northwest of Nozzlerust Post. Return to Narf once the task is complete.\n\nShould you be in need of Xink's Shredder Control Device, speak to Xink at Nozzlerust Post.", completion = "That should make those uglies think twice.  Here... take your reward and get away with ya." }
WordHunterWoW_QuestEN[12053] = { title = "The Might of the Horde", description = "The taunka are now our brothers in arms. We must show our solidarity and retake Icemist Village.\n\nYou will find Icemist Village west of Agmar's Hammer, sitting at the foot of the mountains. Travel there and challenge the Anub'ar Nerubians! Plant our beloved Horde banner at Icemist Village and destroy all that dare come to tear it down!\n\nLet the Anub'ar feel the true might of the Horde! Let our battle standard be the last thing that they see before death!", objectives = "Senior Sergeant Juktok at Agmar's Hammer in the Dragonblight wants you to use the Warsong Battle Standard at Icemist Village and defend it against attackers.\n\nReturn the Warsong Battle Standard when you are finished.", progress = "It is a challenge, <name>!", completion = "We have crushed them by land! Soon we will crush them by air!" }
WordHunterWoW_QuestEN[12054] = { title = "Deciphering the Journal", description = "Vor'takh is right -- we cannot allow this opportunity to slip through our fingers.\n\nFortunately, I think I know of a way to translate the journal of this Brann.\n\nThe shamans of the Redfang furbolgs, who congregate at the Heart's Blood Shrine south of the camp, grow an herb known as spiritsbreath. An experienced mystic can use incense made from it to seek wisdom from the spirits of the ancestors.\n\nSeek out the shaman known as Grumbald One-Eye. He should carry the herb for his devotions to Ursoc.", objectives = "Bring a sprig of Spiritsbreath to Sage Paluna at Camp Oneqwah.", progress = "Have you brought sufficient quantities of the herb?", completion = "Well done, <name>. I'll prepare the incense and then we'll see what exactly this royal dwarf was doing so far from home." }
WordHunterWoW_QuestEN[12055] = { title = "A Strange Device", description = "Picking up this strange device, you are certain that it is magical in nature. Unfortunately, it doesn't seem to connote any other kind of use.\n\nPerhaps the archmage back at Stars' Rest to the east of the Moonrest Gardens would be able to tell what it's used for?", objectives = "Deliver Goramosh's Strange Device to the Image of Archmage Modera at Stars' Rest.", progress = "What do you have there?", completion = "<name>, if I'm not mistaken, you've uncovered the key to allow us to discern exactly what the mage hunter forces are up to!" }
WordHunterWoW_QuestEN[12056] = { title = "Marked for Death: High Cultist Zangus", description = "I witnessed his treachery with my own eyes! The traitor led an Anub'ar assault on this stronghold, taking out some of my best soldiers.\n\n<Gort shakes his head.>\n\nHe'd been working with the Scourge the whole time and we didn't have a clue! How many more like Zangus are there? We'll find 'em all and when we do...\n\n<Gort makes a cutting motion across his neck.>\n\nFirst on the list is Zangus. Our scouts report that he is hiding in The Pit of Narjun, west of here. Find him, kill him, bring me his head.\n", objectives = "Kill High Cultist Zangus and return High Cultist Zangus's Head to Captain Gort at Agmar's Hammer in the Dragonblight.", progress = "Is that a severed orc head in your pack or are you just happy to see me?", completion = "<Gort holds the head up and stares into its dead eyes.>\n\nI told you we'd get you...\n\nHere's your reward, <class>. That's one less headache for us to worry about." }
WordHunterWoW_QuestEN[12057] = { title = "The Flesh-Bound Tome", description = "The tome is bound in flesh and appears to be bleeding. Upon examination you discover page after page filled with strange symbols that appear to be written in blood.\n\nWhatever knowledge is held within the pages of this tome could be important. Return it to Captain Gort at Agmar's Hammer, east of Icemist Village.", objectives = "Return the Flesh-bound Tome to Captain Gort at Agmar's Hammer.", progress = "<Gort raises an eyebrow.>", completion = "<Gort takes the tome from you.>\n\nSavages... Bound in orc flesh... This language... Its existence has never been proven. It is the language of death... The tongue of the Scourge." }
WordHunterWoW_QuestEN[12058] = { title = "The Runic Prophecies", description = "Brann's journal also contained a guide to iron dwarf symbols. I've inscribed these on a keystone which will help you to understand the words inscribed on the rune plates.\n\nFrom the journal entries, it seems Brann may be chasing after clues to the origins of his people. Keep your eyes open for any clues as to his destination.\n\nReturn to Thor Modan, northeast of here, stand before each of the plates, and use the stone to determine the contents of each. We can't allow the Alliance to find him first.", objectives = "Sage Paluna at Camp Oneqwah wants you to decipher the three Rune Plates.", completion = "<Sage Paluna listens as you recall the translations of the plates.>\n\nSo Brann thinks he's discovered a new titan city?\n\n'The cradle of stone and iron.'\n\n'Ulduar nestled in the storm.'\n\nI will ask the chieftain to dispatch longrunners to the Storm Peaks. My people know these lands well and have the best chance of tracking down this wayward dwarf." }
WordHunterWoW_QuestEN[12059] = { title = "A Strange Device", description = "Picking up this strange device, you are certain that it is magical in nature. Unfortunately, it doesn't seem to connote any other kind of use.\n\nPerhaps the archmage back at Agmar's Hammer to the northeast of the Moonrest Gardens would be able to tell what it's used for?", objectives = "Deliver Goramosh's Strange Device to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", progress = "What do you have there?", completion = "<name>, if I'm not mistaken, you've uncovered the key to allow us to discern exactly what the mage hunter forces are up to!" }
WordHunterWoW_QuestEN[12060] = { title = "Projections and Plans", description = "This is a teleportation device. If I had to guess, I'd say that it leads to the surge needle platform floating above the Moonrest Gardens to the west.\n\nI need you to use it to investigate what's up there. It appears that the device works both ways so you shouldn't have to jump off.\n\nI expect that once you teleport to the top of the surge needle, there will be some sort of apparatus on it to observe.\n\nYou should be able to use the teleporter from anywhere within the gardens.", objectives = "Get close to and observe the projection atop the Surge Needle floating above Moonrest Gardens.\n\nAfterward, return to the Image of Archmage Modera at Stars' Rest with the information.", progress = "Back so soon?", completion = "What you're describing... that's a projection of the Arcanomicon!\n\n<The archmage's show of concern is quickly masked behind an impassive countenance.>\n\nThe Arcanomicon is a map of all of the magical ley line intersections in the world. The blue dragonflight has been using it to find and destroy ley line 'anchors' to send the magical power back to the Nexus.\n\nThe question is, why is the path of destruction leading east when it should be heading west instead?" }
WordHunterWoW_QuestEN[12061] = { title = "Projections and Plans", description = "This is a teleportation device. If I had to guess, I'd say that it leads to the surge needle platform floating above the Moonrest Gardens to the southwest.\n\n{name}, I need you to use it to investigate what's up there. It appears that the device works both ways so you shouldn't have to jump off.\n\nI expect that once you teleport up to the top of the surge needle, there will be some sort of apparatus on it to observe.\n\nYou should be able to use the teleporter from anywhere within the gardens.", objectives = "Get close to and observe the projection atop the Surge Needle floating above Moonrest Gardens.\n\nAfterward, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer with the information.", completion = "What you're describing... that's a projection of the Arcanomicon!\n\n<The archmage's show of concern is quickly masked behind an impassive countenance.>\n\nThe Arcanomicon is a map of all of the magical ley line intersections in the world. The blue dragonflight has been using it to find and destroy ley line 'anchors' to send the magical power back to the Nexus.\n\nThe question is, why is the path of destruction leading east when it should be heading west instead?" }
WordHunterWoW_QuestEN[12062] = { title = "Insult Coren Direbrew", description = "Coren Direbrew is in the next room, riling up Dark Iron dwarves for another attack on Brewfest.  Defeat him!\n\nGo to Coren and pick a fight.  Tell him his beer isn't fit for pigs.\n\nWhen you do that, be ready for a fight.  The last person who insulted his brew... was fed to dire boars.", objectives = "Speak with Coren Direbrew." }
WordHunterWoW_QuestEN[12063] = { title = "Strength of Icemist", description = "<Greatmother Icemist bows.>\n\nIt is an honor to meet you, hero. It is because of your actions that many of us are here now, alive and ready for battle against the Scourge.\n\nYou have done so much for us that it shames me to ask you for your assistance once more. Despite my pleas, my only son, Banthok, left here to go in search of his father, High Chief Icemist. He was last seen heading west, towards Icemist Village. Please find Banthok. I do not know what I would do if I lost my son.", objectives = "Find Banthok Icemist at Icemist Village.", completion = "My father still lives! We must save him! I cannot do it alone, <race>. You must help me!" }
WordHunterWoW_QuestEN[12064] = { title = "Chains of the Anub'ar", description = "They have my father bound by magical chains in the middle of Icemist Village. From what I have been able to gather, the prison is controlled by three powerful Anub'ar magi - each holding a piece of the key.\n\nScour Icemist and locate the magi. Kill them and take their key fragments. With all three pieces we might be able to free my father. Once he is free...\n\nRetribution will come swiftly.", objectives = "Banthok Icemist at Icemist Village in the Dragonblight has asked that you bring him Anok'ra's Key Fragment, Tivax's Key Fragment and Sinok's Key Fragment.", progress = "Bring me those key fragments!", completion = "Yes, this will work.\n\n<Banthok expertly manipulates the key fragments.>\n\nHere it is, <class>. With this key, my father will be freed of the Anub'ar prison." }
WordHunterWoW_QuestEN[12065] = { title = "The Focus on the Beach", description = "The mage hunter forces are active on the Glittering Strand to the south of Moonrest Gardens. My guess is that you'll find a heavily guarded focus on the beach and a captain who is in charge of it.\n\nNo doubt the captain will have some sort of controlling device on their person. Get the controller and use it on the focus.\n\nWith any luck, we'll be able to get some more information about what they're really up to out there.", objectives = "Obtain the Ley Line Focus Control Ring and use it to gain information from the Ley Line Focus on the Glittering Strand.\n\nThen, return to the Image of Archmage Modera at Stars' Rest.", completion = "How very odd that it imprinted this information upon you magically.\n\nSo, not only do we know that they've redirected the flow of the power coming out of the Moonrest Gardens, but we now know that the power is being purposefully changed in some way. Just what are they up to with all of that magic?\n\nI don't like where this is leading, <name>, not one bit!" }
WordHunterWoW_QuestEN[12066] = { title = "The Focus on the Beach", description = "The mage hunter forces are active on the Glittering Strand to the south of Moonrest Gardens. My guess is that you'll find a heavily guarded focus on the beach and a captain who is in charge of it.\n\nNo doubt the captain of the force down there will have some sort of controlling device on their person. Get the controller and use it on the focus.\n\nWith any skill on your part, we'll be able to get some more information about what they're really up to out there.", objectives = "Obtain the Ley Line Focus Control Ring and use it to gain information from the Ley Line Focus on the Glittering Strand.\n\nThen, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", completion = "How very odd that it imprinted this information upon you magically.\n\nSo, not only do we know that they've redirected the flow of the power coming out of the Moonrest Gardens, but we now know that the power is being purposefully changed in some way. Just what are they up to with all of that magic?\n\nI don't like where this is leading, <name>." }
WordHunterWoW_QuestEN[12067] = { title = "A Letter for Home", description = "You find a letter secreted in the lining of her robes. It reads:\n\n\"Father,\n\nI'm sorry for disappearing on you. If you're reading this letter, then I'm dead.\n\nI've been forced to work for Malygos's armies under threat that our family would be killed if I didn't. I feel so ashamed.\n\nIf there's anything that you can do to fight them, don't worry about me. I have them fooled and I'm sabotaging them from the inside.\n\nI love you, Daddy!\n\nEm\"\n\nCommander Saia Azuresteel will want to see this!", objectives = "Deliver Captain Malin's Letter to Commander Saia Azuresteel at Stars' Rest.", progress = "A letter for me?\n\n<The commander studies your face a moment.>\n\nI suppose not... must be bad news.", completion = "Oh no... and we sent you down there to kill her, didn't we?\n\n<The commander shakes her head and sighs.>\n\nI'm sorry. I'll see to it that the letter is delivered to her father, Archmage Malin in Stormwind, right away. Don't worry, you won't be implicated... it wasn't your fault.\n\nTry to put it out of your mind. There was no way that you could have known, <name>." }
WordHunterWoW_QuestEN[12068] = { title = "Voices From the Dust", description = "<Drakuru places the Eye of the Prophets on his brow and the Heart of the Ancients on his chest.>\n\nWe be close, mon, very close!\n\nThe Drakkari Tablets be all dat remain ta be found. Nobody be knowin' how old dey be or what dey be sayin', but with the eye and the heart Drakuru can be readin' dem. Dey lie deep inside the crypt at Drakil'jin, due east of here.\n\nOnce ya got the tablets, get sacred mojo from the oracles and protectors so ya can summon me there. They'd be proud to be dyin' for such a cause.", objectives = "Drakuru wants you to collect the Drakkari Tablets from the Ruins of Drakil'jin and 5 Sacred Mojo from Drakkari Oracles and Protectors there. You are then to use Drakuru's Elixir at Drakuru's Brazier at the ruins to summon his image.", progress = "Good to be seein' ya, <name>.\n\nYou find da tablets?", completion = "We've done it, <name>!\n\nWe have all of the components we need to perform the cleansing ritual." }
WordHunterWoW_QuestEN[12069] = { title = "Return of the High Chief", description = "<Banthok hands you the prison key.>\n\nYou must hurry, {name}. Take the key and use it to unchain my father from the Anub'ar prison. Once he is freed, assist him in destroying the Anub'ar leader, Under-king Anub'et'kan. When the Under-king is defeated, take from his chitinous carapace a fragment as a trophy to present to the Horde at Agmar's Hammer. Let Agmar see the might of the High Chief!", objectives = "Free High Chief Icemist using the Anub'ar Prison Key and assist him in defeating Under-king Anub'et'kan.\n\nRecover a Fragment of Anub'et'kan's Husk and return it to Overlord Agmar at Agmar's Hammer in the Dragonblight.", progress = "What is it, <name>? I am extremely busy.", completion = "You are a brave <class>, <name>. You've done the Horde a great service by rescuing the High Chief." }
WordHunterWoW_QuestEN[12070] = { title = "Rallying the Troops", description = "The sons of iron have used their runes to enthrall many of my brothers and are using them to break the siege on Thor Modan. I wish we did not have to fight them, but we have no choice.\n\nMy giants will not hold out long against them.\n\nI have imbued this earthen shard with a blessing that will aid our allies. Take it with you to the battle in the Boulder Hills to the north, and use it to reassure and fortify my brethren.\n\nKill any iron dwarves who would stand in your way.", objectives = "Use the Shard of the Earth to rally the Grizzly Hills Giants fighting in the Boulder Hills, kill any iron dwarves who oppose you, then report to Kurun on the hill overlooking Thor Modan.", progress = "Have you conveyed my blessing upon the giants?", completion = "You have given our allies the strength to fight on, and for that you have my thanks. Even so, we must begin planning a way to end this battle before we are overrun." }
WordHunterWoW_QuestEN[12071] = { title = "Attack by Air!", description = "They have seen the might of the Horde by land, now they must feel it from the air! I want you to report to Valnok Windrager at once! You will find him here, in Agmar's Hammer.\n\nValnok has already been briefed on your mission and is expecting you.\n", objectives = "Speak with Valnok Windrager at Agmar's Hammer.", completion = "<Valnok salutes.>\n\nSo you're the hot shot, eh?" }
WordHunterWoW_QuestEN[12072] = { title = "Blightbeasts be Damned!", description = "You've no doubt seen the army of Anub'ar blightbeasts that are being constructed at Icemist Village. The Anub'ar have plans to send those monsters against our soldiers at the Wrathgate. This cannot happen!\n\nVenture west to Icemist Village with this flare gun and use it to call down one of my war riders. Climb on its back and command it to destroy the blightbeasts that are out of reach from the ground!\n\nOnce you have decimated their aerial forces, return to me for your reward!", objectives = "Use Valnok's Flare Gun to call down a Kor'kron War Rider at Icemist Village. Mount the Kor'kron War Rider and then use it to kill 25 Anub'ar Blightbeasts!\n\nReturn to Valnok Windrager at Agmar's Hammer should you complete this mission.", progress = "Do note that the war riders are trained to only fight inside Icemist. Try to take them elsewhere and they will buck you off.", completion = "<Valnok salutes.>\n\nAnd now they have been crushed by air! Perhaps soon you will be called to Angrathar, hero!" }
WordHunterWoW_QuestEN[12073] = { title = "Pounding the Iron", description = "The Alliance isn't the only force opposing us in Grizzly Hills. The iron dwarves have firm control of the eastern coast, although Thor Modan, to the northeast, is besieged by stone giants.\n\nA skilled warrior uses an enemy's weakness against him and we would be fools to ignore the vulnerability of the iron dwarves at Thor Modan. Show the iron dwarves no mercy. Slay any and all who would stand in your way.\n\nThe 'sons of iron' will learn to fear the Horde.", objectives = "Kill any 10 Iron Dwarves defending Thor Modan and report back to Scout Vor'takh at Camp Oneqwah.", completion = "<Scout Vor'takh smiles.>\n\nThor Modan is on the verge of collapse, then?\n\nVery well. We will soon turn our attention to Dun Argol." }
WordHunterWoW_QuestEN[12074] = { title = "An Expedient Ally", description = "The old iron dwarf capital of Thor Modan, far to the northeast, is under siege by a mysterious band of stone giants and earthen.\n\nWhy the creations of the titans would war against each other is beyond my understanding and the Horde's interest, but there is an opportunity here to weaken a mutual enemy.\n\nTravel to Thor Modan and seek out this 'Kurun' who commands the giants and earthen. Make common cause with him and use his forces to crush the iron dwarves.", objectives = "Speak with Kurun on the hill overlooking Thor Modan.", completion = "<You introduce yourself to Kurun.>\n\nSo the sons of iron are your enemies as well?\n\nMy forces have the iron dwarves pinned inside their city, but we could use help in pressing the attack. Will you aid us?" }
WordHunterWoW_QuestEN[12075] = { title = "Slim Pickings", description = "Cold out here, isn't it, {race}?\n\nKo'char has refused to meet with me. It seems he has more pressing things on his mind - namely, the jormungar that have been attacking them from the cavern below. Maybe you can help me convince Ko'char that I'm one of the good guys.\n\nI saw a giant being eaten by some of the worms at the entrance to the cavern north of here... I'm still puzzled as to how the worms are killing them so easily. Bring me a sample from one of his wounds.", objectives = "Collect a sample of Rockflesh from the Ice Giant corpse at the cavern entrance in the Crystal Vice, north of Zort's location. After this task is complete, return to Zort near the center of the canyon.", progress = "You've returned with my sample then? I'm glad the cold didn't claim you.", completion = "This is perfect.  Thank you, <class>." }
WordHunterWoW_QuestEN[12076] = { title = "Messy Business", description = "Even at first glance, the sample you brought me shows obvious signs of some kind of corrosive spit. It would be a natural assumption that the same substance these worms use to burrow through the ground has allowed them a formidable weapon against the Ice Giants.\n\nTake this scraper and pick a fight with some of the worms. When they spit on you, use the scraper to remove it and bring it back to me.\n\nGet me a couple samples - I'm going to have to use it as the base for an elixir.", objectives = "Collect 2 Vials of Corrosive Spit from the Jormungar by using the scraper on yourself. Bring the vials back to Zort in the Crystal Vice when your task is complete.", progress = "You seem to still have some spit on your shoulder there, <race>. Be careful or it will burn right through your armor.", completion = "Still fresh.  Just a moment and I will mix this with the rest of the elixir that I have prepared." }
WordHunterWoW_QuestEN[12077] = { title = "Apply This Twice A Day", description = "This elixir should protect against their spit. Offer it to Ko'char for me, will you? Tell him there's plenty more where that came from if he'll return the favor.", objectives = "Offer the elixir that Zort has prepared to Ko'char the Unbreakable.", progress = "The runt wants us to fight for him I assume. This is my surprise face.", completion = "I will be blunt little one - I do not trust this mixture, and I will not use it. Keep it... if you find more trust in the green runt than I do, perhaps it will be of use to you." }
WordHunterWoW_QuestEN[12078] = { title = "Worm Wrangler", description = "So be it. If the giants will not come to our aid, perhaps we can make use of these worms. There are sure to be some spawn with their brood mother in the cavern below. Take this box and capture 3 of their spawn and bring them to me.\n\nWhere diplomacy fails, enslaving is a perfectly viable alternative.", objectives = "Enter the caverns in Crystal Vice and trap 3 Jormungar Spawn inside sturdy crates. Be sure to pick the crates up after the Jormungar Spawn are trapped inside!\n\nBring the captured Jormungar Spawn back to Zort in the Crystal Vice.", progress = "You've returned! Do you have the beasts? I need to get out of here... I'm pretty sure Ko'char tried to step on me a few minutes ago.", completion = "These will do nicely. Perhaps after I grow these beasts to full size, I will bring them back and introduce them to the giants personally.\n\nBunch of useless rocks if you ask me." }
WordHunterWoW_QuestEN[12079] = { title = "Stomping Grounds", description = "Greetings little one.  I know not what madness has brought you to the Crystal Vice, but you are welcome in my presence.  \n\nThese ice worms... these jormungar have taken a taste to eating my brothers.  I doubt you will find my kind friendly by any terms during this time of battle, but if you are here to help with the worms, then you have my ear.\n\nIf we are to take the cavern back, we must first clear the canyon of these jormungar feeders.  Join us in battle, {race}!", objectives = "Delve into the cavern at the north end of the Crystal Vice and kill 8 Ice Heart Jormungar Feeders for Ko'char the Unbreakable.", progress = "The battle persists, come with good news or leave me, little one.", completion = "A satisfying display of slaughter." }
WordHunterWoW_QuestEN[12080] = { title = "Really Big Worm", description = "The jormungar have a spawnmother in the caverns below. We call her Rattlebore - a name that was gifted to her by an adventurer from the Plaguelands. I saw her only briefly as I was fighting off their initial onslaught - she is large enough to devour one of my young whole. This cavern will not be ours until she is removed from it.", objectives = "Enter the Ice Heart Cavern and slay Rattlebore. If it is still in your possession, be sure to use Zort's Protective Elixir to protect you from the Jormungar's corrosive spit.\n\nReturn to Ko'char the Unbreakable in the Crystal Vice when the task is complete.", completion = "So she is dead. As it should be. Your intentions do indeed prove nobler than those of the runt.\n\nThrough the north canyon you will find Crystal Song Woods.  It is a cursed and dangerous place, <race>. Should that be your next destination, proceed with caution. \n\nTake this for your efforts, little one, and leave this conflicted land with my blessing." }
WordHunterWoW_QuestEN[12081] = { title = "Gavrock", description = "Without your help, we wouldn't have been able to turn the tide of the battle for Thor Modan. This ancient city has long been a battlefield between the forces of earth and stone. I can only hope we have silenced it for the last time.\n\nThe iron dwarves can still use their magic to capture and enslave my brothers. Gavrock is searching for a way to free the runed giants. Look for him on a small cluster of islands, called the Ruins of Tethys, off the central part of the Eastwind Shore to the south.", objectives = "Speak with Gavrock at the Ruins of Tethys.", completion = "I know Kurun is glad for your help. The defeat of Thor Modan will be a great achievement for us, but it will not free our brothers." }
WordHunterWoW_QuestEN[12082] = { title = "Dun-da-Dun-tah!", description = "Listen, kid. This is no place for you to be playin' around.\n\nI'm about to make a break for it. Stick with me and I'll get you outta here.", objectives = "Escort Harrison from Drakil'jin Ruins, then speak with Harkor at Harkor's Camp.", completion = "So, yah survived a little adventure with our good friend, did yah?\n\nThat should be reward enough in itself, but here - I'm feelin' generous." }
WordHunterWoW_QuestEN[12083] = { title = "Atop the Woodlands", description = "I'm convinced that there must be more of those foci, each of them in-turn redirecting the ley line energies. We still don't know precisely what they're doing with all of that power, though.\n\nMy guess is that you'll find another one atop the Lothalor Woodlands to the southeast. Once again you'll need to find the person in charge and take whatever controlling device they have in their possession as I'm sure that each focus has its own.\n\nBe careful, {name}, those woods are very dangerous.", objectives = "Obtain the Ley Line Focus Control Amulet and use it to gain information from the Ley Line Focus in the Lothalor Woodlands.\n\nThen, return to the Image of Archmage Modera at Stars' Rest.", progress = "What did you find up in the woods?", completion = "They're empowering their forces with it? That doesn't make any sense; the mage hunters aren't that powerful.\n\nThis must mean that they're only using the magic at the terminus of wherever they've redirected the ley line to.\n\nWe're going to need more information if we're to have a chance at finding and stopping them!" }
WordHunterWoW_QuestEN[12084] = { title = "Atop the Woodlands", description = "I'm convinced that there must be more of those foci, each of them in-turn redirecting the ley line energies. We still don't know precisely what they're doing with all of that power, though.\n\nMy guess is that you'll find another one atop the Lothalor Woodlands to the south. Once again you'll need to find the person in charge and take whatever controlling device they have in their possession as I'm sure that each focus has its own.\n\nBe quick about your business, {class}. I feel that time may be running out.", objectives = "Obtain the Ley Line Focus Control Amulet and use it to gain information from the Ley Line Focus in the Lothalor Woodlands.\n\nThen, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", completion = "They're empowering their forces with it? That doesn't make any sense at all; the mage hunters aren't that powerful!\n\nThis must mean that they're only using the magic at the terminus of wherever they've redirected the ley line to.\n\nWe're going to need more information if I'm to devise a plan to stop them!" }
WordHunterWoW_QuestEN[12085] = { title = "A Letter for Home", description = "You find a letter secreted in the lining of his robes. It reads:\n\n\"Deino,\n\nTa'zinni sorry for disappearing on ya. If you're reading this letter, then I be dead.\n\nI been forced to work for Malygos's armies under threat that the family would be killed if I didn't. Ta'zinni wasn't gonna let that happen!\n\nDon't worry about me, just keep your kids safe. I have them fooled and I'm sabotaging them from the inside.\n\nI love you, sistah!\n\nTa'zinni\"\n\nOverlord Agmar is sure to want to see this!", objectives = "Deliver Lieutenant Ta'zinni's Letter to Overlord Agmar at Agmar's Hammer.", progress = "What's this? You think you're going to mail a letter?\n\nAll mail goes through me first. There are spies and traitors amongst us!\n\n<The overlord gives you the once over and you wonder if he's going to have you killed on the spot.>\n\nVery well, be quick about it. But if I don't like what I read, I'm going to feed you to my worgs.\n\n<Agmar grins as both Gar'mak and Lak'tuk turn and look at you like you're their next meal.>", completion = "Ahahahaha... boo hoo, how touching.\n\n<The condescension in the overlord's deep-throated laughter is palpable.>\n\nWhat did I say? Traitors! Still, I knew Deino once upon a time. She at least is a troll with honor!\n\nI'll see to it that she finds out what happened to her brother. I'll even forget to tell her that you're the one that killed him.\n\n<Agmar fixes you with a calculated stare.>\n\nBut I own you now, <class>!" }
WordHunterWoW_QuestEN[12086] = { title = "The Son of Karkut", description = "The man you seek went far to the east, to a place near the coast called Death's Stand, beyond Unu'pe.\n\nBe careful if you go in search of him, {name}.  He bore the mark of Karkut... he who watches over the dead.", objectives = "Go east to Death's Stand, just beyond Unu'pe.", completion = "Thassarian?  Yeah he was here... what of it?  We have more pressing problems right now, my friend." }
WordHunterWoW_QuestEN[12087] = { title = "A Little Help Here? DEPRECATED", description = "We were sent here to take over the Howling Ziggurat, due north.  We weren't expecting to make it back alive.... hell, we already lost half our crew.\n\nTassarian was on point and the higher ups... well, they didn't like something about him.\n\nHe took off this morning... he might've gone to the ziggurat on his own.  But right now we have more pressing matters to worry about.  The Scourge keeps getting closer and closer to the camp, we need to take care of them -- now!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Corporal Venn at Death's Stand wants you to kill 8 Ziggurat Defenders." }
WordHunterWoW_QuestEN[12088] = { title = "Thassarian, the Death Knight", description = "Well, {name}, you helped us out... so I figure it's only fair that we help you out as well.\n\nYou're looking for Thassarian?  He disappeared this morning.  We think he went off north to the Wailing Ziggurat.  If we hadn't fought side by side by him we'd even think he was a traitor.\n\nSee, he's a Death Knight... and I know they're on our side and all... but it wasn't too long ago they were servants of Arthas.\n\nBut not Thassarian, he's a good guy.  Go to the Wailing Ziggurat, see if he's doing okay.", objectives = "Look for Thassarian inside the Wailing Ziggurat, north of Death's Stand.", completion = "Leryssa... is looking for me?  You must help me, <name>.  We must finish this before she gets hurt." }
WordHunterWoW_QuestEN[12089] = { title = "WANTED: Magister Keldonus", description = "By decree of Overlord Agmar:\n\nTarget: Magister Keldonus\n\nCrime: Treason\n\nStatus: Alive\n\nMagister Keldonus, once mage commander of Agmar's Hammer, is to be killed on sight in the name of the Horde.\n\nKeldonus was last seen traveling southwest towards Moonrest Gardens to join the blue dragonflight in their campaign against magic.\n\nApproach with caution as Keldonus is a powerful magus.\n\nAll bounties are paid out by Captain Gort at Agmar's Hammer.", objectives = "Slay Magister Keldonus and return to Captain Gort at Agmar's Hammer in the Dragonblight.", completion = "He wasn't the first of those sissy spell casters to betray us, and he certainly won't be the last. Damned shame, too... He was one of our best mages. He'd summon a buffet that would make your mouth water and your heart jump for joy...\n\nBAH!" }
WordHunterWoW_QuestEN[12090] = { title = "WANTED: Gigantaur", description = "By decree of Overlord Agmar:\n\nTarget: Gigantaur\n\nCrime: Attacks upon the Horde; \"Bein' ugly\"\n\nStatus: Alive\n\nThe magnataur lord, Gigantaur, is wanted in relation to a number of attacks against Horde soldiers and installations in the Dragonblight.\n\nGigantaur was last seen wandering the woods and roads south by southeast of Agmar's Hammer.\n\nGigantaur should be considered armed and extremely dangerous.\n\nAll bounties are paid out by Captain Gort at Agmar's Hammer.", objectives = "Slay Gigantaur and return to Captain Gort at Agmar's Hammer in the Dragonblight.", completion = "You got that ugly son-of-a-horse, eh? Well that's one less nuisance our soldiers will have to deal with out in the frozen wastes." }
WordHunterWoW_QuestEN[12091] = { title = "WANTED: Dreadtalon", description = "By decree of Overlord Agmar:\n\nTarget: Dreadtalon\n\nCrime: Attacks upon the Horde\n\nStatus: Alive\n\nDreadtalon is wanted for numerous attacks upon Horde caravans traveling to and from Venomspite.\n\nDreadtalon makes his home on a bluff overlooking the Ruby Dragonshrine, east of Agmar's Hammer. He should be approached with extreme caution.\n\nAll bounties are paid out by Captain Gort at Agmar's Hammer.", objectives = "Slay Dreadtalon and return to Captain Gort at Agmar's Hammer in the Dragonblight.", completion = "About time someone put a stop to that filthy beast's killing spree! A job well done, <name>." }
WordHunterWoW_QuestEN[12092] = { title = "Strengthen the Ancients", description = "It's not only the {race} race that has been impacted by what the blue dragonflight forces have done. The ancients of the Lothalor Woods to the southeast have been affected as well.\n\nSome have been corrupted-- avoid them at all costs--but most can still be saved. However, the treants of the woods seem to be immune to the magic seeping through the land and the arcane wyrms that have come with it.\n\nAsk the treants for their bark and feed it to the ancients. Hopefully that will be enough to save them.", objectives = "Use the Bark of the Walkers to strengthen 3 Lothalor Ancients and then return to Sarendryana at Stars' Rest.", progress = "An added benefit of saving the ancients may turn out to be that they will consider assisting the Alliance with its hardships. Regardless, it is the right thing to do.\n\nNow, how many were you able to strengthen, <class>?", completion = "Thank you, <race>! We've lost so much already. You've ensured that we won't lose the most majestic of Northrend's children.\n\nI'll soon leave to speak with the ancients you saved and see if they will help us in our time of need." }
WordHunterWoW_QuestEN[12093] = { title = "Runes of Compulsion", description = "Even as Kurun attacks Thor Modan, the iron dwarves work their magics against our brothers. Summoning our brothers from the earth, then binding them with runes, the sons of iron force them to war against the children of stone.\n\nAlong the Eastwind Shore, they use runes of compulsion to send enslaved giants to the battlefields of the north.\n\nFind the four runes of compulsion and force their overseers to appear by defeating the rune-weavers who man each rune. Without the overseers, the runes are useless.", objectives = "Gavrock, at the Ruins of Tethys, wants you to neutralize the four Runes of Compulsion by defeating Overseer Durval, Overseer Korgan, Overseer Lochli, and Overseer Brunon.", completion = "Good. Now, we must act swiftly, before the sons of iron realize that their runes have been rendered harmless." }
WordHunterWoW_QuestEN[12094] = { title = "Latent Power", description = "While the runes of compulsion are dormant, there is a chance we can release the runed giants.\n\nI will give you a piece of stone that has been part of me since my creation. If properly imbued, it can be used to free the bound giants.\n\nTwo ancient stone markers sit atop places of power between the Path of Iron and the forest's edge -- locations your people would call the intersections of ley lines. The other is on an island at the southern end of these ruins. Charge the shard at each stone and return.", objectives = "Charge the Shard of Gavrock at the First Ancient Stone, the Second Ancient Stone, and the Third Ancient Stone, then return to Gavrock at the Ruins of Tethys.", progress = "Did you find the ancient stones?", completion = "I can detect the power you've imbued in the shard and I hope it will be enough to break the runic magic." }
WordHunterWoW_QuestEN[12095] = { title = "To Dragon's Fall", description = "East of here, in the heart of the Dragonblight, is a field full of nothing but dragon bones and snow. The Scourge have set up multiple camps in the central tundra and are raising frostwyrms to send against our forces at the Wrathgate. While most of these frostwyrms are easily dealt with by Rokhan and his dragon hunters, one of them is proving to be a bit problematic.\n\nGo northeast and seek out Rokhan at Dragon's Fall. Help him and his men put down Sarathstra and you'll be rewarded handsomely!", objectives = "Speak with Rokhan at Dragon's Fall in the Dragonblight.", completion = "What make you tink dat you succeed where Rokhan fail?" }
WordHunterWoW_QuestEN[12096] = { title = "Strengthen the Ancients", description = "The ancients of the Lothalor Woods to the south are being corrupted by arcane wyrms... wyrms which have risen out of the ground!\n\nThose that are already corrupted are deadly and of no use to us, but most can still be saved. Luckily, the treants of the woods seem to be immune to everything happening up there.\n\nAsk the treants for their bark and when you get some, feed it to the ancients. This should strengthen them.\n\nNow leave me to my business! I have to keep an eye on these apothecaries.", objectives = "Use the Bark of the Walkers to strengthen 3 Lothalor Ancients and then return to Earthwarden Grife at Agmar's Hammer.", completion = "You have my thanks, <class>.\n\nAs soon as I am done observing what these disgusting apothecaries are up to, I'll head to the woods and see if I can convince these ancients to side with us.\n\nOr, if nothing else, I'll convince them not to attack those that saved them!" }
WordHunterWoW_QuestEN[12097] = { title = "Sarathstra, Scourge of the North", description = "Me hunters be dead or frozen, {name}. You still want to do dis? Just say da word and me call for da dragon once more.\n\nIf ya kill it, take da beast's frozen heart back to Agmar's Hammer and present it to Gort. He sure to reward you good, mon.", objectives = "Speak with Rokhan to call down the frostwyrm, Sarathstra.\n\nKill Sarathstra and deliver Sarathstra's Frozen Heart to Captain Gort at Agmar's Hammer.", progress = "<Gort raises an eyebrow.>\n\nBack so soon?", completion = "HA! You did it! The soldiers at the Wrathgate are indebted to you, <name>! This'll surely buy a few of them another day above ground." }
WordHunterWoW_QuestEN[12098] = { title = "Search Indu'le Village", description = "I'm certain that you'll find the next ley line focus somewhere in the remains of Indu'le Village to the southeast. The problem is, we've had absolutely no reports of there being one there.\n\nIf you would, please investigate the village for any signs of the focus or the mage hunters and their commander in the area.\n\nDon't forget to search in the lake if you have to.", objectives = "Search for the commander of the mage hunter forces at Indu'le Village and Lake Indu'le.", completion = "You find the corpse of the mage hunter commander here.\n\nJudging by his appearance, and the condition of the forces around him, you would guess that they didn't drown. Rather, when they summoned the focus in, they didn't expect the elementals that arose from the rents in the lake bed to attack.\n\nIt would appear that the mage hunter forces were the architects of their own demise." }
WordHunterWoW_QuestEN[12099] = { title = "Free at Last", description = "The rock shard you imbued should be powerful enough to break the runic magic binding my brothers.\n\nTake it with you and find the runed giants walking north along the Eastwind Shore. Unleash the power stored in the stone and observe the results.\n\nIf it works, the runed giants should return to their senses and stop obeying the iron dwarves. If the stone fails to work, the giants may attack in a weakened state. But, what choice do we have? If we do not try, they will remain enslaved without hope.", objectives = "Use Gavrock's Runebreaker to free 4 Runed Giants, then return to Gavrock at the Ruins of Tethys.", completion = "So it's an uncertain thing? I wish it was not a matter of chance, but at least we're on the right path. Without your help, this wouldn't have ever been possible. Should you learn any more about the machinations of the iron dwarves and their plans toward the children of stone, seek us out and we will hear you, <name>." }
WordHunterWoW_QuestEN[12100] = { title = "Containing the Rot", description = "With Scourge comes death and disease. We often overlook that the wildlife of a Scourge infested area is ravaged and ultimately destroyed by rot and contagion.\n\nFor most of the indigenous beasts of the Dragonblight it is too late. The festering disease that the Scourge brings has already infected the beasts and they are now rabid and rotting.\n\nYou must venture west, towards the Pit of Narjun, and cull the infected wildlife. Check their corpses for a preserved organ as we need one to devise a vaccine.", objectives = "Soar Hawkfury at Agmar's Hammer in the Dragonblight wants you to kill 15 Infected Wildlife and recover a Rot Resistant Organ.", progress = "Kill the beasts to prevent the spread and bring me a rot resistant organ.", completion = "It pains me to put animals down, but it is a service that must be performed. Now we must move on to the next step: Inoculation." }
WordHunterWoW_QuestEN[12101] = { title = "The Good Doctor...", description = "Our Forsaken allies have sent their apothecary core here to assist us in destroying the Scourge at the Wrathgate. One among them, Doctor Sintar Malefious, is well versed in the Scourge rot and methods of containing the spread. I had previously worked out a deal with him in regards to devising a vaccine for wildlife. He's since been waiting on the organ.\n\nDeliver this rot resistant organ to Dr. Malefious and let him know it's from me. He'll direct you on your next task.", objectives = "Deliver the Rot Resistant Organ to Doctor Sintar Malefious at Agmar's Hammer.", progress = "What now?", completion = "The oafish man-cow actually acquired a rot resistant organ? Curses... I was certain that task would keep his malformed mind occupied well into the next millennium.\n\nWell give it here, boy. I have much to do without your feeble needs getting in the way." }
WordHunterWoW_QuestEN[12102] = { title = "In Search of the Ruby Lilac", description = "How fortuitous it is that the Ruby Dragonshrine lays just to the east. It is there that you will find a flower called the ruby lilac. This lifegiving plant is all that I need to concoct a vaccine for the untainted beasts of this region.\n\nTravel east and search the Ruby Dragonshrine for the lilac.\n\nJust one thing: The dragonshrine, like all the dragonshrines in this blasted wasteland, is beset by the Scourge. Watch your step. We wouldn't want you to be devoured by an emberwyrm.\n\n<Sintar laughs.>", objectives = "Doctor Sintar Malefious at Agmar's Hammer in the Dragonblight wants you to collect 1 Ruby Lilac.", progress = "Do you have the ruby lilac?", completion = "That wasn't so difficult, now was it?\n\nNow give me a moment to prepare the vaccine." }
WordHunterWoW_QuestEN[12103] = { title = "Before the Storm", description = "{name}! I have been looking all over this strange city for you!\n\nGrand Master Hight has requested all senior monks to return to the Peak of Serenity as soon as possible. That means you too, of course.\n\nI'll bet a week's worth of brew that this has something to do with the assault on the Broken Shore I've heard tales about!", objectives = "Assist Grand Master Hight at the Peak of Serenity.", completion = "Welcome back to the land of the living, <name>. We nearly lost you in that explosion! Lucky for us that the Wandering Isle happened to be traveling nearby.\n\nThe people here have graciously allowed us to reside at the temple. It's not like the Peak of Serenity, but this will make a fine new home." }
WordHunterWoW_QuestEN[12104] = { title = "Return to Soar", description = "<Doctor Malefious hands you a vial full of murky liquid.>\n\nHere you are then, {race}. Take this back to the cow and let him know that all debts have been paid. We are officially \"square.\"\n\nNow leave me before I set Jennings upon you.", objectives = "Deliver Sintar's Vaccine to Soar Hawkfury at Agmar's Hammer.", progress = "Have you got the vaccine?", completion = "<Soar holds the vial up to the sky and examines its contents.>\n\nOnly one thing left to do now." }
WordHunterWoW_QuestEN[12105] = { title = "Descent into Darkness", description = "The journal was written by a denizen of Silverbrook named Mikhail.  It details the arrival of a shadow-worshipping group called the \"wolfcult.\"\n\nThe villagers were reluctant to embrace the cult at first, but sympathizers sprung up gradually among town residents.\n\nUnsettled by this, Mikhail sent his daughter Sasha away from Silverbrook while he attempted to reason with the other villagers.\n\nMikhail's last entry mentions a meeting of local town leaders to discuss unspecified events in Hollowstone Mine.", objectives = "Bring Mikhail's Journal to Lieutenant Dumont in Amberpine Lodge.", progress = "What's that you've got there?", completion = "I imagined there would be more to this than just an isolated town of hostiles.\n\nWe have men near Hollowstone Mine, perhaps it would be in our interest to do a little research." }
WordHunterWoW_QuestEN[12106] = { title = "Search Indu'le Village", description = "I'm certain that you'll find the next ley line focus somewhere in the remains of Indu'le Village to the southeast. The problem is, I've had absolutely no reports of there being one there.\n\nI need you to go investigate the village for any signs of the focus or the mage hunters and their commander in the area.\n\nSearch in the lake if you have to!", objectives = "Search for the commander of the mage hunter forces at Indu'le Village and Lake Indu'le.", completion = "You find the corpse of the mage hunter commander here.\n\nJudging by his appearance, and the condition of the forces around him, you would guess that they didn't drown. Rather, when they summoned the focus in, they didn't expect the elementals that arose from the rents in the lake bed to attack.\n\nIt would appear that the mage hunter forces were the architects of their own demise." }
WordHunterWoW_QuestEN[12107] = { title = "The End of the Line", description = "Within his robes you find two things of interest.\n\nOne is a talisman, which is clearly a focus controlling device. The other is a set of orders from someone named Sidragos, which were ultimately intended for the leader back at the Moonrest Gardens.\n\nThe water-soaked parchment informs Goramosh that he is to move all mage hunter forces east to the Azure Dragonshrine.\n\nPerhaps you should get what information you can from the focus and head east to observe the dragonshrine from its western ledge.", objectives = "Use the Ley Line Focus Control Talisman to gain information from the Ley Line Focus under Lake Indu'le. Then, head east to the Azure Dragonshrine near south central Dragonblight and observe what is occurring there from the western ledge.\n\nAfterward, return to the Image of Archmage Modera at Stars' Rest.", completion = "WHAT?!\n\n<The image before you distorts for a moment as the archmage attempts to regain her composure.>\n\nOf course, we should have guessed that this was what they were up to all along. Quickly, there's no time to waste.\n\nWyrmrest must be warned!" }
WordHunterWoW_QuestEN[12108] = { title = "DEPRECATED", description = "The dirt mound is, indeed, a hastily dug grave.  The body beneath is unrecognizable but you find a note that identifies that man as Mikhail.\n\nThe note mentions Hollowstone Mine once again.  Perhaps someone back at Amberpine Lodge might be familiar with the area.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring Mikhail's Note to Cartographer Tobias at Amberpine Lodge.The dirt mound is, indeed, a hastily dug grave. The body beneath is unrecognizable but you find a note that identifies that man as Mikhail.\n\nThe note mentions Hollowstone Mine once again. Perhaps someone back at Amberpine Lodge might be familiar with the area.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[12109] = { title = "Report to Gryan Stoutmantle... Again", description = "The Westfall boys were sent east to look for a path into the northern territories.  Their secondary objective is to secure strategic resource points, so I'm sure they wouldn't mind investigating a mine.\n\nLook for the Westfall Brigade encampment far to the northeast and seek out Gryan Stoutmantle.  You might remember him if you ever spent any time in Westfall.  Make sure to tell him I sent you.\n\nHe'll be more than happy to let you claim a functioning mine for the king.", objectives = "Speak to Captain Gryan Stoutmantle at the Westfall Brigade Encampment.", completion = "Dumont sent you?  Very well.  Let's see what you can do for us." }
WordHunterWoW_QuestEN[12110] = { title = "The End of the Line", description = "Within his robes you find two things of interest.\n\nOne is a talisman, which is clearly a focus controlling device. The other is a set of orders from someone named Sidragos, which were ultimately intended for the leader back at the Moonrest Gardens.\n\nThe fragile water-soaked parchment informs Goramosh that he is to move all mage hunter forces east to the Azure Dragonshrine.\n\nPerhaps you should get what information you can from the focus and head east to observe the dragonshrine from its western ledge.", objectives = "Use the Ley Line Focus Control Talisman to gain information from the Ley Line Focus under Lake Indu'le. Then, head east to the Azure Dragonshrine near south central Dragonblight and observe what is occurring there from the western ledge\n\nAfterward, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", completion = "WHAT?!\n\n<The image before you distorts for a moment as the archmage attempts to regain his composure.>\n\nOf course, we should have guessed that this was what they were up to all along. Quickly, there's no time to waste.\n\nWyrmrest must be warned!" }
WordHunterWoW_QuestEN[12111] = { title = "Where the Wild Things Roam", description = "Inside this pack are several vials containing the vaccine that Sintar created. I now want you to search the nearby woods for Snowfall elk and arctic grizzlies. When you locate the animals, find a safe distance and throw a vial in their general direction. The vial will shatter and release a fine gas that will act as the inoculating agent. The beasts merely have to step inside the gas and they will be vaccinated - ultimately saved.\n\nInoculate as many of the beasts as you can and return to me.\n", objectives = "Soar Hawkfury at Agmar's Hammer in the Dragonblight wants you to use the Pack of Vaccine to vaccinate 5 Snowfall Elk and 5 Arctic Grizzlies.", completion = "You have done an honorable thing, <name>. Please, choose a reward." }
WordHunterWoW_QuestEN[12112] = { title = "Stiff Negotiations", description = "Well it seems you were of a bit of use after all. It's not been my experience to meet many a {race} that are.\n\nWe don't have any more use for you here. Head into the Vice and see if my brother Zort could use a hand. He went to see if he could con the giants into laying down their lives so that we don't have to. He certainly wasn't known for having the brains in the family.  ", objectives = "Locate Zort in the center of the Crystal Vice, northeast of Nozzlerust Post.", completion = "I can think of some uses for you, go ahead and stay for a bit." }
WordHunterWoW_QuestEN[12113] = { title = "Nice to Meat You", description = "G'day to ya, {class}! Have yerself a seat by me fire, eh?\n\nI'd offer to share a nice hot meal, only I ain't got one. I'm stuck here waitin' on an associate, or I'd be out tryin' to remedy that situation meself.\n\nSay, you seem to have nuthin' but time on yer hands and there be plenty o' meat in these parts. What say ya lend a hand and round up some grub? ", objectives = "Harkor at Harkor's Camp wants you to collect 10 pieces of Fibrous Worg Meat from Duskhowl Prowlers and 10 Shovelhorn Steaks from Longhoof Grazers.", progress = "Me belly be rumblin, <race>. You manage to round up some food?", completion = "Outstanding!\n\nNuthin' better with a pint than a hot morsel of meat." }
WordHunterWoW_QuestEN[12114] = { title = "Therapy", description = "Trolls... me hates 'em all! <Harkor spits.>\n\nI once got meself captured by a band o' tha beasts... came this close ta gettin' me head shrunk!\n\nMe friends tell me to just move on and put it all behind me, but that just ain't sittin' right.\n\nWanna know what would make me feel better, {race}? Seein' a pile of their corpses so high it blots out the sun! I've got good gold to spend if ya can make that happen.", objectives = "Harkor at Harkor's Camp wants you to kill 10 Drakkari Protectors and 10 Drakkari Oracles outside Drakil'jin Ruins.", completion = "Thankyeh, <class>.\n\nWhen time allows I'll git up and have meself a look around." }
WordHunterWoW_QuestEN[12115] = { title = "Koltira and the Language of Death", description = "There is one who recently joined our cause that might be able to decipher this tome. An unbound death knight known as Koltira Deathweaver has temporarily taken residence here at Agmar's Hammer. As he was once a death knight of Arthas and member of the Scourge, he might be able to translate the language of the dead.\n\nTake the flesh-bound tome to Koltira and ask him to translate the pages.\n", objectives = "Take the Flesh-Bound Tome to Koltira Deathweaver.", progress = "What is it, <race>?", completion = "There are only two things in life that interest me, peon, and neither of them involve translating a Scourge tome for you.\n\nHowever... perhaps we could work something out that would benefit the both of us.\n\n<Koltira unsheathes his weapon.>\n\nThis is my runeblade, Byfrost. Byfrost thirsts for the blood of the Lich King and his minions, but first I must etch upon it runes of power: symbols of frost, blood, and unholy. Bring me suitable sources of power and I will translate your tome." }
WordHunterWoW_QuestEN[12116] = { title = "It Takes Guts....", description = "Greetings, {class}. It is kind of you to stop and listen to Kraz's tale.\n\nFor many years Kraz has strained to hear the spirits and do their bidding.\n\nRecently,  many voices have been crying to Kraz from these ruins. They seek for a peace they cannot find on their own.\n\nIf you would help the spirits of those who have come before, enter this crypt and collect something that once belonged to those tormented souls.", objectives = "Kraz at Harkor's Camp wants you to enter Drakil'jin Ruins and collect 5 Drakkari Canopic Jars.", progress = "What have you found in the crypt for Kraz, <class>?", completion = "Entrails? An interesting choice, <race>.\n\nKraz shall see what is to be learned from them. Thank you for braving the depths of that place." }
WordHunterWoW_QuestEN[12117] = { title = "Travel to Moa'ki Harbor", description = "{race}, word just arrived from Moa'ki Harbor. Something very bad happened over there this morning!\n\nYou've been very helpful to us here. Would you consider using the boat from Unu'pe to travel to the great Dragonblight?\n\nBy the sound of things, Elder Ko'nani could certainly use your assistance.", objectives = "Travel to Moa'ki Harbor in the Dragonblight and speak with Elder Ko'nani.", completion = "What's that you say, <race>? Hotawa sent you?\n\nGood, good... there's much to do. We can use all of the help that we can get!" }
WordHunterWoW_QuestEN[12118] = { title = "Travel to Moa'ki Harbor", description = "{race}, word just came in off the boat from Moa'ki Harbor. Something very bad happened over there this morning!\n\nYou've been very helpful to us here. Would you consider using the boat to travel to the great Dragonblight?\n\nBy the sound of things, Elder Ko'nani could certainly use your assistance.", objectives = "Travel to Moa'ki Harbor in the Dragonblight and speak with Elder Ko'nani.", completion = "What's that you say, <race>? Anuniaq sent you?\n\nGood, good... there's much to do. We can use all of the help that we can get!" }
WordHunterWoW_QuestEN[12119] = { title = "Gaining an Audience", description = "{name}, you must travel as swiftly as you can to Wyrmrest Temple and present this letter to the steward, Tariolstrasz.\n\nThe temple sits in the center of the Dragonblight. Follow the road east until it ends, and then cross The Dragon Wastes to get to it.\n\nI'm sure that when the steward reads your introduction, he'll see to it that you gain an audience with Queen Alexstrasza. We can only hope that we're not too late.\n\nThank you for all that you have done on our behalf. Safe journeys!", objectives = "Deliver your Letter of Introduction to Wyrmrest Temple to Tariolstrasz at Wyrmrest Temple.", progress = "Yes, what can I do for you, <race>?", completion = "A letter of introduction to meet with the queen? Let me see that.\n\nWhatever your business is, I hope that it's important.  The skies are full of attacking blues today!" }
WordHunterWoW_QuestEN[12120] = { title = "Drak'aguul's Mallet", description = "Corruption....\n\nEven before you delivered these jars, Kraz could sense it. This corruption fills the ancient Drakkari spirits with great angst and prevents them from entering the rest they seek.\n\nKraz will not lie, {class}. Cleansing this place will require great sacrifice, but we shall speak of that at another time.\n\nThere is one among the living here who holds the key to its cleansing. Seek out Drak'aguul and return to Kraz with the mallet he carries.", objectives = "Kraz at Harkor's Camp wants you to slay Drak'aguul outside Drakil'jin Ruins and return with the Drakil'jin Mallet.", progress = "You find the mallet, <name>?", completion = "You have done well thus far, <name>, but now comes the true test." }
WordHunterWoW_QuestEN[12121] = { title = "See You on the Other Side", description = "These Drakkari have met you with nothing but savage hostility. You owe them nothing. Few indeed would carry out the task that Kraz asks of you today.\n\nTo cleanse this place and send the spirits to their eternal rest, you must join them in death.\n\nThere is one inside the crypt who awaits you - on the other side. He holds the knowledge we seek, {name}.\n\nUse the mallet on the gongs. The spirit of he who corrupts this place will surely deliver you to the spirit world.\n\nKraz awaits your return.", objectives = "Kraz at Harkor's Camp wants you to use the Drakil'jin Mallet on the gongs outside Drakil'jin Ruins. Once you have been slain, you are to enter the ruins and speak with the spirit of Gan'jo while you are dead.", completion = "Your coming has been foretold, friend. It was good of you to come." }
WordHunterWoW_QuestEN[12122] = { title = "Gaining an Audience", description = "{name}, you must travel as swiftly as you can to Wyrmrest Temple and present this letter to the steward, Tariolstrasz.\n\nThe temple sits in the center of the Dragonblight. Follow the road east until it ends, and then cross The Dragon Wastes to get to it.\n\nI'm sure that when the steward reads your introduction, he'll see to it that you gain an audience with Queen Alexstrasza. We can only hope that we're not too late.\n\nThank you for all that you have done on our behalf. Safe journeys!", objectives = "Deliver your Letter of Introduction to Wyrmrest Temple to Tariolstrasz at Wyrmrest Temple.", progress = "Yes, what can I do for you, <race>?", completion = "A letter of introduction to meet with the queen? Let me see that.\n\nWhatever your business is, I hope that it's important.  The skies are full of attacking blues today!" }
WordHunterWoW_QuestEN[12123] = { title = "Informing the Queen", description = "<The dragon steward pulls your letter of introduction out of his sleeve.>\n\nYes... yes, I think that you are ready to see the queen now.\n\nWhen you are ready, speak to me again and I will see to it that one of these drakes delivers you safely to the top of the temple. You will need to present your letter in person to Queen Alexstrasza.", objectives = "Deliver your Letter of Introduction to Wyrmrest Temple to Alexstrasza the Life-Binder at Wyrmrest Temple.", progress = "It is good to finally meet you in person, <name>. I have known you since before you were born.", completion = "You are very courageous to bring us this information. I was beginning to wonder why the blue dragonflight had so boldly initiated an attack upon the temple itself. Now we know that they are using enormous amounts of the very magic they view as such a threat to Azeroth.\n\n<The queen shakes her head in seeming resignation.>\n\nHypocritical, but so be it. If Malygos will not come to his senses, we have no choice but to take action in response to their assault." }
WordHunterWoW_QuestEN[12124] = { title = "Informing the Queen", description = "<The dragon steward pulls your letter of introduction out of his sleeve.>\n\nYes... yes, I think that you are ready to see the queen now.\n\nWhen you are ready, speak to me again and I will see to it that one of these drakes delivers you safely to the top of the temple. You will need to present your letter in person to Queen Alexstrasza.", objectives = "Deliver your Letter of Introduction to Wyrmrest Temple to Alexstrasza the Life-Binder at Wyrmrest Temple.", progress = "It is good to finally meet you in person, <name>. I have known you since before you were born.", completion = "You are very courageous to bring us this information. I was beginning to wonder why the blue dragonflight had so boldly initiated an attack upon the temple itself. Now we know that they are using enormous amounts of the very magic they view as such a threat to Azeroth.\n\n<The queen shakes her head in seeming resignation.>\n\nHypocritical, but so be it. If Malygos will not come to his senses, we have no choice but to take action in response to their assault." }
WordHunterWoW_QuestEN[12125] = { title = "In Service of Blood", description = "The blood of innocents was once used to sate the thirst of the blade. Alas, such options are no longer available to me.\n\n<Koltira pauses to think.>\n\nWe must improvise. South of here, upon the high bluffs, is the tuskarr village of Indu'le. Having been recently overrun by the Blue Dragonflight's chaotic magic, the resident tuskarr of Indu'le have gone mad.\n\nTake this blood gem and use it on a deranged villager. If I cannot take the blood of innocents, I shall have the blood of the meek!", objectives = "Koltira Deathweaver at Agmar's Hammer in the Dragonblight wants you to use the Blood Gem on a Deranged Indu'le Villager and return to him with a Filled Blood Gem.", progress = "Bring the blood of the meek to me.", completion = "A simple task for a simpleton. You have performed within my expectations." }
WordHunterWoW_QuestEN[12126] = { title = "In Service of the Unholy", description = "The power of the unholy is coveted among my kind. It makes up the very fiber of our existence, granting death to those that dare make a mockery of it! Thankfully there is a font from which I may draw from in my time of need.\n\nTake this unholy gem and make your way to the Ruby Dragonshrine, east of here. It is there that you will find Duke Vallenhal, death knight of Arthas. Weaken his resolve in battle and unleash the power of the gem upon him. It will finish him off and steal his unholy energy!\n", objectives = "Koltira Deathweaver at Agmar's Hammer in the Dragonblight wants you to use the Unholy Gem on Duke Vallenhal and return to him with a Filled Unholy Gem.", progress = "Fill the gem with the power of the unholy!", completion = "<Koltira's eyes widen.>\n\nImpressive. You bested a deathknight of Arthas... Clearly you were not alone... but still..." }
WordHunterWoW_QuestEN[12127] = { title = "In Service of Frost", description = "The biting cold protects the death knight while repelling his enemies. He that commands the power of frost can incite chaos and destruction!\n\nTake this frost gem and travel far across the open tundra of the Dragonblight until you come upon the Mirror of Dawn, east of Wyrmrest Temple. It is there that you are to battle the legions of ice revenants that dwell upon the lakes surface and take from them the essence of frost. Utilize the power of the gem when they are weak, {name}!", objectives = "Koltira Deathweaver at Agmar's Hammer in the Dragonblight wants you to use the Frost Gem on Ice Revenants and return to him with a Filled Frost Gem.", progress = "We are all in service of frost here in Northrend.", completion = "I can already feel the cold coursing through me, <name>." }
WordHunterWoW_QuestEN[12128] = { title = "Check Up on Raegar", description = "With all the excitement about the army trying to move through Thor Modan, I'd almost forgotten about Raegar's crew down at Prospector's Point.\n\nI sent Raegar and his assistants, along with a mountaineer friend, down to establish a small post near Dun Argol, at the southern end of the Eastwind Shore.\n\nThey were to investigate the iron dwarf presence in the southern hills, but I haven't received any reports yet. Could you check up on them if you're going down that way?", objectives = "Speak with Raegar Breakbrow at Prospector's Point.", completion = "Hmm... you don't look like a research assistant, which is just as well. The iron dwarves look to be preparing for war, and my research team hasn't returned. We could use some help around here." }
WordHunterWoW_QuestEN[12129] = { title = "The Perfect Plan", description = "The iron dwarves are making no secret of the fact that they're preparing for war. With their giants, golems, and lightning elementals, they'd have a technological advantage against the Westfall Brigade. If they don't find passage north in time, the irons could take them by surprise.\n\nWe've got to tie them up here, and I've got just the way to do it. Dun Argol is full of rune-smiths churning out war golems. They carry plans for specific pieces, so you'll need to find and assemble all the parts.", objectives = "Bring the completed War Golem Blueprint to Raegar Breakbrow at Prospector's Point.", progress = "Were you able to get those plans from the rune-smiths?", completion = "You got all of them? Brilliant! I can't wait to see the looks on their faces when the golem's done." }
WordHunterWoW_QuestEN[12130] = { title = "Why Fabricate When You Can Appropriate?", description = "We've got the blueprints, but we can't do anything with them without parts! We don't have access to a foundry, much less materials, but there's a whole load of parts up in Dun Argol.\n\nYour job?\n\nGive them a new home.\n\nThey're likely to be scattered around any of the buildings where the iron rune-smiths are working, and I wouldn't blame the irons for being cranky when you try to filch their handiwork. The more parts you can bring, the better we can make this golem.", objectives = "Bring 8 War Golem Parts to Raegar Breakbrow at Prospector's Point.", progress = "I see you made it out in one piece. Do you have the parts?", completion = "<Raegar wipes his forehead with the back of his hand.>\n\nOh, no. This is going to be harder than I thought. These things don't have serial numbers or anything, do they?\n\nNever a gnome around when you need one..." }
WordHunterWoW_QuestEN[12131] = { title = "We Have the Power", description = "We're almost there, but the war golem won't run without power cells. From the information I was able to collect in Dun Argol before we were discovered, both Rune-Smith Durar and Rune-Smith Kathorn each create one power cell.\n\nWe'll need one power cell from each of the rune-smiths before our golem will work.\n\nYou should be able to find each rune-smith in his workshop on the central level of Dun Argol.", objectives = "Bring Durar's Power Cell and Kathorn's Power Cell to Raegar Breakbrow at Prospector's Point.", progress = "Well, did you get those power cells?", completion = "<Raegar takes the batteries from you.>\n\nExcellent! We should be all ready to go." }
WordHunterWoW_QuestEN[12132] = { title = "The Power to Destroy", description = "While you have done much for me, one task remains.\n\nBeside the world you know exists another world. It is from that world, the world of shadows, that my tormentors assault me. While I am powerless to face my own demons, you could end their reign of terror. You have the strength, I have seen it with my own eyes.\n\nEnter the world of shadows and face the demons that torment me!\n\nDo this and I will translate the tome, as promised.", objectives = "Koltira Deathweaver at Agmar's Hammer in the Dragonblight wants you to enter the world of shadows and defeat 6 Shadowy Tormentors.\n\nSpeak to Koltira Deathweaver should you need to re-enter the world of shadows.", completion = "The power I hold comes at a great cost, <name>. Many knights, light and dark alike, lost their lives in the final battle at Light's Hope. The prospect of the future looks grim, but at least now I know what I face. The Lich King will never release his grasp and for that alone he must die!" }
WordHunterWoW_QuestEN[12133] = { title = "Smash the Pumpkin", description = "This large jack-o'-lantern rests in the middle of the village.  It eyes those who look upon it, betraying a dark menace within.\n\nSmashing the pumpkin reveals an old, scorched holy symbol.", objectives = "Give the Scorched Holy Symbol to the Costumed Orphan Matron.", progress = "Yes, <name>?", completion = "You found this inside the Headless Horseman's jack-o-lantern?  It is an old symbol of the Light.  It must have been the Horseman's, before he was cursed and turned into the monster he is today.  Thank you, <name>.  This symbol deserves to be with paladins.  I will make sure they get it.\n\nOh, and I almost forgot!  You have a secret admirer...\n\nOne of the children wanted you to have this.  She was too shy to give it to you herself." }
WordHunterWoW_QuestEN[12134] = { title = "Sasha's Hunt", description = "This thing... this curse... that's affecting Silverbrook and Solstice Village... it makes beasts out of people.\n\nMy father tried to warn them, but they all listened to the wolfcult instead.\n\nThey're too far gone now, it's time to put them down... for their own sake.", objectives = "Sasha wants you to kill 12 Solstice Hunters in Solstice Village.", progress = "Have you taken care of the hunters in the village yet, <name>?", completion = "Killing these monsters won't bring my father back... but that's not the point now, is it?" }
WordHunterWoW_QuestEN[12135] = { title = "\"Let the Fires Come!\"", description = "You must help us!  The Headless Horseman will attack the village at any moment!  Fires will be everywhere!  The children aren't safe!\n\nPlease, {name}, will you face the fires of the Headless Horseman?  When he comes, you must join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  If you put out all the fires then we may yet be saved!", objectives = "The Costumed Orphan Matron wants you to help put out all the village fires after the Headless Horseman lights them. When they are out, speak again to the Costumed Orphan Matron.", completion = "Oh, thank you!  May the Light bless your good works, kind sir.  The shadow of the Dark Horseman yet looms, but at least, for now, the village is safe from his flames." }
WordHunterWoW_QuestEN[12136] = { title = "The Translated Tome", description = "Here it is, {name}. I have translated everything printed upon the pages of the tome. Inside it you will find a list of the names of Cult of the Damned members spanning the entire continent.\n\nTheir network of spies and operatives is impressive, to say the least.\n\nFarewell, friend. May the book serve you and your people well.", objectives = "Deliver the Translated Flesh-bound Tome to Captain Gort at Agmar's Hammer.", progress = "It's about time! Where have you been?", completion = "<Gort takes the tome from you and begins reading.>\n\nWHAT! This can't be right. I've known some of these orcs for years!\n\nLeave me, <name>. I have much work to do and many traitors to execute.\n\nTake one of these items for your trouble. You've done a great service for the Horde this day." }
WordHunterWoW_QuestEN[12137] = { title = "Chill Out, Mon", description = "It be as the prophecies said, mon. A {race} {class} be comin' to set our spirits to rest. We been waitin' for a long time now!\n\nThe Drakkari have become a lost people, fierce and savage.\n\nBut here we suffer by no fault of our own, mon. This place need cleansin' and only the living can do it.\n\nSpeak to me when ya be ready to rejoin your body. Then take the snow from the chest near me here and put my bruddas to sleep.\n\nTake their remnants to your spirit guide. He be knowin' what to do next.", objectives = "Gan'jo wants you to collect the Snow of Eternal Slumber from his chest in the Drakil'jin Ruins.\n\nYou are to use the Snow on the Ancient Drakkari Spirits there and take their Drakkari Spirit Particles back to Kraz at Harkor's Camp.", progress = "Have you completed your task in the crypt, <class>?", completion = "You have done well.\n\nPlease, sit and listen. There are many things we must discuss." }
WordHunterWoW_QuestEN[12138] = { title = "... Or Maybe We Don't", description = "You'd think the guys making the power cells would've thought to power them up, but no, they've got to make it difficult for us.\n\nFine, we'll charge those cells the hard way. There's enough power in them to run the golem for a short time, but don't expect it to be any good in combat.\n\nYou see the lightning sentries that the irons have posted around the perimeter of Dun Argol? Bring the golem with you, take it close to them, and use the golem to absorb the power as the sentries die.", objectives = "Charge your War Golem with the energy from 10 Lightning Sentries and return to Raegar Breakbrow at Prospector's Point.", completion = "Finally, it's ready. I only hope it holds together long enough to get the job done. If we don't take out the thane leading Dun Argol, Captain Gryan'll be in for a nasty surprise." }
WordHunterWoW_QuestEN[12139] = { title = "\"Let the Fires Come!\"", description = "The Headless Horseman will attack the village at any moment!  Fires will be everywhere!\n\n{name}, will you face the fires of the Headless Horseman?  When he comes, you must join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  If you put out all the fires then we may yet be saved!", objectives = "The Masked Orphan Matron wants you to help put out all the village fires. When they are out, speak again to the Masked Orphan Matron in town.", completion = "The fires are out!  You and your fire brigade were victorious!  Hah!\n\nThe Headless Horseman's attack has failed, but until he and his head are destroyed together, he will return.\n\nUntil then, however, let's take comfort in the safety you brought our children.  I am honored to have watched your brave work today." }
WordHunterWoW_QuestEN[12140] = { title = "All Hail Roanauk!", description = "Like the tauren, Forsaken, trolls and blood elves, so too do the taunka need a leader born of their own blood. The one you saved from Icemist, Roanauk, will be this leader.\n\n<Overlord Agmar hands you a parchment.>\n\nI give to you something familiar - the blood oath of the Horde.\n\nTake the oath to Roanauk Icemist and initiate him into the Horde as leader of the taunka.\n\nLet us not keep him waiting.\n\n<Agmar nods.>\n", objectives = "Seek out Roanauk Icemist at Agmar's Hammer and initiate him as a member and leader of the Horde forces.\n\nReturn to Overlord Agmar with the Blood Oath of the Horde when you complete this task.", progress = "Do not waste time, <name>. Angrathar awaits!", completion = "With the aid of such a powerful shaman, we are sure to be victorious at the Wrathgate!" }
WordHunterWoW_QuestEN[12141] = { title = "A Diplomatic Mission", description = "I see that you are very eager to help, {name}.  You didn't come all the way to Northrend to stay holed up in a city!  I've just the task for you... something that'll take you far away from here.\n\nWe've long sought to gain the favor of the tuskarr native to Northrend.  Recently a young tuskarr came to us seeking help, something we couldn't offer at the time.\n\nNow that you're around, maybe you can lend him a hand.  Look for Karuk near the Riplash Strand, southwest of here, and see what you can do to help.  ", objectives = "Speak to Karuk at Riplash Strand, southwest of Valiance Keep.", completion = "You've come to my aid?  I thank you, <name>." }
WordHunterWoW_QuestEN[12142] = { title = "Pest Control", description = "Ugh! One of those little snobold runts trashed our camp while we were busy with that last dragon. They've been plaguing us whenever we turn our backs... I've had enough!\n\nTo the south you'll find the snobolds hiding under the skirts of some of the local magnataur. Go slaughter them.\n\nIf the magnataur interfere on behalf of their slaves, kill them as well.", objectives = "Duane at the 7th Legion Front wants you to kill 10 Snowplain Snobolds and 3 Dragonblight Magnataur at the magnataur camps surrounding Wyrmrest.", completion = "Good riddance." }
WordHunterWoW_QuestEN[12143] = { title = "Canyon Chase", description = "I can't believe this! Another band of those vermin just tried to take off with more of our supplies. They're scurrying off towards that north canyon, get after them and deal with whoever they're going to!", objectives = "Duane wants you to chase the snobolds down the canyon northeast of 7th Legion Front and deal with their leader.", completion = "Chilltusk, eh?  I've heard his name before.  That's some good work, <class>.  Hopefully we can turn our attention back to the dragon menace now." }
WordHunterWoW_QuestEN[12144] = { title = "Pest Control", description = "Oi, mon! One of dose little snobold runts trashed our camp during da last dragon attack. Dey've been houndin us wheneva we turn our backs and I've had enough. \n\nTo da east you'll find da snobolds hiding under da skirts of some of da local magnataur. Go slaughter dem. If da magnataur interfere on behalf of deir slaves, kill dem as well.", objectives = "Kontokanis at Dragon's Fall wants you to kill 10 Snowplain Snobolds and 3 Dragonblight Magnataur at the magnataur camps surrounding Wyrmrest.", progress = "Did ya finish off dose pests?", completion = "Good riddance, mon." }
WordHunterWoW_QuestEN[12145] = { title = "Canyon Chase", description = "I can't believe dis! Another band of dose vermin just tried ta take off with more of our supplies. Dey're scurrying down da canyon now, get after dem and deal with whoever dey're going to!", objectives = "Kontokanis wants you to chase the snobolds down the canyon south of Dragon's Fall and deal with their leader.", completion = "Icefist, eh?  I've heard his name before.  Dat's some good work, mon.  Hopefully we Darkspear can turn our attention back to dat dragon menace now." }
WordHunterWoW_QuestEN[12146] = { title = "Disturbing Implications", description = "The underside of the horn boasts an emblazoned seal with a hammer and a lightning bolt. Something about the horn seems extremely out of place on a Magnataur.\n\nTake the horn south down the Path of the Titans to Wyrmrest and seek out someone who might be interested in these threatening implications.", objectives = "Bring the Emblazoned Battle Horn to Wyrmrest and seek out someone who might be interested in assessing the potential threat.", progress = "Yes, <race>?", completion = "It is indeed strange for any magnataur to carry an item such as this... and very concerning. I am glad that you have shown this to me." }
WordHunterWoW_QuestEN[12147] = { title = "Disturbing Implications", description = "The underside of the horn boasts an emblazoned seal with a hammer and a lightning bolt. Something about the horn seems extremely out of place on a Magnataur. \n\nTake the horn east across the Dragon Wastes to Wyrmrest and seek out someone who might be interested in these threatening implications.", objectives = "Bring the Emblazoned Battle Horn to Wyrmrest and seek out someone who might be interested in assessing the potential threat.", progress = "Yes, <race>?", completion = "It is indeed strange for any magnataur to carry an item such as this... and very concerning. I am glad that you have shown this to me." }
WordHunterWoW_QuestEN[12148] = { title = "One of a Kind", description = "Such a strange seal to see among magnataur... it suggests an unusual amount of organization.\n\nMagnataur rarely put aside their aggressive natures to cooperate with each other.  I suspect they have their eyes set on raiding a large settlement.\n\nI very much doubt that this horn is unique, I need you to prove me wrong. In the canyon northwest of the Azure Dragonshrine you will find Bonesunder. Go challenge him and bring me back any evidence you find that might confirm my concerns.", objectives = "Find and kill Bonesunder in or near the canyon northwest of the Azure Dragonshrine. Bring any evidence you find back to Aurastrasza at Wyrmrest Temple.", progress = "Did you find anything?", completion = "So it is true. They could not have chosen better timing for such an attack... between the Scourge and the blue flight, it is unlikely that anyone else has noticed yet." }
WordHunterWoW_QuestEN[12149] = { title = "Mighty Magnataur", description = "Magnataur are hideously violent creatures... this is the main reason we rarely see them come together in any real numbers without killing each other. A powerful leader has stepped up somewhere among them and we need to hunt him down if we are to stop this threat. \n\nI will start asking around. I need you to disrupt them as much as possible in the meantime.\n\nEast of here there are 3 torches erected. Near them, there are 3 dominant Magnataur - put them down to buy us some time to hunt down this leader.", objectives = "Hunt down and kill Bloodfeast, Iceshatter, and Drakegore east of Wyrmrest Temple.\n\nBloodfeast resides in the southeastern corner of the Dragon Wastes, just north of the Emerald Dragonshrine. Iceshatter patrols the northern edge of the Mirror of Dawn. Drakegore wanders at the bottom of the cliffs west of the Bronze Dragonshrine.\n\nReturn to Aurastrasza at Wyrmrest Temple once the magnataur have been slain.", completion = "Excellent work. No one could tell me who this leader might be, but I was able to uncover the name of someone who will have our answer." }
WordHunterWoW_QuestEN[12150] = { title = "Reclusive Runemaster", description = "Dregmar Runebrand is a magnataur runemaster... a rare breed. He's generally solitary, but has been known to associate with the more powerful and influential magnataur in Dragonblight for quite some time. He will know who this new leader is. \n\nIt is unlikely we will gain any aid with the increasing concerns with the Scourge and the blue flight, so I need you to procure the information from Dregmar by any means necessary.\n\nI was told he can be found amongst the cliffs overlooking the Mirror of the Dawn.", objectives = "Locate Dregmar Runebrand near his cave on the path to the cliffs overlooking the Mirror of the Dawn. Challenge him and uncover the name of the magnataur leader by any means necessary. Return to Aurastrasza at Wyrmrest Temple once the information is obtained.", completion = "Grom'thar the Thunderbringer. Good. Let's end any threat these magnataur might pose here and now." }
WordHunterWoW_QuestEN[12151] = { title = "Wanton Warlord", description = "There's no reason to suspect Dregmar's words are anything but true. Whether Grom'thar defeats you or is defeated by you, he can wash his hands of this.\n\nFollow his instructions... take the horn that you brought me earlier, travel to the ring of torches south of the Azure Dragonshrine, and blow it to announce your challenge.\n\nWhen Grom'thar the Thunderbringer arrives, kill him and bring me his head.", objectives = "Travel to the ring of torches south of the Azure Dragonshrine and blow the Emblazoned Battle Horn. Defeat Grom'thar the Thunderbringer and bring his head back to Aurastrasza at Wyrmrest Temple.", progress = "Did you end this threat for good?", completion = "You are formidable indeed.\n\nWith Grom'thar the Thunderbringer gone, we can leave the remaining Magnataur to fight among themselves and turn our attentions back towards more prominent threats.\n\nImpressive work, <class>." }
WordHunterWoW_QuestEN[12152] = { title = "Jin'arrak's End", description = "It is good to see you back among the living. Many who travel the path of the dead do not return to speak of it.\n\nWhile you were away, a vision appeared to Kraz revealing what remains to be done.\n\nA sacred offering lies somewhere inside the crypt. Take this spirit dust fashioned from the remnants you collected and use it on the offering.\n\nThe infused offering will bring an end to the corrupted warlord and will release the many tormented souls.\n\nMay the spirits guide your actions, {name}.", objectives = "Kraz at Harkor's Camp wants you to collect the Sacred Drakkari Offering from the Drakil'jin Ruins and use the Drakkari Spirit Dust on it. You must use the Infused Drakkari Offering at the gongs outside of Drakil'jin Ruins.", completion = "It is done.\n\nYour selflessness has brought eternal peace to many souls, ending eons of misery.\n\nMay this act lighten your own soul and lessen your burdens, for I see that there are yet many perils you must face.\n\nFarewell, <name>." }
WordHunterWoW_QuestEN[12153] = { title = "The Iron Thane and His Anvil", description = "Now that you've charged up your war golem, we're going to put all that energy to good use. Activate the golem inside Dun Argol to take control of it.\n\nOur  information about Dun Argol's leader, Iron Thane Furyhammer, suggests his bodyguard protects him from all harm.\n\nThat bodyguard is the construct he travels with, called The Anvil. Disable the construct, and his protection will disappear.\n\nThe thane stays in the building at the top of Dun Argol and supervises production from the bottom level.", objectives = "Using the abilities of your War Golem, defeat Iron Thane Furyhammer, then return to Raegar Breakbrow at Prospector's Point.", completion = "It worked?\n\n<Raegar clears his throat.>\n\nI mean... of course it worked! This is incredible!\n\nYears from now, Explorers' League initiates will hear the story of how Raegar Breakbrow, <name>, and some hunk o' junk golem defeated the thane of Dun Argol!" }
WordHunterWoW_QuestEN[12154] = { title = "Blackout", description = "The large hall at the top of Dun Argol houses the power source for the entire area. If you can destroy the power core, it will cripple Dun Argol for some time.\n\nNo power means no golems, no sentries, and no more lightning armaments.\n\nWhen we were sent up here, they told us these explosives were for excavation, but thanks to Iron Thane Furyhammer, the research has been scrapped. We may as well get some use out of them, though. They're the only thing we have on hand capable of destroying the power core.", objectives = "Use Raegar's Explosives to destroy the Runic Power Core at Dun Argol, then report to Raegar Breakbrow at Prospector's Point.", completion = "<Raegar nods approvingly.>\n\nI can't stand to see explosives go to waste and it'll set our enemies back for sure." }
WordHunterWoW_QuestEN[12155] = { title = "Smash the Pumpkin", description = "This large jack-o'-lantern rests in the middle of the village.  It eyes those who look upon it, betraying a dark menace within.\n\nSmashing the pumpkin reveals an old, scorched holy symbol.", objectives = "Give the Scorched Holy Symbol to the Masked Orphan Matron.", progress = "Yes, <name>?", completion = "You found this inside the Headless Horseman's jack-o-lantern?  It is an old symbol of the Light.  It must have been the Horseman's, before he was cursed and turned into the monster he is today.  Thank you, <name>.  This symbol deserves to be with paladins.  I will make sure they get it.\n\nOh, and I almost forgot!  You have a secret admirer...\n\nOne of the children wanted you to have this.  She was too shy to give it to you herself." }
WordHunterWoW_QuestEN[12156] = { title = "DEPRECAED", description = "I was meant to set off for Silverbrook, northwest of here, about an hour ago.  My military escort appears to be running late.\n\nI'll be damned if this diplomatic mission gets sidetracked because some new recruit overslept.\n\nWe're negotiating a deal with the locals and timeliness is essential.  What do you say?  If you come with me, you'll be well compensated for your troubles.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Escort the Alliance Envoy to the town of Silverbrook. Report to Lieutenant Dumont at the Amberpine Lodge when you've completed this task.I was meant to set off for Silverbrook, northwest of here, about an hour ago. My military escort appears to be running late.\n\nI'll be damned if this diplomatic mission gets sidetracked because some new recruit overslept.\n\nWe're negotiating a deal with the locals and timeliness is essential. What do you say?  If you come with me, you'll be well compensated for your troubles.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[12157] = { title = "The Lost Courier", description = "We're lucky we made it this far, {name}.  We were ambushed by Scourge as soon as we landed.\n\nOne of our men turned out to be a spy for the Cult of the Damned.  Thassarian appears to have more evidence of cultist infiltration.  Apparently it goes all the way to the top.\n\nI've sent one of my best couriers to our outpost in western Dragonblight, but he has not yet returned. I fear he may have fallen to the Scourge. Will you go to Dragonblight and search for him? Courier Lanson is his name.\n", objectives = "Speak to Courier Lanson at Stars' Rest in Dragonblight.", completion = "As I crossed the bridge into Dragonblight a small group of Anub'ar ambushed me! I was surrounded! Those monsters knew I was coming. I barely made it out of there with my flesh intact. This list I hold must be taken to Wintergarde Keep, but I am too badly injured to make the journey." }
WordHunterWoW_QuestEN[12158] = { title = "Hollowstone Mine", description = "I've been meaning to send some of our lads to check out Hollowstone Mine.  Haven't had a chance to yet -- we've had our hands full between the Horde on the west and the iron dwarves to the east.\n\nIf Dumont sent you, though, the least I can do is point you in the right direction.\n\nYou'll find the mine entrance to the northwest, not far from here.  See if you think operations there can be salvaged.  We sure could use the additional resources until our mine in Farshire is operational again. ", objectives = "Look for clues inside Hollowstone Mine northwest of the Westfall Brigade Encampment.", completion = "You've come to help me, haven't you!" }
WordHunterWoW_QuestEN[12159] = { title = "Souls at Unrest", description = "<Petrov looks deeply disturbed, breathing heavily and shifting his gaze nervously around the mine.>\n\nMy comrades... we must put their souls to rest!  I kill them and kill them but.. they just come back!\n\nI've had an idea for a while but I just don't have the heart to do it myself.\n\nMaybe you can do this for me?  Take this lantern and use its oil to burn their remains so they never get up again.\n\nI'll answer your questions later.  Help my friends first!", objectives = "Petrov at Hollowstone Mine wants you to use the Miner's Lantern to burn the corpses of 8 Hollowstone Miners.", completion = "Rest in peace friends!  Do not worry -- I will tell everyone that we never gave up!" }
WordHunterWoW_QuestEN[12160] = { title = "A Name from the Past", description = "It worked!  It worked!  My comrades can finally enjoy their well-earned rest...\n\nI'll stay here and finish the job.  We Hollowstone miners always finish the job -- we never give up!\n\nThat's why Arugal made an example of us.  We wouldn't fall in line, you see?  We wouldn't join his wolfcult!", objectives = "Return to Captain Gryan Stoutmantle at the Westfall Brigade Encampment.", completion = "Curse our luck.  We find the one functioning mine this side of the hills and it's full of Scourge.\n\nNo offense, friend.  But that survivor you found sounds like he's been a little traumatized due to losing his friends.  Arugal's been dead for years... I even saw his grave once." }
WordHunterWoW_QuestEN[12161] = { title = "Ruuna the Blind", description = "Hey there.  I overheard what you were saying to the captain and I just want you to know...  things aren't that simple in Northrend.\n\nJust because someone's dead it doesn't mean they're out of the picture.\n\nSouthwest of here, near Vordrassil Pass, lives a blind woman who goes by the name Ruuna the Blind.  They say she speaks to the dead and has visions of the past and future.\n\nI haven't heard your whole story but it sounds like she'd be right up your alley.", objectives = "Speak to Ruuna the Blind at Ruuna's Camp near Vordrassil Pass.", completion = "You seek knowledge beyond your reach so you've come to me.  I must warn you, stranger, the answers I provide might not be to your liking." }
WordHunterWoW_QuestEN[12162] = { title = "Solstice Village", description = "", objectives = "" }
WordHunterWoW_QuestEN[12163] = { title = "The Evil Below", description = "", objectives = "" }
WordHunterWoW_QuestEN[12164] = { title = "Hour of the Worg", description = "It is time, then, {name}.  Arugal must be defeated.\n\nGet a couple of people you can trust and head for Bloodmoon Isle.  It's just off the coast, east of here.\n\nWe'll hit them fast.  Take out Arugal's lieutenants -- I'll catch up with you when it's time to take out the monster himself.", objectives = "Sasha at the White Pine Trading Post wants you to go to  Bloodmoon Isle and slay Selas, Varlam, Goremaw and the Shade of Arugal.", completion = "We got him good, <name>.  But not good enough.\n\nOne thing's for sure... we won't be seeing him around these parts any longer." }
WordHunterWoW_QuestEN[12165] = { title = "An Intriguing Plan", description = "Prospector Rokar has decided to help us. He's concocted a plan to use the iron dwarves' strength against them.\n\nI must admit, our new 'friend' is more insightful than I'd given him credit for. He's correct in that our numbers are too few for a direct attack.\n\nTravel to Dun Argol, in the snowy regions to the southeast, and capture all the parts of their war golem blueprints from the iron rune-smiths there. Bring the assembled blueprint to Rokar and we'll see if his plan has any merit.", objectives = "Bring the completed War Golem Blueprints to Prospector Rokar at Camp Oneqwah.", progress = "Do... do you have those blueprints I asked for?", completion = "So Tormak's going to go ahead with the plan? I suppose he wouldn't have sent you if he didn't.\n\nOh, bother... Now how am I going to figure out how to put this together under all this pressure?" }
WordHunterWoW_QuestEN[12166] = { title = "The Liquid Fire of Elune", description = "{race} will you assist me?\n\nThe Scourge have moved into Icemist to the north. Wherever they go, they spread their taint, and the creatures of the land suffer.\n\nTake this vial, which is filled with the liquid fire of Elune from the moonwell. Please, use the liquid to cleanse the corpses of the blighted wildlife that you find.", objectives = "Warden Jodi Moonsong at Stars' Rest has asked you to use the Liquid Fire of Elune to cleanse the corpses of 6 Blighted Elk and 6 Rabid Grizzlies.", completion = "We have done what we can for the creatures of the land. Now we must take direct action against those that have caused this!" }
WordHunterWoW_QuestEN[12167] = { title = "Kill the Cultists", description = "The Anub'ar cultists are indirectly responsible for the plaguing of the beasts, and we must put an end to it!\n\nThe fumes that emit from the cultists' suits seep into everything they come near, poisoning and corrupting their surroundings.\n\nYou must go north to Icemist Village and slay them. Bring back any of their suits that survive your assault and I will see to it that they are properly disposed of.", objectives = "Collect 5 Functional Cultist Suits for Warden Jodi Moonsong at Stars' Rest.", progress = "The cultists are a blight upon creation!", completion = "Well done.\n\nI will dispose of these filthy garments by cleansing them in the moonwell and destroying them through the power of the goddess!" }
WordHunterWoW_QuestEN[12168] = { title = "The Favor of Zangus", description = "An inscription on the back of the favor reads,\n\n\"To my favorite pupil,\n\nIf you continue to show promise, I will teach you wonders beyond your imaginings.\n\nIf you do not, I will have you destroyed!\n\nAs ever,\n\nHigh Cultist Zangus\"\n\nNo doubt the warden at Stars' Rest will want to see this.", objectives = "Deliver the Favor of Zangus to Warden Jodi Moonsong at Stars' Rest.", progress = "I sense something foul is near.\n\nIt is upon your person! What is it, <name>?", completion = "So, the leader of the cultists has revealed himself. We have a name.\n\nVanity and pride will be his downfall!" }
WordHunterWoW_QuestEN[12169] = { title = "The High Cultist", description = "I have dreamed of Zangus before but without the context that you have discovered, I knew not what it meant. You have brought clarity to the vision that the goddess has bestowed upon me, and now I know that he can be found within the Pit of Narjun to the north.\n\nYou know your target, {name}. If there's to be an end to the suffering of the land, the high cultist must die!", objectives = "Warden Jodi Moonsong at Stars' Rest has asked you to slay High Cultist Zangus.", completion = "With the high cultist destroyed, the rest of his forces can be mopped up and the land and its creatures will recover.\n\nThank you, <name>. May the goddess illuminate your path." }
WordHunterWoW_QuestEN[12170] = { title = "Blackriver Brawl", description = "The Venture Company abandoned operations shortly after we showed up.  Clearly they were afraid of what we were going to do to their greedy little hides.\n\nWith them gone, their logging camps are up for grabs.  Our war machine is a hungry beast... without renewing our supplies we won't make it to Icecrown.\n\nUnfortunately the Alliance seems to have the same idea and we must make sure we're the ones that prevail.  Head into the logging camp and help us fight the Alliance scum.", objectives = "Raider Captain Kronn wants you to slay 10 Alliance units or players at the Blackriver Logging Camp.", completion = "Well done, <name>.  Our control over the logging camp might not be complete yet, but thanks to you we're one step closer to smashing these Alliance worms." }
WordHunterWoW_QuestEN[12171] = { title = "Of Traitors and Treason", description = "The list I hold must be delivered to High Commander Halford Wyrmbane. He commands the 7th Legion, stationed at Wintergarde Keep on the eastern borders of Dragonblight.\n\nIf any of the traitors on this list are stationed at Wintergarde... it could be catastrophic.\n\nHurry, {name}. Show the document to Palena Silvercloud here at Stars' Rest and explain the nature of your mission. She will put you on her fastest hippogryph to Wintergarde!", objectives = "Show the Alliance Missive to Palena Silvercloud at Stars' Rest.", progress = "Hello, <race>.", completion = "<Palena reads the note.>\n\nYou will take my fastest hippogryph, <race>! This information must be delivered to High Commander Wyrmbane at once!" }
WordHunterWoW_QuestEN[12172] = { title = "Attunement to Dalaran", description = "Welcome, mage.\n\nBy now you must be wondering where Dalaran is and how to get there. I will help you.\n\nBut before I can teach you how to teleport to our great city, you must attune yourself to the ley lines of Northrend. Otherwise, you risk destroying yourself in the process.\n\nTake this attunement crystal and use it in the pit under the surge needle at the Moonrest Gardens to the west. Then you will be ready to learn the spell.", objectives = "The Image of Archmage Modera at Stars' Rest has asked you to become Attuned to the Ley Lines of Northrend.", completion = "Very well. If you are ready, then so am I." }
WordHunterWoW_QuestEN[12173] = { title = "Attunement to Dalaran", description = "Hello, mage.\n\nBy now you must be wondering where Dalaran is and how to get there. I can help you with this if you can survive a simple test.\n\nBefore I teach you how to teleport to our great city, you must attune yourself to the ley lines of Northrend. Otherwise, you will destroy yourself in the process!\n\nTake this attunement crystal and use it in the pit under the surge needle at the Moonrest Gardens to the southwest. Then you will be ready to learn what I have to teach.", objectives = "The Image of Archmage Aethas Sunreaver at Agmar's Hammer has asked you to become Attuned to the Ley Lines of Northrend.", completion = "Very well. If you think you are ready, then let's not waste anymore of my time." }
WordHunterWoW_QuestEN[12174] = { title = "High Commander Halford Wyrmbane", description = "<Palena hands the missive back to you.>\n\nSnowstorm will take you to Wintergarde, {name}. I guarantee you that it will be the fastest flight you've ever taken. Go now!\n", objectives = "Deliver the Alliance Missive to High Commander Halford Wyrmbane at Wintergarde Keep in eastern Dragonblight.", progress = "What have you got there, soldier?", completion = "<The High Commander reads the missive and then crumples it up.>\n\nDo you know where the people on this list are now? Take a look outside, near the front gate. They're the ones hanging from the arches.\n\nGhoul bait..." }
WordHunterWoW_QuestEN[12175] = { title = "Gray Worg Hides", description = "Let me tell you something, mon.  When you get put in charge of outfittin' the armies of the Horde, you go through a lot of hides!\n\nConqueror Krenna, the she-wolf runnin' this place, she gave me a tight deadline.  If I don't outfit her whole regiment by week's end she's gonna have me wrestling bears in the pit.\n\nHelp me out and I'll pay you top price.  I'll be needin' hides from graymist hunters.\n\nYou'll find them all around in pockets to the north, hunting stag.  Remember, mon.  Top price!", objectives = "Hidetrader Jun'ik in Conquest Hold wants you to get 3 Gray Worg Hides from Graymist Hunters in the woods to the north.", progress = "You get dose hides, mon?", completion = "You're a life saver, brother.  If you're interested in more work, there's more where that came from." }
WordHunterWoW_QuestEN[12176] = { title = "A Minor Substitution", description = "Krenna, she be wantin' worg hides for all the outfits.  There's not gonna be enough worg hides for her army, though.  Not now, not ever.\n\nThose worgs -- they be skinny, mon!  Here's what we're gonna do... if you can keep a secret that is.\n\nEast of Voldrune there be grizzly bears as fat as an ogre.  Those large hides -- those we can use!\n\nHurry, brother.  Krenna's not known for her patience.", objectives = "Hidetrader Jun'ik wants you to bring him 6 Grizzly Hides.", progress = "You get those hides, mon?", completion = "I'm in your debt, mon.  Take this as payment." }
WordHunterWoW_QuestEN[12177] = { title = "Jun'ik's Coverup", description = "Ah, we have a small problem.  Grizzly hides... they be brown, mon!\n\nThink... think!\n\nI got it, mon!  Is like this: gray is black an' white all mixed up.  You get me some coal an' some flour, I'll grind it all up and dust the hides with it.  No one will know the better!\n\nBlacksmiths sell coal for smeltin' an' you can get flour from the provisioner. ", objectives = "Bring 1 piece of Coal and 5 Simple Flour to Hidetrader Jun'ik at Conquest Hold in Grizzly Hills.", progress = "You get the stuff, mon?", completion = "Hope for the best, mon." }
WordHunterWoW_QuestEN[12178] = { title = "Delivery to Krenna", description = "This is it, mon.  Let's take these hides to Krenna and see if they pass the test.\n\nLet's hope for both our sakes Krenna doesn't notice anything.", objectives = "Take the Bundle of Hides to Krenna in Conquest Hold.", progress = "Do you have any idea who you're talking to?", completion = "Just who do you take me for?  These hides smell of flour!\n\nThis is a complete insult to the Horde!" }
WordHunterWoW_QuestEN[12179] = { title = "Specialization 1 [PH]", description = "DESCRIPTION: Complete this quest for Specialization 1.You will receive:", objectives = "LOG: Complete this quest for Specialization 1." }
WordHunterWoW_QuestEN[12180] = { title = "The Captive Prospectors", description = "Raegar sent a team of prospectors into Dun Argol to search for artifacts and information about the history of the settlement. Raegar's team never expected Dun Argol to be this heavily populated.\n\nThey're being held captive while the iron dwarves prepare for war. We haven't the men to charge in after them, and Raegar's too busy fantasizing about defeating the irons to be of much help.\n\nIt falls to you, {name}. Any of the irons or their servants could be carrying the keys to the cages holding our men.", objectives = "Free Prospector Gann, Prospector Torgan, and Prospector Varana, then return to Mountaineer Kilian at Prospector's Point.", progress = "Did you locate the missing prospectors?", completion = "<Mountaineer Kilian listens as you relate what the captive prospectors told you.>\n\nThey mentioned Loken and a war against stone giants? You're certain?\n\nSo Raegar's instincts were right. We have to find a way to get in there and learn more about their plans." }
WordHunterWoW_QuestEN[12181] = { title = "Give it a Name", description = "My, my, how long has it been? How long have we been working on this damned plague? Finally, after an eternity of failure, we are blessed with perfection. This... It doesn't even have a proper name yet! This blight... That's it, BLIGHT! This blight will tear down the very fabric of life!\n\n<Harris hands you a vial.>\n\nNow, find the bat handler, Tobias, and show him the specimen. He'll get you on your way to Venomspite.\n", objectives = "Show the Blight Specimen to Tobias Sarkhoff at New Agamand.", progress = "Highly lethal poisonous gas delivery to Venomspite? Step right up!", completion = "Uh, yea, you can go ahead and hold on to that vial, friend. I trust you." }
WordHunterWoW_QuestEN[12182] = { title = "To Venomspite!", description = "I got a special bat all lined up for you, buddy. Fastest and smoothest ride I've got. He'll take you right to Venomspite - in style.\n\nJust hand that vial over to Chief Plaguebringer Middleton once you land. ", objectives = "Deliver the Blight Specimen to Chief Plaguebringer Middleton at Venomspite in eastern Dragonblight.", progress = "You are the delivery boy?", completion = "Oh joyous day! And look, just beyond the mountain to the northeast creeps a whole field of Scourge for us to obliterate!" }
WordHunterWoW_QuestEN[12183] = { title = "Looking the Part", description = "If, as Prospector Varana said, only certain irons are permitted to communicate with this Loken, it'll probably be the overseers who have the privilege.\n\nWe have to get you in there to see what all this is about, but it won't be easy. The first step will be to get a proper uniform for you.\n\nThen, we'll worry about doing your makeup.\n\nFind one of the overseers at Dun Argol, kill him, and bring back his uniform. If you get blood on it, you'll have only yourself to blame.", objectives = "Bring an Overseer's Uniform to Mountaineer Kilian at Prospector's Point.", progress = "Did you get the uniform?", completion = "<Kilian takes the uniform from you.>\n\nThis should do. I won't have time to sew on a little patch with '<name>' embroidered on it or anything, but anyone looking closely at you should be convinced that you're an overseer by the time we're done with you." }
WordHunterWoW_QuestEN[12184] = { title = "Cultivating an Image", description = "Now that we've got the uniform, we've got to get enough information to complete your camouflage.\n\nRaegar brought along this camera to document the team's finds, but I have a different use in mind. I want you to take it with you to Dun Argol and use it to capture the images of iron dwarves.\n\nOf course, your models aren't going to be a cooperative lot, so you may have to, err... subdue them first. Bring back the camera and the images when you're done.", objectives = "Use Kilian's Camera to record the images of 8 Iron Dwarves in Dun Argol, then return to Mountaineer Kilian at Prospector's Point.", progress = "Did you get those snapshots?", completion = "Good, these should do. Now, to create a kit to pass you off as a convincing iron dwarf." }
WordHunterWoW_QuestEN[12185] = { title = "Put on Your Best Face for Loken", description = "Using the images you've captured, I've created everything you need for your overseer disguise kit. You'll make a fine iron dwarf, if I do say so myself.\n\nTake the kit with you to Dun Argol, use it to disguise yourself, then go to the easternmost building on the broad middle tier of the city.\n\nThere, you should see a pedestal where the thane and overseers receive their orders from this Loken. Activate it while disguised and learn all you can from the communication.", objectives = "Disguise yourself as an Iron Rune Overseer, intercept the message from Loken, then report to Mountaineer Kilian at Prospector's Point.", completion = "Could it be that Loken isn't really exaggerating? The titans' stone and iron sons fighting against each other for control of the ancient city of Ulduar. This is madness, <name> and it could destroy our only chance to learn the true history of dwarvenkind!" }
WordHunterWoW_QuestEN[12186] = { title = "FLAG: Winner", description = "", objectives = "" }
WordHunterWoW_QuestEN[12187] = { title = "FLAG: Participant", description = "", objectives = "" }
WordHunterWoW_QuestEN[12188] = { title = "The Forsaken Blight and You: How Not to Die", description = "The details behind the functionality of the blight are hardly important. All you need to know is that it does the job it was designed to do. I have managed to synthesize a strain of the blight that is inert.\n\n<Middleton uncorks a vial and inhales.>\n\nSee, my body is still, mostly, intact. Now mix this with a reactive agent and we'd all be turned to shapeless piles of goo.\n\nOn the beach south of here you will find pathetic specters of Alliance soldiers past. Slay them and bring me ectoplasmic residue.", objectives = "Chief Plaguebringer Middleton at Venomspite in Dragonblight wants you to bring him 10 Ectoplasmic Residue.", progress = "The residue will be used as the reactive agent to activate the blight!", completion = "This will do nicely, <name>. Did those pathetic whelps put up a fight or did they just shower you with ghostly tears of sorrow?\n\nAh, they get so emotional..." }
WordHunterWoW_QuestEN[12189] = { title = "Imbeciles Abound!", description = "The shipment from New Agamand was to arrive at Venomspite last week and then be delivered to me after some simple field tests. It is a Horde imperative - the last piece of the \"victory puzzle.\"\n\n<Sintar sighs.>\n\nIt is quite disheartening to know that you are surrounded by imbeciles and incompetent boobs!\n\nYou must travel to Venomspite, near the eastern border of Dragonblight. Find that buffoon, Middleton, and let him know that I am waiting on the package.", objectives = "Travel to Venomspite in Dragonblight and speak with Chief Plaguebringer Middleton.", completion = "We ran into a little - MINOR - problem. Everyone that tried handling the blight vaporized. We're working on adjusting the formula a tad so it doesn't instantly kill you for looking at it sideways. The good news is that I think I've almost got it!" }
WordHunterWoW_QuestEN[12190] = { title = "Say Hello to My Little Friend", description = "Harkor's gunna drop a gold brick when he sees these choice ingredients. All that be left is gettin' them to him.\n\nHe's camped out on the eastern coast near dem haunted ruins - Drakil'jin, dey be called.\n\nYou'll likely be makin' it there before I can finish up with these corpses... unless, ya think you'd rather try your hand at embalming?", objectives = "Prigmon wants you to bring Harkor's Ingredients to Harkor at Harkor's Camp.", progress = "What can I do fer ya?", completion = "Well now! Good ol' Prigmon sent ya did he?\n\nThis should make fer some mighty fine eatin'. Needs just a couple things..." }
WordHunterWoW_QuestEN[12191] = { title = "Chug and Chuck!", description = "Hey, you look like you've got a good arm!\n\nWe like to keep things lively around camp, and nothing says fun like a good old-fashioned mug toss!\n\nThink you've got the aim to hit S.T.O.U.T.? Just grab a sampler, take a sip, and see if you can land a hit. It's trickier than it looks, but that's half the fun. Step right up and give it a shot!", objectives = "Use the Alcohol-Free Brewfest Sampler to hit S.T.O.U.T. 5 times.", progress = "Chug from the mug, then chuck the mug at S.T.O.U.T. I think he can withstand the pounding. I wouldn't have stol.. er... built him if he couldn't!", completion = "Wow...  S.T.O.U.T. didn't break... Hmm... Who would have guessed?\n\nI mean, hey, you did it!  Your aim is true, or at least true enough to help guard the camp.  I think you're ready now to take on the Dark Irons if they show up again." }
WordHunterWoW_QuestEN[12192] = { title = "This One Time, When I Was Drunk...", description = "The Dark Irons took a beating!  As they rushed back to the Grim Guzzler, a portion of their transport fell off.  More importantly, you managed to keep the camp safe... today.\n\nHead over to Bizzle and explain your heroic triumph over the Dark Iron dwarves.", objectives = "Talk to Bizzle Quicklift in the Brewfest camp.", completion = "So you managed to stop the Dark Irons... While drunk too?  That, <class>, is truly the spirit of Brewfest!  I guess in keeping with the spirit of Brewfest you want your prize tokens.\n\nThanks for your help, <name>.  Enjoy the rest of Brewfest." }
WordHunterWoW_QuestEN[12193] = { title = "Say, There Wouldn't Happen to be a Souvenir This Year, Would There?", description = "Brewfest isn't just about racing rams, it's also about drinking!  When you have a moment, take this voucher to Belbi Quikswitch.  She's near the back of the Brewfest camp.  If you can't see her, don't worry, she'll be sure to see you.\n\nIn any case, take this voucher to her to get your free Brewfest stein.  She'll also be more than happy to handle any and all other Brewfest transactions.", objectives = "Redeem the Brewfest Stein Voucher with Belbi Quikswitch in the Brewfest camp." }
WordHunterWoW_QuestEN[12194] = { title = "Say, There Wouldn't Happen to be a Souvenir This Year, Would There?", description = "Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.", objectives = "Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp." }
WordHunterWoW_QuestEN[12195] = { title = "The Unexpected 'Guest'", description = "A recent hunting expedition brought back more than just game.\n\nThey encountered a wounded dwarf fleeing the iron dwarf stronghold of Dun Argol. He may have information we can use to strike at our ancient enemy, but before he's of any use to us, we must bring down his fever.\n\nThe horns of the silvercoat stags, who roam the nearby forest, have long been used to make healing poultices. If you can bring enough of the horns to me, we'll see if the poultice can bring our 'guest' around.", objectives = "Bring 5 Mature Stag Horns to Tormak the Scarred at Camp Oneqwah.", progress = "Did you bring the horns?", completion = "These should serve. Now, let's see if it works." }
WordHunterWoW_QuestEN[12196] = { title = "From the Ground Up", description = "We don't have enough time for me to forge the parts myself, but the foundries over at Dun Argol, to the southeast, are working day and night to churn out golem parts.\n\nI think you should go back there and pick up enough of them for me to make a golem from this blueprint.\n\nThey're probably scattered around any of the buildings where the iron rune-smiths are working.\n\nPlease hurry, {name}. That Tormak looks like he's just waiting for an excuse to carry out his threat!", objectives = "Bring 8 War Golem Parts to Prospector Rokar at Camp Oneqwah.", progress = "D-did you b-b-bring those golem parts?", completion = "<Rokar wipes his forehead with the back of his hand.>\n\nOh, thank the Light. He was threatening not to feed me until you returned. Let's sort through this pile of parts and see what we can make." }
WordHunterWoW_QuestEN[12197] = { title = "We Have the Power", description = "Well, we've got the shell of a golem, but that's not good enough for Tormak. He doesn't realize that these things don't just come together and miraculously start working! We're going to need power cells to animate it.\n\nWhen I was in Dun Argol, I noticed that Rune-Smith Durar and Rune-Smith Kathorn were the ones who manufactured the cells. We'll need one from each to power our golem.\n\nYou should be able to find each rune-smith in his workshop on the central level of Dun Argol.", objectives = "Bring Durar's Power Cell and Kathorn's Power Cell to Prospector Rokar at Camp Oneqwah.", progress = "Do you have those power cells?", completion = "<Rokar takes the batteries from you.>\n\nThese are low, but they'll be enough to start up the golem. He's nowhere near ready for battle, though." }
WordHunterWoW_QuestEN[12198] = { title = "... Or Maybe We Don't", description = "The golem's cells have just enough power to run it at the lowest levels, but it can't power any of its combat systems.\n\nThe good news is that the perimeter of Dun Argol is patrolled by lightning sentries. We should be able to use their power to charge up the golem's weapon systems.\n\nBring the golem with you, take it close to them, it will absorb the power as the sentries die.", objectives = "Charge your War Golem with the energy from 10 Lightning Sentries and return to Prospector Rokar at Camp Oneqwah.", progress = "Did you get that golem charged? Tormak is getting impatient again...", completion = "Well, now Tormak can't complain anymore. This baby's as ready as I can make it.\n\nAfter you tear your way through Dun Argol with it, that overgrown cow'll have to release me." }
WordHunterWoW_QuestEN[12199] = { title = "Bringing Down the Iron Thane", description = "Now that the golem is fully charged, it can be used against the leader at Dun Argol.\n\nWhen I observed Iron Thane Furyhammer, he was always guarded by a personal golem that shielded him from all harm.\n\nThat construct, called The Anvil, can be disrupted, causing him to drop the shield. Use your golem's EMP ability to do just that. You'll be able to activate and take control of your golem inside Dun Argol.\n\nThe thane is in the main plant at the top and supervises production from the bottom level.", objectives = "Using the abilities of your War Golem, defeat Iron Thane Furyhammer, then return to Tormak the Scarred at Camp Oneqwah.", progress = "Please tell me it worked...", completion = "So the prospector made good on his promises? Good. I was beginning to wonder if all of this scrounging for bits of metal and stealing building materials would amount to anything.\n\nIt's a shame he's of no further use to us." }
WordHunterWoW_QuestEN[12200] = { title = "Emerald Dragon Tears", description = "With an inert specimen of the blight compound complete and the activating agent in hand there only remains a need for a suitable shell to house the components.\n\nSouthwest of here, on the shores of central Dragonblight, is where you will find the Emerald Dragonshrine. Within the shrine you will find the hardened remnants of a green dragon's tear drop. I don't know the whole story, but apparently they cry a lot right before they die. Go figure.\n\nGo to the Emerald Dragonshrine and gather tears.", objectives = "Chief Plaguebringer Middleton at Venomspite in Dragonblight wants you to collect 8 Emerald Dragon Tears.", progress = "Fortunate it is that we have a location nearby holding a surplus of emerald dragon tears. I would have had to send you to Feralas otherwise.", completion = "I do believe that the blight is now ready for a field test. Fortuitously, the dread citadel, Naxxramas, is laying siege to Wintergarde Keep. From beneath the very earth that Wintergarde was built upon rise the living dead, eager to do the bidding of Kel'Thuzad.\n\nThe Alliance are, of course, outmanned and outgunned. The people laid to rest in the Wintergarde Mausoleum awaken, hungering for flesh!\n\nPerhaps we shall give them a taste of the blight, yes?" }
WordHunterWoW_QuestEN[12201] = { title = "The Overseer's Shadow", description = "It sounds like this Loken is the mastermind behind the sudden preparations for war on the part of the iron dwarves.\n\nOnly the highest ranking irons are likely to have access to him, so we'll have to make you into an overseer to find out what's going on in there.\n\nI have a plan, for that, but we'll need some supplies.\n\nFind one of the iron rune overseers at Dun Argol, to the southeast, kill him, and bring back his uniform. ", objectives = "Bring an Overseer's Uniform to Scout Vor'takh at Camp Oneqwah.", progress = "Did you get the uniform?", completion = "This should work, but there's still the matter of the rest of your disguise. Even those dimwitted metal dwarves will recognize an impostor with a stolen suit." }
WordHunterWoW_QuestEN[12202] = { title = "Cultivating an Image", description = "Now we have to finish the job of making you as repulsive as those iron dwarves.\n\nThe best way to do that is to base your disguise on the ugly mugs of real iron dwarves.\n\nWhen Tormak's hunting party discovered that wayward prospector, they took the camera he carried. Now, I suppose, we'll get the chance to use it.\n\nTake it with you to Dun Argol, kill some iron dwarves, and record their likenesses in this device. Bring it back once you have enough examples.", objectives = "Use Rokar's Camera to record the images of 8 Iron Dwarves in Dun Argol, then return to Scout Vor'takh at Camp Oneqwah.", progress = "Did you get those snapshots?", completion = "These should serve. By Garrosh, these creatures are ugly." }
WordHunterWoW_QuestEN[12203] = { title = "Loken's Orders", description = "I've created everything else you'll need for your overseer disguise kit. Try not to retch when you put it on. I took pains to make it as true to reality as possible.\n\nTake the kit with you southeast to Dun Argol, use it to disguise yourself, then go to the easternmost building on the broad middle tier of the city.\n\nThere, you should see a pedestal where the thane and overseers receive their orders from this Loken. Activate it while disguised and learn all you can from the communication.", objectives = "Disguise yourself as an Iron Rune Overseer, intercept the message from Loken, then report to Scout Vor'takh at Camp Oneqwah.", completion = "So he means to foment civil war between the factions of the titans' creation? Why does this titan city of Ulduar mean so much to him? I suppose this is what Kurun and his giants are hoping to prevent.\n\nWell, I doubt we're in a position to keep the giants from fighting each other, but we can find a way to use this to our advantage. I must inform our leaders at once." }
WordHunterWoW_QuestEN[12204] = { title = "In the Name of Loken", description = "The iron dwarves stand as one of the fiercest and most coordinated foes in Northrend. Wherever we have traveled, they have battled us with the name of Loken on their lips.\n\nWe must learn who this Loken is and what he seeks. The locals may be of help.\n\nTo the northeast, at the Redwood Trading Post, a human named Hugh Glass peddles his wares. Further east, at the Ruins of Tethys, you'll find a stone giant named Gavrock. Ask them about this Loken. They've got to know something of use.", objectives = "Speak with Hugh Glass and Gavrock about Loken, then report your findings to Scout Vor'takh at Camp Oneqwah.", completion = "So he is the mastermind behind the iron dwarves? We must find out what he has been ordering the iron dwarves of Dun Argol to do." }
WordHunterWoW_QuestEN[12205] = { title = "WANTED: The Scarlet Onslaught", description = "By order of High Executor Wroth all members of the illegal organization known as the Scarlet Onslaught are to be put to death immediately.\n\nNo quarter is to be offered, and those proceeding to action upon this decree should be aware that any who are captured by the humans will be left to die, or worse!\n\nIn the High Executor's words, \"Paint the snow red with their blood!\"", objectives = "Kill 20 members of the Scarlet Onslaught and report to High Executor Wroth at Venomspite.", completion = "Very well done, <race>. I trust that you were cleverly vicious in your slaying?\n\nLet's see, how much I can offer you from the coffins... er, excuse me, coffers?" }
WordHunterWoW_QuestEN[12206] = { title = "Blighted Last Rites", description = "Have you read the wanted poster? What is the high executor thinking?!\n\n<Vicky looks around and continues in hushed tones.>\n\nWe can't very well have those Scarlet Onslaught idiots being raised by their priests, or worse, rising as the Scourge, now can we?\n\nNo, I'm in total agreement with you, we have to do something about the corpses.\n\nI have just the thing. Take this blight that we just created and test it on the prisoner in the cage right here.\n\nNo muss, no fuss, no returning enemies.", objectives = "Apothecary Vicky Levine at Venomspite has asked you to test the Flask of Blight upon the Scarlet Onslaught Prisoner.", progress = "Did you do it?\n\nHey, I forgot to tell you that you probably shouldn't let any of that stuff get on you! It's nasty, and you'll never get the stains out, let alone have a hell of a time healing the bubbled-away fleshy bits.", completion = "WHAT?! That's impossible! We've perfected the blight. It has a one-hundred percent lethality.\n\n<The apothecary wrings her hands, concern crossing her unliving visage. Clearly frustrated, she continues in an angry tone.>\n\nThis is just really odd. Hand me that flask, <class>. I'm not going to be known as the apothecary that ruined everything!" }
WordHunterWoW_QuestEN[12207] = { title = "Vordrassil's Fall", description = "Long ago, powerful druids planted a tree to the northeast of here.\n\nIt was called Vordrassil and it was to be a world tree.  It is not known why, but after the tree was fully grown, the druids decided it needed to be destroyed.\n\nEver since we arrived here, the earth has spoken to me, {name}.  Its cries of pain come from the places where Vordrassil's remains fell on the ground.\n\nCorrupting ooze roams those places.  Bring me samples of it so we may begin to heal the land.", objectives = "Windseer Grayhorn in Conquest Hold wants you to go to Vordrassil's Limb, Vordrassil's Heart or Vordrassil's Tears and obtain 6 Slime Samples from the Entropic Oozes.", progress = "Have you obtained the samples, <name>?", completion = "This slime is foul with a darkness far more ancient than their worldly forms would indicate.  The land itself has a memory of this evil for as long as it has existed.\n\nWe must find out more, <name>." }
WordHunterWoW_QuestEN[12208] = { title = "Good Troll Hunting", description = "Good for nothing wretches!\n\nThey could have had it easy. We extended our hand in peace. All they had to do was give us passage through Drak'Tharon and we'd have let them be.\n\nBut no, the prideful little ice trolls decided that they wanted it rough. Now they'll be destroyed and we'll pass through their precious keep to Zul'Drak anyway.\n\nWe've contracted a gang to deliver us captured trolls. Talk to Samir if you want in on the action. You can find him to the northwest of here, due south of Zeb'Halek.", objectives = "Sergeant Thurkin told you to speak to Samir at Granite Springs.", completion = "Here to get in on the bounty action, eh?" }
WordHunterWoW_QuestEN[12209] = { title = "Materiel Plunder", description = "Ah good, new meat. Do you wish to prove yourself, new meat?\n\nThe Scarlet Onslaught, the most zealous and racist of the Scarlet Crusade, are in our backyard to the south. If we're going to fight them, we'll need more armor and weapons than I can make in such a short time.\n\nWhy don't we take theirs?\n\nMore to the point, why don't YOU take theirs?", objectives = "Quartermaster Bartlett at Venomspite has asked you to steal 8 Scarlet Onslaught Armor and 8 Scarlet Onslaught Weapons.", progress = "I'll take what armor and weapons you can steal for me, new meat.\n\nThough they'll be of inferior quality to what I can make here, it's better than nothing.", completion = "You do not smell so fresh now, new meat.\n\nVery well, all of this will do. By what name might I call you, <class>?" }
WordHunterWoW_QuestEN[12210] = { title = "Troll Season!", description = "You, {race}! No sense standing around here when there's work to be done!\n\nDrak'Theron Keep is the most direct route to Zul'Drak. We MUST capture it to ensure safe passage for the Alliance. But until we get the numbers to make an assault, we'll have to content ourselves in thinning out the ice trolls and collecting intel.\n\nTo that end, we've conscripted a gang of thugs to capture and deliver live trolls for interrogation. Travel northwest and speak with Samir at Granite Springs. He'll direct you further.", objectives = "Lieutenant Dumont at Amberpine Lodge wants you to speak to Samir at Granite Springs.", completion = "Here to get in on the bounty action, eh?" }
WordHunterWoW_QuestEN[12211] = { title = "Let Them Not Rise!", description = "I don't understand it. The blight should have worked!\n\nNo sense worrying about it now.\n\n<The apothecary seems relieved for some reason.>\n\nThough it doesn't work on the Onslaught for some strange reason, we still need to keep their priests from raising them.\n\nI have another idea, one that their corpses shouldn't have any protection from.\n\n{name}, take a container of my rats and unleash them upon any Onslaught corpses you come across at New Hearthglen. I starve the vermin, so they should be voracious!", objectives = "Apothecary Vicky Levine at Venomspite has asked you to use her Container of Rats to pick clean the corpses of 15 Scarlet Onslaught members at New Hearthglen.", completion = "Oh good! For a moment I thought I was going to have to test the rats out on someone to make sure that they weren't defective.\n\nProgress, finally!" }
WordHunterWoW_QuestEN[12212] = { title = "Replenishing the Storehouse", description = "G'day, {class}.\n\nThe good lieutenant here says that there's been a Horde raid on our storehouse that's left our food supply dangerously low.\n\nNo doubt we'll make those cretins pay, but first we need to focus our attention on restocking. My men are doing all they can, but we're going to need every able body to contribute if we're to avert a crisis.\n\nYou should have no trouble harvesting venison from the local stag in these parts. Happy hunting!", objectives = "Master Woodsman Anderhol at Amberpine Lodge wants you to kill Tallhorn Stag and collect 8 Succulent Venison.", progress = "How goes the hunt, <race>?", completion = "These are some choice pieces of meat!" }
WordHunterWoW_QuestEN[12213] = { title = "The Darkness Beneath", description = "Something... dark... happened to the tree Vordrassil.  After the druids decided to destroy it, its hollow remains grew roots deep into the ground.\n\nI want you to go to the three locations to the northeast where the tree's trunk shattered and go as far beneath the ground as you can.\n\nUse this orb once you get there to get an imprint of the energy surrounding the area.  This might shed some light on what happened to Vordrassil and why it failed to become a world tree.", objectives = "Windseer Grayhorn in Conquest Hold wants you to go to Vordrassil's Heart, Vordrassil's Tears and Vordrassil's Limb and use the Geomancer's Orb in the depths beneath the surface.", completion = "This orb... it has been tainted by... a purely evil force.\n\nWhatever else I might learn from studying this energy, one thing is certain.  I must destroy this orb as soon as possible.  Its corrupting force is just too strong." }
WordHunterWoW_QuestEN[12214] = { title = "Fresh Remounts", description = "Hello. I am Hansel. Pleased to meet you, sir.\n\nThe high executor came to me and said, 'Hansel, I want you to get us new mounts.'\n\nWhere does he think dreadsteeds come from? The ground?\n\n<whispering> Actually, they do if you can find a horse graveyard.\n\nBut we don't have one of those, so what we need you to do is go south to New Hearthglen, kill the knights, take their riding crops, and steal their warhorses.\n\nRide the horse back to me here and hand over the reins, if you would.", objectives = "Hansel Bauer at Venomspite has asked you to steal 3 Onslaught Warhorses and deliver them to him, handing over the reins when you do so.", progress = "I'm sure glad that you came around. I was afraid that I was going to have to go down there and rustle them up myself.", completion = "Ah, nothing makes me happier than a job well done.\n\nYou've done Venomspite a great service in acquiring these horses, <class>." }
WordHunterWoW_QuestEN[12215] = { title = "Them or Us!", description = "As if we didn't have enough to concern ourselves with....\n\nWith the present food crisis, we find ourselves competing for food with the local worgs. The situation is becoming more dire, and I fear that if we don't address the issue immediately we'll soon find ourselves with nothing to hunt.\n\nScour the forest, {race}. Kill any graymist you find. Recent reports have sighted a concentration of them on the other side of the river west of here.", objectives = "Anderhol at Amberpine Lodge wants you to find and kill 6 Graymist Hunters in Grizzly Hills.", completion = "Good work, <class>.\n\nThis should help ensure that the wildlife in these parts ends up where it should - roasting over our fires." }
WordHunterWoW_QuestEN[12216] = { title = "Take Their Rear!", description = "We've all been working hard and it's beginning to pay off, but we're still far from our goal. We need much more meat than we have and it's growing clear that the local stag population won't be enough by itself.\n\nI'm afraid we need you to turn your attention to more dangerous prey - the grizzlies that give this region its name. They're plentiful, and they're well fed from the abundant fish that swim in these streams.\n\nBe safe, {class}!", objectives = "Anderhol at Amberpine Lodge wants you to collect 8 Grizzly Flanks from the Grizzly Bears in Grizzly Hills.", progress = "The mighty <class> has returned!", completion = "Outstanding!\n\nOur stores are nearly replenished now. You've done your part, <name>." }
WordHunterWoW_QuestEN[12217] = { title = "Eagle Eyes", description = "Well, {name}, we've determined how the Horde was able to locate our hidden stores of food.\n\nIt turns out that they were binding their sight to the unsuspecting eagles that soar above the trees here. Using eagle vision, they were able to effectively spy on our every action.\n\nBy order of the lieutenant, we've got to hunt down these majestic birds in order to thwart our enemy.", objectives = "Anderhol in Amberpine Lodge wants you to kill 5 Imperial Eagles and then report back to him.", completion = "A somber task, I know. But we can rest easier now knowing the enemy's eyes are no longer upon us." }
WordHunterWoW_QuestEN[12218] = { title = "Spread the Good Word", description = "Before I can ship you off to Doctor Malefious with the good news, you will have to run a simple field test of the blight with the modifications I have made.\n\nThe hungering dead stream out from what remains of Old Wintergarde. Commandeer a vehicle from the east gate and drive it northeast through Vengeance Pass until you reach the twin towers at the southeastern edge of Wintergarde. Drop the blight bomb on the undead that cover the area. Report back to me with the results!", objectives = "Chief Plaguebringer Middleton at Venomspite in Dragonblight wants you to use the Forsaken Blight Spreader's Blight Bomb to destroy 30 Hungering Dead on the outskirts of the Carrion Fields.", completion = "As much as it irritates me that we may have assisted the Alliance, I declare the field test a success! Next stop: Agmar's Hammer!" }
WordHunterWoW_QuestEN[12219] = { title = "The Failed World Tree", description = "My ancestors once planted a tree in the middle of the Grizzly Hills.\n\nIt was called Vordrassil and it was to become a world tree.\n\nFor reasons long forgotten, after the tree was fully grown, they decided it needed to be destroyed.  Its giant trunk splintered at three locations in the area to the north.\n\nWhere the tree touched the ground, foul ooze began to crawl the earth.  Bring me slime samples so I can begin my work and the earth can be healed.", objectives = "Hierophant Thayreen at Amberpine Lodge wants you to go to Vordrassil's Limb, Vordrassil's Heart or Vordrassil's Tears and obtain 6 Slime Samples from the Entropic Oozes.", progress = "Have you gathered the samples, <name>?", completion = "The slime is not natural, <name>.  Its very nature is corrupt and... evil.\n\nWe must find out more." }
WordHunterWoW_QuestEN[12220] = { title = "A Dark Influence", description = "When the tree Vordrassil fell, its hollow remains grew roots deep into the ground.\n\nI want you to go north of here to the three locations where the trunk shattered and go as far beneath the ground as you can.  You'll find them west of Grizzlemaw.\n\nUse this orb once you get there to get an imprint of the energy surrounding the area.  If we're to heal the land, we must first find out what caused Vordrassil to fail as a world tree all those years ago.", objectives = "Hierophant Thayreen at Amberpine Lodge wants you to go to Vordrassil's Heart, Vordrassil's Tears and Vordrassil's Limb and use the Geomancer's Orb in the depths beneath the surface.", completion = "The energy in the orb is... overpowering...\n\nA dark force has tainted the ground near Vordrassil's remains.  We will need to investigate more." }
WordHunterWoW_QuestEN[12221] = { title = "The Forsaken Blight", description = "I have prepared a package that must be delivered to Doctor Sintar Malefious at Agmar's Hammer. The contents of the package include the final blight specimen along with instructions on preparation and samples of the reactive agent.\n\nYou will find Agmar's Hammer in western Dragonblight. Just look for the black, jagged metal orc buildings - that will be Agmar's Hammer.\n", objectives = "Deliver The Forsaken Blight to Doctor Sintar Malefious at Agmar's Hammer.", progress = "About bloody time!", completion = "<Doctor Malefious looks through the contents of the package.>\n\nGlorious! Exactly to specifications!\n\nHere is your payment, <name>. Keep what you've seen and done to yourself. This work is all classified - information is given out on a need to know basis." }
WordHunterWoW_QuestEN[12222] = { title = "Secrets of the Flamebinders", description = "Even as we attempt to fight off the Horde, the Dragonflayer tribe musters in their village of Voldrune, near the coast to the south.\n\nThe most powerful warriors in the village are granted flame-imbued talismans that give them the ability to control powerful, savage proto-drakes. If we can gain control of one of these drakes, perhaps we can use it to neutralize the threat posed by Voldrune.\n\nThe Dragonflayer flamebinders create the talismans and imbue them with power. Kill them and take the talismans.", objectives = "Bring 3 Flame-Imbued Talismans to Woodsman Drake at Amberpine Lodge.", progress = "Did you collect those talismans?", completion = "With the talismans in hand, the drake will have no choice but to obey you. I can't wait to see the look on the thane's face when he realizes you've commandeered his proto-drake." }
WordHunterWoW_QuestEN[12223] = { title = "Thinning the Ranks", description = "There's a flurry of activity down in Voldrune village to the south. Thane Torvald Eriksson and his huscarls are preparing for war. With most of our men in the field dealing with the Horde's treachery, Amberpine will be vulnerable.\n\nTravel to Voldrune, which is near the southern coast, and show those Dragonflayers we're no soft target.\n\nSlay as many of the huscarls as you can find. Make them think twice about taking advantage of our conflict with the Horde.", objectives = "Kill 12 Dragonflayer Huscarls and return to Woodsman Drake at Amberpine Lodge.", completion = "Well done, <name>. Now, we must follow through and press the advantage." }
WordHunterWoW_QuestEN[12224] = { title = "The Kor'kron Vanguard!", description = "You have done well, brother. All that you have faced, you have done as a champion of the Horde. The Scourged Anub'ar of Azjol-Nerub, crushed under your foot! The taunka, brave and powerful new members of the Horde, because of you! Our super-weapon against the Scourge, tested and perfected by you!\n\nThe time has come, the moment is now - our elite soldiers at the Wrathgate need you. The son of Saurfang awaits your arrival at the Kor'kron Vanguard. Go now, northeast to the Wrathgate.", objectives = "Report to Saurfang the Younger at the Kor'kron Vanguard.", completion = "Lok'tar ogar! I have heard much about you, <name>. Your battle scars run deep - a testament to your dedication and power!\n\nWith the flanking attacks of the Lich King crushed in both the west and east, only the forces at the gate remain. We gain ground each day, soon to break through this wall and into Icecrown!\n\nOnce we stop the skeletal dragons, Highlord Fordragon and I will take the field." }
WordHunterWoW_QuestEN[12225] = { title = "Mmm... Amberseeds!", description = "Your stomach growls as the pungent smell of hearty nuts draws your attention to the bucket of seeds.\n\nSome thoughtful soul has obviously left these complimentary morsels here to rejuvenate weary visitors. Grateful, you take the remaining few and devour them.\n\nThe seeds do not disappoint. Finding yourself hungry for more, you set out to discover their origins....", objectives = "Speak with Master Woodsman Anderhol in Amberpine Lodge.", completion = "You did what!!!\n\nThose were Amberseeds! And that was an entire harvest's worth!\n\nThose magical seeds may have been the answer to our food crisis. Believe me when I tell you, <name>, you're going to make this right!" }
WordHunterWoW_QuestEN[12226] = { title = "Just Passing Through", description = "We must act quickly, {race}! We can't risk letting those precious seeds become fully digested. They need to come out, NOW.\n\nForage up some blackroot from the riverbank just west of here and I'll make you a purgative that should get things moving.\n\nHurry now! And remember, you brought this upon yourself....", objectives = "Anderhol at Amberpine Lodge wants you to bring him 5 Blackroot Stalks.", progress = "Have you found the blackroot?", completion = "These should do just fine...\n\n<Anderhol deftly twists the stalks, collecting their slick fluids in a tiny vial.>\n\nThere we go, now it's time to get down to business." }
WordHunterWoW_QuestEN[12227] = { title = "Doing Your Duty", description = "Alright, {race}. Here's the juice.\n\nIt works immediately, so don't use it until you're safely inside the outhouse.\n\nNow go get me those seeds!", objectives = "Anderhol in Amberpine Lodge wants you to take the Anderhol's Slider Cider and use the nearby outhouse to retrieve the Partially Processed Amberseeds.", progress = "Got those seeds for me yet, <race>?", completion = "Well, <name>? Everything come out okay?\n\nHmm, looks like we caught 'em just in time...." }
WordHunterWoW_QuestEN[12228] = { title = "Reacquiring the Magic [PH]", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[12229] = { title = "A Possible Link", description = "Not long ago we sent an expedition to the east, where it was attacked by crazed furbolgs.  One of the survivors described slaying one of them and its body expelling a dark slimy substance.\n\nFor thousands of years, the furbolgs in this region have been peaceful.  It is possible that there is a link to the furbolgs' behavior and the dark energy we were able to detect earlier.\n\nBring me samples of the furbolgs' blood.  You will find them to the east in the Rage Fang Shrine and the Heart's Blood Shrine.", objectives = "Windseer Grayhorn in Conquest Hold wants you to obtain 8 Crazed Furbolg Blood from the Furbolgs at Heart's Blood Shrine and Rage Fang Shrine.", progress = "Have you obtained the blood samples, <name>?", completion = "This blood carries the same taint as the slime you obtained earlier... this does not bode well, <name>." }
WordHunterWoW_QuestEN[12230] = { title = "Stealing from the Siegesmiths", description = "I'm tasked with the destruction of the Scarlet Onslaught's ballistae. Unfortunately, the apothecaries and I are at odds on the use of our resources, so I've nothing to destroy them with!\n\nTo the northeast are the Carrion Fields. The Scourge siegesmiths there at their forge and meat wagons are demolition masters.\n\nLuckily for us, they also leave their bombs lying about. \n\nI want you to retrieve them for me, off of the ground or the siegesmiths, I don't care which.", objectives = "Deathguard Molder at Venomspite has asked you to retrieve 6 Siegesmith Bombs.", progress = "You'd think that they'd let me make use of the blight spreaders... maybe load them up with something nasty to destroy the ballistae.\n\nBut no, they tell me that they're only for special missions.\n\nWhatever!", completion = "<The deathguard rubs his hands together in anticipation.>\n\nExcellent. Their loss is my... our gain!\n\nYou didn't have trouble with any of these along the way? Some of them look rather unstable. I may be undead, but I value my existence!" }
WordHunterWoW_QuestEN[12231] = { title = "The Bear God's Offspring", description = "It is possible that the furbolg of Grizzly Hills have the same taint that plagued Vordrassil.  They've been involved in a deadly tribal war recently after years of peaceful coexistence.\n\nThe shrines that they guard to the east are home to Ursoc's offspring.\n\nIf the corruption has affected the furbolg, it is possible that because of their lineage, Kodian and Orsonn have remained unharmed.\n\nIf that's the case, find them and listen to what they have to say.", objectives = "Windseer Grayhorn in Conquest Hold wants you to speak to Orsonn at the Ragefang Shrine and Kodian at the Heart's Blood Shrine.", completion = "Ursoc's children are wise.  Their words explain much of what we've seen so far." }
WordHunterWoW_QuestEN[12232] = { title = "Bombard the Ballistae", description = "At last, our chance to strike at their siege engines! Don't flub it.\n\nI kid.\n\nA little.\n\n{class}, bombard New Hearthglen's ballistae with these bombs.\n\nWe'll show the Royal Apothecary Society how it's done old style. No concoctions required!", objectives = "Deathguard Molder at Venomspite has asked you to use the Siegesmith Bombs to bombard 5 New Hearthglen Ballistae.", completion = "Oh happy day!\n\nBy not using the time and resources of the apothecaries to get the job done, I'm sure to attract the attention of the high executor!\n\nThinking outside the box, that's what I'm all about. Yes, yes, you had a hand in helping too.\n\nHere, if I give you something will you promise to not mention your part in all of this?" }
WordHunterWoW_QuestEN[12233] = { title = "[Depricated]Sewing Your Seed", description = "No, no... You hold on to these.\n\nYou didn't actually expect me to handle them after all of that did you?\n\nhere's what you're going to do....", objectives = "" }
WordHunterWoW_QuestEN[12234] = { title = "Need to Know", description = "I need to know what New Hearthglen is up to.\n\nI want you to steal their orders of the day so that I can find that out.\n\nHead south and in their abbey, in their barracks, and on their beach, find those daily plans!\n\nJust in case you're confused, the barracks is the large building right next to the smithy.", objectives = "Spy Mistress Repine at Venomspite has asked you to steal the Scarlet Onslaught Daily Orders: Abbey, Scarlet Onslaught Daily Orders: Barracks, and Scarlet Onslaught Daily Orders: Beach.", progress = "If you take too long, their daily plans will change, and we may have to start over again.\n\nDon't take too long!", completion = "Well, what are you waiting for, <race>? Hand them over!" }
WordHunterWoW_QuestEN[12235] = { title = "Naxxramas and the Fall of Wintergarde", description = "Lord Fordragon has led a crushing assault against Arthas at the Wrathgate. In response to this affront, Arthas has sent Naxxramas down upon us. While Kel'Thuzad hides in the floating citadel, his ground commander, Thel'zan, lays siege to Wintergarde Keep. The lower village is already lost and any chance of extracting survivors from the ruins diminishes by the minute.\n\nWe must act quickly! Report to Gryphon Commander Urik at the gryphon station at once! He'll get you up to speed.\n\nLeave me!\n", objectives = "Speak with Gryphon Commander Urik at the gryphon station in Wintergarde Keep.", completion = "<Urik points to a gryphon.>\n\nHave you ever ridden one of those? It's simple, friend. Just hop on and tell it where to go." }
WordHunterWoW_QuestEN[12236] = { title = "Ursoc, the Bear God", description = "The time has come, {name}.  Now we will learn whether our efforts will accomplish what we need or nothing at all.\n\nTake these ashes and seek the furbolg that Kodian told you about, Tur Ragepaw, near Ursoc's Den.  You will find the den to the north of Grizzlemaw.\n\nConvince Tur to aid you, for you will need all the help you can get.\n\nOnce you've defeated the bear god, use these ashes over his body.\n\nEven if his worldly form is destroyed, his spirit must be saved.", objectives = "Windseer Grayhorn in Conquest Hold wants you to find Tur Ragepaw near Ursoc's Den and defeat Ursoc with his help. Use the Purified Ashes of Vordrassil on Ursoc's Corpse when you've accomplished this.", progress = "You've returned.  Did you succeed?", completion = "<The druid looks pale and her eyes stare blankly past you.  She has left a package in anticipation of your return.>" }
WordHunterWoW_QuestEN[12237] = { title = "Flight of the Wintergarde Defender", description = "With this whistle you can call down a Wintergarde gryphon. Mount the creature and head towards the ruins of Wintergarde Village, now known as the Carrion Fields, southeast of here. Once at the fields, keep your eyes peeled for helpless Wintergarde villagers. When you spot one, fly low and use the gryphon to pick them up. Return the rescued villager here, to the gryphon station.\n\nThere are Scourge all over the place so you'll need to keep your wits about you, hero. Good luck!", objectives = "Rescue 5 Helpless Wintergarde Villagers and return to Gryphon Commander Urik at Wintergarde Keep.", progress = "Hurry, <name>! You need to save the helpless villagers!", completion = "Outstanding work, <name>! We can get this keep back into working order now with the return of our citizens." }
WordHunterWoW_QuestEN[12238] = { title = "Cleansing Drak'Tharon", description = "Drak'Tharon soon be cleansed of them foul undead and restored to her noble purpose. In return for your help, the keep's most valuable treasures be yours, mon!\n\nOnce ya be reachin' its top, ya must summon me, and I'll perform the ritual.\n\nAlas, my summonin' will be comin' at a cost. Ya must collect mojo from the survivors.", objectives = "Drakuru wants you to use Drakuru's Elixir at his brazier inside Drak'Tharon. Using Drakuru's Elixir there will require 5 Enduring Mojo.", completion = "We done a great thing, mon! And dis just be da beginning....\n\nSeek me out in Zul'Drak when da time be right.\n\nDere be a war to be won, mon!" }
WordHunterWoW_QuestEN[12239] = { title = "The Spy in New Hearthglen", description = "I have a spy within the ranks of the Scarlet Onslaught. I need you to deliver these daily orders to her so that she can plan the next phase of our assault.\n\nShe goes by the name of Agent Skully and she's under a magical guise to appear as the Onslaught's cemetery caretaker.\n\nHere, take these orders to her, and then do as she asks. You'll find the graveyard on the side of the abbey.", objectives = "Deliver the Scarlet Onslaught Daily Orders to Agent Skully at New Hearthglen.", progress = "<The agent eyes you up and down, and then silently motions you over.>\n\nDon't blow my cover, <class>!", completion = "You have word from the spy mistress?\n\n<The agent looks around to make sure that no one is watching as she puts down her shovel.>\n\nLet me see those plans." }
WordHunterWoW_QuestEN[12240] = { title = "A Means to an End", description = "I received a few barrels of termites from my sister at the Bulwark back home in the last shipment. I think they're going to come in handy for something I have in mind for you.\n\nThe lumbermill operations at New Hearthglen are problematic for us, but so far we haven't been able to get anyone in there to take out their foreman.\n\nI think that if you were to unleash these termites on his precious woodworks, he'd be sure to come running.\n\nReady to take him out, {class}?", objectives = "Apothecary Vicky Levine at Venomspite has asked you to use the Levine Family Termites to lure Foreman Kaleiki out and kill him.", completion = "I knew my sister wouldn't let us down.\n\nWell done, <name>. The Onslaught's lumbermill will be out of commission for a while, which means no new construction or ballistae.\n\nThanks for helping me to live up to the family name." }
WordHunterWoW_QuestEN[12241] = { title = "Destroy the Sapling", description = "The furbolgs' work must be undone, {name}.  The best of intentions do not count for much when the result is tainted by such strong a corruption.\n\nThe sapling must be destroyed, for it is the source of this dark influence.  Take this torch and use it to set fire to the corrupted sapling and bring me its ashes.\n\nOnce cleansed, by fire, I will use what power I can to remove the taint from them.  You will need the ashes to purify Ursoc from the evil power that holds sway over him.", objectives = "Windseer Grayhorn in Conquest Hold wants you to take the Verdant Torch and use it to burn Vordrassil's Sapling. Bring Vordrassil's Ashes back to Windseer Grayhorn.", progress = "Have you brought me the ashes, <name>?", completion = "I can't make any promises, <name>.  But I will try my best to purify these." }
WordHunterWoW_QuestEN[12242] = { title = "Vordrassil's Seeds", description = "We must make sure that Vordrassil is never regrown.  The furbolg must have harvested its seed.\n\nGo to Grizzlemaw, in central Grizzly Hills, and obtain all the seeds that you can find.  I will make sure they're properly destroyed.", objectives = "Windseer Grayhorn in Conquest Hold wants you to go to Grizzlemaw and obtain 8 of Vordrassil's Seeds.", progress = "Have you obtained Vordrassil's seeds yet, <name>?", completion = "Thank you, <name>.  I'll take those from you.\n\nThe corruptive power of these seeds is dangerous.  I must destroy them right away." }
WordHunterWoW_QuestEN[12243] = { title = "Fire Upon the Waters", description = "I have another mission for you.\n\nI was able to repurpose some of the blight to concoct my world-famous burning water. I want you to take it and set the sails of the Sinner's Folly ablaze!\n\nUse it from the dock. Once the sails are on fire, the deckhands will be busy putting them out, and you'll slip belowdecks to 'retrieve' the captain's rutters.\n\nYou'll find the ship on Crusader's Landing, below and south of New Hearthglen. Look for the captain's quarters on the first lower deck, behind the stairs.", objectives = "Apothecary Vicky Levine at Venomspite has asked you to use her Apothecary's Burning Water to set the sails of the Sinner's Folly afire.\n\nWhile the deckhands are busy attempting to put the fires out, head belowdecks and retrieve Captain Shely's Rutters from the captain.", progress = "Please do NOT tell me that their sails were somehow protected from my burning water!\n\nI'd hate to have to test it out here again.", completion = "Ahhahahahahahahahaha!\n\nWithout their rutters, they've got nowhere to run to now.\n\nLooks to me like the end of the Scarlet Onslaught, and just when they were getting started. How sad.\n\nHeh." }
WordHunterWoW_QuestEN[12244] = { title = "Shredder Repair", description = "Listen, pal. Why don't ya roll up your sleeves and grab a wrench? There's work to be done! They need these shredders refurbished and sent down to Venture Bay, and they need it done yesterday....\n\nNo wrench? Well what good are ya then? May as well go down with the rest of the lugheads and play with the Horde!\n\nWhile you're there, see if you can drive some of those broken-down shredders up here for repairs. Be careful! They're in pretty bad shape.", objectives = "Synipus at Blue Sky Logging Grounds wants you to bring 3 Broken-down Shredders back to him.", completion = "<Synipus whistles.>\n\nOh, she's a beauty! We'll fix her up nice.\n\nIf you're short on things to do, go talk to Gordun and get a ride down to Venture Bay. They're sure to need a hand.\n\nOh, and while you're there, use these keys on a Refurbished Shredder. Wait 'til ya see what these babies can do when they're cleaned up!" }
WordHunterWoW_QuestEN[12245] = { title = "No Mercy for the Captured", description = "We have more fools for you to kill.\n\nMy agents tell me that several of our good citizens have seen fit to fall into the hands of the Scarlet Onslaught.\n\nThis will not do.\n\nGo back to New Hearthglen and eliminate Deathguard Schneider, Senior Scrivener Kinnedius, Engineer Burke and Chancellor Amai.\n\nFrom what I hear, they're spread out throughout the area. No doubt they are being kept in cages awaiting torture.\n\nSpeak with them and then kill them!", objectives = "Spy Mistress Repine has asked you to slay Deathguard Schneider, Senior Scrivener Kinnedius, Engineer Burke, and Chancellor Amai.\n\nWhen you've accomplished this task, report your success to High Executor Wroth at Venomspite.", completion = "What? You were expecting us to have you rescue them?\n\nNow why would we do that when they have a proven track record of getting themselves captured in the first place?\n\nNorthrend is a cold place, young <name>. I suggest that you adjust to it." }
WordHunterWoW_QuestEN[12246] = { title = "A Possible Link", description = "The furbolgs that live east of here are more aggressive and bestial than the ones we're used to.  Our forces have squared off with them more than once, and the survivors always speak of a dark, slimy substance dripping from their corpses.\n\nTheir condition could be linked with the contaminants we found on Vordrassil's remains.\n\nBring me samples of the furbolgs' blood.  You will find them in the Rage Fang Shrine and the Heart's Blood Shrine, far to the east.", objectives = "Hierophant Thayreen at Amberpine Lodge wants you to obtain 8 Crazed Furbolg Blood from the Furbolgs at Heart's Blood Shrine and Rage Fang Shrine.", progress = "Have you obtained the blood samples, <name>?", completion = "The corruption present in this blood is identical to that of the slime.  I don't have a good feeling about this." }
WordHunterWoW_QuestEN[12247] = { title = "Children of Ursoc", description = "The furbolgs of Grizzly Hills carry with them a corruption of some kind, that is for sure.  Tribal war has broken out amongst them after years of peaceful coexistence.\n\nWhat remains to be seen is whether the bears they worship as gods have also been tainted.\n\nUrsoc's two children, Orsonn and Kodian, dwell in the Heart's Blood Shrine and the Rage Fang Shrine, south and southeast of Grizzlemaw.\n\nSee if they will speak to you regarding what has happened here.", objectives = "Hierophant Thayreen at Amberpine Lodge wants you to speak to Orsonn at the Rage Fang Shrine and Kodian at the Heart's Blood Shrine.", completion = "Ursoc's children are wise.  Their words explain much of what we've seen so far." }
WordHunterWoW_QuestEN[12248] = { title = "Vordrassil's Sapling", description = "The druids of old seem to have had good reasons for destroying Vordrassil.  We cannot let the furbolgs regrow it.\n\nOn the other hand, saving Ursoc's spirit hinges on the magic contained by the sapling.\n\nTake this torch and use it to burn the tree.  You will find it in the middle of Grizzlemaw, inside Vordrassil's old trunk.\n\nBring me Vordrassil's ashes.  It is my hope that once purified by fire, we may use its magic to cleanse Ursoc's spirit of its dark taint.", objectives = "Hierophant Thayreen in Amberpine Lodge wants you to take the Verdant Torch and use it to burn Vordrassil's Sapling. Bring Vordrassil's Ashes back to Hierophant Thayreen.", progress = "Have you brought me the ashes, <name>?", completion = "Yes!  Vordrassil's magic is still present in these ashes.  There might be hope for Ursoc yet." }
WordHunterWoW_QuestEN[12249] = { title = "Ursoc, the Bear God", description = "It is time, {name}.  Take these ashes and look for the furbolg that Kodian spoke of.  If he went to seek Ursoc, he will be near his den, north of Grizzlemaw.\n\nYou will need his help.  You won't be able to defeat Ursoc alone.\n\nOnce you've defeated Ursoc, use these ashes to purify his spirit.  Only then will we know whether our efforts have been in vain or not.", objectives = "Hierophant Thayreen at Amberpine Lodge wants you to find Tur Ragepaw near Ursoc's Den and defeat Ursoc with his help. Use the Purified Ashes of Vordrassil on Ursoc's Corpse when you've accomplished this.", completion = "<The druid looks pale and her eyes stare blankly past you.  She has left a package in anticipation of your return.>" }
WordHunterWoW_QuestEN[12250] = { title = "Vordrassil's Seeds", description = "We cannot allow Vordrassil to grow again.  If the furbolg regrew it once, they can do it again.\n\nGo to Grizzlemaw, in central Grizzly Hills, and obtain Vordrassil's seeds.  I will make sure they're properly disposed of.", objectives = "Hierophant Thayreen at Amberpine Lodge wants you to go to Grizzlemaw and obtain 8 of Vordrassil's Seeds.", progress = "Do you have the seeds, <name>?", completion = "Thank you, <name>.  I'll take those from you.\n\nThe corruptive power of these seeds is dangerous.  I must destroy them right away." }
WordHunterWoW_QuestEN[12251] = { title = "Return to the High Commander", description = "Return to High Commander Halford Wyrmbane at once, {name}. Let him know that your mission was a success and that the few remaining villagers that were rescued are back to work.", objectives = "Speak with High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.", completion = "<Halford salutes.>\n\nThe townsfolk are all back to work? Already? Outstanding, soldier! We'll get this town built back up and fortified in no time. Before long, reinforcements will be ready to join the fight with Lord Fordragon at the Wrathgate.\n\nI'm getting ahead of myself, of course, as there is much left to do here before we can even think about sending you to the aid of Bolvar." }
WordHunterWoW_QuestEN[12252] = { title = "Torture the Torturer", description = "Enough! I want you to put an end to the torture of my people!\n\nThe Onslaught's torturer, Alphonse, has been bleeding information out of everyone that gets caught by those fiends! I need to know what they know.\n\nMy sources tell me that he has set up shop in the basement of their barracks, which is right next to the smithy.\n\nI'll loan you my personal branding iron to see to it that the job is done right.\n\nFind him and get that information.", objectives = "High Executor Wroth at Venomspite wants you to use the branding iron 5 times on Torturer Alphonse to get the information out of him. After that, kill him.", completion = "They knew all of that? And who the hell is this Grand Admiral Westwind that he spoke of?!\n\n<The high executor grumbles to himself about hating surprises.>\n\nBetter that we know than have to guess. I hope that you left your... er, my mark." }
WordHunterWoW_QuestEN[12253] = { title = "Rescue from Town Square", description = "Just down this path here is Wintergarde's town square. Once a hive of activity for the citizens of Wintergarde, now a warzone, filled with murderous geists hell-bent on vengeance towards the living.\n\nIn the buildings surrounding the town square are trapped villagers that must be rescued! I ask much of you, now, {name}, but you are the only soldier I can spare. Free our people. Take this path down into town square and enter those houses. Kill anything that gets in your way! Return to me should you survive.", objectives = "High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight wants you to rescue 6 Trapped Wintergarde Villagers.", completion = "<Halford says a prayer for the deceased.>\n\nYou do the Light's work, <name>.\n\nI fear that our work has only just begun." }
WordHunterWoW_QuestEN[12254] = { title = "Without a Prayer", description = "These plans indicate something imminent is being planned.\n\nBut first, there's the matter of this strange protection that the Onslaught forces have. If Venomspite is to deal with them once and for all, we must find out who's behind it and eliminate them.\n\nI've noticed that the bishop in the chapel on the far side of New Hearthglen, across from the lumbermill, has stepped up his blessing of the troops. Kill him and steal his prayer book.\n\nMaybe it will give us a clue.", objectives = "Agent Skully at New Hearthglen has asked you to acquire Bishop Street's Prayer Book.", progress = "You have the bishop's prayer book? Did you find anything unusual in it?", completion = "A newly scribed blessing at the back of the book you say?\n\n<The agent glances over your shoulder as you flip to the page at the end.>\n\nDamn it all! That's the high abbot's handwriting! I'd stake your life on it." }
WordHunterWoW_QuestEN[12255] = { title = "The Thane of Voldrune", description = "Now that you've captured the flame-imbued talismans and weakened Voldrune's defenses, we can strike at its leader, Thane Torvald Eriksson.\n\nThe thane's favorite mount is an unruly proto-drake he calls Flamebringer. It is kept bound in chains in the western part of Voldrune, but with the talismans, you should be able to control it long enough to use it against the thane.\n\nOnce you have Flamebringer under your control, search the tops of the towers of Voldrune for the thane and show him no mercy.", objectives = "Use Flamebringer to defeat Thane Torvald Eriksson and report to Woodsman Drake at Amberpine Lodge.", progress = "Have you overcome the thane? We cannot risk leaving him in power.", completion = "Good work, <name>. I doubt any of the woodsmen would've wanted to take a crack at the proto-drake, but we couldn't afford to let the Dragonflayers build a base of power in Grizzly Hills. If only the Horde was so easily dealt with..." }
WordHunterWoW_QuestEN[12256] = { title = "The Flamebinders' Secrets", description = "Even as the Alliance cowards attack our positions, the Dragonflayer vrykul outpost of Voldrune, to the southeast, prepares for war. The vrykul are far from the strongest enemy we face here, but we must eliminate them before they can truly threaten us.\n\nTheir most powerful warriors are permitted to ride half-trained proto-drakes into battle. To control the beasts, their flamebinders create powerful talismans. You'll need to slay them and take the talismans if our plan is to work.", objectives = "Bring 3 Flame-Imbued Talismans to Sergeant Nazgrim at Conquest Hold.", progress = "Did you collect those talismans?", completion = "With the power of the talismans, the drake has no choice but to obey your commands. The thane's fate is sealed." }
WordHunterWoW_QuestEN[12257] = { title = "A Show of Strength", description = "Preparations for war are underway in the vrykul village of Voldrune to the southeast. Voldrune's thane cannot field a large army, but with our forces spread thin, we are still at risk.\n\nWe cannot risk giving the thane and his men an opportunity to attack, so we must take the battle to them. If you are truly a {class} of the Horde, you will relish the chance to demonstrate our strength.\n\nCut down the huscarls and prove to this Dragonflayer clan that the Horde is not to be trifled with!", objectives = "Kill 12 Dragonflayer Huscarls and return to Sergeant Nazgrim at Conquest Hold.", completion = "You have done exactly as I asked. We've got the Dragonflayers on the defensive and it'll soon be time to deal with their leader." }
WordHunterWoW_QuestEN[12258] = { title = "The Fate of the Dead", description = "The town square, down this path, is overrun with the undead citizens of Wintergarde! Our own crypt provides a seemingly endless supply of soldiers for the Scourge to throw at us. Take no pity on them, though, {name}. While they were once mortal, capable of compassion and thought, they are now ravaging undead with only one purpose: our destruction.\n\nVenture forth to the town square and deliver the vengeful geists to their maker. Give them peace.", objectives = "Commander Lynore Windstryke at Wintergarde Keep in Dragonblight wants you to kill 15 Vengeful Geists.", completion = "Perhaps now they will rest easy, their spirits free to ascend to the Light.\n\nMy thoughts and prayers now turn to Lord Fordragon and our forces at the Wrathgate. We must persevere here, if only to buy them enough time to defeat the Lich King. Wintergarde cannot fall." }
WordHunterWoW_QuestEN[12259] = { title = "The Thane of Voldrune", description = "With the flame-imbued talismans, we can finally challenge the thane.\n\nHis favorite mount is a ferocious proto-drake called Flamebringer. It is kept bound in chains in the western part of Voldrune, but with the power of the talismans, you should be able to bend it to your will and use it against the thane.\n\nOnce you have Flamebringer under your control, search the tops of the towers of Voldrune for the thane and use Flamebringer to destroy him.", objectives = "Use Flamebringer to defeat Thane Torvald Eriksson and report to Sergeant Nazgrim at Conquest Hold.", progress = "Have you overcome the thane?", completion = "The few remaining Dragonflayers dare not challenge us after your battle with the thane. Show no mercy to our enemies - that is the way of the Horde." }
WordHunterWoW_QuestEN[12260] = { title = "The Perfect Dissemblance", description = "You may wonder how I can maintain this guise; I use a magic mirror that was loaned to me by the spy mistress.\n\nIt only has so much power in it, but I think there's enough for the both of us. Here, take it. I want you to use it to impersonate one of the Onslaught raven priests.\n\nBe quick about it... I have no idea how long my glamour will last while you have the mirror.\n\nRealize that you won't immediately be perfectly disguised, so don't count on it being foolproof until I've had a chance to help you.", objectives = "Agent Skully at New Hearthglen has asked you to steal the image of an Onslaught Raven Priest. Return the Banshee's Magic Mirror to her when you have done so.", progress = "Please tell me that you didn't break the mirror?!", completion = "Not bad, <class>. Now that the priest's image is trapped within the mirror, I have something else that needs doing." }
WordHunterWoW_QuestEN[12261] = { title = "No Place to Run", description = "They're drawing power from the bones of my dead brothers...\n\nI have no love for the cult, but I'm baffled by their audacity. There will be no mercy shown for them... not that I ever would have anyway.\n\nEnsure that they have no place to flee when the slaughter starts. Place a destructive ward at the end of the path leading out of the shrine... where the road starts to give way to snow. Defend it until it is fully charged.", objectives = "Place a Destructive Ward at the end of the path leading out of Obsidian Dragonshrine, where the road starts to give way to snow. Protect the ward until it is fully charged, then return to Serinar.", progress = "Have you placed the ward?", completion = "Excellent. When they begin to flee in fear, the ward shall be there to wish them a fond farewell." }
WordHunterWoW_QuestEN[12262] = { title = "No One to Save You", description = "We will spare no one. \n\nOutside, lowly necrolytes and their skeletal servants shame my land with their presence. Slaughter them all.", objectives = "Kill 6 Burning Depths Necrolytes and 10 Smoldering Skeletons outside of the Obsidian Dragonshrine. Return to Serinar once the task is complete.", completion = "Did they beg for their miserable lives? Weaklings." }
WordHunterWoW_QuestEN[12263] = { title = "The Best of Intentions", description = "The Cult of the Damned has not come just to extract power from dead dragons. I suspect I know what they are up to, but I need you to prove me correct.\n\nI will grant you the guise of this dead necrolyte. Proceed to the back of the cave and confirm their intentions for being in this sacred place. I will watch through your eyes. \n\nBe cautious {name}, any damage done to you is likely to break the fragile illusion.", objectives = "Wait for Serinar to administer the disguise of a Burning Depths Necrolyte, then proceed to the back of the Maw of Neltharion to uncover what the Cult of the Damned is doing there. Return to Serinar with details regarding their purpose.", completion = "We are the Black Dragonflight. We have rained destruction on the lands of Azeroth for thousands of years. The decrepit Cult of the Damned worships death and we shall be glad to oblige." }
WordHunterWoW_QuestEN[12264] = { title = "Culling the Damned", description = "The cave beyond was swarming with Cult atrocities. There is only one way to deal with such creatures... you know what to do.", objectives = "Kill 3 Burning Depths Necromancers, 6 Smoldering Constructs, and 6 Smoldering Geist in the Maw of Neltharion, and then return to Serinar.", completion = "Hearing their screams... watching the last life fade from their wretched bodies... it's invigorating, is it not?\n\nI relish it." }
WordHunterWoW_QuestEN[12265] = { title = "Defiling the Defilers", description = "I sensed a large accumulation of magic in the runes that we witnessed when you were scouting the cave. I will not have you toy with extracting the magic... often the most straight forward solution is the most effective one.\n\nDestroy the runes... stamp them out and ensure that the Cult will not have access to whatever power that they've accumulated there.", objectives = "Locate and stamp out 8 Necromantic Runes that have been drawn on the floor inside the Maw of Neltharion. Return to Serinar once the task is complete.", completion = "Good. There is more to be done." }
WordHunterWoW_QuestEN[12266] = { title = "Tales of Destruction", description = "You can leave now, {race}.\n\nGo tell Nalice she missed out on a good slaughter.", objectives = "Travel back to Wyrmrest and let Nalice know that Serinar's task is complete.", completion = "Oh, it's you.\n\nI had hoped Serinar would simply return himself once the task was done... I suppose he's distracted by something or another to kill. He's missing out on a gloriously messy battle!\n\nAre you still here? I'm done with you." }
WordHunterWoW_QuestEN[12267] = { title = "Neltharion's Flame", description = "With the cult's ranks thinned and some of their power stripped, it's time to strike at the source of the corruption.\n\nRothin the Decaying is resurrecting black dragons as magmawyrms in the back of the cave. Go to the summoning chamber and cleanse the remaining bones in the only way that will ensure that they will never be toyed with again... with flame.\n\nBurning the bones will surely gain Rothin's attention, see to it that he is destroyed as well.\n\nThe magic in this vial should see the task done.", objectives = "Use Neltharion's Flame to douse the summoning area in the back of the Maw of Neltharion. Once you get the attention of Rothin the Decaying, kill him, then return to Serinar at the front of the cave.", progress = "You are quite an effective tool, <class>. Your hand in this purging is appreciated.", completion = "The bones of my brood have been spared this filth. You have served me well, and as such, you shall be awarded appropriately." }
WordHunterWoW_QuestEN[12268] = { title = "Pieces Parts", description = "Ack! This thing's a mess!\n\nGoblin engineering leaves a great deal to be desired, believe you me. Just look at this! It's a wonder it ever worked to begin with.\n\nGive me a hand, will ya? To get this even close to operable specifications I'll need to replace a few cogs, sprockets, and springs. You should have no trouble finding them down around the sawmill.", objectives = "Pipthwack in Blue Sky Logging Grounds wants you to collect 4 Grooved Cogs, 3 Notched Sprockets, and 2 High Tension Springs.", progress = "Got those parts for me, <class>?", completion = "Yes indeed. These should do the trick...\n\nThere. One more shredder ready for the fight. Thanks, <name>." }
WordHunterWoW_QuestEN[12269] = { title = "Not In Our Mine", description = "That blasted necropolis blindsided us! In the wake of its destruction Wintergarde Mine was lost. Worse yet, Kel'Thuzad's acolytes have raised the slain miners as Scourge and are using them to supply their siegesmiths with materials from our mine!\n\nThe supply line must be halted and our lost brothers must be put to rest.\n\nTravel to Wintergarde Mine, northeast of here in the Carrion Fields, and destroy the risen miners. Return to me with their miner cards so that I may put their passing in our registry.", objectives = "Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight wants you to recover 10 Wintergarde Miner's Cards.", progress = "Did you recover their cards?", completion = "<Leoric takes the cards from you.>\n\nI will get these to our recorder and deliver the grim news to the families of the miners.\n\nThere is still much to be done if we are to succeed here and ultimately at the Wrathgate. Lord Fordragon is depending on us." }
WordHunterWoW_QuestEN[12270] = { title = "Shred the Alliance", description = "Read my lips, {class} - I need those shredders! Just as important - I need to keep them out of the hands of the Alliance!\n\nThey've been refurbishing the shredders and using them against our brothers in Venture Bay. Now we're going to give them a taste of their own medicine!\n\nYou see a shredder out there, grab it! You see one of the Alliance scum on one, kill 'em and then grab it! Once you have one, drive it back here to me and we'll get to work on it.\n\nDismissed!", objectives = "Grekk at Blue Sky Logging Grounds wants you to acquire 3 shredders and return to him with them.", completion = "Good work, soldier!\n\nNow take this key and get yourself down to Venture Bay. It'll let you use one of the refurbished shredders to unleash chaos on our enemies.\n\nOh yes, and talk to Darrok if you want to take the shortcut!" }
WordHunterWoW_QuestEN[12271] = { title = "The Rod of Compulsion", description = "A rod drops from Alphonse's dead hand. There are pulsing magical runes along its length.\n\nCould this be how he was getting his confessions?\n\nBetter let the high executor have a look at it.", objectives = "Deliver the Torturer's Rod to High Executor Wroth at Venomspite.", progress = "Did you get that rod from their torturer?", completion = "LeCraft had it you say? That makes sense.\n\nI recognize it from my youthful days as a torturer in the court of King Terenas of fallen Lordaeron. It's known as a rod of compulsion.\n\n<The high executor wrings his hands together in evil anticipation of what's to come.>\n\nI have an idea for how we can make good use of it!" }
WordHunterWoW_QuestEN[12272] = { title = "The Bleeding Ore", description = "Hours before the Naxxramas invasion, one of the miners stumbled upon a dark ore that was oozing a viscous fluid. In the chaos that occurred during the evacuation of the mine, we lost the samples taken from the alien node. Now the Scourge prospects the ore for use in their machines of death.\n\nYou must get back to Wintergarde Mine, due northeast of here in the Carrion Fields, and recover the strange ore. It is imperative to our mission's success!", objectives = "Siege Engineer Quarterflash at Wintergarde Keep in Dragonblight wants you to recover 10 samples of Strange Ore from Wintergarde Mine.", progress = "Have you recovered samples of the strange ore?", completion = "This might be the moment, the very second, that the tide turns against the Scourge. You have proven yourself as a hero of the Alliance, at least in my eyes, <name>.\n\nNow if you would be so kind as to give me some space. I will require additional time to study this ore in order to isolate impurities and weakness.\n\nCarry on, ally. I will contact you once I have an update." }
WordHunterWoW_QuestEN[12273] = { title = "The Denouncement", description = "It's time for us to utterly demoralize the Onslaught forces!\n\nI want you to take the rod and use it on four of their leaders: Commander Jordan upstairs at the barracks, Lead Cannoneer Zierhut down the southeast ramp overlooking the beach, Blacksmith Goodman at the smithy, and Stable Master Mercer at the stables.\n\nPlace them under the rod's compulsion, concentrate on making them denounce the Onslaught, and then kill them!", objectives = "High Executor Wroth at Venomspite has tasked you with using the Rod of Compulsion on Commander Jordan, Lead Cannoneer Zierhut, Blacksmith Goodman, and Stable Master Mercer.\n\nOnce the rod has been used on them, kill each to exact a denouncement of the Scarlet Onslaught as their final words.", completion = "<You think you see just the hint of a smile cross Wroth's face before quickly disappearing.>\n\nYou're now my favorite <class>, <name>. If you have a mind to, I'd like you to think about joining up as an officer in the Hand of Vengeance.\n\nWe can start you out as a deathguard, and in a few decades I think you have what it takes to make junior executor!\n\nNo? Well don't be too hasty... take your time and mull it over." }
WordHunterWoW_QuestEN[12274] = { title = "A Fall From Grace", description = "We need more information from the high abbot, and now that we have the visage of one of the raven priests, I think we can get you close to talk with him.\n\nUnfortunately, we need to separate him from his bodyguards or you'll never get any information out of him.\n\n<The agent leans on her shovel and thinks a moment.>\n\nI think I've got it! While in disguise, go to the top of the abbey and ring the bell. That should bring the abbot's bodyguards running and you can then head down to speak with him.", objectives = "Agent Skully at New Hearthglen has asked you to ring the bell in the abbey and then go speak with the high abbot and get information out of him.", progress = "What did you find out? Have you even talked with him yet?", completion = "What the hell is going on here?!\n\nHe jumped on his own? You're certain that you didn't push him?\n\n<The agent narrows her eyes at you.>\n\nFine. Clearly there's much more going on in this place than we first thought." }
WordHunterWoW_QuestEN[12275] = { title = "The Demo-gnome", description = "Quarterflash recently requisitioned my group for a specialist that he could send on a reconnaissance mission to the Wintergarde Mine. To that end, I sent him Slinkin, my demolitionist. I foolishly thought that he could close off that pit of damnation after his mission for Quarterflash was complete, securing another victory for us against the Scourge.\n\nAn entire day has now passed and Slinkin has not returned. I want answers! Speak with Siege Engineer Quarterflash and track down my missing agent!", objectives = "Speak with Siege Engineer Quarterflash at Wintergarde Keep in Dragonblight.", completion = "I feel terrible about this, friend. I fear that in my haste to recover the strange ore from Wintergarde Mine I may have doomed agent Slinkin." }
WordHunterWoW_QuestEN[12276] = { title = "The Search for Slinkin", description = "While I have not heard from Slinkin or know what fate has befallen him, perhaps I can assist in finding him.\n\n<Quarterflash holds up a tiny mechanical toy.>\n\nThis is not a toy, newfound compatriot. It is, in fact, my latest mechanical creation. The machine was created with the sole purpose of finding that which has been lost. These are unfortunate circumstances, but the machine is your best chance at finding Slinkin.\n\nWhen you are ready to begin your search, place the bot on the ground next to me.", objectives = "Find Slinkin the Demo-gnome in Wintergarde Mine. Use Quarterflash's Homing Bot if you need help finding the mine.\n\nProvided item:", completion = "<There is a note in Slinkin's death grip.>\n\nChased into a dead end. Hidden for now, but they know I'm here. It won't be long until they find me.\n\nThe miners work tirelessly to unearth the strange ore that fuels the Scourge war machines. There is much banter. The language of death confounds me, but I have been able to identify commonly uttered sounds and phrases. The word \"Yogg-Saron\" is said with great contempt and is usually followed by loud outbursts. They refer to the ore as \"saronite.\" Meaning?" }
WordHunterWoW_QuestEN[12277] = { title = "Leave Nothing to Chance", description = "If there is good in your heart and your conscience is clear, read on.\n\nIn this mine, near the foreman's scaffold, rests a hefty cargo of dynamite. Go there and pick up several bundles of the explosive and make your way towards the entrance of the mine. Once there, set the dynamite and blow up the entrance. Remember to do this for the upper and lower entry points of Wintergarde Mine.\n\nYou must leave nothing to chance. The evil that exists here must never be allowed out. Light guide you.", objectives = "Retrieve a Wintergarde Mine Bomb and use it to blow up the Upper Wintergarde Mine Shaft and the Lower Wintergarde Mine Shaft. Report back to Siege Engineer Quarterflash at Wintergarde Keep in Dragonblight when you have completed this task.", completion = "His death will not have been in vain, friend. The information that Slinkin died for will be instrumental in defeating the Lich King. I promise you that we will make this right." }
WordHunterWoW_QuestEN[12278] = { title = "Brew of the Month Club", description = "Membership has its privileges.  Being part of the \"Brew of the Month\" club means knowing where to get the latest and greatest brew.\n\nBring your \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.", objectives = "Bring the \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.", progress = "Do you have your membership forms filled out?", completion = "Your paperwork looks to be in order.  Welcome to the club, <name>!\n\nYou can expect to get our mail at the start of every month.  If you like what you got, stop by and we can sell you some more.  This is the club that keeps on giving." }
WordHunterWoW_QuestEN[12279] = { title = "A Bear of an Appetite", description = "Thank goodness you're back, Limpy! I worried that Griselda and I were going to be all alone.\n\nI'm cooking up some food here for us, but Griselda'll have none of it.\n\nShe's fond of the fish that live off the coast of the Eastwind Shore, to the east. Can't stand them myself, but she's always been a picky eater. Six good-sized fish ought to keep her happy for a while.\n\nNow, run... err... limp along, Joe. Wouldn't want to keep the girl waiting, would ya?", objectives = "Bring 6 Northern Salmon to Hugh Glass at the Redwood Trading Post.", progress = "If you don't hurry, it'll be more than just her stomach growling...", completion = "You! You're not Limpy Joe!" }
WordHunterWoW_QuestEN[12280] = { title = "Making Repairs", description = "Twenty shredders by noon tomorrow!\n\nWho makes these schedules, anyway? No one who ever put one of these garbage cans back together, that's who....\n\nIf I'm going to hit my quota, I'll need a hand. Help me out and I'll share my commission with you - fair enough?\n\nI need cogs, sprockets and springs. They're littered across the ground down by the shredders.", objectives = "Lurz at Blue Sky Logging Grounds wants you to collect 4 Grooved Cogs, 3 Notched Sprockets, and 2 High Tension Springs.", progress = "Ya fetch those parts for me yet?", completion = "Thanks, <name>. That should keep me going - at least until tomorrow....\n\nHere's the cash I promised." }
WordHunterWoW_QuestEN[12281] = { title = "Understanding the Scourge War Machine", description = "We must take solace in the fact that Slinkin's death, while tragic, was for the greater good. His discovery coupled with your heroics in the mine and the samples you returned brings us one step closer to understanding the Scourge war machine.\n\nTake this package to High Commander Halford Wyrmbane. It holds a sample of the strange ore and my analysis.", objectives = "Deliver Quarterflash's Package to High Commander Halford Wyrmbane at Wintergarde Keep.", progress = "I heard about your bravery in the mine, <name>.", completion = "<Halford opens the package and reads the analysis.>\n\nI am by no means a scientist, <name>, so you'll have to forgive my plebian understanding of what has been written. Now, according to this analysis - assuming I have the brain power of at least an adolescent school boy - we still don't know jack squat about the Scourge war machine. The only thing we do know is that the Scourge uses this foul metal to craft its siege engines, armor and weaponry." }
WordHunterWoW_QuestEN[12282] = { title = "Imprints on the Past", description = "The memories of the past haunt this land, {name}. I hear the cries of the fallen echo across Northrend - calling to me.\n\nArthas left a terrible imprint on everything he touched. Only wither and decay remains in his wake. It is important, then, for us to study the past so that we may better know our enemy. Perhaps untold truths shall surface that could help in our campaign.\n\nFirst, you must recover my scrying orb from the town hall, {name}. Exit this tower and turn left down the path to reach the town square.", objectives = "Zelig the Visionary at Wintergarde Keep in Dragonblight wants you to recover his Scrying Orb.", progress = "Have you recovered my scrying orb?", completion = "Well done, <name>. As fate foretold, you will be the one to carry us through these hard times. Now the long journey begins." }
WordHunterWoW_QuestEN[12283] = { title = "The Truth Will Out", description = "We have to figure out what's going on here. We need the general's diary!\n\nI'm pretty sure that you'll find it on her nightstand upstairs at her house. It's the one next to church, across from the stables and the lumbermill.\n\nOnce you acquire the diary, take it to the high executor back at Venomspite.\n\nYou'll have to do this the old-fashioned way; the power of the mirror is low and there's only enough left for me.\n\n<The agent smirks.>", objectives = "Agent Skully has asked you to acquire The Diary of High General Abbendis and to deliver it to High Executor Wroth at Venomspite.", progress = "It's about time, <name>! What's been keeping you?", completion = "Damn it all! Why couldn't you have come to me with good news?!" }
WordHunterWoW_QuestEN[12284] = { title = "Keep 'Em on Their Heels", description = "We've suffered heavy casualties here, {race}.\n\nThe only good news is that we've given as much as we've taken. I've requested more troops, but the bulk of our forces are bogged down in Venture Bay. It looks like we're on our own for now.\n\nNo matter how bad it gets, we MUST stand our ground! The precious resources of this region are essential to the Horde's long-term success in Northrend.\n\nWe've got to keep the Alliance on their heels until help arrives. Get out there and give 'em something to think about.", objectives = "Commander Bargok wants you to kill 15 Alliance units or players in Blue Sky Logging Ground.", completion = "Fifteen down, eh? Good to hear it, <class>.\n\nIf nothing else you've bought us a bit of time - at least a day by my figuring.\n\nHere's your pay." }
WordHunterWoW_QuestEN[12285] = { title = "Do Unto Others", description = "Their attack is imminent, {class}. I need you to get in there and sever the head of the Scarlet Onslaught, literally!\n\nIt's not going to be easy... Abbendis is sure to be surrounded by a great many of her men.\n\nBring back her head and I'll see to it that you're properly rewarded for saving Venomspite.\n\nFail and don't even bother to return!", objectives = "High Executor Wroth at Venomspite has ordered you to return with The Head of the High General.", progress = "Should I tell my forces to begin making our way toward Agmar's Hammer?\n\nOr did you manage kill the high general?", completion = "Let's see them bring her back to life without her head!\n\n<The high executor's laugh draws a number of furtive glances.>\n\nI'm a little concerned that you let this grand admiral get away, but you're still the hero of the day, <name>!\n\nTake your pick... you've earned it!" }
WordHunterWoW_QuestEN[12286] = { title = "Candy Bucket", description = "", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!" }
WordHunterWoW_QuestEN[12287] = { title = "Orik Trueheart and the Forgotten Shore", description = "I have gazed upon the orb and seen the path that you must walk, {name}.\n\nMany years ago an atrocity was committed upon the shores of Dragonblight. The act itself remains shrouded in darkness, but I am certain that your destiny lies south, amidst the ruins of the Forgotten Shore.\n\nTake the road southeast through the ravaged town square. Follow the trail until you arrive at Dawn's Reach. You will meet an old friend of mine there known as Orik Trueheart. He will be expecting you.", objectives = "Seek out the assistance of Orik Trueheart at Dawn's Reach in Dragonblight.", completion = "Zelig sent word, friend. We have been expecting you.\n\nI am Orik Trueheart, paladin of the Argent Crusade. The priestess standing across the campfire from me is Tilda Darathan. We are here on behalf of the Argent Crusade - sent to quell the unfortunate damned souls attempting to escape Wintergarde." }
WordHunterWoW_QuestEN[12288] = { title = "Overwhelmed!", description = "You there, {class}! Help me!\n\nWe're losing valuable lives! There are simply too many wounded for me to tend to alone. If we can't get our soldiers healed we could be run out of Grizzly Hills altogether!\n\nTake this tourniquet and use it on the wounded down on the battlefield.\n\nHurry, {name}! They're dyyying!!", objectives = "Aumana at Blue Sky Logging Grounds wants you to use the Renewing Tourniquet on 10 Wounded Skirmishers.", completion = "Oh, thank you, thank you.\n\nYou've helped us to live another day. Perhaps there's hope yet." }
WordHunterWoW_QuestEN[12289] = { title = "Kick 'Em While They're Down", description = "It is a dark day for the Alliance. Many good men lay dead or dying here. Our only consolation is that they fought well and brought down many of the enemy with them.\n\nWith the bulk of our forces committed to Venture Bay we stand alone to weather this storm. The resources in this region are vital to the Alliance and may well make the difference in our struggle against the Horde. We must not fail!\n\nGo, {name}. Strike at them while they lick their wounds. Avenge your fallen brothers and keep our hopes alive!", objectives = "Sergeant Hartsman wants you to defeat 15 Horde units or players in Blue Sky Logging Grounds.", completion = "Well done, <name>.\n\nYou've bought us some time here, though likely no more than a day. Nevertheless, the Alliance is grateful for your efforts." }
WordHunterWoW_QuestEN[12290] = { title = "The Murkweed Elixir", description = "The spirits of the damned haunt the coast. In life they were brave and noble soldiers of the Alliance, but in death they are cursed - bound to this world until the end of days. We must discover the source of their anguish if we are to free them!\n\nTo the southeast, on the Eldritch Heights, you will find a rare herb known as murkweed. It is murkweed that I will use to concoct an elixir that will allow you temporary entry into the world of the forgotten. Go now and gather the weed.", objectives = "Orik Trueheart at Dawn's Reach in Dragonblight wants you to recover 5 Murkweed from the Eldritch Heights.", progress = "Have you recovered the murkweed?", completion = "<Orik takes the murkweed and begins mixing an elixir.>\n\nIt won't be much longer, <name>." }
WordHunterWoW_QuestEN[12291] = { title = "The Forgotten Tale", description = "The toxins in the murkweed elixir will render you unconscious. So powerful is the effect of the murkweed that even your spirit will be fooled, allowing you to temporarily enter the world of the dead.\n\nOnce a spirit, you must speak to the ghostly denizens of the Forgotten Shore. Seek out the cause of their anguish and return to me.\n\nRemember, {name}, these spirits were once Alliance soldiers. Treat them with respect, honor, and dignity.\n\nNow, with elixir in hand, venture south to the Forgotten Shore.", objectives = "Hear the tales of a Forgotten Peasant, Forgotten Rifleman, Forgotten Knight, and Forgotten Footman.", progress = "I have enough murkweed to make more elixirs, <name>.", completion = "<Orik's eyes fill with tears.>\n\nThey don't know. None of them know! They think Arthas to be some great hero, when in truth it was Arthas who ordered the ships to be burned. It was Arthas who left us all for dead in this frozen wasteland!\n\n<Orik weeps.>\n\nNot all of the soldiers from the Prince's fleet perished in the freezing winter. I was only a lad when I was given the chance to battle the Scourge... to save our home from certain destruction. I took that chance, <name>." }
WordHunterWoW_QuestEN[12292] = { title = "Local Support", description = "We've reached a deadlock with the Horde in Grizzly Hills.  Our forces are just about evenly matched and all signs so far have pointed to a stalemate.\n\nUntil this morning, that is.  The local trappers have requested our help.  Apparently the Horde took something that belongs to them... a relic of some sort.\n\nWe get this back for them and they'll give us the edge we need.  Head to the Evergreen Trading Post, west of Conquest Hold and look for a cedar chest.", objectives = "Lieutenant Dumont at Amberpine Lodge wants you to go to Evergreen Trading Post and obtain the Cedar Chest.", progress = "You bring me that box, <name>?", completion = "It's locked, isn't it?  It looks pretty ordinary.\n\n<Lieutenant Dumont Shakes the chest, producing a rattling wooden sound.>\n\nNo matter, I suppose.  If this gets us the edge we need against the Horde, then I could care less if the cure for the Plague was in there." }
WordHunterWoW_QuestEN[12293] = { title = "Close the Deal", description = "We have what the trappers want.  Now it's up to us to sign them up with our side.\n\nTake the chest to a trapper named Ivan at the Aspen Grove Post, just north of here.\n\nIf all goes well, we'll have local woodsmen serving as scouts for the king's army in no time.", objectives = "Bring the Cedar Chest to Ivan at Aspen Grove Post.", progress = "You've brought something for us?", completion = "You did it!  You recovered the Sc... you recovered the chest that the Horde stole from us.  We thank you, <name>." }
WordHunterWoW_QuestEN[12294] = { title = "A Tentative Pact", description = "Very well, {name}.  Your people kept their end of the bargain.\n\nTell Dumont that we'll honor the deal.", objectives = "Return to Lieutenant Dumont in Amberpine Lodge.", completion = "Excellent news, <name>.  With the locals' help we'll have the logistical support we need to outmaneuver the Horde in this region.\n\nI have further tasks for you if you're interested." }
WordHunterWoW_QuestEN[12295] = { title = "An Exercise in Diplomacy", description = "We'd been trying to negotiate with the trappers for weeks, but we'd gotten nowhere until you found that blasted chest of theirs.\n\nThis should be good news to our envoy in Silverbrook.  We sent Ducal there about a week ago and his last letter indicated he'd been making little progress.\n\nGo to Silverbrook and aid him in his diplomatic efforts.  Take the roads heading northwest of here and you should find it after crossing a couple of bridges. ", objectives = "Speak to Envoy Ducal in Silverbrook.", completion = "It's good to finally meet you, <name>!  We'd heard about you up here.  Welcome to Silverbrook.\n\nThese trappers are a great bunch of lads and lasses.  Hardy people, they know the lay of the land really well.  You'll find it's a great thing that we finally won them over to our side." }
WordHunterWoW_QuestEN[12296] = { title = "Life or Death", description = "Oh, the carnage....\n\nI've been through many battles, {class}, and this one was more brutal than any I've seen. Our fight with the Horde has become more intense than ever. It's them or us here in Northrend - life or death.\n\nIf we are to survive here another day we'll need to mend our wounded. There are too many for me to rescue alone.\n\nI've prepared special bandages that will enable you to assist me. Take one and tend to those who have not yet succumbed to their wounds.", objectives = "Rheanna at Blue Sky Logging Grounds wants you to use the Renewing Bandage on 10 Wounded Westfall Infantry units.", completion = "Wonderful!\n\nThe Alliance shall live to see another day, in part due to your diligence.\n\nPlease accept my thanks, friend." }
WordHunterWoW_QuestEN[12297] = { title = "Of Traitors and Treason", description = "The list I hold must be delivered to High Commander Halford Wyrmbane. He commands the 7th Legion, stationed at Wintergarde Keep on the eastern borders of the Great Dragonblight.\n\nIf any of the traitors on this list are stationed at Wintergarde... it could be catastrophic.\n\nHurry, {name}. Show the document to Greer Orehammer here at Westguard Keep and explain the nature of your mission. He'll put you on his fastest gryphon to Wintergarde!", objectives = "Captain Adams has asked you to show the Alliance Missive to Greer Orehammer at Westguard Keep.", progress = "Hello, <class>.", completion = "<Greer lifts his glasses onto the top of his head and reads the note, looking back up at you curiously when he's done.>\n\nYou will have my fastest gryphon! This information must be delivered to High Commander Wyrmbane at once!" }
WordHunterWoW_QuestEN[12298] = { title = "High Commander Halford Wyrmbane", description = "<Greer hands the missive back to you.>\n\nSkysong will take you to Wintergarde, {name}. I guarantee you that it will be the fastest flight you've ever taken. Go now!\n", objectives = "Deliver the Alliance Missive to High Commander Halford Wyrmbane at Wintergarde Keep in eastern Dragonblight.", progress = "What have you got there, soldier?", completion = "<The High Commander reads the missive and then crumples it up.>\n\nDo you know where the people on this list are now? Take a look outside, near the front gate. They're the ones hanging from the arches.\n\nGhoul bait..." }
WordHunterWoW_QuestEN[12299] = { title = "Northern Hospitality", description = "It's good to meet you.  Let us celebrate our pact by partaking in some good old fashioned Horde-killing.\n\nYou'll find marauders from Conquest Hold just outside our town, west of here.  Why don't you head out there and hunt them like the filthy animals they are?\n\nLet's see if our new allies can back all their talk with some action.", objectives = "Sergei at Silverbrook wants you to slay 8 Conquest Hold Marauders.", completion = "Not bad, not bad.  You might not be as soft as some of the others." }
WordHunterWoW_QuestEN[12300] = { title = "Test of Mettle", description = "Alright, friend.  You've done us a favor or two, but that's not the true test of a person's courage.\n\nAround these parts, you're not a real hunter unless you wear your prey's skin.\n\n<Sergei unsheathes his skinning knife and hands it to you.>\n\nThe leader of those motherless orcs attacking our town is called Bonesnap; you'll find him at a camp further northwest.\n\nThat's right.  You're going to skin the monster.", objectives = "Find Sergeant Bonesnap northwest of Silverbrook and pass the Test of Mettle.", progress = "The people in Silverbrook... they're not what they seem.", completion = "Don't do it, <name>.  The people that sent you here.... you shouldn't trust them." }
WordHunterWoW_QuestEN[12301] = { title = "The Truth Shall Set Us Free", description = "Zelig gave this crystal ball to me years ago with specific instruction on its use. For five years, whenever I would feel anger, anxiety, or sorrow over the events that transpired here, I was to focus my thoughts upon the orb.\n\nI now understand why Zelig gave this crystal to me.\n\nTake my crystalline orb to the Forgotten Shore. Find the ruins of my old base on the upper reaches of the beach and place the orb in the center of town. Let the forgotten see the world through my heart and soul.", objectives = "Use Orik's Crystalline Orb in the ruins located at the Forgotten Shore to redeem the Forgotten.", progress = "Is it done?", completion = "<Orik beams a smile at you.>\n\nYou did a good thing this day, <name>. Hundreds of lost souls are now redeemed, thanks to you." }
WordHunterWoW_QuestEN[12302] = { title = "Words of Warning", description = "Thanks for helping me, {name}.  My name's Sasha.  Listen, I have to get the hell out of here.\n\nThe people that sent you here... my people... they've changed.  They're not good people anymore... and they want to turn you into one of... one of them.\n\nThis... 'test' they sent you on is just the beginning.\n\nHead to the northwestern end of Silverbrook.  You'll find something of interest to you.\n\nGood luck... and trust no one.", objectives = "Go to the northwestern end of Silverbrook.", completion = "Who's there?  Are you here to kill me?\n\nPlease!  You don't have to do this!" }
WordHunterWoW_QuestEN[12303] = { title = "Funding the War Effort", description = "<The quartermaster lowers his voice and whispers to you.>\n\n{class}, I need your help; our coffers are empty. The Kor'kron Vanguard at the Wrath Gate has taken all of our coin for the fight there.\n\nBut, I've heard whispers that there's treasure to be had amongst the wrecks on the Forgotten Shore to the southeast.\n\nWe have to do something soon, or we won't be able to continue the fight against the Scarlet Onslaught. War isn't cheap, you know!", objectives = "Quartermaster Bartlett at Venomspite has asked you to recover 6 Forgotten Treasure.", progress = "How much of that Alliance treasure did you manage to get your hands on?", completion = "<The quartermaster gasps, but then his eyes narrow as he studies you for a moment.>\n\nI trust that you didn't stash any of this on the side for yourself? You wouldn't be that selfish when the fate of Venomspite is at stake?\n\nBesides, I'm going to reward you with a percentage of the take. It's not much, but in times like this, we all have to make sacrifices." }
WordHunterWoW_QuestEN[12304] = { title = "Beachfront Property", description = "It's time for Venomspite to expand!\n\nWe'll take care of the Onslaught in due time, but I want you to spearhead our efforts on the Forgotten Shore. The property value has outstanding potential and just look at that view!\n\nUnfortunately, there's an infestation of human ghosts, shipwrecked crews and the like who haven't quite realized that they're dead.\n\nClear the beach and the waters off the shore, and maybe you and I will talk about building a cozy, new mausoleum down there soon.", objectives = "Surveyor Hansen, just north of the Forgotten Shore, has asked you to slay 20 Forgotten ghosts.", completion = "Can't you just see it now, <class>? It'll be the vacation spot of Northrend!\n\nWhat do you think of the name, \"Hansen's Cove\", or maybe \"<name> Bay\"? Kind of catchy, don't you think?" }
WordHunterWoW_QuestEN[12305] = { title = "Parting Thoughts", description = "You have honored me and honored the memory of hundreds of Alliance veterans, {name}. Zelig was wise in sending you here. Please return to him and give him my thanks. He will be happy to hear of the events that transpired at the Forgotten Shore.\n\nI do not have the gift of foresight like Zelig, but I am certain that great things await you, friend.\n\nFarewell. \n", objectives = "Return to Zelig the Visionary at Wintergarde Keep in Dragonblight.", completion = "<Zelig smiles.>\n\nIt is I who owe you a debt of gratitude, hero. Orik is like a brother to me. You have changed his life and given renewed hope to countless others." }
WordHunterWoW_QuestEN[12306] = { title = "Brew of the Month Club", description = "There is strength in numbers, {name}.  Being part of the \"Brew of the Month\" club means knowing you and your brethren will always have access to the best brew.\n\nBring your \"Brew of the Month\" club membership form to Ray'ma in Orgrimmar.", objectives = "Bring the \"Brew of the Month\" club membership form to Ray'ma in Orgrimmar.", progress = "Do ya have your membership forms filled out?", completion = "So you be joinin' our ranks, <name>?  We treat ya nice here.  You only get the best when you part of dis club!\n\nWe be sendin' out brew to you at da start of every month.  If you like what you got, and you be wantin' more, head back over here.  We make sure you get more of da brew you like." }
WordHunterWoW_QuestEN[12307] = { title = "Wolfsbane Root", description = "Have you heard of the wolfsbane plant?  It is a horrible weed... it destroys our farmable crops.\n\nWe spent all of last week cutting them down, but the roots are beginning to sprout again.\n\nIt might not seem like an urgent matter, but a resurgence of the plant could be a real... disaster.  Do you think you could help us by uprooting them where you find them near the village?", objectives = "Katja in Silverbrook wants you to uproot 8 Wolfsbane Roots.", completion = "<Katja reels away from you nervously.>\n\nThank you, <name>.  You didn't get any wolfsbane on you, did you?  I've got these... allergies that act up once in a while." }
WordHunterWoW_QuestEN[12308] = { title = "Escape from Silverbrook", description = "You... you're not one of them?  Quick!  Let me out!\n\nWe have to get to Amberpine Lodge immediately!  Once Lieutenant Dumont finds out who these people really are, this town will be reduced to rubble!", objectives = "Open the Wooden Cage and help the Freed Alliance Scout escape from Silverbrook. Report to Lieutenant Dumont when you reach Amberpine Lodge.", completion = "Worgen.  Blasted, Light-forsaken, filth-ridden worgen.\n\nIt's time we showed the locals what us civilized folk do with beasts like them." }
WordHunterWoW_QuestEN[12309] = { title = "Find Durkon!", description = "After the Scourge breached the south wall, I ordered Cavalier Durkon to investigate the town crypt. Moments ago I was handed his report.\n\nThe undead that plague us are coming from two sources: the ruins of Wintergarde, now a breeding ground for Scourge, and our very own town crypt! Amidst the chaos and confusion the Scourge managed to get a necrolord inside the crypt.\n\nIn his message, Durkon requested assistance. You will find him and help him, {name}. The crypt is on the western border of the town square.", objectives = "Seek out Cavalier Durkon at the Wintergarde Crypt in Dragonblight.", completion = "Oh brother, it's a mess down there! I barely made it out last time - which is what prompted my request to the High Commander.\n\n<Durkon looks you up and down.>\n\nYou got that crazy look in your eyes, <race>. Thankfully, you're gonna need to be crazy to do what I'm about to ask of you." }
WordHunterWoW_QuestEN[12310] = { title = "A Swift Response", description = "Our response must be immediate.  Decisive.  We must teach these savages not to cross us.\n\nOur scouts have located what's left of the Silverbrook trappers... you know, the ones you didn't get to douse in flames.  Apparently they're blockading the road to the southeast... perhaps they're trying to box us in.\n\nHead to the Forest's Edge post and take care of them.  Their leader's reported to be a man named Vladek... make sure he's dealt with.", objectives = "Lieutenant Dumont wants you to go to Forest's Edge Post and slay Vladek and 7 Silverbrook Hunters.", completion = "It's a shame those trappers turned out to be... afflicted.  We sure could've used a few more fighting men.\n\nMay the poor souls rest in peace." }
WordHunterWoW_QuestEN[12311] = { title = "The Noble's Crypt", description = "Held within the cold stone walls of this crypt are the remains of the nobles and dignitaries that died in Northrend. At its very core now sits a necrolord who raises the corpses as servants of the Scourge.\n\nYou must make your way to the bottom of the Wintergarde Crypt and kill Necrolord Amarion. Only then will the assault from within cease!\n\nAnd {name}, be on the lookout for any information that might be laying about inside the room where Amarion resides. \n", objectives = "Cavalier Durkon at Wintergarde Keep wants you to slay Necrolord Amarion.", completion = "Now if we could stop the Scourge attacks coming from outside the keep we might be able to send help to Lord Fordragon at the Wrathgate." }
WordHunterWoW_QuestEN[12312] = { title = "Secrets of the Scourge", description = "Scrawled across the flesh-bound chapters of this tome are strange symbols and shapes that seem to have been scraped into the pages with a blade. You have no idea what is written, but you are certain that whatever it is, it must be important.\n\nDeliver the tome to Cavalier Durkon standing guard topside at Wintergarde Crypt.", objectives = "Deliver the Flesh-bound Tome to Cavalier Durkon at Wintergarde Keep in Dragonblight.", progress = "A Scourge tome?", completion = "Whatever information is held in this book must be of great importance! I could hear the howls and wails echoing through the crypt as you made your escape!\n\nThe High Commander must be notified!" }
WordHunterWoW_QuestEN[12313] = { title = "UNUSED Save Brewfest!", description = "Save Brewfest!  Talk to the Brewfest spy in the Grim Guzzler of Blackrock Depths.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Talk to the Brewfest spy in the Grim Guzzler of Blackrock Depths.Save Brewfest!  Talk to the Brewfest spy in the Grim Guzzler of Blackrock Depths.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[12314] = { title = "Down With Captain Zorna!", description = "The Horde's forces are poised to break through our lines and complete their conquest of Venture Bay if we do not act. The Horde's forces in the port are commanded by Captain Zorna, near the ship on the far side of the bay.\n\nIf you can defeat her, the Horde's offensive will falter and we can seize the chance to capture the port. Beware, {name}, for Zorna is a fierce fighter. It may take several people to defeat her, or if you have access to a repaired shredder, you might try using it to your advantage.", objectives = "Slay Captain Zorna and report to Baron Freeman at Venture Bay.", completion = "Well done, <name>! Without their leader, the Horde is weak and disorganized. I will order our men forward." }
WordHunterWoW_QuestEN[12315] = { title = "Crush Captain Brightwater!", description = "With every advance, our men are met by fresh Alliance reinforcements. It's almost as though their commander anticipates my every move!\n\nThe time has come for good Captain Brightwater to meet his end. He commands his troops from aboard an Alliance destroyer at the far end of the bay.\n\nThis will be no easy fight, {name}. Take along a couple of trusted friends, or if you have a key to one of those repaired shredders, use it to disembowel Brightwater! Either way, he must fall!", objectives = "Slay Captain Brightwater and report to General Khazgar at Venture Bay.", completion = "You are a true soldier of the Horde, <name>. Your bravery will inspire my men to victory!" }
WordHunterWoW_QuestEN[12316] = { title = "Keep Them at Bay!", description = "We cannot permit the Horde to control Venture Bay. The port is essential to our operations in Grizzly Hills and beyond.\n\nCaptain Stoutmantle has taken the rest of the Westfall Brigade east in search of a passage through the mountains, so we'll have no reinforcements.\n\nGo into the field, {name}, and kill the Conquest Hold berserkers the Horde has sent against us. Cut them down until none remain standing. The Alliance must have this port!", objectives = "Defeat 10 Horde units or players in Venture Bay and return to Lieutenant Stuart.", completion = "Your bravery has inspired the men of the Westfall Brigade. Even now they fight with greater ferocity. The port will soon be ours." }
WordHunterWoW_QuestEN[12317] = { title = "Keep Them at Bay", description = "This wretched Westfall Brigade is proving a tougher opponent than we'd thought. Though few in number, they fight well and bravely, but we cannot afford to wait them out.\n\nConqueror Krenna's orders were to capture the port quickly. You must break the stalemate, {name}. Find the enemy's marines and slaughter them until the resistance ceases. Only then will we be able to claim ownership of the port.\n\nGo quickly. We don't want to keep Conqueror Krenna waiting.", objectives = "Defeat 10 Alliance units or players in Venture Bay and return to Centurion Kaggrum.", completion = "The port will soon fall to us. You have done well this day, <name>." }
WordHunterWoW_QuestEN[12318] = { title = "Save Brewfest!", description = "{name}, our spies have discovered a fiendish plot! The Dark Iron dwarves want our beloved Brewfest destroyed!\n\nCoren Direbrew, head of a renegade family of brewers, has marshaled the dwarves of Blackrock Depths. Their vile mole machines attack us constantly.\n\nOur spy is in the Grim Guzzler, a tavern in the bowels of Blackrock Depths. He'll know more of Direbrew's plot.\n\nFind our spy. Save Brewfest!", objectives = "Speak with the Brewfest Spy in the Grim Guzzler of Blackrock Depths.<name>, our spies have discovered a fiendish plot! The Dark Iron dwarves want our beloved Brewfest destroyed!\n\nCoren Direbrew, head of a renegade family of brewers, has marshaled the dwarves of Blackrock Depths. Their vile mole machines attack us constantly.\n\nOur spy is in the Grim Guzzler, a tavern in the bowels of Blackrock Depths. He'll know more of Direbrew's plot.\n\nFind our spy. Save Brewfest!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[12319] = { title = "Mystery of the Tome", description = "What can it be, {name}? That was certainly no ordinary curse that the blasted lich put on you!\n\n<Durkon flips through the grisly pages of the tome.>\n\nI don't even know if I'm looking at it the right way. We must find out what information is held within this tome!\n\n<Durkon hands the book back to you.>\n\nThe High Commander will know what to do. Take the flesh-bound tome to him and tell him exactly what happened here.", objectives = "Take the Flesh-bound Tome to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.", progress = "The necrolord is no more?", completion = "<Halford's eyes widen.>\n\nThe fates smile down upon us on this day, <name>. I know just the person to see about this tome." }
WordHunterWoW_QuestEN[12320] = { title = "Understanding the Language of Death", description = "Take the book and follow the path leading up to the barracks. Once inside the barracks take the staircase down to the prison. At the prison you will find Inquisitor Hallard and our mayor, Godfrey. I believe Godfrey might be the missing piece of this puzzle and Hallard the man to put it all together.\n\nGo now!", objectives = "Take the Flesh-bound Tome to Inquisitor Hallard at the Wintergarde Keep prison.", progress = "You come from high command, my son?", completion = "Perhaps, with proper motivation, Godfrey will tell us what he knows about the tome.\n\n<Hallard turns to Mayor Godfrey.>\n\nIsn't that right, mayor?" }
WordHunterWoW_QuestEN[12321] = { title = "A Righteous Sermon", description = "Godfrey Goodard, once a righteous man and mayor of Wintergarde, is now an agent of the Scourge. His transformation from man to undying ghoul has taken place slowly, over time. He hears the call of the Lich King now and lives only to serve his master.\n\nBut as with all Scourge, Godfrey knows the language of death and with proper motivation, will tell us what we need to know about the tome.\n\nOnce you hear what you need to hear, return to the High Commander at the front lines. I'll clean up here as needed.", objectives = "Wait for Inquisitor Hallard to finish his Righteous Sermon and return to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight with the information you uncover.", completion = "We should have known about the damned mausoleum. This is preposterous! Duke August Foehammer and Ambo Cash will be dispatched to the front lines in preparation for our next assault.\n\nOnce you have cleared the mines I will send you to Foehammer so that we may begin our attack against the Scourge of Naxxramas!\n\nThe information you have garnered thus far will be sent to Lord Fordragon at the Wrathgate upon the wings of our most able gryphon!" }
WordHunterWoW_QuestEN[12323] = { title = "Smoke 'Em Out", description = "There are still pockets of cowardly Venture Company men holed up in some of the buildings at the center of Venture Bay. I need every man I can spare out there fighting against the Horde, but we can't allow those Venture Company stragglers to camp out in those buildings, either.\n\nMaybe we can \"convince\" them to make for their ship. Take this smoke bomb and use it to smoke out the stragglers from their places in the bunkhouse, sawmill, or stables. Don't get too close, though; they probably bite.", objectives = "Use the Smoke Bomb to drive 20 Venture Company Stragglers from their buildings and then report to Sergeant Downey.", completion = "Well done, soldier! Now the rest of the men can focus their efforts on the Horde." }
WordHunterWoW_QuestEN[12324] = { title = "Smoke 'Em Out", description = "Not only is this port infested with sniveling Alliance cowards, but to make matters worse, there are still Venture Company employees holed up in some of the buildings. They're not worth the time it takes to kill and I can't spare the warriors anyway.\n\nMaybe we can \"convince\" them to make for their ship. Take this smoke bomb and use it to smoke out the stragglers from their places in the bunkhouse, sawmill, or stables. Don't get too close, though; there's no telling what diseases they're carrying.", objectives = "Use the Smoke Bomb to drive 20 Venture Company Stragglers from their buildings and then report to Stone Guard Ragetotem.", completion = "The general will be pleased that you've dealt with the Venture Company problem. Now, the men can focus on beating back the Alliance." }
WordHunterWoW_QuestEN[12325] = { title = "Into Hostile Territory", description = "You have done much to advance our efforts against the Scourge, {name}. In fact, the morale of all those who have come into contact with you soars! Such is your influence over the soldiers and citizenry of Wintergarde, ally.\n\nAnd because of you we are now prepared to go on the offensive! You are to report to Duke August Foehammer, across the Carrion Fields at Thorson's Post, east of here. Gryphon Commander Urik at the gryphon station has prepared a special gryphon to drop you behind enemy lines. Go now!", objectives = "Speak with Gryphon Commander Urik to secure a ride to Thorson's Post. Report to Duke August Foehammer when you arrive at Thorson's Post in Dragonblight.", completion = "Ah, the distinguished hero arrives. Welcome to ground zero, <name>. Allow me to bring you up to speed!\n\nThel'zan's most powerful forces have made their way into the Wintergarde Mausoleum. They plumb its depths in search of corpses and souls to send against Wintergarde while Naxxramas rains down terrible Scourge plague machines, set to hold us at bay!\n\nWe must strike now and hope that Lord Fordragon is able to hold out at the Wrathgate for just a little longer." }
WordHunterWoW_QuestEN[12326] = { title = "Steamtank Surprise", description = "This is a seek and destroy mission. You'll be driving a tank into the Carrion Fields to dismantle Scourge plague wagons. With the tank comes a crew of three 7th Legion soldiers. All must survive if this mission is to succeed!\n\nYou'll need to get in close to a plague wagon to unleash your engineer. Let them do their deed and move on to the next one. When the field is clear of plague wagons, head to the mausoleum in front of the ruined keep and drop off the rest of your crew. Meet with Ambo Cash inside.", objectives = "Use an Alliance Steam Tank to destroy 6 Plague Wagons and deliver the 7th Legion Elites to Wintergarde Mausoleum. Speak with Ambo Cash inside the Wintergarde Mausoleum in Dragonblight should you succeed.", progress = "Name's Cash. Ambo Cash. And the pleasure is all yours.", completion = "Why I'm not wearing any pants isn't important. Let's just say I took some Scourge shrapnel in the wrong place and leave it at that, ok?\n\nSo you wiped out those plague wagons up in the fields and got my soldiers here in one piece. Impressive. You're one of the first to make it this far, friend. Too bad you gotta go right back out into the Carrion Fields. Yep, we've had a bit of a setback." }
WordHunterWoW_QuestEN[12327] = { title = "Out of Body Experience", description = "Ah, you seek a vision of the past.  You're a wise {race}.\n\nEvery time someone drops by for a reading, they seem to always ask about the future.  When you get to be my age, you learn that scrying the past, more often than not, is more useful.\n\nDrink this potion and peer into my crystal ball.  Let us see what knowledge we can obtain.", objectives = "Drink the Gossamer Potion near Ruuna's Crystal Ball and witness the Vision from the Past.", progress = "Yes, <name>?", completion = "Did you learn anything from your vision?  You mentioned Solstice Village during your trance -- which marks the second time someone has spoken the place's name today." }
WordHunterWoW_QuestEN[12328] = { title = "Ruuna's Request", description = "I will not charge you gold for my services, for I can foresee that your actions are necessary and much hinges on what you learn today.\n\nI will, however, ask you to collect a reagent for me.  Obtain gossamer dust from the fern feeder moths northeast of here.  Do this and I will prepare a potion that will take you to the time and place where the events took place that you need to witness.", objectives = "Ruuna the Blind wants you to obtain 4 handfuls of Gossamer Dust.", progress = "Did you obtain the dust, <name>?", completion = "Good.  These will do just fine.\n\nI will have the potion ready for you in no time at all." }
WordHunterWoW_QuestEN[12329] = { title = "Fate and Coincidence", description = "There are two types of people in this world, {name}.  Those who believe in coincidence and those who don't.\n\nOn the day I lost my eyesight I was given the gift of clairvoyance.  I suppose you can guess what sort of person I am.\n\nEarlier today, a young woman named Sasha was granted the same vision you were.  You will want to talk to her.\n\nYou'll find her directly east of here at the White Pine Trading Post, on the way to Solstice Village.", objectives = "Speak to Sasha at the White Pine Trading Post.", completion = "I was wondering when you'd turn up.  Think you can give me a hand here?" }
WordHunterWoW_QuestEN[12330] = { title = "Anatoly Will Talk", description = "My sister is here somewhere, and I can't seem to get this monster to talk.\n\nHe doesn't seem to care about his own well-being, but I've an idea.  I knew Anatoly's wife, Tatjana, from before the wolfcult arrived -- she was a horse-handler.\n\nTake this tranquillizer dart.  Bring her back alive, we're going to need her if we're to have any leverage with Anatoly.\n\nI will help you find the person behind all this once we save my sister.", objectives = "Sasha at the White Pine Trading Post wants you to take the Tranquilizer Dart and use it on Tatjana in Solstice Village. Bring Tatjana back to the White Pine Trading Post.", completion = "That... that was close.\n\nWe need to save Anya.  Now!" }
