WordHunterWoW_QuestEN[12372] = { title = "Defending Wyrmrest Temple", description = "Emboldened by the overabundance of magic now flowing through the Azure Dragonshrine, the blue dragonflight has dared to attack Wyrmrest Temple itself!\n\nI ask that you ride one of our defenders into battle to slay their dragons and drakes, and to attack the eruption of ley line energies at the dragonshrine itself in order to destabilize it.\n\nOutside on the east and west terraces are wyrmrest defenders. Speak with one to ride it into battle.\n\nWithout your help, {name}, we will surely lose.", objectives = "Devrestrasz at Wyrmrest Temple has asked you to slay 3 Azure Dragons, slay 5 Azure Drakes, and to destabilize the Azure Dragonshrine while riding a Wyrmrest Defender into battle.", progress = "How fares the fight?  Are we pushing them back?", completion = "Incredible! Let me just say that I continue to be amazed by what you younger races seem capable of.\n\nWe are indebted to you. Will you come back and help us again tomorrow?" }
