WordHunterWoW_QuestEN[12411] = { title = "A Sister's Pledge", description = "Please, {name}.  I know it is Arugal you're after.  I swear on my father's memory I will help you take him down.\n\nBut I must beg you... Anya is completely innocent, we cannot leave her with these savages.\n\nHelp me rescue my sister and you'll have me at your side when you face Arugal.\n\nI know the den Anatoly spoke of.  We'll find it on the other side of this hill.  Let's go, my sister's in danger.", objectives = "Look for Anya in the Duskhowl Den near Solstice Village.", completion = "I don't want to be here anymore.  The worgen-men are mean." }
WordHunterWoW_QuestEN[12412] = { title = "My Enemy's Friend", description = "If there is one thing I can get through your head, let it be this: the Alliance will be crushed in the Grizzly Hills.\n\nThere is far too much lumber, ore, game and strategic territory for us to give up on any single battlefront here.\n\nSo far we've been successful... but there's something that could tip the scales in our enemy's favor.\n\nFar to the east  of here, at the Forest Edge's Post, local trappers seek to join the Alliance.  Slaughter them before they have the chance to do so.", objectives = "Conqueror Krenna in Conquest Hold wants you to slay 8 Silverbrook Hunters and their leader, Vladek, at the Forest's Edge Post.", completion = "You're back.  And you're alive.\n\nNow what's this nonsense about worgen?" }
WordHunterWoW_QuestEN[12413] = { title = "Attack on Silverbrook", description = "A few hours ago, the trappers were nothing but peasants threatening to add their number to the Alliance's.\n\nNow they've become something else... an uncertainty.  I do not like uncertainties.  Go to the hills outside their main town in northern Grizzly Hills, Silverbrook, and help my men crush them.", objectives = "Conqueror Krenna at Conquest Hold wants you to slay 8 Silverbrook Defenders in the Silverbrook Hills.", completion = "Not bad, <name>.  You might be slightly more useful than I initially thought." }
WordHunterWoW_QuestEN[12414] = { title = "Mounting Up", description = "Cap'n Stoutmantle left most of our calvary... cavlary... uh, horsemen at the fight for Venture Bay.\n\nWe chose a good place to put the camp 'cause there are tons of highland mustangs running around near here and in the Boulder Hills to the northeast. The Cap'n put me in charge of capturing some of 'em.\n\nWill you help? I've got a stick and some string, and there are loads of wild carrots growing near the camp. Pick the carrots and use them with the stick to lure in the mustang, then ride it back here.", objectives = "Ride 5 Highland Mustangs back to Squire Percy at the Westfall Brigade Encampment.", progress = "Did you get all the mustangs we'll need?", completion = "Wow! These sure are good horses! I think the Cap'n will be real pleased with our work." }
WordHunterWoW_QuestEN[12415] = { title = "The Horse Hollerer", description = "The Alliance's 'Westfall Brigade' is camped far to the north, near Thor Modan. They have foolishly divided their forces to contest our control of Venture Bay, and they have been left without cavalry.\n\nThey're now trying to capture and tame the wild highland mustangs that roam the area around the Westfall Brigade Encampment and Boulder Hills. We must stop them before they're able to replace their lost mounts. Take this and throw it near the horses to drive them away.", objectives = "Scare 15 Highland Mustangs and return to Soulok Stormfury at Camp Oneqwah.", completion = "<Soulok nods in approval.>\n\nWell done, <name>. We must not let the Alliance gain any kind of advantage." }
WordHunterWoW_QuestEN[12416] = { title = "Heated Battle", description = "The Scourge have overrun the shrine. The shrine's keeper, Dahlia Suntouch, is nowhere to be found. The red wyrms that fell in the shrine's defense now beset us in the form of twisted skeletal emberwyrms. The situation is dire, {race}.\n\nCaptain Iskandar leads a group of your kind in stemming the flow of the Scourge out of the shrine.\n\nGo to his aid... but please stay behind his men. The flow of Scourge is endless and I don't want to lose you in one of those scarred canyons.", objectives = "Aid Captain Iskandar in holding the canyons by participating in the death of 12 Frigid Ghoul Attackers, 8 Frigid Geist Attackers, and 1 Frigid Abomination Attacker.\n\nReturn to Ceristrasz once you have finished this task.", progress = "I'm glad you're still with us, <race>.", completion = "It is a disgusting task, but I thank you dearly for doing it.\n\nThe Scourge cannot be permitted to push any further towards Wyrmrest or we are sure to lose it." }
WordHunterWoW_QuestEN[12417] = { title = "Return to the Earth", description = "I have another task that needs attention. I have brothers who are falling in the battle overhead and if we do not act quickly, they will only bolster the emberwyrm ranks.\n\nGet into the shrine through one of the other passes to the south or north... the Scourge presence should be lighter there.\n\nSearch the shrine for ruby acorns that have fallen from the tree and plant them near the bodies of my fallen brood. Through this, they can give new life... a proud fate for any of my kind.", objectives = "Enter the Ruby Dragonshrine through one of the northern or southern passes and search for Ruby Acorns. Use the Ruby Acorns on the fallen red dragons to return their bodies to the earth. Return to Ceristrasz once the task is complete.", completion = "In the earth, my brothers can grant life anew. You have saved them from a fate far worse than death.\n\nI don't know a word in your tongue that could express how much this means to my kind. Thank you, <race>." }
WordHunterWoW_QuestEN[12418] = { title = "Through Fields of Flame", description = "I have one final task for you, {race}... one that should turn the tide of this fight.\n\nReturn to the shrine and kill the necromancers that are fueling this onslaught. With them dead, we should be able to beat these forces back and eventually retake the shrine.\n\nI also need you to find the source of the corruption under the shrine and put an end to it.\n\nI know I have asked a lot of you, but if you do this for me, we will win this battle.", objectives = "Enter the Ruby Dragonshrine through one of the northern or southern passes, then kill 6 Frigid Necromancers and eliminate the source of the corruption under the shrine. Return to Ceristrasz once the task is complete.", completion = "Dahlia... they turned her?\n\nDahlia has been loyal to us for a very long time... if they can corrupt a being of her devotion, it does not bode well for the rest of the young races. Thank you for freeing her. I hope she has found some peace.\n\nYou have honored us with your selfless assistance today, <race>. I will send word to the council of what your kind have accomplished here. Go with our blessing." }
WordHunterWoW_QuestEN[12419] = { title = "The Fate of the Ruby Dragonshrine", description = "As you pick up the brooch, its faint glow brightens slightly.\n\nKrasus will want to know of Dahlia's fate. Take the brooch to him at Wyrmrest.", objectives = "Bring Dahlia Suntouch's Ruby Brooch to Krasus in the Ruling Council Chamber at Wyrmrest and inform him of Dahlia's fate.", progress = "Hello, <race>. I sense the presence of my Ruby Brooch. Hand it here.\n\nWhat has become of Dahlia?", completion = "Dahlia was taken by the Scourge? This is a sad day for all of us.\n\nI will look to finding a new keeper once the shrine is retaken. Thank you for your efforts... the Ruby Dragonshrine is a sacred place to us, and the sacrifices your kind have made will not be easily forgotten.\n\nIt is good to know there are still heroes such as you - I will call upon you one day. Until that day comes, may your adventures be fruitful." }
WordHunterWoW_QuestEN[12420] = { title = "Brew of the Month Club", description = "Membership has its privileges.  Being part of the \"Brew of the Month\" club means knowing where to get the latest and greatest brew.\n\nBring your \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.", objectives = "Bring the \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.", progress = "Do you have your membership forms filled out?", completion = "Your paperwork looks to be in order.  Welcome to the club, <name>!\n\nYou can expect to get our mail at the start of every month.  If you like what you got, stop by and we can sell you some more.  This is the club that keeps on giving." }
WordHunterWoW_QuestEN[12421] = { title = "Brew of the Month Club", description = "There is strength in numbers, {name}.  Being part of the \"Brew of the Month\" club means knowing you and your brethren will always have access to the best brew.\n\nBring your \"Brew of the Month\" club membership form to Ray'ma in Orgrimmar.", objectives = "Bring the \"Brew of the Month\" club membership form to Ray'ma Orgrimmar.", progress = "Do ya have your membership forms filled out?", completion = "So you be joinin' our ranks, <name>?  We treat ya nice here.  You only get the best when you part of dis club!\n\nWe be sendin' out brew to you at da start of every month.  If you like what you got, and you be wantin' more, head back over here.  We make sure you get more of da brew you like." }
WordHunterWoW_QuestEN[12422] = { title = "Tactical Clemency", description = "Listen, {name}.  I need you to act with discretion and speed.\n\nOne of Krenna's top sergeants has captured a trapper outcast outside of Silverbrook.  Now, if things turn out the way they usually do, the prisoner is going to be executed before the day is over.\n\nWe can't let that happen.  You see, the prisoner matches the description of Mikhail's older daughter in his diary.\n\nIf we set her loose and follow her closely, she'll lead us to whoever's controlling the trappers.  Take this letter to her.", objectives = "Deliver the Letter of Amnesty to the Captured Trapper in Silverbrook Hills.", progress = "Are you here to kill me?", completion = "You're going to let me go... just like that?  Listen, I don't want any trouble with you... these monsters killed my father and took my sister.  I have other things on my mind right now." }
WordHunterWoW_QuestEN[12423] = { title = "Mikhail's Journal", description = "From what you can gather, this journal was written by a denizen of Silverbrook named Mikhail.\n\nIt is written in some variant of the common human tongue.  Perhaps you should bring this back to Conqueror Krenna.", objectives = "Bring Mikhail's Journal to Conqueror Krenna in Conquest Hold.", progress = "What's that you've got there?", completion = "Hah!  Is this some sort of joke?\n\nI barely have any use for books I can actually understand." }
WordHunterWoW_QuestEN[12424] = { title = "Gorgonna", description = "This book is written in the pig-tongue the humans use.  It needs to be burned immediately.\n\nHand it to my sister Gorgonna and do not waste my time.", objectives = "Bring Mikhail's Journal to Gorgonna in Conquest Hold.", progress = "You have something to show me?", completion = "Could it be?  The man who wrote this journal feared for his daughters' lives so he sent them away from Silverbrook.\n\nWe just captured an outcast in the outskirts of town about the same age as the eldest daughter.\n\nListen, <name>.  There's more happening here than meets the eye... we can't just burn this diary." }
WordHunterWoW_QuestEN[12425] = { title = "Ruuna the Blind", description = "This trapper business has the potential to be more important than we've accounted for.\n\nIf they're not with the Alliance, there's a good chance they're with the Scourge, which could mean trouble.\n\nOur previous efforts might've paid off, though.  We spotted our former captive meeting with a fortune teller of some sort before we lost track of her.\n\nI'm almost certain now that she will take us to their leader if we can find her again.  Find Ruuna the Blind and see what you can find out.", objectives = "Speak to Ruuna the Blind at Ruuna's Camp near Vordrassil Pass.", completion = "You seek knowledge beyond your reach so you've come to me.  I must warn you, stranger, the answers I provide might not be to your liking." }
WordHunterWoW_QuestEN[12426] = { title = "DEPRECATED", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[12427] = { title = "The Conquest Pit: Bear Wrestling!", description = "So you're interested in the fights, eh?  Well, Krenna has outlawed pit-fighting for all enlisted combatants.  But you, my friend, are technically a free agent and are not included in this prohibition.\n\nNice loophole, eh?\n\nAnyway, if you're interested I can start you off with something easy, a measly bear.  I'll even let you bring friends along!", objectives = "Defeat Ironhide inside the Conquest Pit and speak to Bookie Vel'jen for a reward.", progress = "It's not over until you or the bear tips over, friend!", completion = "Nice work, mon!  Here's your cut." }
WordHunterWoW_QuestEN[12428] = { title = "The Conquest Pit: Mad Furbolg Fighting", description = "You're not bad.  Not bad at all.\n\nThink you can take a furbolg?  What about one of those extra-large crazed Northrend furbolgs?\n\nGood, good.  Get your crew together, and head to the ring.  Let's give these folks a show... maybe we can earn some more coin while we're at it.", objectives = "Defeat Torgg Thundertotem inside the Conquest Pit and speak to Bookie Vel'jen for a reward.", completion = "Those were some sharp moves, friend!  Lots of bets against you, which is good news cash-wise!" }
WordHunterWoW_QuestEN[12429] = { title = "The Conquest Pit: Blood and Metal", description = "It's nice to have a real fighter around these parts... we'd only had prisoners and caged beasts for the past few weeks.  The people get bored, ya know?\n\nAnyhow, your next challenge is a genuine iron golem stolen from the depths of Thor Modan... think you can swing it?", objectives = "Defeat Rustblood inside the Conquest Pit and speak to Bookie Vel'jen for a reward.", completion = "My heart nearly skipped a beat there!  Thought that mound of metal was gonna get ya, mon!" }
WordHunterWoW_QuestEN[12430] = { title = "The Conquest Pit: Death Is Likely", description = "I'm gonna shoot straight with ya, kid.  This next contender's a murderer.\n\nLiterally.\n\nHe was to be executed last week, but he strangled the hangman with his left hand, so Krenna's guards sort of let me have him.\n\nFeel free to pass on this one.  I wouldn't blame ya.", objectives = "Defeat Horgrenn Hellcleave inside the Conquest Pit and speak to Bookie Vel'jen for a reward.", completion = "Fancy footwork, fancy footwork.  You really made quick work of that crazy orc, friend.\n\nOdds were against you seven-to-one; made some nice coin on that one!" }
WordHunterWoW_QuestEN[12431] = { title = "The Conquest Pit: Final Showdown", description = "You must've really upset Krenna.  She and Gorgonna have had a spat and you're wanted in the pit immediately.\n\nThere are some wild rumors that it's a fight to the death!  That would be bad news for you, but great news for our business venture!\n\nAt any rate, you can't run away from fate... best get in there on the quick and get it over with.", objectives = "Defeat Krenna in the Conquest Pit.", completion = "What happened today... had to happen.  It doesn't mean I have to be happy about it.\n\nI've freed my people from a tyrant, but I've also lost a sister.  I thank you for your help, <name>.  I wish to be alone now." }
WordHunterWoW_QuestEN[12432] = { title = "Riding the Red Rocket", description = "You there, {race}! Get your lousy carcass over here!\n\nThe Alliance have a shipment of lumber all ready for transport just northeast of here. Since getting our hands on that wood is out of the question, there's only one thing to do - destroy it!\n\nThe goblin at the end of the dock here has some torpedoes all ready to go. He's got all the fuel for them on the docked goblin ship to the north.\n\nGet some fuel, then commandeer one of the torpedoes and ride it into their ship.\n\nDismissed!", objectives = "General Gorlok at the lighthouse in Venture Bay wants you to destroy the Alliance Lumber Boat.\n\nGeneral Gorlok will only be present at the lighthouse when the Horde has it in their possession.", progress = "Has that Alliance lumber been burned yet, <class>?", completion = "Ha hah! What a ride, eh <class>?\n\nIf we can't control the resources here, then no one can!\n\nWhen will those puny Alliance pests realize that they are no match for the might of the Horde?" }
WordHunterWoW_QuestEN[12433] = { title = "Seeking Solvent", description = "Gah! Not again. Another blown gasket....\n\nEvery time one of these goes, lubricant gums up all of the gears. Without solvent, it takes hours to clean.\n\nTell ya what, {race}. There's some fancy rocket fuel on the Venture Company barge in the dock there - element 115 I think they call it. That stuff makes for a great solvent.\n\nGet me one of those and I'll make it worth your trouble.", objectives = "Gurtor at the Venture Bay Horde base wants you to bring him a canister of Element 115.", progress = "You got some of that element 115, <name>?", completion = "Ahh yes. That'll save me hours.\n\nTake this for your trouble, friend. And keep an eye out for more element 115. I'll take all you can find." }
WordHunterWoW_QuestEN[12434] = { title = "Always Seeking Solvent", description = "", objectives = "" }
WordHunterWoW_QuestEN[12435] = { title = "Report to Lord Devrestrasz", description = "I abhor the loss of life... any life. But I will not stand idly by and allow Malygos to kill us and defile the temple!\n\nI have appointed Lord Devrestrasz as the commander of Wyrmrest's defenses.\n\nSpeak with Torastrasza to ride a drake down to him.\n\nPlease lend him your aid, {name}. Your involvement with the defense of Wyrmrest will be critical to us prevailing against the blue dragonflight.", objectives = "Speak with Lord Devrestrasz at Wyrmrest Temple.", completion = "You must be <name>. The queen informed me that you would be coming.\n\nIf you are willing, we are in great need of your assistance." }
WordHunterWoW_QuestEN[12436] = { title = "Supplemental Income", description = "Hail, {class}.  You'll find that here at Conquest Hold, we buy and sell what Krenna wants us to buy and sell... at the price that Krenna wants us to buy and sell.\n\nAll this is stifling business.  I'm hoping to make a little bit of coin on the side and feed our grunts at the same time.  Why don't you go hunt down some stag and bring me the venison?\n\nThey're numerous in the area, so bring me only the best meat.", objectives = "Provisioner Lorkran at Conquest Hold wants you to obtain 5 Succulent Venison from  the nearby Tallhorn Stag.", progress = "You get that venison yet, <name>?", completion = "Nice job, <name>.  These will feed two or three grunts each.  Not bad." }
WordHunterWoW_QuestEN[12437] = { title = "Riding the Red Rocket", description = "Listen, {name}. This battle is as much over resources as tactical supremacy.\n\nI have a mission that could turn the tide in our struggle against the Horde here.\n\nThere are torpedoes at the end of the dock that we can use to take down the Horde's lumber ship to the northwest.\n\nYou'll need to get some of the fuel that's stored on the docked goblin ship just north of here, then ride one of the torpedoes into their transport!", objectives = "Commander Howser at the lighthouse in Venture Bay wants you to destroy the Horde lumber shipment.\n\nCommander Howser will only be present at the lighthouse when the Alliance has it in their possession.", progress = "Has that Horde lumber ship been burned yet, <name>?", completion = "Good to see that you survived that impact. Quite the explosion!\n\nWe can't afford for the Horde to make off with all that lumber.\n\nWell done, <class>." }
WordHunterWoW_QuestEN[12438] = { title = "WANTED: Kreug Oathbreaker", description = "Posted by: Illusia Lune\n\nThe Scourge flesh giant known as Kreug Oathbreaker was responsible for the deaths of my husband, children and my dear friends, the Whisperveils. Those brave enough to take on this bounty will find Kreug in the southeastern reaches of the Carrion Fields.\n\nI demand justice! Kill Kreug Oathbreaker!\n\nIn the event that Kreug is slain, I have pooled money and items together and given them to Highlord Leoric Von Zeldig to give out as a reward.\n\nPlease vindicate us!", objectives = "Kill Kreug Oathbreaker and return to Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight to collect your reward.", completion = "Well done, <name>. I will notify Illusia that a hero has heard her call for help and risen to meet the challenge! Here is your reward." }
WordHunterWoW_QuestEN[12439] = { title = "A Disturbance In The West", description = "Another force threatens to destroy all that we have worked for, {name}. You must head westward to Stars' Rest. Archmage Modera has sensed a great disturbance in the magical ley lines of our world that must be dealt with immediately!\n\nGo now, {name}! Speak to Rodney Wells at the gryphon station here in Wintergarde and let him know the nature of your mission. He will place you on his fastest gryphon to deliver you to Stars' Rest. Speak with Archmage Modera when you arrive.", objectives = "Speak to Rodney Wells at Wintergarde Keep to secure a ride to Stars' Rest in western Dragonblight.", completion = "We definitely don't want another sundering, friend. I'll do all that I can to help you on your mission." }
WordHunterWoW_QuestEN[12440] = { title = "To Stars' Rest!", description = "When you are ready I will place you on my fastest gryphon to Stars' Rest. Once you get there, find and speak with Archmage Modera.\n\nGood luck, ally!", objectives = "Speak with the Image of Archmage Modera at Stars' Rest in western Dragonblight.", completion = "Vas heard my distress call then, eh? Not a moment too soon, friend." }
WordHunterWoW_QuestEN[12441] = { title = "WANTED: High Shaman Bloodpaw", description = "Posted by: Drolfy\n\nWhile out in the Eldritch Heights with my cousins, Skrotee and Brote, a vicious band of wolvar from the Bloodpaw tribe attacked us. We attempted to flee, but I fear they got Skrotee and Brote.\n\nI demand retribution! Is there someone brave enough to venture to the southeastern reaches of Dragonblight, to the Eldritch Heights, and kill High Shaman Bloodpaw and his cronies?\n\nI have given a hefty sum of gold to Highlord Leoric Von Zeldig to disperse to anyone that claims this bounty!", objectives = "Kill High Shaman Bloodpaw and return to Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight to collect your reward.", completion = "Outstanding work, <name>! I will notify Drolfy that a hero did rise to meet his challenge and that the cruel Bloodpaw is no more!" }
WordHunterWoW_QuestEN[12442] = { title = "WANTED: Onslaught Commander Iustus", description = "Posted by: Highlord Leoric Von Zeldig\n\nUpon the northeastern path from Wintergarde a battalion of 7th Legion were ambushed and slain by Onslaught Commander Iustus and an army of mindless Scarlet Onslaught zealots. Such cold and calculated actions must be met with force!\n\nWintergarde demands justice! Seek out Onslaught Commander Iustus at Onslaught Base Camp to the northeast and end his miserable existence.\n\nI will hand out the reward for this bounty to any who would dare take up the task!\n", objectives = "Kill Onslaught Commander Iustus and return to Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight to collect your reward.", completion = "At least for now the Scarlet Onslaught suffers a setback in their nefarious plans. You have done Wintergarde a great service, <name>." }
WordHunterWoW_QuestEN[12443] = { title = "Seeking Solvent", description = "Gah! Not again. Another blown gasket....\n\nEvery time one of these goes, lubricant gums up all of the gears. Without solvent, it takes hours to clean.\n\nTell ya what, {race}. There's some fancy rocket fuel on the Venture Company barge in the dock there - element 115 I think they call it. That stuff makes for a great solvent.\n\nGet me one of those and I'll make it worth your trouble.", objectives = "Barblefink at the Alliance base in Venture Bay wants you to bring him a canister of Element 115.", progress = "You got some of that element 115, <name>?", completion = "Ahh yes. That'll save me hours.\n\nTake this for your trouble, friend. And keep an eye out for more element 115. I'll take all you can find." }
WordHunterWoW_QuestEN[12444] = { title = "Blackriver Skirmish", description = "The Venture Company's on its way out of Grizzly Hills.  They used to run logging operations here, but things got a little too dangerous for them.\n\nTheir abandoned sites are up for grabs and we sure as hell can't let the Horde get their hands on them.\n\nThe Blackriver Logging Camp is the smallest of the three logging sites in this zone, but we still need it.  Do your part and fend off the Horde forces.  Any lumber they get here will be made into weapons to be used against us elsewhere.", objectives = "Scout Captain Carter wants you to kill 10 Horde units or players in the Blackriver Logging Camp.", progress = "How's the hunt going?", completion = "Nice work, <name>.  We could use a few more folks like you up here.  We could really show the Horde not to mess with us." }
WordHunterWoW_QuestEN[12446] = { title = "Always Seeking Solvent", description = "", objectives = "" }
WordHunterWoW_QuestEN[12447] = { title = "The Obsidian Dragonshrine", description = "The Scourge come. Korialstrasz calls upon his allies in a futile attempt to save their Ruby Dragonshrine, but it seems the good graces of the red flight don't extend to saving the shrines of the other flights.\n\nSurprised? I'm not.\n\nThere is another of my brood who has left to clear our Obsidian Dragonshrine of the undead vermin that now infest it. All it would take to prove yourself more noble and righteous than Alexstrasza herself is a quick jaunt over there and a few swings of a blade.\n\nI'm amused.", objectives = "Travel to the Obsidian Dragonshrine Northwest of Wymrest and just West of the Wrath Gate. Locate Serinar inside of the shrine and offer him your aid.", completion = "I'm trying to decide at which I'm more surprised... that you actually came to the aid of a Black Dragon or that you're still in one piece after speaking with Nalice.\n\nHer words drip venom, but I suppose Wyrmrest can keep even our kind in check sometimes.\n\nOr perhaps it's just the armies of the red dragonflight that are massed around her." }
WordHunterWoW_QuestEN[12448] = { title = "Heated Battle", description = "The Scourge have overrun the shrine. The shrine's keeper, Dahlia Suntouch, is nowhere to be found. The red wyrms that fell in the shrine's defense now beset us in the form of twisted skeletal emberwyrms. The situation is dire, {race}.\n\nCaptain Drayzen leads a group of your kind in stemming the flow of the Scourge out of the shrine.\n\nGo to his aid... but please stay behind his men. The flow of Scourge is endless and I don't want to lose you in one of those scarred canyons.", objectives = "Aid Captain Drayzen in holding the canyons by participating in the death of 12 Frigid Ghoul Attackers, 8 Frigid Geist Attackers, and 1 Frigid Abomination Attacker.\n\nReturn to Vargastrasz once you have finished this task.", progress = "I'm glad you're still with us, <race>.", completion = "It is a disgusting task, but I thank you for doing it.\n\nThe Scourge cannot be permitted to push any further out of the shrine lest all of these lands be overrun." }
WordHunterWoW_QuestEN[12449] = { title = "Return to the Earth", description = "I have another task that needs attention. I have brothers who are falling in the battle overhead and if we do not act quickly, they will only bolster the emberwyrm ranks.\n\nGet into the shrine through the pass in the south... the Scourge presence should be lighter there.\n\nSearch the shrine for ruby acorns that have fallen from the tree and plant them near the bodies of my fallen brood. Through this, they can give new life... a proud fate for any of my kind.", objectives = "Enter the Ruby Dragonshrine through the southern pass and search for Ruby Acorns. Use the Ruby Acorns on the fallen red dragons to return their bodies to the earth. Return to Vargastrasz once the task is complete.", completion = "In the earth, my brothers can grant life anew. You have saved them from a fate far worse than death.\n\nI don't know a word in your tongue that could express how much this means to my kind. Thank you, <race>." }
WordHunterWoW_QuestEN[12450] = { title = "Through Fields of Flame", description = "I have one final task for you, {race}... one that should turn the tide of this fight.\n\nReturn to the shrine and kill the necromancers that are fueling this onslaught. With them dead, we should be able to beat these forces back and eventually retake the shrine.\n\nI also need you to find the source of the corruption under the shrine and put an end to it.\n\nI know I have asked a lot of you, but if you do this for me, we will win this battle.", objectives = "Enter the Ruby Dragonshrine through the southern pass, then kill 6 Frigid Necromancers and eliminate the source of the corruption under the shrine. Return to Vargastrasz once the task is complete.", completion = "Dahlia... they turned her?\n\nDahlia has been loyal to us for a very long time... if they can corrupt a being of her devotion, it does not bode well for the rest of the young races. Thank you for freeing her. I hope she has found some peace.\n\nYou have honored us with your selfless assistance today, <race>. Perhaps not all of the Horde bear the black hearts of their ancestors.  I will send word to the council of what your kind have accomplished here." }
WordHunterWoW_QuestEN[12451] = { title = "Onward to Camp Oneqwah", description = "While we build Conquest Hold, I sent Scout Vor'takh to make contact with our taunka allies in the east. They're based in Camp Oneqwah, which is in the easternmost part of Grizzly Hills, beyond Grizzlemaw.\n\nMake the journey there, hear Vor'takh's report and offer your assistance with anything he and the local chieftain may need. Your contributions to Conquest Hold have been exemplary and I know Vor'takh will be grateful for the assistance.", objectives = "Speak with Scout Vor'takh at Camp Oneqwah.", completion = "<You offer a short introduction, explaining you were sent by Sergeant Nazgrim.>\n\nAh, so you're something in the way of reinforcements, then. Good.\n\nTormak and his men have need of your blade." }
WordHunterWoW_QuestEN[12452] = { title = "zzOLD The Fate of the Ruby Dragonshrine", description = "", objectives = "Bring Dahlia's Ruby Broach to Ceristrasz and inform him of her fate." }
WordHunterWoW_QuestEN[12453] = { title = "Eyes Above", description = "I've been asked to lend my support to our efforts against the Alliance.  At the moment our military forces are about evenly matched and we're looking for ways to find an edge.\n\nThe imperial eagles that fly over the mountains and trees in this area would make excellent scouts for us.  Take this silver feather and use it to bind my sight to that of them.\n\nBeing able to see our enemy's movements will grant us the strategic advantage we need.  You'll find abundant eagles in the mountains to the east.", objectives = "Windseer Grayhorn wants you to use the Silver Feather on 6 Imperial Eagles in Grizzly Hills.", completion = "I thank you, <name>.  Your help is appreciated." }
WordHunterWoW_QuestEN[12454] = { title = "Cycle of Life", description = "Ysera sleeps in the Emerald Dream, watching over both the Dream and Azeroth. But a horrible nightmare has taken hold in the Dream, and now I fear that Ysera is being affected by it.\n\nRecently, I asked her to aid in the fight against the Scourge that are raising frostwyrms at the other dragonshrines. She misunderstood.\n\nInstead, she told our dragonshrine's defenders to treat those not of the green dragonflight as enemies.\n\nI need you to slay some of the skytalons. The shrine must regain its balance.", objectives = "Nishera the Garden Keeper at the Emerald Dragonshrine has asked you to slay 5 Emerald Skytalons.", progress = "The sooner that the emerald skytalons can be dealt with, the sooner the Emerald Dragonshrine can be returned to its natural balance.", completion = "Do not regret the part that you played in the cycle of life. Birth, death, and rebirth are all part of the natural order." }
WordHunterWoW_QuestEN[12455] = { title = "Scattered To The Wind", description = "The munitions drop went badly, friend. The shipment of ammo from Westguard Keep was intercepted by the frostwyrms circling overhead. The flying machines were torn apart in a matter of seconds and their cargo was scattered to the wind. Most of it is still topside - on the Carrion Fields.\n\nI'm gonna need you to go back up and recover the munitions crates that are scattered all over this damned place.\n\nHurry it up! We can't start this offensive without guns and ammo, buddy!", objectives = "Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to recover 8 Wintergarde Munitions.", progress = "Where are my munitions, fella?", completion = "Just in time! Some of my soldiers got a little overzealous and decided to wade into the crypts directly to the east and west of us. Needless to say, they were quickly overwhelmed by those mindless ghouls. We need to rescue the survivors!" }
WordHunterWoW_QuestEN[12456] = { title = "The Plume of Alystros", description = "I can feel that the shrine is not completely back in balance. The verdant keeper has been angered by our actions, and I sense that he will not listen to reason.\n\nAlystros is an immense skytalon who perches at the south end of the Emerald Dragonshrine. It is he who is in charge of the dragonshrine's aerial defenses. I fear that we will have to deal with him.\n\nTake these skytalon molts and place them on the ground where he can see them. He will come. Bring me his plume.", objectives = "Nishera the Garden Keeper at the Emerald Dragonshrine has asked you to acquire The Plume of Alystros.", progress = "Have you managed to deal with Alystros? Do not be afraid to ask your friends for assistance.\n\nIn fact, given that the verdant keeper is very powerful, I recommend it!", completion = "Do not weep for Alystros. He has dedicated his eternal life to the defense of the Emerald Dragonshrine and will be reborn.\n\nHopefully when he returns to us, he will not be gripped with the confusion of the Emerald Nightmare that seems to have taken hold of The Dreamer." }
WordHunterWoW_QuestEN[12457] = { title = "The Chain Gun And You", description = "We've set up chain guns and barricades directly to the east and to the west. Our injured soldiers are hiding in both rooms - trying their best to not alert the mindless ghouls to their presence.\n\nNow that we have ammo, I need you to man one of the chain guns and use it to blast a path clear for our soldiers! Once you're on board, call a soldier out from hiding and then lay down heavy fire to keep the Scourge off him!\n\nGet a move on!", objectives = "Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to save 8 Injured 7th Legion Soldiers.", progress = "Have you rescued our injured soldiers?", completion = "<name>, I haven't seen heroics like that since Silithus!\n\nI'll be sure that each and every one of those soldiers puts in a recommendation to Lord Fordragon that you be promoted!\n\nNow, on to more pressing matters. We've gotten reports back from our scouts that Thel'zan is close." }
WordHunterWoW_QuestEN[12458] = { title = "Seeds of the Lashers", description = "We need more weapons in the fight against the Scourge. The natural properties of the Emerald Dragonshrine to the southeast may be the answer.\n\nAny unliving creature, save those that Sylvanas has redeemed, that steps foot in the dragonshrine falls to dust.\n\nI want to test a theory, and I want you to be my instrument in doing so, young {race}. Go to the Emerald Dragonshrine and take the seeds from the emerald lashers therein.", objectives = "Lord Itharius at the top of Wyrmrest Temple has asked you to return with 3 Lasher Seeds.", progress = "And just how many seeds have you managed to acquire thus far?", completion = "Even now I can feel the pulse of nature from within these seeds.\n\nWe must put them to good use!" }
WordHunterWoW_QuestEN[12459] = { title = "That Which Creates Can Also Destroy", description = "Since we only have three seeds, we must put them to the best possible use.\n\nYour targets are one of the reanimated frost wyrms circling to the north near Galakrond's Rest, Turgid the Vile in the ruined barracks at the Carrion Fields to the east, and Overseer Deathgaze at Jintha'kalar far to the northeast.\n\nWhile the seeds would outright destroy one of the lesser Scourge, they will greatly weaken these three. Enough so, in fact, that you should be able to handle them on your own.", objectives = "Lord Itharius at the top of Wyrmrest Temple has asked you to destroy a Weakened Reanimated Frost Wyrm, Weakened Turgid the Vile, and Weakened Overseer Deathgaze.", completion = "Excellent. Just as I suspected all along. I shall have to attempt to contact Ysera and see if she approves.\n\nIf she can be coaxed from her nightmare, of course.\n\nThank you, <name>. You have been indispensable." }
WordHunterWoW_QuestEN[12460] = { title = "Report to the Ruby Dragonshrine", description = "We need you at the Ruby Dragonshrine.\n\nThe dragons are beset on all sides by the blue flight and the scourge... they're in no better a state than we are. The situation seems dire, but this affords us a rare opportunity to establish a valuable alliance.\n\nI secured a regiment to aid the red dragonflight against the Scourge at the Ruby Dragonshrine. If you have a fight in you, please go find Ceristrasz on the ridge east of the shrine and help him in any way that you can.", objectives = "Report to Ceristrasz on the ridge east of the Ruby Dragonshrine, west of Wyrmrest.", completion = "Ambassador Lauriel sent you?\n\nIf you talk to her again, please let her know that we are very appreciative of her aid. We are fighting battles on far too many fronts." }
WordHunterWoW_QuestEN[12461] = { title = "Report to the Ruby Dragonshrine", description = "You are leaving to the Ruby Dragonshrine. This is not a request.\n\nThe dragons are beset on all sides by the blue flight and the scourge... they're in no better a state than we are. It is not often we are afforded the opportunity to redeem ourselves for the transgressions of our ancestors.\n\nI have secured a regiment to aid the red dragonflight against the Scourge at the Ruby Dragonshrine. Join them and crush the Scourge beneath your boots!\n\nFor the Horde!", objectives = "Report to Vargastrasz on a ridge outside of the Ruby Dragonshrine, just east of Agmar's Hammer.", completion = "Ambassador Golluck sent you?\n\nIf you talk to him again, please let him know that we are very appreciative of his aid. We are fighting battles on far too many fronts." }
WordHunterWoW_QuestEN[12462] = { title = "Breaking Off A Piece", description = "Just down the steps lies the gateway to damnation: Scourge as far as the eye can see and getting thicker with each passing moment. What little intelligence we've been able to gather indicates that two Scourge necrolords are furiously working at emptying the first two crypts down below. Before we can breach the inner chamber to Thel'zan, we'll need to take care of those two clowns and their Naxxramas cronies.\n\nGo down into the mausoleum and take out the necrolords and the Naxxramas dreadguards and shades.", objectives = "Yord \"Calamity\" Icebeard at the Wintergarde Mausoleum in Dragonblight wants you to kill Necrolord X'avius, Necrolord Horus, and 15 Naxxramas Scourge.", progress = "Did you break yourself off a piece?", completion = "That oughta buy Ambo a little bit of time to get things situated." }
WordHunterWoW_QuestEN[12463] = { title = "Plunderbeard Must Be Found!", description = "There's been talk of a tunnel dug by Scourge that connects the embalming chambers of the mausoleum with the large crypts, now unearthed by Thel'zan and his minions. I recently sent my best rogue, Plunderbeard, in search of answers, but have yet to hear back from him. If I were a betting man I'd wager that he's a goner.\n\nI want you to go down those steps and head straight through the embalming chamber and look for Plunderbeard. Dead or alive, he'll have answers.\n", objectives = "Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to find Plunderbeard.", completion = "<You discover a journal on Plunderbeard's corpse.>\n\nEntry One:\n\nThey drag corpses through the tunnel to the embalming room for experimentation. There is an endless supply in this mausoleum. Whatever cannot be reanimated is turned into a bone construct of one kind or another.\n\nEntry Two:\n\nI fear that this lich, Thel'zan, hides a dark secret. Who is he? Was he once... one of us?\n\nEntry Three: I have discovered the location of the lich's phylactery. It is...\n\n<The rest of the pages are torn out.>" }
WordHunterWoW_QuestEN[12464] = { title = "My Old Enemy", description = "My old enemy, High General Abbendis, has come to Northrend.\n\nSomehow she survived the attacks upon Tyr's Hand and brought a small force north. They've established New Hearthglen to the south.\n\nWhile they could prove useful in fighting the Scourge, Abbendis herself is far too shrewd an opponent to let live. Trust me, if we let them stand, she will be at our throats before the dust settles.\n\nSo, we'll deprive them of their leadership and go about our business. Bring me her head as proof.", objectives = "Deliver The High General's Head to Commander Eligor Dawnbringer at Wintergarde Keep.", progress = "It is done then?", completion = "An unfortunate, but necessary action that we had to take in dealing with Abbendis. In another lifetime, I think I could have imagined fighting side-by-side with her.\n\n<The commander's voice trails off as he reflects a moment before proceeding.>\n\nI'm a little concerned about this grand admiral you describe. Barean Westwind you say? I can't believe that he's still alive. He must be ancient. We'll have to deal with him later, however.\n\nIn the meantime, I think you've earned a reward and a little R & R." }
WordHunterWoW_QuestEN[12465] = { title = "Plunderbeard's Journal", description = "Whatever was written on the remaining pages of Plunderbeard's journal must be recovered. Search the chambers located on the other side of this tunnel for Plunderbeard's assailants. They must be the ones who tore the journal apart!\n\nShould you recover the missing pages, return them to Ambo Cash at the entrance of the Wintergarde Mausoleum.", objectives = "Recover Page 4 of Plunderbeard's Journal, Page 5 of Plunderbeard's Journal, Page 6 of Plunderbeard's Journal, and Page 7 of Plunderbeard's Journal and return them to Ambo Cash at the Wintergarde Mausoleum in Dragonblight.", progress = "I certainly don't feel like a winner...", completion = "<Ambo reads through the recovered journal pages.>\n\nThere's some good news and there's some bad news. Which do you want first?\n\nAh hell, why give you a choice? The good news is that if we can get Thel'zan's phylactery, we can destroy him. The bad news is that the phylactery is on a rather large frostwyrm." }
WordHunterWoW_QuestEN[12466] = { title = "Chasing Icestorm: The 7th Legion Front", description = "You need to get to the 7th Legion Front in northern Dragonblight. Return to Wintergarde Keep and take the north gate out of town. Keep north until you hit a road. Take a left on that road and follow it until you reach the snowline. Once at the snowline keep heading west until you hit the Path of the Titans. Follow that north and it'll lead you right into the 7th Legion Front.\n\nOnce there, speak with Legion Commander Tyralion. He'll be expecting you.\n\nAnd {name} - it has been a pleasure. Farewell.", objectives = "Report to Legion Commander Tyralion at the 7th Legion Front in central Dragonblight.", completion = "Now you know why they call this the Dragon Wastes. Bones of the beasts are strewn about as far as the eye can see.\n\nWe've probably taken down a dozen or more frostwyrms and there's still no end in sight. The Scourge's got fuel for ten-thousand more what with all the bones laying about.\n\n<Tyralion clears his throat.>\n\nI don't mean to bore you with the details, hero. We've got the wyrm you're looking for locked in our sights." }
WordHunterWoW_QuestEN[12467] = { title = "Chasing Icestorm: Thel'zan's Phylactery", description = "Your frostwyrm is out there.\n\n<Tyralion points west.>\n\nAnd it's a big one!\n\nWhen you're ready to fight, go speak with \"Wyrmbait.\" He'll \"fetch\" her. Once Icestorm is close enough we'll chain her to the ground and finish her off! Hopefully, with your help, we'll be able to take her down and get you that phylactery.\n\nOnce you've got the phylactery, return to Wintergarde Keep and report to High Commander Halford Wyrmbane. He's been making preparations for the final showdown with Thel'zan.", objectives = "Recover Thel'zan's Phylactery from Icestorm and return it to High Commander Halford Wyrmbane at Wintergarde Keep.", progress = "Have you recovered Thel'zan's phylactery?", completion = "We've lost so many good soldiers to that monster, Thel'zan. I wish I could be there to see you crush his phylactery in front of him and end his existence." }
WordHunterWoW_QuestEN[12468] = { title = "The Conqueror's Task", description = "The Horde is a magnificent war machine and you are nothing but a cog.\n\nI am in charge of securing fuel for this machine.  If I fail, the machine fails.\n\nLumber, ore, water... it's all here and we want it.  And so does the Alliance.\n\nBefore we can move against the human scum, we need to solidify our control over the western region.\n\nSpeak to Sergeant Nazgrim about eradicating the vrykul in Voldrune and then maybe - if you turn out to not be a complete failure - we'll send you on further tasks.", objectives = "Speak to Sergeant Nazgrim in Conquest Hold.", completion = "So Krenna sent you to me?  She must've not liked you very much, but then again who does she like?\n\nCracking this vrykul outpost is going to be a tough, tough job." }
WordHunterWoW_QuestEN[12469] = { title = "Return to Sender", description = "Upon closer examination, the goblin appears to have been running a pack full of explosives across the wastes for delivery. The harpy feathers half-buried in the snow nearby suggest how he met his ill fate.\n\nIt appears that the goblin was bringing the explosives towards the Wrath Gate from somewhere to the east. It seems most prudent to follow the ridge back to the east and inform the sender of their runner's fate.", objectives = "Follow the ridge to the east and deliver the pack of explosives to Xink at Nozzlerust Post in northern Dragonblight.", progress = "Hello there!", completion = "Hah! We lost another one, eh? Those harpies are becoming a real nuisance.\n\nNo matter! There's work to be done. Lend a hand around here, will ya?" }
WordHunterWoW_QuestEN[12470] = { title = "Mystery of the Infinite", description = "A time storm at the Bronze Dragonshrine to the northeast is keeping immortals from entering.\n\nThe Infinite Dragonflight are in a fight inside with the defenders to wrest control of the dragonshrine. We must take this opportunity to gain information.\n\nYou are not immortal. You can cross into the dragonshrine and use the Hourglass of Eternity. Protect the hourglass for long enough and the leader of the Infinite Dragonflight should be revealed.\n\nBe warned, the Infinite Dragonflight will try to stop you!", objectives = "Chromie, at the top of Wyrmrest Temple, has asked you to travel to the Bronze Dragonshrine. Once inside, place the Hourglass of Eternity on the ground.\n\nProtect the hourglass for as long as it lasts and then return to her with whatever information you gain.", progress = "What news do you bring? What happened at the Bronze Dragonshrine?\n\nDid you find out who the leader of the Infinite Dragonflight is?", completion = "You saw Nozdormu? That doesn't make any sense.\n\n<Chromie thinks a moment about what you've said.>\n\nActually, that's great news! We had no idea of where or when the Lord of Time had gone to. We just knew that he had disappeared to deal with very important matters.\n\nSo, even though the leader of the Infinite Dragonflight wasn't revealed, you've discovered that Nozdormu is alive and well, and fighting back against them!\n\nThank you, <name>. I'll be seeing you soon!" }
WordHunterWoW_QuestEN[12471] = { title = "Cruelty of the Kvaldir", description = "I thank you for saving me, {name}.  The kvaldir are animals!\n\nThey made us fight the other prisoners.  It would've been more merciful to just kill us all.\n\nThe youngling Karuk is still alive -- I noticed him arrive here.  Tell him his father fought until the end.", objectives = "Speak to Karuk about the Captured Tuskarr Prisoner.", completion = "I thank you, <name>.  You've shown a great deal of goodwill towards my clan." }
WordHunterWoW_QuestEN[12472] = { title = "Finality", description = "Thanks to your heroics, Lord Fordragon has given the command to launch a full assault against Thel'zan. 7th Legion have made their way into the summoning chamber of the mausoleum and located what appears to be a gateway to hell. The only piece that's missing now is you.\n\nTake the phylactery and report to Legion Commander Yorik inside the Wintergarde Mausoleum.\n\nThere is a tunnel that the Scourge dug out just outside the keep that you can take to get to Yorik quickly. Go now, {name}! Lead us to victory!", objectives = "Take Thel'zan's Phylactery to Legion Commander Yorik inside the Wintergarde Mausoleum in Dragonblight.", progress = "<Yorik lets out a sigh of relief.>\n\nWe thought you might not show up, <name>.", completion = "When you're ready I'll place the phylactery out in front of the gateway and call forth Thel'zan." }
WordHunterWoW_QuestEN[12473] = { title = "An End And A Beginning", description = "Every good story has a beginning and an ending, {name}. While your story is far from over, I'll be damned if it's not already turning out to be the stuff of legend! No matter what happens to us when this is all over, what you've done at Wintergarde will be a tale told for years to come.\n\nNow, ally, when you are ready I will use the phylactery to coax Thel'zan out of hiding.\n\nShould we somehow succeed, report the victory to High Commander Halford Wyrmbane at Wintergarde Keep.", objectives = "Defeat Thel'zan the Duskbringer and report to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.", completion = "Wintergarde is saved because of you, <name>. To think that one man could so swiftly turn the tides of battle is hard for most to comprehend; yet here we are - victorious! You have managed to restore the faith of these people and earned the respect of your commanding officers.\n\n \n\nLord Fordragon has returned to Angrathar to prepare our forces for the destruction of the Wrathgate and has requested that you join him! I couldn't recommend a better soldier for the job, <name>." }
WordHunterWoW_QuestEN[12474] = { title = "To Fordragon Hold!", description = "With the Naxxramas war machine stopped dead in its tracks the time has come for you to help our forces at Angrathar, the Wrathgate. Nestled against the mountain in northern Dragonblight is our base of operations, Fordragon Hold. It is there that Lord Fordragon awaits your arrival! Go now, {name}!\n\nTake the north gate out of town and travel north by northwest until you arrive at your destination.\n\nLight protect you!", objectives = "Venture to Fordragon Hold in Dragonblight and speak with Highlord Bolvar Fordragon.", completion = "This commendation is only given to those who have gone above and beyond the call of duty in the name of the Alliance. I could count the number of times I've handed this one out on one hand, <name>, and never has anyone been more deserving than you! Congratulations!\n\nNow, let us look upon the Wrathgate. Does it look familiar? It should. That strange ore you found at the Wintergarde Mine is exactly what the Wrathgate is made from. We will find its weakness and expose it for all to see! First, though..." }
WordHunterWoW_QuestEN[12475] = { title = "What Secrets Men Hide", description = "After the betrayal at the Forgotten Shore, Prince Arthas - with Muradin in tow - began his quest for Frostmourne. Could the location of the cavern where Frostmourne was found be near? What secrets could it hold? While the orb has no answers for these questions, it does show me something.\n\nTo the northeast of Wintergarde Keep is an outpost built by the Scarlet Onslaught. Somewhere within that outpost is a map. The orb tells me that this map will be of great use to us.\n\nRetrieve it!", objectives = "Zelig the Visionary at Wintergarde Keep in Dragonblight wants you to find the Onslaught Map and return it to him.", progress = "Have you recovered the Onslaught map?", completion = "A cave? Could it be? There can be no other correlation!" }
WordHunterWoW_QuestEN[12476] = { title = "The Return of the Crusade?", description = "To the northeast of Wintergarde Keep is a newly built encampment, set up by the Scarlet Crusade - or rather - the Scarlet Onslaught as they now call themselves. While we are unsure as to why they are in Northrend, they are certainly no less dangerous than they were before. As of last night the Scarlet Onslaught has killed twelve of our soldiers. They must be taught a lesson, {name}.\n\nGo to Onslaught Base Camp and thin them out. \n", objectives = "Commander Lynore Windstryke at Wintergarde Keep in Dragonblight wants you to kill 20 Scarlet Onslaught at the Onslaught Base Camp.", completion = "Hopefully the message is now clear to the Onslaught. I hope it was enough of a beating to make them doubt their affiliations." }
WordHunterWoW_QuestEN[12477] = { title = "The Path of Redemption", description = "\"The Path of Redemption,\" ever heard of it? It is allegedly a journal that holds the prophetic ramblings of High General Abbendis of the Scarlet Onslaught. Within that book can be found the motivations and goals of the Scarlet zealots - not to mention a whole lot of insanity.\n\nVenture to Onslaught Base Camp, northeast of Wintergarde Keep, and recover a copy of \"The Path of Redemption\" from one of the Onslaught soldiers.", objectives = "Return \"The Path of Redemption\" to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.", progress = "Did you find a copy?", completion = "<Halford reads the journal.>\n\nAbbendis has gone off the deep end. The Light speaks to her now?\n\nDespite the inane ramblings, this journal gives us a never before seen look into the mind of the Scarlet zealots. This was a great find, <name>. Lord Fordragon will be pleased." }
WordHunterWoW_QuestEN[12478] = { title = "Frostmourne Cavern", description = "They have labeled the cave as Frostmourne Cavern. Why the Scarlet Onslaught is interested in such things is unknown, but by the look of things, the area surrounding the cave is heavily guarded. Nonetheless, we must proceed!\n\nTake this scrying orb and travel north out of town and then northwest toward Scarlet Point. Make your way into the cave and battle your way to the bottom. Once there, use the orb. Return here with what you discover.", objectives = "Use Zelig's Scrying Orb at the bottom of Frostmourne Cavern. Unlock the secrets of the past!", progress = "Have you searched Frostmourne Cavern?", completion = "Muradin lives? Could it be? I must notify King Bronzebeard at once!\n\nI need to consult the orb. There must be more information - somewhere!" }
WordHunterWoW_QuestEN[12479] = { title = "Wrath of the Lich King: Onwards to Northrend!", description = "Welcome to the Wrath of the Lich King Friends and Family Alpha.  Use the portals next to me to begin your journey into Northrend.\n\nYou can choose to report to the Alliance recruiter in Valiance Keep in Borean Tundra or you can go to Valgarde in Howling Fjord.", objectives = "Speak to the Alliance Recruiter inside Valiance Keep in Borean Tundra or the one at Vengeance Landing in Howling Fjord.Welcome to the Wrath of the Lich King Friends and Family Alpha. Use the portals next to me to begin your journey into Northrend.\n\nYou can choose to report to the Alliance recruiter in Valiance Keep in Borean Tundra or you can go to Valgarde in Howling Fjord." }
WordHunterWoW_QuestEN[12480] = { title = "Wrath of the Lich King: Onwards to Northrend!", description = "Welcome to the Wrath of the Lich King Friends and Family Alpha.  Use the portals next to me to begin your journey into Northrend.\n\nYou can choose to report to the Horde recruiter in Warsong Hold in Borean Tundra or you can go to Vengeance Landing in Howling Fjord.", objectives = "Speak to the Horde Recruiter inside Warsong Hold in Borean Tundra or Vengeance Landing in Howling Fjord.Welcome to the Wrath of the Lich King Friends and Family Alpha. Use the portals next to me to begin your journey into Northrend.\n\nYou can choose to report to the Horde recruiter in Warsong Hold in Borean Tundra or you can go to Vengeance Landing in Howling Fjord.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[12481] = { title = "Adding Injury to Insult", description = "The vrykul are being clever about this.  Fortunately I've a trick up my sleeve.\n\nThis leader of theirs, Bjorn, is a real hothead.  We've pieced together enough of their language to fashion what we think is a good insult.  Something involving his mother and large barnyard animals... we're not quite sure.\n\nTake this piece of paper and read it to him.  Once he starts chasing you, lure him back here.  We'll make sure he doesn't make it out alive.", objectives = "Read the Vrykul Insult to Bjorn Halgurdsson in Baleheim, then lead him back to Lydell's Ambush and help slay him.", progress = "Assassination work isn't as glamorous as it's made out to be.", completion = "Nice work.  That poor sap never saw it coming." }
WordHunterWoW_QuestEN[12482] = { title = "Against Nifflevar", description = "We await reinforcements from Vengeance Landing to move against Nifflevar.  If we were to capture it earlier, though, it would provide us with a great advantage over the Alliance.\n\nHead into town and see if you can put a dent in their numbers.", objectives = "Ranger Captain Areiel wants you to go to Nifflevar and slay 5 Dragonflayer Warriors, 4 Dragonflayer Rune-Seers and 4 Dragonflayer Hunting Hounds.", completion = "Excellent work, <name>.  When our forces from Vengeance Landing arrive, we'll be able to take care of any vrykul that are left." }
WordHunterWoW_QuestEN[12483] = { title = "Shimmercap Stew", description = "Say, while yer here, how bout ya help ol' Prigmon with a little chore? I got a friend who can make a mean stew - one like ya never tasted before!\n\nThere be a few ingredients found in these parts that he be needin'. They be in ruins to the southwest and the camp just north o' here.\n\nWhatd'ya say, mon?", objectives = "Prigmon in Granite Springs wants you to collect 5 Shimmering Snowcaps and 5 Ice Serpent Eyes from Drak'Zin Ruins and 5 Sweetroot from Zeb'Halak.", progress = "You get those ingredients for 'ol Prigmon, <name>?", completion = "Oh, mon - shimmercap stew! I can almost taste it already...." }
WordHunterWoW_QuestEN[12484] = { title = "Scourgekabob", description = "Ugh.\n\nWrappin' up these unfortunate trolls be makin' my heart ache, but not so much as my back!\n\nHelp ol' Prigmon out and haul one of these carcasses over to Mack.\n\nIf we don't burn 'em they be walkin' again in no time.", objectives = "Prigmon at Granite Springs wants you to bring a Mummified Troll Carcass to Mack Fearsen and place it in the fire.", progress = "Whatcha got there, <race>?", completion = "Nothin' better than watchin' them shcourge burn... <hic>.\n\nWrote a little shong about it. Wanna hear it? Here goes...." }
WordHunterWoW_QuestEN[12485] = { title = "Howling Fjord: aa - A - LK FLAG", description = "", objectives = "" }
WordHunterWoW_QuestEN[12486] = { title = "To Bor'gorok Outpost, Quickly!", description = "Did you feel it?\n\n<Sauranok momentarily clutches his chest in confusion. His hand comes away trailing red-hot steam.>\n\nSomething terrible has happened to my old friend, Farseer Grimwalker. I just sensed it.\n\nHe had a pupil that he took with him when he went north. They were going to help the overlord establish an outpost on the edge of Sholazar Basin.\n\nHer name is Snarlfang. She is a spirit talker.\n\nPerhaps she will know what happened. Or, at least, she can help you to find out.", objectives = "Speak with Spirit Talker Snarlfang at Bor'gorok Outpost.", completion = "The mystic knows? You say he felt that something horrible happened to Farseer Grimwalker?\n\nIt is as I feared!" }
WordHunterWoW_QuestEN[12487] = { title = "To Conquest Hold, But Be Careful!", description = "I've received a request for help from our base in the Grizzly Hills. I'm sending you to see Conqueror Krenna.\n\n<The high executor waves a sheaf of parchment in the air as if he could care less what is written on it.>\n\nShe's attempting to secure all of the natural resources or somesuch. Just watch your back around her. The word is that she's aggressive even for an orc.\n\nFollow the road east and then southeast. Cross the bridge at the Dragonspine Tributary and go east from the Evergreen Trading Post.", objectives = "Present yourself to Conqueror Krenna at Conquest Hold in the Grizzly Hills.", completion = "Who are you?\n\nTell me why I shouldn't split you in two where you stand!" }
WordHunterWoW_QuestEN[12488] = { title = "The High Executor Needs You", description = "It's a good thing that I intercepted this request from High Executor Wroth before it got to Overlord Agmar. What is Wroth thinking?\n\n<The sergeant rips up the letter that he's holding.>\n\n{class}, go see what it is that the high executor wants.\n\nFollow the road east and pass through The Dragon Wastes. You'll find a path leading up out of the wastes on the southeast side, and the Forsaken town, Venomspite, will stand before you on the south side of the mountain.", objectives = "Speak with High Executor Wroth at Venomspite in Dragonblight.", completion = "You were sent from Agmar's Hammer? It's about time!\n\nNo, the help is not for me. I simply have no one else to spare, but you'll do." }
WordHunterWoW_QuestEN[12489] = { title = "Welcome to Sholazar Basin", description = "So, where did you come from? I don't suppose that fool of an archmage sent you, too?\n\nYou're lucky to be in one piece, laddie! They nearly blew you up!\n\nThe jungle here's a darned dangerous place, 'specially with the Venture Company about.\n\n Git you! Go see the boss... he'll sort you out. The camp's at the end of that path to the northwest.\n\nNow, git!", objectives = "Follow the path to the northwest to reach the camp that Monte mentioned.", completion = "Hah! It's not often you run into a complete stranger in the middle of the jungle.\n\nYou one those druid lackeys sent to \"stop me and my evil ways?\" Yeah, good luck with that one!\n\n<Hemet lets out a hearty laugh and pats his gun.>\n\nDidn't think so! You're more than welcome to join us in the hunt, soon as we've dealt with those Venture Company dogs. There'll be plenty to go around." }
WordHunterWoW_QuestEN[12490] = { title = "Veehja's Revenge", description = "We share a common enemy today, {race}!  My people have been wiped out by these Kvaldir... my city has been all but destroyed.  It is time for exacting revenge!\n\nIn return for my help, I'd like you to slay the barbaric monsters that defile Riplash.  You will be well rewarded, {class}.", objectives = "Veehja at the Shrine of Scales wants you to slay 6 Skadir Mariners, 3 Skadir Mistweavers and 2 Skadir Runecasters." }
WordHunterWoW_QuestEN[12491] = { title = "Direbrew's Dire Brew", description = "Coren Direbrew's corpse clutched this small cask tightly to its gut.  This must be his infamous Dire Brew!", objectives = "Give Direbrew's Dire Brew to Ipfelkofer Ironkeg at the Brewfest camp near Ironforge.", progress = "<name>, your face has a grim set to it.  Do you have dire news?", completion = "This is the Coren Direbrew's drink?  The brew he wanted more than anything to submit at Brewfest?  Well, officially we can't recognize this submission, but out of respect for a fallen brewer, perhaps I'll have a taste..." }
WordHunterWoW_QuestEN[12492] = { title = "Direbrew's Dire Brew", description = "Coren Direbrew's corpse clutched this small cask tightly to its gut.  This must be his infamous Dire Brew!", objectives = "Give Direbrew's Dire Brew to Tapper Swindlekeg at the Brewfest camp near Orgrimmar.", progress = "Hey <name>, your face is all smudged!  Have you been to Blackrock Depths?", completion = "Ah, so Direbrew finally submitted his brew.  What a pity he had to die to do it...\n\nOh, well.  Bottoms up, eh?" }
WordHunterWoW_QuestEN[12493] = { title = "PvP Test", description = "Kill me some guys from the other side!  Those guys suck!  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.  I need to test something, so let's just repeat this over and over again.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 10 opponents." }
WordHunterWoW_QuestEN[12494] = { title = "FLAG: Riding Trainer Advertisement (20)", description = "", objectives = "" }
WordHunterWoW_QuestEN[12495] = { title = "Audience With The Dragon Queen", description = "Our assault against Angrathar has staggered the Scourge, but they remain unrelenting. From overhead they send their frost wyrms to strafe the field of battle, making an advance upon the gate itself impossible. The frost wyrm attacks must be stopped, but before we defile the bones of ancient dragons, we must gain permission from their queen.\n\nTravel southeast to Wyrmrest Temple and seek out Queen Alexstrasza. Tell her what we must do and ask her for guidance.\n\nGo now, {name}!", objectives = "Seek out Alexstrasza the Life-Binder at Wyrmrest Temple in Dragonblight.", completion = "You have come seeking my council, mortal. This I know, but do you know what it is that you face?\n\n<Alexstrasza points northward.>\n\nNorth of here are the dying grounds of Galakrond - progenitor of dragonkind. It is from Galakrond that the Titans created the Aspects. Imagine, then, the power of Galakrond. His size alone was greater than all of the Aspects combined! Now attempt to understand what the Scourge do in the Great Dragonblight.\n\nFrost wyrms, mortal, should be the least of your concerns." }
WordHunterWoW_QuestEN[12496] = { title = "Audience With The Dragon Queen", description = "Though I know you hunger to destroy the Scourge that stand before us at the Wrath Gate, we must first deal with the threat that looms overhead. Until the strafing assaults of the frost wyrms are halted, we cannot move forward.\n\nBut before we assault the dying grounds of dragons, we must first be granted permission. Venture now to the hallowed halls of dragonkind: Wyrmrest Temple. Once there, seek out Queen Alexstrasza.\n\nRide now, {name}! Southeast, to Wyrmrest!", objectives = "Seek out Alexstrasza the Life-Binder at Wyrmrest Temple in Dragonblight.", completion = "You have come seeking my council, mortal. This I know, but do you know what it is that you face?\n\n<Alexstrasza points northward.>\n\nNorth of here are the dying grounds of Galakrond - progenitor of dragonkind. It is from Galakrond that the Titans created the Aspects. Imagine, then, the power of Galakrond. His size alone was greater than all of the Aspects combined! Now attempt to understand what the Scourge do in the Great Dragonblight.\n\nFrost wyrms, mortal, should be the least of your concerns." }
WordHunterWoW_QuestEN[12497] = { title = "Galakrond and the Scourge", description = "Atop the Wicked Coil, the Grand Necrolord of the Scourge, Antiok, sits upon the shoulders of the reconstructed storm giant lord, Thiassi. From there he commands the armies of undead to work day and night to unearth Galakrond's massive bones. Should they succeed in raising Galakrond, all of your efforts will have been for naught.\n\nWhile I cannot call down the full fury of the Red Dragonflight to assist you in your journey, I will grant you my blessing. Go now and speak with my majordomo, Torastrasza. ", objectives = "Speak with Torastrasza at Wyrmrest Temple in Dragonblight.", completion = "The bravery of mortals never fails to astound me. Death affixes its cold stare upon you and in return you rise to challenge its assertion! It is why your kind is so loved... and so hated.\n\nEven though the Red Dragonflight is entrenched in a war with Malygos, there is something that we can do to help." }
WordHunterWoW_QuestEN[12498] = { title = "On Ruby Wings", description = "Use this beacon to signal a Wyrmrest vanquisher. Climb upon its back and fly north to Galakrond's Rest. Once there, command the dragon to destroy the Scourge scavengers that work to unearth Galakrond. Once the area has been cleansed, fly to the Wicked Coil, overlooking Galakrond's Rest, to destroy Grand Necrolord Antiok and recover the scythe that he uses to control the wyrms.\n\nDo this and return to Queen Alexstrasza for a hero's reward!\n\n{name}, beware the rotting storm giants that wander the area!", objectives = "Destroy 30 Wastes Scavengers and recover the Scythe of Antiok. Return to Alexstrasza the Life-Binder at Wyrmrest Temple should you complete this task.", progress = "Destroy the Scourge at Galakrond's Rest before it is too late!", completion = "I knew that you would return, <name>. You have served the Wyrmrest Accord and saved your people from certain death. Let it be known to all and let it be recorded for posterity!" }
WordHunterWoW_QuestEN[12499] = { title = "Return To Angrathar", description = "With Antiok slain and the scythe in our possession, the frost wyrm assaults upon your forces at Angrathar will halt. The wyrms that remain in the Dragonblight will be hunted and destroyed, their bones returning to the earth.\n\nThe time to make your final stand is now, {name}. Return to Fordragon Hold and notify Highlord Fordragon.\n", objectives = "Speak with Highlord Bolvar Fordragon at Fordragon Hold and tell him of your victory over the Scourge.", completion = "Know this: all that you have done has led to this moment. Without your efforts, we would have been finished! Now, stand guard as I take to the field and end this!" }
WordHunterWoW_QuestEN[12500] = { title = "Return To Angrathar", description = "With Antiok slain and the scythe in our possession, the frost wyrm assaults upon your forces at Angrathar will halt. The wyrms that remain in the Dragonblight will be hunted and destroyed, their bones returning to the earth.\n\nThe time to make your final stand is now, {name}. Return to the Kor'kron Vanguard and notify Saurfang the Younger.", objectives = "Speak with Saurfang the Younger at the Kor'kron Vanguard and tell him of your victory over the Scourge.", completion = "My father was right about you, <name>. Everything that he said has come to pass - only one final duty remains unfulfilled. I will now lead the Kor'kron to the front line. The time to end this war is at hand. The Lich King's tyranny ends today!\n\nTake my post now, <name>, and stand guard over our forces." }
WordHunterWoW_QuestEN[12501] = { title = "Troll Patrol", description = "Unsheathe that weapon, {race}. It's time to go on patrol!\n\nI've got four posts under my command and it's crucial to our success that they remain in our control. I'm ordering you to visit each of them and offer your assistance.\n\nYou can begin with Captain Brandon southeast of here. He'll direct you to the next post when he's finished with you.\n\nReport back to me once you've assisted each of my men. And remember, you'll be more richly rewarded for returning to me quickly - so double-time it!\n\nDismissed!", objectives = "Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain's orders, and then return and report to him.\n\nCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Captain Grondel is posted in Drak'Agal, and Alchemist Finklestein is posted in Heb'Valok.", completion = "Well, <name>, at least you've made it back in one piece. I suppose that's worth something...." }
WordHunterWoW_QuestEN[12502] = { title = "Troll Patrol: High Standards", description = "Listen, {class}. This is the Argent Crusade. Our men will fight to the end and never complain no matter what the conditions.\n\nThat said, we've taken some heavy casualties in this campaign and we've been hitting it hard with little or no sleep for months. That all takes a toll on morale, whether we admit it or not.\n\nIt may not seem like much, but seeing our standard raised over the battlefield is of considerable comfort to a soldier. Take these banners and raise them at the pedestals in Drak'Sotra.", objectives = "Captain Brandon wants you to place the Argent Crusade Banner in the Drakkari Pedestals at Drak'Sotra.", completion = "Good work, friend.\n\nAmazing what a little of one's colors do for a battleground.\n\nYou'll want to head on over to Captain Rupert next. He's stationed at the wall, just northeast of here." }
WordHunterWoW_QuestEN[12503] = { title = "Defend the Stand", description = "Despite our substantial successes in the lower third of Zul'Drak, we must still face the onslaught of the Scourge. Such is the way in this frigid hell.\n\nThe attacks are unrelenting, yet my men need rest. If you are willing, we could use your aid in reinforcing them.\n\nBelow in the courtyard you'll find no end to the fighting. Dispatch the Scourge there with all the zeal you can muster, {class}.", objectives = "Commander Falstaav has tasked you with the destruction of any 10 Scourge in the courtyard at The Argent Stand.", completion = "Your assistance in this matter is greatly appreciated. Were it not for your efforts, we would have difficulty in holding the unliving back from our steps." }
WordHunterWoW_QuestEN[12504] = { title = "Argent Crusade, We Are Leaving!", description = "<The sergeant quickly reads through the orders you've handed him, a frown coming over his face.>\n\nLook, lad, I'd love to just up and leave, but take a look out there. All of my people are fighting.\n\nTell you what, you've come this far, you think you're up to doing me a small favor? Head out there and round up my soldiers?\n\nTell 'em that the sergeant orders them to report back immediately. Lend them a hand if you will.", objectives = "Sergeant Stackhammer at the Altar of Sseratus wants you to speak with 10 of his Argent Soldiers and tell them to report back to him.", completion = "Alright then. We'll collect up the rest and head back to the stand.\n\nIt's a shame that we have to leave so soon. Doesn't quite feel like the job's done here, and quite frankly, I get the feeling that prophet in front of the altar is going to be big trouble!" }
WordHunterWoW_QuestEN[12505] = { title = "New Orders for Sergeant Stackhammer", description = "{class}, you're here to help, right? I've got new orders for our forces that are currently deployed at the Drakkari altar to the north.\n\nYou can't miss it. Just head straight up the avenue. Sergeant Stackhammer shouldn't be hard to find.", objectives = "Commander Kunz has asked you to deliver the New Deployment Orders to Sergeant Stackhammer at the Altar of Sseratus.", progress = "What's this all about?", completion = "<The dwarf sergeant warily eyes the orders in your hand.>\n\nAre those new orders for me, mister?" }
WordHunterWoW_QuestEN[12506] = { title = "Trouble at the Altar of Sseratus", description = "There's trouble at the altar of the snake god.\n\nThe presence of the Scourge has weakened the land, {race}. This in turn has weakened the wild gods.\n\nWe know that the Drakkari are taking advantage of this to do evil things to the gods.\n\nI need you to be my eyes and ears. The Altar of Sseratus is at the end of the avenue to the north. Sneak around the back and get a look inside of the main altar building.\n\nWhatever you do, avoid the prophet at all costs!", objectives = "Hexxer Ubungo at The Argent Stand has asked you to investigate the main altar building at the Altar of Sseratus.", completion = "Dead?\n\n<The hexxer's spirit is visibly lowered at the news you bring.>\n\nThey've killed Sseratus and drunk deeply of his mojo; the prophet especially!\n\nWe must figure out a way to put an end to him before he drinks too much more!" }
WordHunterWoW_QuestEN[12507] = { title = "Strange Mojo", description = "This bottle of strange mojo may be the key to what is truly going on here.\n\nThe Zandalari troll Hexxer Ubungo, back at The Argent Stand, may want to take a look at it.", objectives = "Deliver the Strange Mojo to Hexxer Ubungo at The Argent Stand.", progress = "What's that you have there?", completion = "That's the mojo of the wild gods, <class>!\n\nThis is not good!" }
WordHunterWoW_QuestEN[12508] = { title = "Mopping Up", description = "I couldn't help but overhear what you were talking to the sergeant about. That doesn't change the fact that we still have a job to do here.\n\nWhile you're out there, do you think you could help us to put some of those followers of Sseratus out of their misery?", objectives = "Corporal Maga at the Altar of Sseratus wants you to kill any combination of 10 Champions of Sseratus, Priests of Sseratus, or Drakkari Snake Handlers.", completion = "Thanks, <class>. I'd have hated to leave without accomplishing what we came out here for in the first place." }
WordHunterWoW_QuestEN[12509] = { title = "Troll Patrol: Intestinal Fortitude", description = "Finally, the patrol arrives!\n\nHere's the situation, {race}. We've lost many of our finest soldiers in this campaign and have had to call upon our recruits to fill in the gaps.\n\nWe've just fought one of our fiercest battles and many of the recruits were simply not prepared to face this enemy. There are more fights ahead, and I need them ready to follow orders.\n\nIf there's one thing I can't stomach, it's cowardice. Perhaps you can help them find the courage to continue. ", objectives = "Captain Rupert in Drak'Sotra wants you to restore courage to the cowering Crusade Recruits.", completion = "Well done, <class>. And not a moment too soon. I've received word that a counter-attack is imminent.\n\nYou should be on your way. The next post is to the northeast, near the coliseum. Captain Grondel should be waiting for you there." }
WordHunterWoW_QuestEN[12510] = { title = "Precious Elemental Fluids", description = "<The hexxer examines the decanter of mojo.>\n\nI have an idea for how to deal with the prophet of Sseratus. But first, we're going to need some things.\n\nThe Drak'Sotra Fields are directly to the south. Because of the stresses on the land from the Scourge and the deaths of gods, the wall between worlds has weakened and the elementals are flooding in.\n\nWe need the precious fluids of their lords. If you combine three links from the elementals a tether will be made, and one of their lords can be summoned.", objectives = "Hexxer Ubungo at The Argent Stand wants you to acquire 3 Precious Elemental Fluids.", progress = "Do you have the precious fluids?", completion = "Excellent. When combined with the mojo, these fluids will dilute the effectiveness of the mojo without completely eliminating it.\n\nNow, one more thing." }
WordHunterWoW_QuestEN[12511] = { title = "The Hills Have Us", description = "While we focus to hold our ground at Wintergarde and deal with the unfolding events of the Wrathgate, battalions from as far away as Westfall battle their way through the dense foliage and inhospitable denizens of Grizzly Hills. All in hopes of finding an alternate route into Icecrown.\n\nLieutenant Dumont, stationed at Amberpine Lodge, has enlisted the aid of able bodied citizens willing to risk life and limb in the uncharted wilds. Will you rise to meet this challenge?", objectives = "Report to Lieutenant Dumont at Amberpine Lodge in western Grizzly Hills.", completion = "You were almost shot down, eh? Savage monsters - those Horde.\n\nPayback will come for what they've done. You can count on at least that much, <class>.\n\nNow, it's time to put you to work." }
WordHunterWoW_QuestEN[12512] = { title = "Leave No One Behind", description = "Ahh, good. They sent someone.\n\nListen, {race}. We need a hand here. Our forces were pushed back and we've lost Drak'Sotra to the Scourge. Where they came from is anyone's guess....\n\nThe point is, we need every man we can get here, and some of our best have yet to return from battle.\n\nI need you to enter the ruins now that the fighting has died down and find our wounded, patch them up, and bring them here to me.\n\nScour Drak'Sotra! They couldn't have gone far.", objectives = "Dr. Rogers at Drak'Sotra wants you to find Crusader Lamoof, Crusader Jonathan, and Crusader Josephine. Use the Crusader's Bandage on them, and escort them safely back to him.", progress = "Have you rescued our veterans, <name>?", completion = "Saved them all, did you? Outstanding!\n\nMaybe you'd consider sticking around the post here? We could sure use someone like you...." }
WordHunterWoW_QuestEN[12513] = { title = "Nice Hat...", description = "My hat? Yes, it's an unusual style, I know, from far away... few tailors here know how to make them.\n\nWhen I was young and hot-blooded, I wore it as a standing challenge. Many came seeking to defeat me and win it for themselves... but no one ever did.\n\nAh, but those days are long past. I'm an old man, now: I drink, I fish, but I no longer duel.", objectives = "Don Carlos has inadvertently challenged you to defeat his younger self in Old Hillsbrad. Afterwards, bring Don Carlos' Hat to him in Tanaris as proof.", progress = "I was unbeatable, in those days... proud, and rightly so. No challenger ever won this fine hat...", completion = "My... my hat! So... it WAS you. I'd thought so. The old scars ached when you drew near, but... so young! You've not changed at all!\n\nWell... so now you know my secret. I WAS beaten... once. Here: take this hat, in return for mine. You've more than earned it." }
WordHunterWoW_QuestEN[12514] = { title = "Mushroom Mixer", description = "Now what we need is something to spike the mojo with. Something that'll make it so that when the prophet drinks it, he'll become less powerful.\n\nDrak'Agal lies to the east. There's a mushroom there that the natives call muddlecap fungus. I think it's exactly what we need.\n\nBring back lots of them. When we mix them into the mojo, the mind of anyone who drinks it will become muddled.", objectives = "Collect 10 Muddlecap Fungus and deliver them to Hexxer Ubungo at The Argent Stand.", progress = "Do you have all of the fungus?\n\nOh, and watch out for the basilisks lurking over there.", completion = "<The hexxer nods his approval.>\n\nHand that fungus over and I'll mix it up with the mojo and elemental lord fluids." }
WordHunterWoW_QuestEN[12515] = { title = "Nice Hat...", description = "My hat? Yes, it's an unusual style, I know, from far away... few tailors here know how to make them.\n\nWhen I was young and hot-blooded, I wore it as a standing challenge. Many came seeking to defeat me and win it for themselves... but no one ever did.\n\nAh, but those days are long past. I'm an old man, now: I drink, I fish, but I no longer duel.", objectives = "Don Carlos has inadvertently challenged you to defeat his younger self in Old Hillsbrad. Afterwards, bring Don Carlos' Hat to him in Tanaris as proof.", progress = "I was unbeatable, in those days... proud, and rightly so. No challenger ever won this fine hat...", completion = "My... my hat! But... how did you...?\n\nWell... no matter. So, now you know my secret. I WAS beaten... once. Here: take this hat, in return for mine. You've earned it." }
WordHunterWoW_QuestEN[12516] = { title = "Too Much of a Good Thing", description = "There. I've modified the mojo. Now when the prophet drinks it, not only will he lose some of his power, his mind will also be addled by the effects of the fungus.\n\nAt least that's the theory.\n\nAs for how to get him to drink it, might I suggest you simply throw it at him? No doubt he'll catch and drink it given the arrogance that he's displayed at the altar.\n\nUnless you can kill him, {class}, your Argent Crusade is about to come to a terrible end.", objectives = "Slay the Muddled Prophet of Sseratus and then return to Hexxer Ubungo at The Argent Stand.", completion = "Amazing! You've saved your people and the rest of Northrend from his madness.\n\nUnfortunately there's more of this insanity occurring up in the higher tiers of Zul'Drak." }
WordHunterWoW_QuestEN[12517] = { title = "Rogues Deck", description = "Now that you have gathered all of the Rogue cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.\n\nYou feel the card could be used to communicate with someone or something.", objectives = "Use the Rogues Deck to summon a Darkmoon Fortune Teller and give the deck to them.", progress = "I see that you have managed to collect a deck of Rogues!   I'm impressed.", completion = "The tarot cards are of great interest to the Darkmoon Faire, so do not hesitate to call upon us if you manage to collect more.  We are not without our own skilled tradesmen, so please allow us to offer something in return." }
WordHunterWoW_QuestEN[12518] = { title = "Mages Deck", description = "Now that you have gathered all of the Mage cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.\n\nYou feel the card could be used to communicate with someone or something.", objectives = "Use the Mages Deck to summon a Darkmoon Fortune Teller and give the deck to them.", progress = "I see that you have managed to complete a deck of Mages!   Congratulations!", completion = "The tarot cards are of great interest to the Darkmoon Faire, so do not hesitate to call upon us if you manage to collect more.  We are not without our own skilled tradesmen, so please allow us to offer something in return." }
WordHunterWoW_QuestEN[12519] = { title = "Troll Patrol: Whatdya Want, a Medal?", description = "Look at me, {race}. Do I look like I have time fer fillin' out reports?\n\nIt be all I can do to keep this post free o' the bloody Scourge, and they want me to mess with paperwork!\n\n<sigh> No sense in complainin'. I need to get the commander some kinda kill count from the last skirmish.\n\nYou wanna be helpful? Go and get me all the medals you can find from the dead trolls around here. That'll hafta be close enough.", objectives = "Captain Grondel outside the Coliseum wants you to gather 7 Drakkari Medallions from the nearby Drakkari Corpses.", progress = "You get those medals for me, <race>?", completion = "Well, now!\n\nYa saved me a fair bit o' work there lad. I'm grateful. I'll be sure ta make mention of ya in me report.\n\nOff with yeh now. Finklestein'll likely be waitin fer ya a bit west o' here." }
WordHunterWoW_QuestEN[12520] = { title = "Rhino Mastery: The Test", description = "No rough landing is going to stop ol' Hemet from mastering the largest game Sholazar has to offer. In the wilds northwest of the camp, the jungles are ruled by the mighty shardhorn rhino. You can prove your worth to the expedition, lad, by showing me that you're tough enough to face down those powerful beasts.", objectives = "Kill 15 Shardhorn Rhinos and return to Hemet Nesingwary at the Nesingwary Base Camp.", completion = "Well, well, well, it looks like you've survived the rhinos, after all, and in pretty good shape if I do say so myself. But there's more to rhino hunting than just staring down the beast as it charges you and hoping your aim is true. No, you'll need more than that to take on the rhino patriarch that's rumored to dwell in the jungle." }
WordHunterWoW_QuestEN[12521] = { title = "Where in the World is Hemet Nesingwary?", description = "When I heard that the legendary Hemet Nesingwary was setting sail for the Sholazar Basin, I offered to help fund his expedition. We know little of Sholazar,  but it's said to be a lush paradise in the midst of this frozen continent.\n\nHemet has agreed to send back samples of exotic plants, reagents, and crystals. There hasn't been any word from him. Monte Muzzleshot was supposed to be bringing them supplies, but he hasn't returned, either. If you'll look into it, I'll send you in my flying machine.", objectives = "Talk to Archmage Pentarus when you're ready to leave for Sholazar Basin. When you arrive, speak with Monte Muzzleshot in the Wildgrowth Mangal of Sholazar Basin.", completion = "Aye, Hemet's here. He's at the camp, just go northwest toward the river and you'll soon see it. And for the love of the Light, lad, have him send someone to cut me down!" }
WordHunterWoW_QuestEN[12522] = { title = "Need an Engine, Take an Engine", description = "She's ruined... ruined! I told that captain to be careful with such a precious cargo, but would she listen to me? No!\n\nWhen the ship ran aground, it damaged my flying machine, the Spirit of Gnomeregan. Now, we're left without any means to send our reports!\n\nThere is a chance, though, that the Venture Company's antics may work in our favor. They shot down another flying machine right about where Monte parachuted into the swamp to the east. Go there and retrieve the engine. It may be our only hope.", objectives = "Weslex Quickwrench at the Nesingwary Base Camp wants you to bring him a Flying Machine Engine.", progress = "Well, were you able to get the engine? I just know that archmage who funded the expedition is getting nervous.", completion = "There... just set it down there. Be careful! If you ruin this one, we're in big trouble. Now, let's see what I can do." }
WordHunterWoW_QuestEN[12523] = { title = "Have a Part, Give a Part", description = "Great, now that we've got an engine, we're going to need an assortment of other parts to get her back in flying condition. Don't worry, I know what I'm doing.\n\nA good mechanic can hold his creations together with anything, but we're better off if it doesn't come to that.\n\nAnyway, those Venture Company dullards have plenty of spare parts for their mining equipment all over Swindlegrin's Dig on the far side of that yellow crystal pillar to the northeast. Scoop up a few and bring them back here.", objectives = "Bring 7 Venture Co. Spare Parts to Weslex Quickwrench at the Nesingwary Base Camp.", progress = "Did you get those parts?", completion = "With a little work, these should suffice. My poor flying machine might end up looking more like a Venture Company shredder, though. Poor girl will have to wait until we get back to Dalaran to be restored to her rightful form." }
WordHunterWoW_QuestEN[12524] = { title = "Venture Co. Misadventure", description = "Ever since we arrived, the Venture Company has hampered our efforts to secure our campsite and survey the area. Normally, we wouldn't care what they were up to, but they've started antagonizing our scouts and shooting down supply flights.\n\nWe can't allow this insult to stand. Hemet Nesingwary's expedition came here to hunt, and hunt it shall.\n\nGo to Swindlegrin's Dig, on the far side of the crystal pillar to the northeast, and kill any Venture Company employee you see!", objectives = "Debaar at the Nesingwary Base Camp wants you to kill 15 Venture Company members. You may kill either Venture Co. Ruffians or Venture Co. Excavators.", completion = "That should hamper their operations, but I worry that the foreman will try to bring in more workers. We have to complete the job while we can." }
WordHunterWoW_QuestEN[12525] = { title = "Wipe That Grin Off His Face", description = "We must send Foreman Swindlegrin packing if we're going to shut down his mine permanently, but be careful. His bodyguard, Meatpie, is a large, mean ogre, and  isn't likely to let you see the foreman without a fight.\n\nThe two probably occupy a platform that would let them look out over the entire Venture Company operation at Swindlegrin's Dig.\n\nRemember, the dig is on the far side of the Suntouched Pillar to the northeast. Good luck, {name}.", objectives = "Kill Foreman Swindlegrin and Meatpie and return to Debaar at the Nesingwary Base Camp.", completion = "What a relief to hear that the Venture Company will trouble us no more. You have my thanks, and that of Hemet for dealing with this problem. A game hunter cannot, in good conscience, lift her weapon against another person." }
WordHunterWoW_QuestEN[12526] = { title = "Rhino Mastery: The Chase", description = "Well, that's settled then. We'll seek out this native sage and have a word with him. He's not likely to volunteer his services, though.\n\nI'm told he keeps a small lean-to near the Bones of Nozronn, just across the river to the south. Seek him out, introduce yourself, and ask what he requires to help us track down this patriarch of the rhinos.", objectives = "Speak to Oracle Soo-rahm at the Bones of Nozronn.", completion = "What brings you to Rahm's shrine?" }
WordHunterWoW_QuestEN[12527] = { title = "Gluttonous Lurkers", description = "My master, Finklestein, is in the shrine at Heb'Valok to the northwest preparing a truth serum, and he needs basilisk crystals. Heb'Valok is on the west side of the road leading north before the Altar of Sseratus.\n\nThere are basilisks to the east at Drak'Agal.\n\nIf you grab the Zul'Drak rats and throw them at the basilisk, they will become gorged and docile after eating five. Then you'll be able to take their crystals.\n\nKilling the basilisk won't do you any good. That'd just break its crystals!", objectives = "Deliver 5 Basilisk Crystals to Alchemist Finklestein in the shrine at Heb'Valok.", progress = "What's all this?\n\nBy any chance have you seen my no-good apprentice, Pestlepot?\n\nI sent him on an errand quite some time ago and he has yet to return!", completion = "Oh, most excellent! Thank you. The crystals appear to be in fine condition!\n\nI have no doubt that Pestlepot put you up to doing his chores for him. Nevertheless, your assistance in this matter is greatly appreciated!" }
WordHunterWoW_QuestEN[12528] = { title = "Playing Along", description = "My kill! You take my kill!\n\n<Gekgek taunts you with his spear.>\n\nYou dumb, {race}. Now you owe Gekgek! You be Frenzyheart slave. You slay many more beasts for Frenzyheart.\n\nYou go Frenzyheart Hill to northeast - you tell High-Shaman Rakjak you the new slave.\n\nGo, {race}! Go or I taunt you a second time!\n\n<Gekgek waves his spear around menacingly.>", objectives = "Report to High-Shaman Rakjak at Frenzyheart Hill as the new \"slave.\"", completion = "You the new slave?\n\nGood. We running out." }
WordHunterWoW_QuestEN[12529] = { title = "The Ape Hunter's Slave", description = "You think you so great hunter, eh? You no Frenzyheart, you not know of hunt.\n\nGoregek is great ape hunter. He slay so many ape you can't count on claws.\n\nYou go with Goregek and hunt hardknuckles to east. You the slave, {race}. You do what Goregek tell you.", objectives = "Kill 8 Hardknuckle Foragers and 6 Hardknuckle Chargers for High-Shaman Rakjak at Frenzyheart Hill.\n\nIf you lose Goregek's Shackles, speak to Elder Harkek in Frenzyheart Hill.", completion = "Goregek show silly <race> slave how it done." }
WordHunterWoW_QuestEN[12530] = { title = "Tormenting the Softknuckles", description = "Slave thing!\n\nRakjak want me to babysit you while I kill hardknuckles. I feeling generous today, so I let you kill some too, but don't get in Goregek's way!\n\nRakjak not know yet, but Goregek has eye on big bad hardknuckle mama. We go to Hardknuckle Clearing to east and poke softknuckles with poker and she sure to come yelling!\n\n<Goregek rubs his hands together gleefully.>", objectives = "Goregek has given you a Softknuckle Poker for use on Softknuckles to draw the Hardknuckle Matriarch out of hiding. Slay the Hardknuckle Matriarch and report her death to High-Shaman Rajak at Frenzyheart Hill.\n\nIf you lose Goregek's Shackles, speak to Elder Harkek in Frenzyheart Hill.", completion = "Goregek take you to kill big mom of hardknuckles, eh? You lucky!\n\nDumb softknuckles squeal good!\n\n<Rakjak squeals loudly and breaks out laughing.>" }
WordHunterWoW_QuestEN[12531] = { title = "The Underground Menace", description = "Lion killer, chicken chaser, new Frenzyheart slave...\n\nI know you no want to stay slave, so I tell you what to do. Show you better than the other Frenzyheart hunters and then Rakjak respect you.\n\nUnder sands of south river there a beast that kills wasp, apes, and even wolvar. He called Serfex. You bring claw of Serfex to Rakjak and maybe he release you from slaveness.\n\nHope Dajik teaching you good so Serfex be easy stuff.", objectives = "Locate Serfex under the sands of the southern river, slay him, and bring his claw to High-Shaman Rakjak at Frenzyheart Hill.\n\nIf you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.", progress = "I not ask for you, <race>. What you want?", completion = "You kill Serfex? I bet you follow mighty wolvar that kill Serfex and take claw.\n\nMy claw now." }
WordHunterWoW_QuestEN[12532] = { title = "Flown the Coop!", description = "Dumb Goregek stumble into chicken house and let all the chickens go!\n\nThey all around hill - go get chickens back!\n\n<Elder Harkek shoos you away.>", objectives = "Capture 12 Chicken Escapees for Elder Harkek.\n\nIf you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.", progress = "You catch chickens?", completion = "Good! I was worried about foodstuffs. I already pretty hungry.\n\nThank you, <race>." }
WordHunterWoW_QuestEN[12533] = { title = "The Wasp Hunter's Apprentice", description = "Rakjak not dumb. Maybe you good at killing things. Maybe Frenzyheart can make you into real hunter.\n\nDajik hunts giant wasp things better than all wolvar. Go with Dajik to Sapphire Hive to southeast or to river in south and learn the hunt.", objectives = "Kill 6 Sapphire Hive Wasps and 9 Sapphire Hive Drones for High-Shaman Rakjak in Frenzyheart Hill.\n\nIf you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.", completion = "We kill many many wasps.\n\nRakjak don't think they run out." }
WordHunterWoW_QuestEN[12534] = { title = "The Sapphire Queen", description = "Bristlepine can be dangerous, but most stay far away from wolvar. Wasps on other hand not fear the Frenzyheart... they even kill some of our hunters.\n\nI know Rakjak want wasp queen dead, but no wolvar want to go into her hive. You go kill wasp queen in Sapphire Hive to southeast and get stinger for Rakjak. Me bet Rakjak like that. ", objectives = "Bring the Stinger of the Sapphire Queen to High-Shaman Rakjak at Frenzyheart Hill.\n\nIf you lose Dajik's Worn Chalk, speak to Elder Harkek in Frenzyheart Hill.", progress = "You smell like wasp things.", completion = "You killed queen wasp! You stronger than Rakjak thought.\n\nMaybe wasps go away now and stop attacking Frenzyheart hunters." }
WordHunterWoW_QuestEN[12535] = { title = "Mischief in the Making", description = "You good hunter, but Frenzyheart can make you stronger. Harkek think maybe you ready for something more important.\n\nBefore Rakjak send you on important mission, you need gather things for Rakjak. All along river to south are blue crystals. Rakjak need lots of blue crystals.\n\nYou go get crystals now.", objectives = "High-Shaman Rakjak at Frenzyheart Hill wants 8 Skyreach Crystal Clusters.", progress = "Almost ready for long journey. Gekgek come back with crocolisk just moment ago.", completion = "Good <race>! Okay, all ready." }
WordHunterWoW_QuestEN[12536] = { title = "A Rough Ride", description = "Zepik is best hunter of the Frenzyheart. Zepik hunts big-tongues... ugly things near swamps that try to steal all stuff they can find.\n\nZepik going on long trek to break big-tongue shrine and try to scare them away. We no want big-tongues in this land anymore.\n\nThere a crocolisk chained on northeast side of hill, next to tree - go with Zepik and do what Zepik tell you.", objectives = "Ride the captive crocolisk to Mistwhisper Refuge and then speak to Zepik for further instructions.\n\nIf you lose Zepik's Hunting Horn, speak to Elder Harkek in Frenzyheart Hill.", progress = "They tell Zepik you good hunter for not being Frenzyheart.", completion = "We here! Must work fast.\n\nWatch out for big-tongues." }
WordHunterWoW_QuestEN[12537] = { title = "Lightning Definitely Strikes Twice", description = "Okay, the crystal things...\n\nThe big-tongues use the crystals to power their rain shrines. Zepik not know quite how it works, but Zepik does know that if they use wrong crystals, the clouds and the rain go crazy!\n\nZepik tried to sneak in at one of their other rain shrines, but it not go so well. It sure to go much better with two!\n\nTake crystals, place at big stone pillar shrine thing, then smash them to release power. Zepik not sure what will happen, so might want to step back after.", objectives = "Zepik wants you to smash the Skyreach Crystal Clusters in front of the Mistwhisper weather shrine.\n\nIf you lose Zepik's Hunting Horn, speak to Elder Harkek in Frenzyheart Hill.", progress = "Zepik think this go much better with partner. You strong for not Frenzyheart.", completion = "It work so good!\n\nYou see lightning smash that oracle guy? So good!\n\n<Zepik rubs his hands together and chuckles maniacally.>" }
WordHunterWoW_QuestEN[12538] = { title = "The Mist Isn't Listening", description = "Gorillas and wasps are boring! Big-tongues the only thing fun to hunt.\n\nWhile we mess up rain shrine, we kill lots of mist big-tongues. That sure to make them not want to come back to village thing.\n\n<Zepik nods to himself confidently.>", objectives = "Zepik wants you to kill 12 Mistwhisper Gorlocs.\n\nIf you lose Zepik's Hunting Horn, speak to Elder Harkek in Frenzyheart Hill.", completion = "I stab those big-tongues good.\n\nYou did okay I guess.\n\nNo, I just kidding! You good hunter. I glad to hunt with you." }
WordHunterWoW_QuestEN[12539] = { title = "Hoofing It", description = "Okay, we done! Time to go back. No crocolisk to ride this time though.\n\nIf we go east and stay near ridge, it should lead all the way back near hill.\n\nNeed to be careful not to go far below ridge though or we might go right into big-tongue tree village thing. Zepik not think they like us right now.", objectives = "Find your way back to Frenzyheart Hill and speak to High-Shaman Rakjak.", completion = "Blown up by lightning?\n\n<Rakjak breaks out laughing for a moment.>\n\nYou good hunter. Rakjak like you. Maybe one day you can be honorary Frenzyheart!\n\nOnly maybe though!" }
WordHunterWoW_QuestEN[12540] = { title = "Just Following Orders", description = "Okay guy, Rakjak have very important job. You go capture injured big-tongue that tracker spotted at river to north.\n\nNot bring hunter this time because they maybe want to just kill it. I want to hide it so that I can poke it and make it tell me things.\n\nGo you and bring me big-tongue prize thing.", objectives = "Locate an Injured Rainspeaker Oracle for High-Shaman Rakjak at Frenzyheart Hill.", completion = "No kill me please! We was just looking for fish. We not want to die." }
WordHunterWoW_QuestEN[12541] = { title = "Troll Patrol: The Alchemist's Apprentice", description = "Ahh, you must be the promised patrol. Your timing couldn't be better. I have urgent need of an extra pair of hands.\n\nWe have a Drakkari prisoner who's been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum.\n\nCreating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step.\n\nLet me know when you're ready, {race}. And remember, timing is everything!\n", objectives = "Alchemist Finklestein at Heb'Valok wants you to assist him in the creation of a truth serum.\n\nWhen you are ready to begin, you are to speak to him and follow his instructions.", progress = "You see, <name>, there is far more to true alchemy than mixing a few ingredients....", completion = "You've done it!\n\nThe intelligence gathered from that troll will undoubtedly be of great value. I'll be certain to make mention of your efforts in my report to the commander.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[12542] = { title = "The Call Of The Crusade", description = "{class}! The Argent Crusade is looking for able bodied soldiers that are willing to set aside their differences and join forces to battle the forces of the Lich King. Will you take up our cause?\n\nShould you be interested, venture north to Light's Trust and speak with Crusader Valus.\n\nYou will find Light's Trust amidst the ruins of the sacked troll city of Jintha'kalar - bordering Zul'Drak.\n\nFarewell. ", objectives = "Report to Crusader Valus at Light's Trust in Dragonblight.", completion = "Mere footsteps from here lies the Drakkari empire.\n\n<Valus points east.>\n\nFor thousands of years the Drakkari remained isolated, preferring to keep within the boundaries of their sprawling temple cities and ziggurats. It was surprising then, to come upon this wreckage. Further up, beyond the foreboding stairs leading into Zul'Drak, Drak'Tharon Keep lies in ruin. The entire first tier of Zul'Drak, destroyed...\n\nWhy has the Scourge waited until now to attack?" }
WordHunterWoW_QuestEN[12543] = { title = "An Offering for Soo-rahm", description = "We not know you, stranger, but we know you want something.\n\nWe will talk to Bones of Nozronn for you, but you must bring us offerings. We need powerful emperor cobra fangs to complete our oracle's necklace.\n\nGo to the Wildgrowth Mangal, northeast of our hut, find cobras and bring back best fangs. Then we make bones speak to you.", objectives = "Bring 5 Intact Cobra Fangs to Oracle Soo-rahm, near the Bones of Nozronn.", progress = "We must know -- do you bring fangs?", completion = "<The oracle inspects the fangs.>\n\nWe approve! Bones of Nozronn will speak to <name>!" }
WordHunterWoW_QuestEN[12544] = { title = "The Bones of Nozronn", description = "Bones of Nozronn, Oracle Soo-rahm sends {name} to you!\n\nWe have prepared incense for you. Light it and place it near Nozronn's head and you will hear his voice.\n\n<Confused, you tell Soo-rahm that you haven't even told him your question.>\n\nTrue, we not know, but mighty Nozronn does. Do not doubt. Nozronn will answer your heart's question.\n\nGo. Nozronn not wait long.", objectives = "Use Soo-rahm's Incense near the Bones of Nozronn, then return to Hemet Nesingwary at Nesingwary's Base Camp with the information you learned.", progress = "Well, have you consulted the native oracle?", completion = "<Hemet listens as you describe what you learned.>\n\nWay to go, lad. No dead rhino tells Hemet Nesingwary where and what he can hunt. We'll show that heap o' bones." }
WordHunterWoW_QuestEN[12545] = { title = "The Cleansing Of Jintha'kalar", description = "We wrested this ancient Drakkari temple from a swarm of invading Scourge. Not more than one-hundred paces from where we stand is the ruined city of Jintha'kalar. Scourge necromancers run amok, turning the living Drakkari trolls that remain into servants of the Lich King.\n\nAll are now lost to the Light. All must be purged.\n\n<Valus looks upon you sternly.>\n\nAll.", objectives = "Crusader Valus at Light's Trust in Dragonblight has asked you to slay 15 Jintha'kalar Scourge.", completion = "As you can see, the Scourge war machine presses onward, yet the armies of the Horde and the Alliance remain divided, making for easy prey. It is for this reason that we must remain united.\n\n<Valus is lost in contemplation for a moment.>\n\nThe Argent Crusade has use for a man like you. Perhaps you would be interested in joining our cause? To battle and die at the side of the Ashbringer?" }
WordHunterWoW_QuestEN[12546] = { title = "Reclamation", description = "It is time, {name}.  The Etymidian is one of the most destructive forces ever created by the titans and I am loathe to unleash him in my lands.\n\nThere is little choice, however.  Our enemies have forced my hand and the fury of the titans will cleanse all.", objectives = "Go to the Avalanche in Sholazar Basin and use the Omega Rune to deploy Etymidian. Use him to slay 200 Scourge Minions, Bythius the Flesh-Shaper, Urgreth of the Thousand Tombs and Hailscorn.\n\nSpeak to the Avatar of Freya in Sholazar Basin when you've completed this task.", completion = "I am grateful for your help, <name>.  It is my duty to watch over these lands and all life that dwells on them.\n\nThanks to you, that life will continue to thrive while the forces of death wage in the bordering regions.\n\nYour actions will not be forgotten." }
WordHunterWoW_QuestEN[12547] = { title = "The Activation Rune", description = "This colossal being appears to be inactive.  You notice an empty rune-shaped slot on its chest.\n\nPerhaps you might be able to find the missing rune inside the nearby overlook.", objectives = "Obtain the Omega Rune inside the Shaper's Terrace and bring it to The Etymidian.", progress = "<The rune-shaped slot on The Etymidian's chest appears to glow with faint power.>", completion = "<You hear the rumbling sound of stone grinding as The Etymidian's limbs come to life.>\n\nI am needed somewhere?" }
WordHunterWoW_QuestEN[12548] = { title = "The Etymidian", description = "It is time, {name}.  The Waygate has been activated for the first time in seven centuries.  Use it to travel to where our final hope lies.\n\nLet us put an end to those who would seek to bring the taint of undeath to this pristine land.  Let us unleash the Etymidian.", objectives = "Go through the Waygate in the southern end of Sholazar Basin and look for the weapon known as the Etymidian on the other side.", completion = "<As you read the engravings on this stone colossus, you realize that this is the weapon that Freya spoke of.  This is the Etymidian.>" }
WordHunterWoW_QuestEN[12549] = { title = "Dreadsaber Mastery: Becoming a Predator", description = "If you've hunted with Hemet before, you know that he's tested his skill against many large cats, but the dreadsabers here in Sholazar are different. They're able to bring down larger game than I've ever seen a cat hunt. To overcome and kill such a predator is the mark of a true hunter.\n\nIf you seek to prove you're up to the challenge, test yourself against the dreadsabers. They live in the wilderness surrounding the camp and south of the river.", objectives = "Kill 15 Dreadsabers and return to Buck Cantwell at the Nesingwary Base Camp.", completion = "Well, you've proven yourself a capable hunter, but how are you as a tracker?" }
WordHunterWoW_QuestEN[12550] = { title = "Dreadsaber Mastery: Stalking the Prey", description = "I have heard that the natives tell stories of a large dreadsaber they call Shango. I haven't seen any evidence of this Shango's existence, but my injuries have kept me from venturing outside the camp.\n\nIf you fancy yourself something of a tracker, you might be able to find out the truth about Shango. Debaar said she saw some large tracks on her last outing. Go north from the camp toward Bittertide Lake, and search its southern shore for the prints.", objectives = "Buck Cantwell at the Nesingwary Base Camp wants you to identify 3 Shango Tracks from the Dreadsaber Tracks near Bittertide Lake.", completion = "<Buck listens as you recount your findings.>\n\nI think you may have found the proof we need for this Shango. And I think I have an idea as to where we can find him." }
WordHunterWoW_QuestEN[12551] = { title = "Crocolisk Mastery: The Trial", description = "I warn you, stranger -- do not make any comments about crashing the ship. I already get enough of it from the rest of the expedition.\n\nIf you're looking to try your hand at hunting, though, you should test your skills against the wily mangal crocolisks. They live all along the river to the south, and in the Wildgrowth Mangal to the east. Prove you can hold your own against them and we'll talk again, hunter.", objectives = "Kill 15 Mangal Crocolisks and return to Debaar at the Nesingwary Encampment.", completion = "Impressive, <class>. Are you certain you're not a member of the expedition?\n\nNo, I'm certain of it. There would've been a crash joke in there somewhere." }
WordHunterWoW_QuestEN[12552] = { title = "Death to the Necromagi", description = "When the trolls brought down Kolramas, it crashed next to us to the southeast. Unfortunately the crash did not destroy all of the Scourge within.\n\nNow they're raising our men from the dead and using them against us!\n\nThis will not be allowed to continue. You will see to it that their necromagi are slaughtered! Do we understand each other?", objectives = "Sergeant Moonshard at Drak'Sotra has asked you to destroy 8 Hath'ar Necromagi.", completion = "It's not enough!\n\n<The sergeant's voice cracks as he mourns the corruption of his fallen comrades.>\n\nWe must do more to show respect for the memories of those men!" }
WordHunterWoW_QuestEN[12553] = { title = "Skimmer Spinnerets", description = "Why do I always get the tough tasks to tackle?\n\nThe Scourge at Kolramas have plague sprayers that are getting dangerously close. You don't want to know what's going to happen if they start heading this way!\n\nI've got an idea for how we might bring them down, but first we're going to need something... something from their own creatures.\n\nThe Hath'ar skimmers can spin a very strong web that we can put to good use. Bring back some of their spinnerets.", objectives = "Specialist Cogwheel at Drak'Sotra has asked you to collect 5 Intact Skimmer Spinnerets.", progress = "Those spinnerets have to be intact if I'm going to be able to put them together into a device that you can use.", completion = "Those'll do!\n\nNow we're going to need some raw parts so that I can put the launching device together for you." }
WordHunterWoW_QuestEN[12554] = { title = "Malas the Corrupter", description = "{name}, head back down there!\n\nYou'll find the leader of Kolramas, Malas the Corrupter, gloating from atop the crashed necropolis.\n\nKill him and bring me his head!", objectives = "Sergeant Moonshard at Drak'Sotra insists that you return with the Head of the Corrupter.", progress = "I look forward to mounting his head on a pike. Let's see him come back from that!", completion = "You're the hero of the hour, <name>.\n\n\n\nYou deserve our deepest respect, and something more I think." }
WordHunterWoW_QuestEN[12555] = { title = "A Tangled Skein", description = "There! One tangled skein thrower ready and waiting for you to take those plague sprayers down.\n\nYou just aim and let loose. The webbing should foul up their hover spells long enough to cause them to crash to the ground just like Kolramas.\n\nKind of poetic. I like that!", objectives = "Specialist Cogwheel at Drak'Sotra has asked you to use the Tangled Skein Thrower in order to cause the destruction of 5 Plague Sprayers.", completion = "Yay! You're the best, <name>!\n\nI wasn't looking forward to being sprayed with Scourge stuff, that's for sure! I guess it's going to be hard for those stupid nerubians to spread their evil now!\n\nHow about I give you a little something for saving my skin?" }
WordHunterWoW_QuestEN[12556] = { title = "Rhino Mastery: The Kill", description = "Now that we know where to find Farunn, all that remains is the battle against the great beast. Are you ready to take on this rhino, {name}? For all the spirit's blustering, I'm certain it was telling the truth about the beast's strength.\n\nWhen you're ready to face him, head north past the Suntouched Pillar and look for Farunn on the northeast shore of the Bittertide Lake. It may even venture near the Glimmering Pillar. Bring back its horn to commemorate your kill.", objectives = "Bring Farunn's Horn to Hemet Nesingwary at the Nesingwary Base Camp.", progress = "Did you kill the beast?", completion = "<Hemet examines the horn.>\n\nAn astounding trophy from an amazing animal! <name>, I've been hearing rumors of even bigger, more ferocious game in the northern reaches of the basin and I'd like you to help us track it down." }
WordHunterWoW_QuestEN[12557] = { title = "Lab Work", description = "I assume by your interruption that you wish to be numbered among those I am considering for apprenticeship.\n\nA worthy aspiration...\n\nShould I someday choose to accept your petition, I must be confident that you can find your way around my laboratory. I have many ingredients here; some plentiful, and others in short supply.\n\nTake your time, {class}. Find a muddy mire maggot, a withered batwing, an amberseed, and some chilled serpent mucus.\n\nSucceed, and I'll know to take your request seriously.", objectives = "Alchemist Finklestein at Heb'Valok wants you to find a Muddy Mire Maggot, a Withered Batwing, an Amberseed, and some Chilled Serpent Mucus from within his laboratory.", progress = "Have you become accustomed to my laboratory, <class>?", completion = "Yes, yes, that's a good start.\n\nShould I call upon you to help me with an actual recipe, you'll need to locate ingredients in a timely manner.\n\nKeep that in mind, <class>.\n\nFarewell." }
WordHunterWoW_QuestEN[12558] = { title = "Dreadsaber Mastery: Ready to Pounce", description = "Shango awaits, {name}. If you have succeeded in your tracking, he will not know that you stalk him, and you will need the advantage.\n\nHe is supposed to be bigger, stronger, and more ferocious than the other dreadsabers of the basin. Travel north, to the western shore of Bittertide Lake and near the falls that feed it, do battle with Shango. If you succeed, return with his pelt.", objectives = "Bring Shango's Pelt to Buck Cantwell at the Nesingwary Base Camp.", progress = "Have you taken on Shango?", completion = "What an exquisite pelt from such a noble animal! It heartens me to see that the rumors about Shango were indeed true, <name>. Your pursuit of the creature has been flawless. You are a true huntsman." }
WordHunterWoW_QuestEN[12559] = { title = "Powering the Waygate - The Makers' Perch", description = "It is time then.  Let us activate the waygate.\n\nYou will find the first switch inside the Makers' Perch in the western edge of the basin.\n\nBeware, {name}.  The titans used the perch to watch over their creations.  Many of their stone servants still guard the place.", objectives = "The Avatar of Freya at the Rainspeaker Rapids wants you to go to the Makers' Perch and use the Activation Switch Gamma.", progress = "You're back, little one.  I was beginning to worry about your well-being.", completion = "We're halfway there, <name>.  One more switch needs to be activated before we can retrieve the Etymidian." }
WordHunterWoW_QuestEN[12560] = { title = "Crocolisk Mastery: The Plan", description = "The mangal crocolisk is a master of the ambush, and I intend to beat the best at his game. To do that, we'll need to construct a convincing camouflage for you. We'll use plants that grow in the sandy soil of the riverbanks and lake beaches.\n\nThe sandfern is best for this purpose. It grows in the sandy areas near the shores of the Seabreach Flow, just to the south, Bittertide Lake and Bittertide Falls, to the north, and the edges of River's Heart, the large lake beyond the mangal to the east.", objectives = "Bring 5 Sandfern fronds to Debaar at the Nesingwary Base Camp.", progress = "Did you bring all the ferns we'll need?", completion = "<Debaar accepts the sandfern fronds from you and starts bending them around your body.>\n\nYes, this should work. Stand still! We'll make a bush of you yet." }
WordHunterWoW_QuestEN[12561] = { title = "An Issue of Trust", description = "This should never have happened.  The forces of undeath storm the very cradle of life!\n\nIf you're not here to destroy the minions of the Lich King, then leave at once.  Do not incur my wrath by distracting me from my duties.", objectives = "Obtain Freya's trust by destroying 6 Blighted Corpses and 10 Bonescythe Ravagers in the Lost Lands.", progress = "Do not waste my time, mortal.  The titans' creations must be defended!", completion = "Very well, <race>.  I am satisfied that you're not one of the Lich King's minions... perhaps there is something you can do for us after all." }
WordHunterWoW_QuestEN[12562] = { title = "The Drakkari Do Not Need Water Elementals!", description = "Intelligence reports that ever since those water elementals appeared in the Drak'Sotra Fields, a number of Drakkari shaman have come down from the upper tiers of Zul'Drak to take control of them.\n\nI cannot stress enough, sir, how dangerous that could prove. We do not want them to have water elementals at their disposal.\n\nThe commander has ordered that these Drakkari water binders are to be put to the sword. Head south when you're ready.", objectives = "Sub-Lieutenant Jax at The Argent Stand has asked you to kill 10 Drakkari Water Binders.", completion = "Excellent work, sir!\n\nI'll see to it that the commander is apprised of your mission results." }
WordHunterWoW_QuestEN[12563] = { title = "Troll Patrol", description = "Unsheathe that weapon, {race}. It's time to go on patrol!\n\nI've got four posts under my command and it's crucial to our success that they remain in our control. I'm ordering you to visit each of them and offer your assistance.\n\nYou can begin with Captain Brandon southeast of here. He'll direct you to the next post when he's finished with you.\n\nReport back to me once you've assisted each of my men. And remember, you'll be more richly rewarded for returning to me quickly - so double-time it!\n\nDismissed!", objectives = "Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain's orders, and then return and report to him.\n\nCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Captain Grondel is posted in Drak'Agal, and Alchemist Finklestein is posted in Heb'Valok.", completion = "Well, <name>, at least you've made it back in one piece. I suppose that's worth something...." }
WordHunterWoW_QuestEN[12564] = { title = "Troll Patrol: Something for the Pain", description = "Gritty as my men are, they're still mortal.\n\nWounds and pain diminish their ability to perform their missions. No amount of training changes that simple fact of life.\n\nThankfully, one of our alchemists has developed a recipe for a salve that binds to our bandages and greatly reduces the pain our soldiers experience.\n\nThe salve requires a special poppy these trolls cultivate just west of here. Go to Drak'Sotra Fields and harvest some of them to keep our stockpiles from running out.", objectives = "Captain Brandon at Drak'Sotra wants you to collect 5 Mature Water-Poppies from Drak'Sotra Fields.", progress = "Have you collected the water-poppies, <name>?", completion = "Fine specimens, <name>.\n\nOn behalf of my soldiers, I thank you for your efforts today.\n\nCaptain Rupert is likely the next stop on your patrol. He's stationed at the wall just east of here." }
WordHunterWoW_QuestEN[12565] = { title = "The Blessing of Zim'Abwa", description = "I am heartened to see the zeal with which your Argent Crusade is dealing with the Scourge, {race}. I would like to help with your efforts.\n\nThe Drakkari trolls of this once-great city used to make regular offerings to their gods, but now neglect them, or worse.\n\nIf you were to make offerings to the gods, they would show their appreciation in return.\n\nZim'Abwa's statue is just to the southwest. Zim'Abwa would gladly accept your offerings of Drakkari artifacts as a sign that you are protecting Zul'Drak.", objectives = "Hexxer Ubungo at The Argent Stand wants you to present 10 Drakkari Offerings to the statue of Zim'Abwa.", progress = "<Zim'Abwa stares inscrutably to the north and the south.>", completion = "<If Zim'Abwa could move his face, Zim'Abwa would make a vicious grin.>" }
WordHunterWoW_QuestEN[12566] = { title = "Help for Camp Winterhoof", description = "I am Longrunner Nanik of the Taunka, sent by the chieftain of Camp Winterhoof to seek out allies in the fight against the vrykul. They mass to the west and south of our village, and though we slay 10 of them for every one of our dead, we cannot hold.\n\nApothecary Scyllis has promised to send brave {class}s northwest to our aid. Will you help my people fend off the vrykul assaults?\n\nFollow the road far to the northwest, across the river, and into the foothills of the mountains to reach Camp Winterhoof.", objectives = "Speak with Chieftain Ashtotem at Camp Winterhoof.", completion = "So, Nanik did find help then? Tell me, <name>, how is it you made it here without him? None know this land better than the Taunka." }
WordHunterWoW_QuestEN[12567] = { title = "Blessing of Zim'Abwa", description = "", objectives = "<Zim'Abwa's stony visage pierces your soul.\n\nZim'Abwa is pleased, but wants you to show more appreciation and respect by giving him more Drakkari offerings.\n\nHe will reward you in kind.>", progress = "<Zim'Abwa's stony visage pierces your soul.\n\nZim'Abwa is pleased, but wants you to show more appreciation and respect by giving him more Drakkari offerings.\n\nHe will reward you in kind.>", completion = "<You sense Zim'Abwa's approval. Somehow you know that Zim'Abwa wants more tribute!>" }
WordHunterWoW_QuestEN[12568] = { title = "Troll Patrol: Done to Death", description = "Trust me, {race}. I know....\n\nThe smell of burnt flesh has become sickening to even me, a Forsaken. Nevertheless, it is our solemn duty to ensure that our brethren never walk with the Scourge.\n\nPour this oil on the corpses of our fallen to ensure that we never face them on the battlefield as enemies.", objectives = "Captain Rupert wants you to use the Incinerating Oil on 5 Defeated Argent Footmen in Drak'Sotra.", completion = "Thank you, <name>.\n\nIt's not the most glorious job on the battlefield, but it must be done. I'll make note of your service in my report.\n\nCaptain Grondel is likely waiting for you to the northeast, just outside the amphitheater." }
WordHunterWoW_QuestEN[12569] = { title = "Crocolisk Mastery: The Ambush", description = "The largest crocolisk in the basin, known around here as \"Bushwhacker\" for his ambush prowess, likes to sun himself in the shallow waters of River's Heart. It's the large lake at the basin's center, and is to the east of our camp.\n\nI want you to take the camouflage I've prepared and hide on the western beach of River's Heart and ambush Bushwhacker when he shows himself. Bring back his mighty jaws if you are able to overcome him.", objectives = "Bring Bushwhacker's Jaw to Debaar at the Nesingwary Base Camp.", progress = "Did our plan work?", completion = "<Debaar listens as you describe the failure of the disguise.>\n\nWhat do you mean, our plan didn't work as intended?\n\nWell, you did manage to get the kill, to your credit. Look at the size of this jaw! Hemet will be proud of our efforts. This crocolisk was truly a monster." }
WordHunterWoW_QuestEN[12570] = { title = "Fortunate Misunderstandings", description = "I sorry! I not mean to get you in trouble!\n\n<The injured oracle stares at you blankly for a long while.>\n\nYou save me! We thank you. We going to go back to village now. You come too... you can stay with us! Puppy-men kind of mean anyway.\n\nLet me know when you ready to go, okay?", objectives = "Escort the Injured Rainspeaker Oracle to Rainspeaker Canopy and speak to High-Oracle Soo-say.", progress = "Who you? You stink of puppy-men.", completion = "You help us? You welcome then, dryskin." }
WordHunterWoW_QuestEN[12571] = { title = "Make the Bad Snake Go Away", description = "We were here long before the puppy-men came. This is very sacred place - we will not leave.\n\nYou seem like maybe you good, but we have Lafoo stay with you just in case. You understand we think.\n\nThere snakes thing that keeps trying to eat our hatchlings. Go with Lafoo and make them stop, okay? Especially big one near waterfall to northeast.", objectives = "High-Oracle Soo-say in Rainspeaker Canopy wants you to kill Venomtip and 10 Emperor Cobras.\n\nIf you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.", completion = "Snake gone?\n\nGood <race>. We thank you." }
WordHunterWoW_QuestEN[12572] = { title = "Gods like Shiny Things", description = "Soo-say said we go with you. You be nice, okay?\n\nOoh, ooh! We know! We can make Soo-say happy if we bring back more offerings for shrine! We not need to go far, there's always stuffs to dig up around village... just look for sparkles in dirt!\n\nLet's go! Let's go! More offerings for shrine!", objectives = "Collect 6 of the treasures that Lafoo digs up and bring them to High-Oracle Soo-say in Rainspeaker Canopy.\n\nIf you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "Hello dryskin. You get along with Lafoo good?", completion = "Shinies for the Great Rain Stone! Good! Good!\n\nWe offer these right away. Lafoo thought of this, yes? He a very smart Rainspeaker." }
WordHunterWoW_QuestEN[12573] = { title = "Making Peace", description = "We have great idea. You were friends with puppy-men, they maybe listen to you.\n\nWe want you to go give offering to Shaman Vekjik. He southwest where river turns into waterfall.  Tell puppy-man we no want fight. Tell him we play nice.\n\nYou good {race}. We trust you do this right.", objectives = "High-Oracle Soo-say at Rainspeaker Canopy wants you to give a peace offering to Shaman Vekjik and then return with his response.\n\nIf you lose Lafoo's Bug Bag, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "Puppy-men play nice now?", completion = "So mean! We only be nice and they only be mean.\n\nThey keep messing with great stones... maybe they not know great stones are sacred." }
WordHunterWoW_QuestEN[12574] = { title = "Back So Soon?", description = "<High-Oracle Soo-say stares at your forehead for a while before speaking.>\n\nSoo-gan ask for help. We think they might have been attacked by puppy-men again.\n\nWe sending you and Jaloot to help... follow west river up to Mistwhisper Refuge. Do what Soo-gan says... hit the puppy-men on the nose if they being mean, they don't like that.\n\n<High-Oracle Soo-say goes back to staring at your forehead as you leave.>", objectives = "Travel to Mistwhisper Refuge and speak to Mistcaller Soo-gan.\n\nIf you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.", completion = "We think we seen you before. You visit Mistwhisper village sometime already?\n\nSoo-say said you good. Soo-say smart, so we trust you too.\n\n<Mistcaller Soo-gan offers an awkwardly large smile.>" }
WordHunterWoW_QuestEN[12575] = { title = "The Lost Mistwhisper Treasure", description = "So some puppy-men come and smash blue crystals at Great Mist Stone! Lots of rain and lightning and badness... blue is wrong crystal for Great Mist Stone! Dumb puppy-men.\n\nAfter lightning, puppy-men stole big treasure we found in the sea-lake. We need treasure back to give to Great Mist Stone! Mist Stone is angry after what the puppy-men did!\n\nOne who took it named Tarter... no, Tiktak... no, no... Tartek. That it, Tartek! He went to the camp thing to north. Go get treasure back!", objectives = "Kill Warlord Tartek and retrieve the Mistwhisper Treasure for Mistcaller Soo-gan at Mistwhisper Refuge.\n\nIf you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "Dumb puppy-thieves.", completion = "You did it! You strong and nice! Good friend of Mistwhispers!\n\n<Mistcaller Soo-gan lets loose a big toothy grin.>" }
WordHunterWoW_QuestEN[12576] = { title = "Forced Hand", description = "We try to be nice to puppy-men ever since they came, but they nothing but mean.\n\nWe okay with them being dumb - they not do much harm. Now they mess with sacred shrines though. Sacred shrines not for messing with. The Great Stones are here from all the way back when the Great Ones made us.\n\nWe wouldn't know what to do if the Great Mist Stone were hurt. Go to their camp to north... make puppy-men stop and not come back!", objectives = "Kill 8 Frenzyheart Spearbearers and 6 Frenzyheart Scavengers for Mistcaller Soo-gan at Mistwhisper Refuge.\n\nIf you lose Jaloot's Favorite Crystal, speak to High-Oracle Soo-say in Rainspeaker Canopy.", completion = "You squash good. Thank you for help." }
WordHunterWoW_QuestEN[12577] = { title = "Home Time!", description = "You're a good dryskin. Mistwhisper safe, treasure safe, and puppy-men sure to leave us alone now.\n\nYou go back to Rainspeaker Canopy and tell Soo-say you done good.", objectives = "Return to Rainspeaker Canopy.", completion = "You back so soon!\n\nWent good then, yeah?" }
WordHunterWoW_QuestEN[12578] = { title = "The Angry Gorloc", description = "I not think you be back in time to go out again, but I wrong. I sending Moodle to nearby Mosswalker friends to bop silly Mosswalkers for not coming see shrine. Their village is east, up ridge, northeast of broken pillar.\n\nYou go with Moodle! He extra smart Rainspeaker... you listen to him good-like.", objectives = "Travel to Mosswalker Village and speak to Moodle once you've arrived.\n\nIf you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "Soo-say fumbles a bit, but he's not dumb. I do think he's been far too forgiving though... the puppy-men are not going to stop or leave us alone. The only way to stop them is to kill them... there is no \"peace.\"\n\n<Moodle puffs up his chest and points to himself.>\n\nThat I am good at.", completion = "Before you say anything, do not assume me as foolish as most of the Oracles you've met. I've been into the world a bit, I've learned your language, and I'm not easily duped.\n\nI knew the Mosswalkers were dead before we ever came, though I didn't know that the undead were behind it.\n\nThey are not supposed to be able to enter this land... the destruction of the Lifeblood Pillar must have allowed them in somehow. We must see to it that they leave." }
WordHunterWoW_QuestEN[12579] = { title = "Lifeblood of the Mosswalker Shrine", description = "I've always suspected that the pillars have been the main reason for our weather and seclusion from the undead... this confirms it a bit.\n\nNot terribly long ago, there was a sound of a great explosion when the Lifeblood Pillar fell. The weather changed for the mosswalkers almost immediately... it began to snow, something we never see.\n\nThey were able to stop the snow by bringing more lifeblood crystals to the Great Moss Stone. Perhaps if we can do the same, it will help ward off the undead as well.", objectives = "Moodle wants you to collect 10 Lifeblood Shards, but stay away from the cave inside of the pillar itself.\n\nIf you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "The Mosswalkers were good people... they did not deserve this.", completion = "We might be too late for the shards to make a difference, but our options are somewhat limited." }
WordHunterWoW_QuestEN[12580] = { title = "The Mosswalker Savior", description = "There's some small chance that the Mosswalkers are not all dead yet... and at the very least, they deserve to not be butchered like this.\n\nLet's find some revenge for this slaughter and see if there are any to be saved in the process.", objectives = "Moodle wants you to rescue 6 of the Mosswalker Victims in Mosswalker Village, though some of them may no longer be alive to save.\n\nIf you lose Moodle's Stress Ball, speak to High-Oracle Soo-say in Rainspeaker Canopy.", progress = "I wish I had known how key the pillars and the stones were much earlier... perhaps I could have prevented this.", completion = "I'm very glad there were some to be saved... with luck, they'll make it back to Rainspeaker Canopy safely." }
WordHunterWoW_QuestEN[12581] = { title = "A Hero's Burden", description = "Perhaps the crystals will ward off the undead gradually, but there is one more thing that must be done.\n\nWe need to find the leader of these undead and kill him to ensure there's no one to push the wretches back upon us. If my suspicions are correct, he will be somewhere inside the fallen pillar... the Sundered Shard.\n\nThe corpses being dragged there would suggest as much anyway.\n\nI'll place the shards and bring the news to Soo-say... I'll leave the rest up to you.", objectives = "Kill Artruis the Heartless.\n\nMoodle will not be able to accompany you on this task.", progress = "<The phylactery rests ominously on the ground next to Artruis' dead form.>", completion = "<Inside Artruis's Phylactery you see what seems like an endless void... and you think you hear screaming in the distance from somewhere inside.>\n\n<As you're about to leave, you see an object floating in the void, just barely in reach.>" }
WordHunterWoW_QuestEN[12582] = { title = "Frenzyheart Champion", description = "", objectives = "I know you weren't traitor thing like others said. We hunt together... I know you better than all of them. Thank you for saving me.\n\nMay sound funny... I not a big fan of big-tongues... but even I feel little bad for big-tongue dying like that though...they fight good enough they deserve fair fight.\n\nYou want to be friends with Frenzyheart again? I think I can convince them that you save me and got the big-tongues good. I no want you to make me look dumb though, so you sure no more big-tongues for you?" }
WordHunterWoW_QuestEN[12583] = { title = "Crashed Sprayer", description = "I know that one of those plague sprayers crashed somewhere within Drak'Sotra to the west of us.\n\nWhy don't you see if you can find it. I can use the parts from the sprayer to create the device that's going to bring those things down!", objectives = "Specialist Cogwheel at Drak'Sotra has asked you to collect Plague Sprayer Parts.", progress = "Do you have the parts? Huh? Do you?", completion = "<The specialist steps back a bit when presented with the parts.>\n\nEw, those things are totally gross!\n\nOkay, okay, hand them over and I'll see what I can do. I probably should have had you take them to a priest first for purification." }
WordHunterWoW_QuestEN[12584] = { title = "Pure Evil", description = "We know that Kolramas, the crashed necropolis to the southeast, was carrying a large amount of an ore known as saronite when the trolls shot it down.\n\nMy scouts tell me that much of the saronite is strewn about within the innards of that thing.\n\nEitrigg and his friends back at The Argent Stand want a bunch of the stuff so that they can study it.\n\nI want you to head in there and see if you can collect enough for them.", objectives = "Captain Rupert has asked you to collect 10 Chunks of Saronite and deliver them to Eitrigg at The Argent Stand.", progress = "Yes, <class>?\n\nPlease tell me that you have the saronite that we requested Captain Rupert to acquire?", completion = "Can you not feel the pure evil of the stuff?\n\nWe must use the expertise and magics at our disposal, combined with the power of the Holy Light, to pierce the veil of iniquity surrounding this tainted ore. We must determine its origins.\n\nQuickly, hand the saronite to me!" }
WordHunterWoW_QuestEN[12585] = { title = "Troll Patrol: Creature Comforts", description = "Well, it ain't glamorous, but it needs doin'.\n\nMy troops have been fightin' their hearts out while knee-deep in stagnant water for days on end. That just can't be good fer ya.\n\nWhat they need is a nice fire to dry 'em out and lighten their spirits.\n\nThis part of the city's soaked, but the dead roots of these thornwood trees have a way of resistin' the moisture.\n\nRound us up some fuel for burnin' and we'll be mighty grateful.", objectives = "Captain Grondel at Drak'Agal wants you to bring him 20 pieces of Dead Thornwood.", progress = "Ya got the wood fer a fire, <race>?", completion = "Mighty kind of ya, <name>. Mighty kind indeed.\n\nNow you'll be findin' Cap'n Arnath due west o' here, just over the rise." }
WordHunterWoW_QuestEN[12586] = { title = "In Search of Bigger Game", description = "Well, <name>, you've been an enormous asset to the expedition so far. Debaar, Buck, and I couldn't have have assembled such an amazing collection of trophies without you.\n\nBut, I hear there are even fiercer monsters in other parts of the basin. I've sent a search party up north to get an idea of what other beasts await us.\n\nI'd like you to meet up with them and see what they've found. Head north, beyond Bittertide Lake and search for the encampment.", objectives = "Talk to <x> at <x>.Well, <name>, you've been an enormous asset to the expedition so far. Debaar, Buck, and I couldn't have have assembled such an amazing collection of trophies without you.\n\nBut, I hear there are even fiercer monsters in other parts of the basin. I've sent a search party up north to get an idea of what other beasts await us.\n\nI'd like you to meet up with them and see what they've found. Head north, beyond Bittertide Lake and search for the encampment." }
WordHunterWoW_QuestEN[12587] = { title = "Troll Patrol", description = "Unsheathe that weapon, {race}. It's time to go on patrol!\n\nI've got four posts under my command and it's crucial to our success that they remain in our control. I'm ordering you to visit each of them and offer your assistance.\n\nYou can begin with Captain Brandon southeast of here. He'll direct you to the next post when he's finished with you.\n\nReport back to me once you've assisted each of my men. And remember, you'll be more richly rewarded for returning to me quickly - so double-time it!\n\nDismissed!", objectives = "Commander Kunz at the Argent Stand wants you to visit the four Argent Crusade posts, follow their captain's orders, and then return and report to him.\n\nCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Captain Grondel is posted in Drak'Agal, and Alchemist Finklestein is posted in Heb'valok.", completion = "Well, <name>, at least you've made it back in one piece. I suppose that's worth something...." }
WordHunterWoW_QuestEN[12588] = { title = "Troll Patrol: Can You Dig It?", description = "One of our troops came across an old treasure map during our last offensive. If what it shows is true, then there are priceless troll artifacts nearby.\n\nMy soldiers have their hands full, pressed between the Drakkari and the Scourge. I need you to follow up on this intelligence.\n\nTake this shovel and use it at the loose dirt mounds to the southwest. Return to me after a diligent search has been conducted.", objectives = "Captain Brandon in Drak'Sotra wants you to use the Steel Spade on the nearby Ancient Dirt Mounds to recover the Ancient Drakkari Relic.", completion = "Thank you for looking into this for me, <name>. I'll make mention of your service in my report.\n\nYou'll likely want to visit Captain Rupert next. He's stationed at the wall due east of here." }
WordHunterWoW_QuestEN[12589] = { title = "Kick, What Kick?", description = "So you think you can shoot?\n\nWell, let's give it a try. Here, we'll start you out with something nice and gentle. Don't worry, it's got no kick to it at all. Remember, don't point that gun at anything you don't intend to fire at.\n\nNow, when you're ready, just take aim at that apple on top o' old Lucky Wilhelm's head and let 'er fly!", objectives = "Using the RJR Rifle, shoot the apple on top of Lucky Wilhelm's head, then speak with Drostan.", progress = "Satisfied with the results?", completion = "You're not a bad shot, but you'll get better with practice. How would you like to make a little wager?" }
WordHunterWoW_QuestEN[12590] = { title = "Blahblah[PH]", description = "", objectives = "" }
WordHunterWoW_QuestEN[12591] = { title = "Troll Patrol: Throwing Down", description = "Clever...\n\nJust when it seemed we were getting things under control, they tunneled right underneath us and secured the shrine!\n\nNow we're caught between two nethurbian armies and our predicament is worsening by the minute.\n\nAs our first course of action, we must stop them from reinforcing. Their tunnels must be sealed.\n\nTake these grenades and throw them down their craters to the northwest.", objectives = "Captain Rupert at Drak'Sotra wants you to use High Impact Grenades near 5 Nethurbian Craters.", completion = "We're not out of the woods by any means, but your efforts have helped to slow the enemy down.\n\nCaptain Grondel up in Drak'Agal will likely have need of you.\n\nFarewell, <name>." }
WordHunterWoW_QuestEN[12592] = { title = "The Great Hunter's Challenge", description = "So y'have something of a hunter's instinct. You're not a bad shot, and Hemet hasn't driven you out, so he must be planning on including you in the hunt.\n\nHow'd you like to have a bit of a competition, just me and you?\n\nHemet and the others will ask you to help in their hunting. Along the way, you and I will count up the kills we contribute to their goals. Now, this isn't something you can win in the blink of an eye, and you'll find yourself killing many different kinds of creatures. Good luck!", objectives = "Kill 60 Game Animals while you aid Hemet and his companions in their hunting. When you've killed your 60, return to Drostan at the Nesingwary Base Camp to compare numbers.", completion = "So, you've come to concede already?\n\n<Drostan's jaw drops as you tell him you've already made all your kills.>\n\nNo way! How in Azeroth did you do that? I just made my 58th. So close!\n\nBut fair's fair. I underestimated you, <name>, but you've earned this victory fair and square." }
WordHunterWoW_QuestEN[12593] = { title = "In Service Of The Lich King", description = "All that I am: anger, cruelty, vengeance - I bestow upon you, my chosen knight. I have granted you immortality so that you may herald in a new, dark age for the Scourge.\n\nGaze now upon the lands below us. The Scarlet Crusade scurries to undo my work, while Light's Hope stands defiantly against us - a blemish upon these Plaguelands. They must all be shown the price of their defiance.\n\nYou will become my force of retribution. Where you tread, doom will follow. Go now and claim your destiny, death knight.", objectives = "Report to Instructor Razuvious in the Heart of Acherus.", completion = "You have heard the call of the Lich King, <class>. Now is the time to answer your master." }
WordHunterWoW_QuestEN[12594] = { title = "Troll Patrol: Couldn't Care Less", description = "Of all the posts, they throw me in this one.\n\nThe place is flooded with putrid, stagnant water and now it's host to sewage elementals!\n\nI don't really know what they are or why they're here, and frankly I couldn't care less. What I do know is they're making a mess of my sector! How am I supposed to conduct any dignified military operations with those foul things roaming around?\n\nGet out there, {class}, and don't come back 'til you've cleared your share of 'em off of my battlefield!", objectives = "Captain Grondel wants you to kill 7 Mossy Rampagers in Drak'Agal.", progress = "You clear the area of bog beasts yet, <class>?", completion = "You sure about that, <race>?\n\nSeems to me like there are more of them things out there now than when you started!" }
WordHunterWoW_QuestEN[12595] = { title = "In Search of Bigger Game", description = "Well, {name}, you've certainly proven your mettle as a hunter of all kinds of game animals -- rhinos, cats, and crocolisks. For some members of the expedition, these creatures are sufficient to test their hunting skills, but others, like myself, crave larger challenges.\n\nDorian Drakestalker went north, across Bittertide Lake and established a camp there. He's heard rumors of gigantic primordial drakes. Just imagine what a quarry they would be! Go check up on Dorian and see if he's had any luck.", objectives = "Speak with Dorian Drakestalker at Dorian's Outpost in Sholazar Basin.", completion = "So old Hemet didn't forget about me, after all. I suppose he's going to want to participate in the hunt once we've done all the hard work. Don't worry, there are plenty of drakes to go around. Hemet will get his wish." }
WordHunterWoW_QuestEN[12596] = { title = "Pa'Troll", description = "Welcome to The Argent Stand, scrub. I am Commander Kunz, but you - you can call me... Commander.\n\nDon't think you're going to just cruise through my region, picking which missions you're going to participate in, answering to no one.\n\nHere, you report to me and you follow my orders to the letter. Understood?!\n\nFirst, you're going to get familiar with my men and the region we're charged with clearing.\n\nReport to each of them and do as they ask. Return to me when your patrol is done.", objectives = "Commander Kunz at The Argent Stand wants you to visit the four Argent Crusade posts, follow their leaders' orders, and then return and report to him.\n\nCaptain Brandon and Captain Rupert are posted at Drak'Sotra, Southeast of here.\n\nCaptain Grondel is posted in Drak'Agal, due east.\n\nAlchemist Finklestein is posted in Heb'Valok, to the north.", completion = "It's about time you got your carcass back here! Thought we'd lost ya to the Scourge - not that it would've been a great loss....\n\nIf you're going to continue to serve the Crusade, you'd best make a more impressive showing.\n\nTake note, <race>! Your future patrols will be rewarded based on your timeliness.\n\nDismissed." }
WordHunterWoW_QuestEN[12597] = { title = "Something for the Pain", description = "Gritty as my men are, they're still mortal.\n\nWounds and pain diminish their ability to perform their missions. No amount of training changes that simple fact of life.\n\nThankfully, one of our alchemists has developed a recipe for a salve that binds to our bandages and greatly reduces the pain our soldiers experience.\n\nThe salve requires a special poppy these trolls cultivate just west of here. Go to Drak'Sotra Fields and harvest some of them to keep our stockpiles from running out.", objectives = "Captain Brandon at Drak'Sotra wants you to collect 5 Mature Water-Poppies from Drak'Sotra Fields.", progress = "Have you collected the water-poppies, <name>?", completion = "Fine specimens, <name>.\n\nOn behalf of my soldiers, I thank you for your efforts today.\n\nCaptain Rupert is likely the next stop on your patrol. He's stationed at the wall just east of here." }
WordHunterWoW_QuestEN[12598] = { title = "Throwing Down", description = "Clever...\n\nJust when it seemed we were getting things under control, they tunneled right underneath us and secured the shrine!\n\nNow we're caught between two Nerubian armies and our predicament is worsening by the minute.\n\nAs our first course of action, we must stop them from reinforcing. Their tunnels must be sealed.\n\nTake these grenades and throw them down their craters to the northwest.", objectives = "Captain Rupert at Drak'Sotra wants you to use High Impact Grenades near 5 Nerubian Craters.", progress = "Have you sealed the nerubian tunnels, <name>?", completion = "We're not out of the woods by any means, but your efforts have helped to slow the enemy down.\n\nCaptain Grondel up in Drak'Agal will likely have need of you.\n\nFarewell, <name>." }
WordHunterWoW_QuestEN[12599] = { title = "Creature Comforts", description = "Well, it ain't glamorous, but it needs doin'.\n\nMy troops have been fightin' their hearts out while knee-deep in stagnant water for days on end. That just can't be good fer ya.\n\nWhat they need is a nice fire to dry 'em out and lighten their spirits.\n\nThis part of the city's soaked, but the dead roots of these thornwood trees have a way of resistin' the moisture.\n\nRound us up some fuel for burnin' and we'll be mighty grateful.", objectives = "Captain Grondel at Drak'Agal wants you to bring him 20 pieces of Dead Thornwood.", progress = "Ya got the wood fer a fire, <race>?", completion = "Mighty kind of ya, <name>. Mighty kind indeed.\n\nNow you'll be findin' ol' Finklestein due west o' here, just over the rise." }
WordHunterWoW_QuestEN[12600] = { title = "Upper Deck Promo - Bear Mount", description = "", objectives = "" }
WordHunterWoW_QuestEN[12601] = { title = "The Alchemist's Apprentice", description = "Ahh, you must be the promised patrol. Your timing couldn't be better. I have urgent need of an extra pair of hands.\n\nWe have a Drakkari prisoner who's been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum.\n\nCreating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step.\n\nLet me know when you're ready, <race>. And remember, timing is everything!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Alchemist Finklestein at Heb'valok wants you to assist him in the creation of a truth serum.\n\nWhen you are ready to begin, you are to speak to him and follow his instructions." }
WordHunterWoW_QuestEN[12602] = { title = "The Alchemist's Apprentice", description = "Ahh, you must be the promised patrol. Your timing couldn't be better. I have urgent need of an extra pair of hands.\n\nWe have a Drakkari prisoner who's been sent here to undergo questioning. Before the interrogation begins, I require assistance in the creation of a truth serum.\n\nCreating a truth serum is tricky business, demanding keen instincts, perfect timing, and improvisation at every step.\n\nLet me know when you're ready, <race>. And remember, timing is everything!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Alchemist Finklestein at Heb'valok wants you to assist him in the creation of a truth serum.\n\nWhen you are ready to begin, you are to speak to him and follow his instructions." }
WordHunterWoW_QuestEN[12603] = { title = "Sharpening Your Talons", description = "The primordial drakes occupy most of the area to the north and east, and I can feel the heat of their breath even at this distance. Before we can challenge the mightiest among the drakes, we must test our skills against the lesser creatures.\n\nStill, don't let your guard down; any one of these beasts can devour a man whole. Once you've familiarized yourself with the combat tactics of these drakes, return and I will tell you our next step.", objectives = "Kill 6 Primordial Drakes and then speak with Dorian Drakestalker at Dorian's Outpost.", completion = "I can hear the confidence in your words. Good, the experience will come in handy when we face the queen of the drakes." }
WordHunterWoW_QuestEN[12604] = { title = "Congratulations!", description = "You made excellent time on that patrol, {race}. It appears that you may be of use to us after all.\n\nAs promised, here's a little something extra for you're efforts.", objectives = "You made excellent time on that patrol. It appears that you may be of use to us after all.\n\nAs promised, here's a little something extra for your efforts.\n\nKeep up the good work, <name>.\n\nDismissed." }
WordHunterWoW_QuestEN[12605] = { title = "Securing the Bait", description = "We're not likely to get Broodmother Slivina's attention waving our arms around like fools, but if we're smart, we can bait her into fighting us. We'll also secure more, uh, fodder for my little project.\n\n<Dorian glances over at Zootfizzle.>\n\nBut don't worry about that for now. Just look for the primordial drake eggs in the area east and northeast of the camp. Burst them open and scoop up the hatchlings that come out. When the broodmother realizes what we've done, she'll have no choice but to face us.", objectives = "Bring 6 Primordial Hatchlings to Dorian Drakestalker at Dorian's Outpost.", progress = "Have you secured the bait we'll need to get the broodmother's attention?", completion = "Ah, well done. Plenty of little hatchlings for Zootfizzle over there!" }
WordHunterWoW_QuestEN[12606] = { title = "Cocooned!", description = "Now that the tunnels have been sealed, our next concern is recovering those who have fallen to the enemy.\n\nWith any luck, several of our soldiers are still alive and relatively well inside the nerubian cocoons.\n\nFree them, {class}, while you still can!", objectives = "Captain Rupert wants you to open the Nerubian Cocoons in Drak'Sotra and return to him once you have freed 3 Captive Footmen.", completion = "These nerubians have taken a heavy toll, <class>.\n\nNevertheless, I am grateful for your efforts." }
WordHunterWoW_QuestEN[12607] = { title = "A Mammoth Undertaking", description = "Before you go off challenging Broodmother Slivina, Dorian thought it might be a good idea for you and Hemet to coordinate your efforts by riding into battle on the back of a mammoth.\n\nThe area around the camp is full of them. Just take this bridle and slip it over the head of a shattertusk mammoth. Be careful of the bulls, though. They won't tolerate the harness at all. Bring the mammoth back here when you've found a suitable one.", objectives = "Bring a Shattertusk Mammoth to Zootfizzle at Dorian's Outpost.", completion = "Perfect! Now, all we need to do is get Hemet a stepladder..." }
WordHunterWoW_QuestEN[12608] = { title = "Cultist Incursion", description = "<It appears the Avatar of Freya was right.  The undead were not able to enter Sholazar Basin before the Lifeblood Pillar was brought down -- they used their living agents from the Cult of the Damned instead.>\n\n<You'd best warn her about the Lich King's living agents within Sholazar Basin.>", objectives = "Speak to the Avatar of Freya at the Rainspeaker Rapids.", completion = "The living... willingly serve the Lich King?\n\nAll this time I've been searching for the wrong enemy, <race>.  Let us make haste and uproot these cultists from these lands." }
WordHunterWoW_QuestEN[12609] = { title = "Stocking the Shelves", description = "Listen, {class}. I realize that it's a lot to ask....\n\nFresh spider ichor is somewhat hard to come by, even in these heavily infested regions. But Finklestein said he'd settle for no less than a vat of it, and that he needs it soon.\n\nI'll keep my men out in the field collecting reagents, but if the alchemist's order is going to be filled in time, they'll require some assistance.\n\nAs you roam the fields of Zul'Drak, keep your eyes peeled for trapdoor crawlers and bring me all of the ichor you can find.", objectives = "Captain Arnath in Heb'Valok asked you to collect 7 units of Fresh Spider Ichor from the Trapdoor Crawlers in Zul'Drak.", progress = "Have you collected the reagents I need, <class>?", completion = "These look to be excellent samples, <name>.\n\nThank you for your assistance." }
WordHunterWoW_QuestEN[12610] = { title = "Clipping Their Wings", description = "Ever since Finklestein's arrival, I've been relegated to collecting various ingredients for his experiments and recipes.\n\nI'll follow my orders as I've vowed to do, but I'm a seasoned veteran. I've taken part in dozens of conflicts. I'd much rather be on the front lines, having a more direct impact on the Crusade's outcome here.\n\nHelp me, {race}. Collect some bat wings for me so that I might get back to the real action sooner.", objectives = "Captain Arnath in Heb'Valok has asked you to collect 7 Unblemished Bat Wings from Zul'Drak Bats.", progress = "Have you finished collecting those bat wings for Finklestein?", completion = "Excellent work, <name>.\n\nI thank you for your assistance." }
WordHunterWoW_QuestEN[12611] = { title = "Returned Sevenfold", description = "The agents of the Lich King have foolishly trespassed upon these lands where the power of life rules supreme.  All harm they inflict will be returned to them sevenfold.\n\nThe monster directly responsible for corrupting the land is known as Thalgran Blightbringer; you will find him just to the north of here.  Take this ward and use it to reflect the power of death upon him.  Show the Scourge that the power of life prevails above all.", objectives = "The Avatar of Freya wants you to defeat Thalgran Blightbringer by using Freya's Ward to reflect his Deathbolts back to him sevenfold.", progress = "Is it done, <name>?", completion = "You continue to prove yourself, <name>.  Perhaps I was too quick to judge you.\n\nI had assumed you were here with the poachers who were recently stranded in my lands, but perhaps you're ready to put that behind you." }
WordHunterWoW_QuestEN[12612] = { title = "The Fallen Pillar", description = "The titans shaped entire life forms here, fostering their unfettered growth.\n\nThe five crystal pillars that surround the basin emanate pure lifeforce.  The Scourge should've never been able to penetrate the basin, but one of the pillars was destroyed.\n\nGo to the Lifeblood Pillar and see if you can find out what happened.  No undead would've been able to approach the pillar, so keep your eyes out for living intruders.  You'll find what remains of the pillar directly south of here.", objectives = "Travel to the Lifeblood Pillar and look for clues to its destruction.", completion = "<The corpse is badly burnt.  There appear to be the remains of several powder kegs in the vicinity.>" }
WordHunterWoW_QuestEN[12613] = { title = "Powering the Waygate - The Makers' Overlook", description = "We cannot stop now, {race}.  You've triggered the first switch, but one remains.\n\nThe titans constructed a second vantage point where they oversaw their creations.  You'll find it to the east, high in the mountains.\n\nPull the activation switch theta inside the overlook and the waygate will open.", objectives = "The Avatar of Freya wants you to head to the Makers' Overlook in eastern Sholazar Basin and use the Activation Switch Theta.", completion = "The waygate is active, <name>.  It is time!" }
WordHunterWoW_QuestEN[12614] = { title = "Post-partum Aggression", description = "Broodmother Slivina's likely to be a snarling ball of teeth, spikes, and talons. You've gone and stolen her children away and no mother takes kindly to that.\n\n'Tis true they hatched from eggs, but she loves the little beasts no less than your mother loves you.\n\nShe'll be desperate and fierce in equal measures, everything Hemet loves in a target. You and he, along with that mammoth, should be a match for her.\n\nShe's on her perch at the northern edge of the Savage Thicket and hungers for revenge.", objectives = "Kill Broodmother Slivina and return to Dorian Drakestalker at Dorian's Outpost.", progress = "Well, you're alive. How did you fare?", completion = "Well, I had a whole speech prepared, but the old man himself has some words he wants to say to you." }
WordHunterWoW_QuestEN[12615] = { title = "The Blessing of Zim'Torga", description = "Hexxer Ubungo probably told you about making offerings to the gods of Zul'Drak. Zim'Abwa is not the only god that stands forgotten by the Drakkari.\n\nWe have taken refuge within the presence of Zim'Torga, the Mother of Prosperity. As with Zim'Abwa, if you were to give offerings of the Drakkari to her, she is sure to give you her blessing.", objectives = "Witch Doctor Khufu wants you to present 10 Drakkari Offerings to the statue of Zim'Torga.", progress = "<You can feel the eyes of the Mother of Prosperity upon you. She is wondering what a <race> such as yourself is doing standing before her.>", completion = "<Zim'Torga's thoughts pervade your own. She senses the offerings you are about give to her and is pleased.>\n\n<She conveys that you will be appropriately rewarded.>" }
WordHunterWoW_QuestEN[12616] = { title = "Chamber of Secrets", description = "Excellent, an experienced adventurer. Precisely what we need.\n\nThere has been talk from the Kirin Tor guarding Medivh's tower that something is amiss with Karazhan. There is a new power lurking within, one that answers neither to the Guardian's magic nor the Legion. From what they've scouted, it appears it is an elven prince called Tenris Mirkblood, and there is reason to believe he serves the Scourge.\n\nGo, my friend, investigate Mirkblood's chamber, and return with any information you might find.", objectives = "The Argent Dawn Emissary wants you to search the chamber of Tenris Mirkblood within the Servant's Quarters of Karazhan." }
WordHunterWoW_QuestEN[12617] = { title = "Exterminate the Intruders", description = "I am an embodiment of but one aspect of Freya, daughter of the titans.  I am the Lifewarden -- I was left here to protect this land against the threat of the Scourge.\n\nI never anticipated the Lich King would send willing living servants to do his work.\n\nI could easily crush these cultists myself, but I am all that stands between the undead armies and the rest of the basin.  Go, {name}.  Deliver my wrath to these insolent trespassers.", objectives = "The Avatar of Freya at the Rainspeaker Rapids wants you to go to the Death's Hand Encampment to the northwest and slay 8 Cultist Infiltrators.", completion = "You speak the truth.  The intruders at the camp were dealt with... but I'm afraid it might have been too late." }
WordHunterWoW_QuestEN[12618] = { title = "Blessing of Zim'Torga", description = "", objectives = "<Zim'Torga looks on impassively. She wonders if you seek her continued blessing by presenting more Drakkari offerings to honor her.>", progress = "<Zim'Torga looks on impassively. She wonders if you seek her continued blessing by presenting more Drakkari offerings to honor her.>", completion = "<The Mother of Prosperity beams her approval down upon you.>" }
WordHunterWoW_QuestEN[12619] = { title = "The Emblazoned Runeblade", description = "The single most important piece of equipment to a death knight is the runeblade. It is through the runeblade that a death knight commands the powers of frost, blood and the unholy. The runeblade also acts as a vessel to store the death knight's runic power.\n\nThe time has come to create your first runeblade. Search the weapon racks on this floor and locate a battle-worn sword. Once found, take the sword to a nearby runeforge and use it to create a runeblade.", objectives = "Search the weapon racks in Ebon Hold for a Battle-worn Sword and then use it on a runeforge to craft a Runebladed Sword.\n\nReturn the Runebladed Sword to Instructor Razuvious in Ebon Hold.", progress = "The runeblade is an extension of your being. A <class> cannot battle without a runeblade.", completion = "Well done, <name>. You have successfully created your first runebladed weapon. With it you will sow the seeds of chaos and destruction! In your wake will be a bloodied field of battle, littered with the corpses of all that would dare oppose the Scourge." }
WordHunterWoW_QuestEN[12620] = { title = "The Lifewarden's Wrath", description = "We were not quick enough, {name}.  The cultist scum have arrived at the Glimmering Pillar and are making preparations to destroy it, I can sense them.\n\nWe don't have much time.  Blow upon this horn atop the Glimmering Pillar to channel my power through the crystal.\n\nWe shall show this scum to not trifle with the titans' creations.", objectives = "The Avatar of Freya at the Rainspeaker Rapids wants you to use Freya's Horn atop of the Glimmering Pillar.", progress = "Have you taken care of the cultists, <name>?", completion = "Impressive.  I wasn't expecting a mere mortal to prove as worthy an ally as you.\n\nI fear our efforts have not been sufficient, however.  The Scourge shows no signs of stopping." }
WordHunterWoW_QuestEN[12621] = { title = "Freya's Pact", description = "The cultists have been taken care of, but the Scourge's invasion has not slowed down.  The situation is becoming desperate, {name}.\n\nThere exists a last resort.  Before I reveal any more, however, I must be sure I have your absolute trust.", objectives = "Listen to what the Avatar of Freya has to say.", progress = "We have little time.  The Scourge is preparing for a final push.", completion = "There is no turning back now.  If you agree to help me, you will do so without hesitation." }
WordHunterWoW_QuestEN[12622] = { title = "The Leaders at Jin'Alai", description = "You thinkin' what Ahunae thinkin', mon?\n\nSome of the Drakkari trolls have gathered at the Pools of Jin'Alai to the southwest. We be needin' to draw out their leaders, and Ahunae knows just how you be doin' it, too!\n\nGo in there and kill those trolls. When you kill enough, their leaders show up.\n\nWhen they show up next to their totems, you make sure to be gettin' the treasure of Kutube'sa, Gawanil, and Chulo the Mad, mon.", objectives = "Scalper Ahunae at Zim'Torga has asked you to retrieve the Treasure of Kutube'sa, the Treasure of Gawanil, and the Treasure of Chulo the Mad.", progress = "The <class> must be back talkin' to Ahunae because the <class> has all that treasure.", completion = "The scalper thinkin' that you be his kind of <race>!\n\nWhat's these candybars doin' in here? What we do with this, mon?\n\nAhunae say that you can have them back!" }
WordHunterWoW_QuestEN[12623] = { title = "To the Witch Doctor", description = "We Zandalari could use your help, {name}. We must put an end to what the Drakkari are doing to their gods!\n\nTo the northeast, up the great steps that lead to the next tier of Zul'Drak, lies Zim'Torga. It is the home to another of the god statues and a refuge that my people are desparately attempting to defend.\n\nI would like for you to travel there and speak to Witch Doctor Khufu. Be warned though, the place is under constant attack from the Drakkari.", objectives = "Speak with Witch Doctor Khufu at Zim'Torga.", completion = "Greetings to you, <class>. I am glad to hear that Ubungo found someone that he could trust.\n\nWelcome to Zim'Torga." }
WordHunterWoW_QuestEN[12624] = { title = "It Could Be Anywhere!", description = "When I found out that Miss Boulian was helping Nesingwary with his expedition, I signed up as a deckhand immediately.  You see, I'd been meaning to marry her for months!\n\nI had it all planned out.  I was going to propose the very night of the shipwreck... but now the ring is gone.  I've searched everywhere!\n\nI know it might sound crazy, but I know the engagement ring is in the Basin.  If some Venture Company didn't steal it, maybe a wild creature ate it.  But it's here somewhere... I just know it!", objectives = "Look for a Golden Engagement Ring on the various creatures in Sholazar Basin.", progress = "The ring, <name>!  Please... tell me you've found it!", completion = "You did it!  You actually found it!\n\nI don't know... I don't know how to thank you!" }
WordHunterWoW_QuestEN[12625] = { title = "Dominion Over Acherus", description = "Behold, Acherus, the grand citadel of death! It has no equal in this world! Not even the mighty Naxxramas could withstand a direct assault from the Ebon Hold.\n\nThough your thoughts may still be hazy, we haven't a moment to spare. You must claim dominion over Acherus and your mind! The horns of war surge!\n\nTake the stairs on this floor - located north, south, east and west - to the garrison floor above us. Seek out Master Siegesmith Corvus and acquire his status report. It must be delivered to Thalanor.You will receive:", objectives = "Report to Master Siegesmith Corvus on the garrison floor of Ebon Hold.Behold, Acherus, the grand citadel of death! It has no equal in this world! Not even the mighty Naxxramas could withstand a direct assault from the Ebon Hold.\n\nThough your thoughts may still be hazy, we haven't a moment to spare. You must claim dominion over Acherus and your mind! The horns of war surge!\n\nTake the stairs on this floor - located north, south, east and west - to the garrison floor above us. Seek out Master Siegesmith Corvus and acquire his status report. It must be delivered to Thalanor.You will receive:" }
WordHunterWoW_QuestEN[12626] = { title = "Company of the Damned", description = "<Corvus salutes.>\n\nOur stockpiles of weapons, armor and munitions are nearly at maximum capacity. We are ready for war!\n\n<Corvus rolls up a fleshy piece of vellum.>\n\nOn the other side of this garrison floor, southwest of here, you will find the officers' quarters. Take this status report there and deliver it to Scourge Commander Thalanor, battalion commander of the Company of the Damned.You will receive:", objectives = "Deliver Corvus' Report to Scourge Commander Thalanor at the garrison floor of Ebon Hold." }
WordHunterWoW_QuestEN[12627] = { title = "Breaking Through Jin'Alai", description = "I have been trying to commune with the gods. However, the medicine men at the Pools of Jin'Alai are performing rituals that are interfering with my attempts.\n\nIt is imperative that we break through their obtrusion. If you were to head southwest into the pools area, I am certain that you would come across the cauldrons they are using for their magic.\n\nDisturb each of the cauldrons to bring down their ritual that is blocking me.", objectives = "Witch Doctor Khufu at Zim'Torga has asked you to disturb the Blue Cauldron, Green Cauldron, Purple Cauldron, and Red Cauldron.", completion = "Yes, I can already feel the difference. Thank you.\n\nLet us see if we can make contact with the gods now." }
WordHunterWoW_QuestEN[12628] = { title = "To Speak With Har'koa", description = "The gods have spoken, {name}. We now know what you must do.\n\nYou must now go to the Altar of Har'koa to the southeast and speak with the leopard goddess.", objectives = "Speak with Har'koa at the Altar of Har'koa.", completion = "Listen closely, little <race>. Time is of the essence." }
WordHunterWoW_QuestEN[12629] = { title = "You Can Run, But You Can't Hide", description = "Once the Scourge have a target in their sights, they'll stop at nothing to acquire it.\n\nYou're doomed to a mindless existence as a walking corpse....\n\n<Stefan's face twists into a cruel grin.>\n\n... unless we can use their desires against them.\n\nI'll explain later. I have complex magic to prepare which requires certain material components.\n\nTravel due east of here to the Reliquary of Agony. Slay abominations and gather the ghoul drool you'll find there then return to me with their remnants.", objectives = "Stefan in Ebon Watch asked you to go to the Reliquary of Agony to collect 5 Putrid Abomination Guts from the Putrid Abominations and 5 Gooey Ghoul Drools.", progress = "Have you brought me the components I asked for, <name>?", completion = "<Stefan sifts through the foul components.>\n\nWell, it's far from perfect, but it'll have to do. Now brace yourself, <class>. This is where it gets good...." }
WordHunterWoW_QuestEN[12630] = { title = "Kickin' Nass and Takin' Manes", description = "Before you meet Nass, there's something you should know.\n\nHe got a toxic dose of blight back in the day, and now he's deaf, blind, and mostly numb.\n\nIt's not all bad, though. He's virtually immune to the stuff now, which makes him perfect for certain tasks - like the one I'm about to give you.\n\nThere are many freshly scourged trolls nearby and we need to study the blight's effect on them. Take Nass, and this boot. When you've slain a troll, give him a good kick and he'll know to take a hair sample.", objectives = "Stefan in Ebon Watch wants you to use Nass to collect 10 hair samples from Withered Trolls.\n\nIf you lose Nass, return to Stefan to recover him.", completion = "You know, you remind me an awful lot of my Nass.\n\nMaybe it's just the nose..." }
WordHunterWoW_QuestEN[12631] = { title = "An Invitation, of Sorts...", description = "Crafted of bone and dripping with blood, this choker is of intricate and deliberate design.\n\nGazing upon it overwhelms you with an ominous presence - one that compels you to wear it. You fight the urge, and resolve to bring it back to Ebon Watch.\n\nIf anyone can explain this, a death knight can....", objectives = "Take the Unliving Choker to Stefan at Ebon Watch.\n\nProvided item:", completion = "I am indeed familiar with items such as this.\n\n<Stefan looks you in the eye.>\n\nIt would seem, <name>, that you have been... chosen." }
WordHunterWoW_QuestEN[12632] = { title = "But First My Offspring", description = "I am the last of the gods to be subdued, so we must first attempt to free the others. Bound by the magics of my subduers, I am unable to discern their fates.\n\nBut first, I would ask that you do me a kindness. Already the Drakkari turn my magic against me. They have transformed my offspring into monstrosities.\n\nTake one of my whiskers. Slay my tortured children and use the magic of it to release them from their nightmare, and bring them back to life.", objectives = "Har'koa has asked you to use her whisker on the corpses of her children to free and resurrect them. Return to her at the Altar of Har'koa when you are done.", progress = "There are more of my offspring that you must free from their torment!", completion = "Thank you, <name>. I will never forget what you have done." }
WordHunterWoW_QuestEN[12633] = { title = "Darkness Calling", description = "Crafted of bone and dripping with blood, this choker is of intricate and deliberate design.\n\nGazing upon it overwhelms you with an ominous presence - one that compels you to wear it. You fight the urge, and resolve to bring it back to Ebon Watch.\n\nIf anyone can explain this, a death knight can....", objectives = "Take the Writhing Choker to Stefan in Ebon Watch.\n\nProvided item:", completion = "I am indeed familiar with items such as this.\n\n<Stefan looks you in the eye.>\n\nIt would seem, <name>, that you have been... chosen." }
WordHunterWoW_QuestEN[12634] = { title = "Some Make Lemonade, Some Make Liquor", description = "Life's tossed me a cartload of lemons this time! When the ship ran aground, the kegs carrying my best brew burst! All we have now are a few bottles of rum, and it won't sustain a thirsty expedition!\n\nWe need to get some booze cooking, and fast!!\n\nThe trees in the Wildgrowth Mangal, to the east, seem laden with fruit, but it's too high for me to reach. Look for good, strong vines, see if you can use it to shake some of that fruit out of the trees. Bring me whatever you can find.", objectives = "Bring 1 Orange, 2 Banana Bunches, and 1 Papaya to Grimbooze Thunderbrew at the Nesingwary Base Camp.", progress = "Did you have luck winning any of that fruit from those darn tall and stingy trees?", completion = "Well, that's a better assortment than I would've expected from this place. Now, for the important question: can we distill it into anything drinkable? We'd better get started." }
WordHunterWoW_QuestEN[12635] = { title = "Relics of the Snow Leopard Goddess", description = "I overheard that you are going to see to the well-being of Har'koa. Good luck to you.\n\nI am wondering if while you are in the vicinity of the altar, you would be willing to recover their relics? I do not require many, and it is only a short trip to the southeast.\n\nWhat do you say?", objectives = "Chronicler To'kini at Zim'Torga wants you to recover 10 Har'koan Relics.", progress = "The Drakkari are so busy destroying themselves, it would be a shame if the historical significance of their empire were to be likewise lost.", completion = "Aw, prime specimens!\n\nYou can see there the divergence from the root symbology. Quite extraordinary.\n\nWhat a pity that the ice trolls are determined to bring about their own demise.\n\nDid you know, for instance, that the Drakkari were exiled from the rest of the troll nations for their extremely violent ways?\n\nIt's true! How did you think trolls ended up in such a harsh climate as this?" }
WordHunterWoW_QuestEN[12636] = { title = "The Eye Of Acherus", description = "Behold, Acherus, the grand citadel of death! It has no equal in this world! Not even the mighty Naxxramas could withstand a direct assault from the Ebon Hold. Looming above the face of the necropolis is the all-seeing eye of Acherus. From it the master is able to see great distances into the territories held by our enemies. What the eye sees, the Lich King sees, and now the time has come for you to peer through the eye! The Lich King has called for you, {name}.\n\nGo now! Suffer well, brother...\n", objectives = "Report to the Lich King in Ebon Hold.", completion = "The time to spill the blood of our enemies approaches. You must first learn what it is that you seek to destroy, before rushing headlong into battle. It is what separates a <class> from a mindless ghoul.\n\nI will grant you sight beyond sight, my champion. You will use the eye of Acherus to steal our enemies' secrets." }
WordHunterWoW_QuestEN[12637] = { title = "Near Miss", description = "It was either wisdom or luck that prevented you from wearing this choker, {race}.\n\nEither way, your acquiring it was no random occurance. You've been targeted by someone, or something....\n\nTake your choker to Bloodrose, here. Let her demonstrate the fate that nearly befell you.", objectives = "Stefan at Ebon Watch wants you to take the Unliving Choker to Bloodrose Datura.", progress = "Yes, <race>?", completion = "Now you've observed the fate that was meant to befall you.\n\nAs I mentioned before, this was no coincidence. The creation of such a device is very involved, and the required resources would not be squandered on a random target.\n\nThe simple truth of the matter is this; You're wanted by the Scourge...." }
WordHunterWoW_QuestEN[12638] = { title = "Close Call", description = "It was either wisdom or luck that prevented you from wearing this choker, {race}.\n\nEither way, your acquiring it was no random occurence. You've been targeted by someone, or something....\n\nTake your choker to Bloodrose, here. Let her demonstrate the fate that nearly befell you.", objectives = "Stefan at Ebon Watch wants you to take the Writhing Choker to Bloodrose Datura.", progress = "Yes, <race>?", completion = "Now you've observed the fate that was meant to befall you.\n\nAs I mentioned before, this was no random act. The creation of such a device is very involved. You've somehow caught the attention of the Scourge leadership.\n\nThe question is not how, why, or even who... but what will we do about it?" }
WordHunterWoW_QuestEN[12639] = { title = "The Frozen Earth", description = "We captured these elementals from nearby, and I have plenty of defenders now. But, it takes a great deal of power to make them strong enough to stand up to our enemies.\n\nThe frozen earth at Drak'Mabwa to the northwest have what I need to maintain our defenses. I'll need more of their essence if I'm to keep this up.", objectives = "Element-Tamer Dagoda at Zim'Torga wants you to collect 7 Essence of the Frozen Earth.", progress = "I hope that you've returned with enough. The attacks from the Pools of Jin'Alai have become more desperate after what you did to them.", completion = "Thank you, <class>. Those essences should be enough to fuel my casting for quite some time." }
WordHunterWoW_QuestEN[12640] = { title = "Sealing the Rifts", description = "Dagoda gonna be sendin' you northwest to Drak'Mabwa to get her more stuff for her defenders if she didn't already.\n\nWhile you up there, Ahunae be wantin' you to destroy the rifts those elementals pourin' out of. The last thing we needin' is for them to attack us!\n\nJust watch out, more of those frozen earth'll show up when you try to seal the rifts.", objectives = "Scalper Ahunae at Zim'Torga has asked you to seal 7 Elemental Rifts.", completion = "Ahunae hopin' that Dagoda got all of the defenders she wantin'. With those rifts sealed, it's not likely she'll be gettin' any more." }
WordHunterWoW_QuestEN[12641] = { title = "Death Comes From On High", description = "Towering above this platform is the eye of Acherus. From it you will call forth a probe that you will then use to analyze Scarlet Crusade fortifications at New Avalon. The eye has a host of powers that should make the acquisition of this data simple.\n\nUse the eye's siphon to analyze the forge, town hall, hold, and chapel. The eye's control mechanisms are located on either side of this platform. Waste no more time, {name}.\n\nThe Scourge will have this place. The Lich King commands it!", objectives = "The Lich King commands you to use the Eye of Acherus to analyze the Scarlet Hold, New Avalon Forge, New Avalon Town Hall and the Chapel of the Crimson Flame.\n\nControl the Eye of Acherus by using the Eye of Acherus Control Mechanism.", progress = "Our assault upon the Scarlet Crusade will become legend.", completion = "They prepare for battle - as expected - but there is something else. I sense an old enemy. An enemy that I destroyed long ago...\n\nIt matters not. We will send the full might of the Scourge against them before they have a chance to evacuate their homes and put in place their defenses." }
WordHunterWoW_QuestEN[12642] = { title = "Spirit of Rhunok", description = "My feelings tell me that Rhunok doesn't have much time.\n\nI can tell that the arctic bear god's spirit has already separated from his weakened body. It is his spirit with which you must commune.\n\nHis altar lies to the northwest beyond Drak'Mabwa.", objectives = "Speak with the Spirit of Rhunok at the Altar of Rhunok.", completion = "I am barely hanging on. You must work quickly or all will be lost." }
WordHunterWoW_QuestEN[12643] = { title = "Silver Lining", description = "Once the Scourge have a target in their sights, they'll stop at nothing to acquire it.\n\nYou're doomed to a mindless existence as a walking corpse....\n\n<Stefan's face twists into a cruel grin.>\n\n... unless we can use their desires against them.\n\nI'll explain later. I have complex magic to prepare which requires certain material components.\n\nTravel due east of here to the land beneath the Reliquary of Agony. Slay the ghouls and abominations you'll find there and return to me with their remnants.", objectives = "Stefan in Ebon Watch asked you to go to the Reliquary of Agony to collect 5 Putrid Abomination Guts from the Putrid Abominations and 5 Gooey Ghoul Drools.", progress = "Have you brought the components I asked for, <name>?", completion = "<Stefan sifts through the foul components.>\n\nWell, it's far from perfect, but it'll have to do.\n\nNow brace yourself, <class>. This is where it gets good...." }
WordHunterWoW_QuestEN[12644] = { title = "Still At It", description = "Now that we've got the raw materials, I've had my assistant ready the still. He'll oversee the process, but I want you to help keep everything under control. You might be tempted to think that we just throw everything into the still and let it sit, but you're wrong.\n\nIngredients and heat need to be added at certain times, and the pressure regulated at others. You'll have no more than 10 seconds to react to a situation. Speak with \"Tipsy\" McManus when you're ready to start distilling.", objectives = "Successfully complete the distillation process and bring the completed Thunderbrew's Jungle Punch to Grimbooze Thunderbrew at the Nesingwary Base Camp.", progress = "Well, how did it turn out?", completion = "<Grimbooze gives the cask a shake.>\n\nThere's something in here, but the million gold question is, can you drink it? Don't you go anywhere; you'll be responsible for overseeing the sampling of the product, too." }
WordHunterWoW_QuestEN[12645] = { title = "The Taste Test", description = "And now for the moment of truth!\n\n<Grimbooze chuckles.>\n\nI've always wanted to say that. Normally, I'd debut a new drink at a banquet, but we can't have one in the middle of the jungle.\n\nInstead, just take samples to a few trusted friends and return with their comments. Let's see, we'll definitely want Hemet Nesingwary's opinion, and Hadrius Harlowe's, too. They're here in camp. You'll want to head over to Lakeside Landing, near the center of the Basin and offer Tamara Wobblesprocket a taste.", objectives = "Offer a sample of Thunderbrew's Jungle Punch to Hemet Nesingwary, Hadrius Harlowe, and Tamara Wobblesprocket, then return to Grimbooze Thunderbrew at the Nesingwary Base Camp.", completion = "Two out of three drinkers agree, eh? Not bad for a first try. Not bad at all. I suppose I'll have to whip up something else for Tamara by way of apology.\n\nNow... what should we call this creation?" }
WordHunterWoW_QuestEN[12646] = { title = "My Prophet, My Enemy", description = "My prophet absorbed too much of my power too quickly, and subsequently killed himself. You can see the results at the water-filled crater to the south in Drak'Mabwa.\n\nMy former priests have already resurrected him so that he can finish the job. They're channeling my power back into him, and it will not be long now before he reawakens.\n\nYou must put an end to him and return with my mojo before it is too late.", objectives = "The Spirit of Rhunok at the Altar of Rhunok has asked you to acquire his Arctic Bear God Mojo.", progress = "Quickly, <race>, do you have my mojo?", completion = "You did it.\n\nBut now there is one other thing that I need you to do." }
WordHunterWoW_QuestEN[12647] = { title = "An End to the Suffering", description = "My body is too far gone now, {name}. It is only a matter of time before a new prophet is elevated and finishes what the other began.\n\nI am going to imbue you with the last of my power. The tormentor inside the altar building carries incense, which will awaken my body and make it vulnerable.\n\nUse the incense and do me the kindness of putting an end to my suffering.\n\nI apologize if I fight back. Even for me, the will to survive is strong.", objectives = "The Spirit of Rhunok has asked you to use the Tormentor's Incense to awaken his body. You are then to slay Rhunok using the power that his spirit has imbued you with.\n\nIf for some reason you lose the Mojo of Rhunok aura, you can return to the Spirit of Rhunok to have it reapplied.", progress = "If you do not put an end to my suffering soon, <name>, all may be lost.", completion = "You've done what had to be done and honored me in the process.\n\nI give you my deepest thanks, <name>. I only hope that you and Har'koa will be able to help the others." }
WordHunterWoW_QuestEN[12648] = { title = "Dressing Down", description = "There... I've created a disguise that should make you indistinguishable from the Scourge.\n\nYou'll be free to walk among them as long as the disguise holds. Only the blightguards will be able to see through my illusion. Watch out for them!\n\nAnother thing you must know is that the disguise is unstable and may drop unexpectedly, so stay alert.\n\nLet's test it out. Use the choker and visit the Scourge merchant just east of here. Return to me with a bottle of bitter plasma.", objectives = "Stefan at Ebon Watch wants you to use the Ensorceled Choker to apply the Scourge disguise.\n\nWhile in Scourge form, you are to purchase Bitter Plasma from Gristlegut.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", progress = "Well, <name>?\n\nDid you purchase that flask?", completion = "So? How are you enjoying scourge life?\n\nBelieve me, it's not all it's cracked up to be...." }
WordHunterWoW_QuestEN[12649] = { title = "Suit Up!", description = "There... I've created a disguise that should make you indistinguishable from the Scourge.\n\nYou'll be free to walk among them as long as the disguise holds. Only the blightguards will be able to see through my illusion. Watch out for them!\n\nAnother thing you must know is that the disguise is unstable and may drop unexpectedly, so stay alert.\n\nLet's test it out. Use the choker and visit the Scourge vendor just east of here. Return to me with a bottle of bitter plasma.", objectives = "Stefan at Ebon Watch wants you to use the Ensorcelled Choker to apply the Scourge disguise.\n\nWhile in Scourge form, you are to purchase Bitter Plasma from Gristlegut.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", progress = "Well, <name>?\n\nDid you purchase that flask?", completion = "So? How are you enjoying Scourge life?\n\nBelieve me, it's not all it's cracked up to be...." }
WordHunterWoW_QuestEN[12650] = { title = "Plundering Their Own", description = "There is another altar nearby where there are artifacts to be saved.\n\nIt is said that the Drakkari at the Altar of Rhunok to the northwest, beyond the broken tundra of Drak'Mabwa, have already plundered their own holy site.\n\n{class}, I would be appreciative if you could rescue those artifacts from their undeserving hands.", objectives = "Chronicler To'kini at Zim'Torga wants you to recover 7 Rhunokian Artifacts.", progress = "There is no comprehending the Drakkari. They are brutal savages who have sunk to a new low.", completion = "Let me look at those.\n\n<The chronicler examines the artifacts that you have recovered.>\n\nHmph, I'd say that we're lucky you liberated these when you did, <class>.\n\nHow very interesting. This artifact here depicts the events of the Sundering. There was a time when Northrend was the far northern portion of Kalimdor.\n\nBut after the Sundering, the land broke off, eventually becoming Northrend.\n\nThis, of course, is why we see Drakkari in the southern continents as well as here." }
WordHunterWoW_QuestEN[12651] = { title = "Lakeside Landing", description = "When the trouble with the Venture Company started, I asked Marvin Wobblesprocket and his wife, Tamara, to take their flying machines east to River's Heart. I asked them to setup a small camp there so that we could use them as a relay to fly in supplies and survey the area.\n\nThey should have arrived by now and started setting up. River's Heart is near the center of the basin where the rivers converge. Search for Lakeshore Landing on the northeast shore. Marvin mentioned it would be the best spot.", objectives = "Speak with Tamara Wobblesprocket at Lakeside Landing.", completion = "So, Hemet sent you? We were just about to let him know that we've gotten things up and running here. Please forgive Marvin if he seems to be ignoring you, but he gets very absorbed in his work." }
WordHunterWoW_QuestEN[12652] = { title = "Feedin' Da Goolz", description = "Git o'er heer, gool! Yeh, I talkin' to yoo.\n\nIt feedin' time now. Gotta git da grub ta all da gools!\n\nSpeshal grub dis time! Bowels an' brainz bowl... num, num, num.\n\nJus drop da bowl nexta da gool. Gud way ta make frenz.\n\nYoo got goolfrenz? Ha, ha, hah!", objectives = "Gristlegut at the Reliquary of Agony wants you to use Bowels and Brains Bowl next to 10 Decaying Ghouls.", completion = "Num num!" }
WordHunterWoW_QuestEN[12653] = { title = "Back to Har'koa", description = "And now it is time for you to return to the leopard goddess. Somehow I sense that she has other plans for you.\n\nTell her that no matter what, we are eternal.", objectives = "Speak with Har'koa at the Altar of Har'koa.", completion = "<The cat goddess howls in pain.>\n\nMy spirit cries out in grief at the loss of another friend. But fear not, he will return and his spirit will live on forever." }
WordHunterWoW_QuestEN[12654] = { title = "The Part-time Hunter", description = "When Hemet asked me to accompany Marvin out here, I hoped that I might have the opportunity to work on my own hunting skills in between repairing the flying machines and setting up the camp.\n\nI wanted to take down a ferocious lion named Pitch. He's said to make his home south of here, near where the Wildgrowth Mangal meets the northern face of the Skyreach Pillar. If you can find the beast, would you bring back his remains? If the rumors are true, they'd make a trophy even Hemet will respect!", objectives = "Bring Pitch's Remains to Tamara Wobblesprocket at Lakeside Landing.", progress = "Did you find Pitch?", completion = "You got it! Now all I have to do is make a trophy out of it. That'll be the hard part -- finding a way to preserve it so that Hemet doesn't have a good laugh at my expense." }
WordHunterWoW_QuestEN[12655] = { title = "The Blessing of Zim'Rhuk", description = "There is another god of Zul'Drak that is being neglected.\n\nZim'Rhuk's statue lies directly to the north. Known as \"The Wise One\", Zim'Rhuk is also known to be very protective of his domain. He maintains guardians that deal harshly with anyone that does not have the wits to slip past them.\n\nAvoid the guardians and give the Drakkari offerings to Zim'Rhuk so that you will benefit from his blessing.", objectives = "Witch Doctor Khufu wants you to present 10 Drakkari Offerings to the statue of Zim'Rhuk.", progress = "<You sense that Zim'Rhuk does not trust you. He is attempting to call out to one of his guardians.>", completion = "<Zim'Rhuk acknowledges the offerings you intend to place before him, though he knows that you took them from the corpses of others.>\n\n<If you give the offerings to him, he reluctantly agrees to grant you his blessing.>" }
WordHunterWoW_QuestEN[12656] = { title = "Blessing of Zim'Rhuk", description = "", objectives = "<Zim'Rhuk is impressed and frustrated that once more you seem to have dodged his guardians. At least for now.>\n\n<Place the offerings before him and he will grant you his blessing again.>", progress = "<Zim'Rhuk is impressed and frustrated that once more you seem to have dodged his guardians. At least for now.>\n\n<Place the offerings before him and he will grant you his blessing again.>", completion = "<Zim'Rhuk forces an image into your mind of one of his guardians squishing you beneath its foot. Perhaps you should attempt to appease Zim'Rhuk with more offerings.>" }
WordHunterWoW_QuestEN[12657] = { title = "The Might Of The Scourge", description = "Listen well, death knight, for I give to you the words that will start a war. My final judgment has been passed: Death. To. All. None shall stand so boldly against the might of the Scourge without reprisal!\n\nAs you have served me well in your first task, so too shall you serve me in your next task. Take my judgment to Highlord Mograine at the command post of Acherus, found on the first floor. Tell him to begin the assault.\n\nAnd when the Crusade has been dealt with, we will finish off the Argent Dawn.\n", objectives = "The Lich King commands you to carry his orders to Highlord Darion Mograine at Ebon Hold.\n\nUse the glowing transporter behind The Lich King to reach Highlord Darion Mograine in the Hall of Command.", completion = "The horns of war will soon echo across this land, waking the dead and calling forth the Scourge war machine. Woe unto those that would stand in our way!\n\nYou and your brethren will lead the charge, <name>. When next I look upon the Scarlet lands, my sight will be obscured by the legions of Acherus. The march upon New Avalon begins now." }
WordHunterWoW_QuestEN[12658] = { title = "My Pet Roc", description = "Dorian's had me training and feeding the baby drakes he captures, and it has gotten me thinking. I want a pet of my own!\n\nNo, not a juvenile drake. I don't want a pet capable of biting my hand off!\n\nHowever, in the Bonefields to the northeast of the camp, beyond the area dominated by the drakes, there's a large population of goretalon rocs. The grown ones are beyond hope of domesticating, but if you bring me the eggs from their nests, I can raise them from the time they hatch.", objectives = "Bring 7 Roc Eggs to Zootfizzle at Dorian's Outpost.", progress = "Do you have those eggs?", completion = "Oh, these are very nice! I've gotten so tired of robotic squirrels and chickens for company. It'll be wonderful to have a pet whose joints won't require oiling!" }
WordHunterWoW_QuestEN[12659] = { title = "Scalps!", description = "I thinkin' it be time to do some scalpin', mon!\n\nThe trolls at Heb'Drakkar to the northeast should do nicely. With their fancy bats and attackin' us, they got it comin'!\n\nAhunae even give you his own knife so that you do the job right.", objectives = "Scalper Ahunae at Zim'Torga wants you to use Ahunae's Knife to scalp 10 Heb'Drakkar trolls.\n\nThe scalper reminds you that you should loot them first.", completion = "Aw, me thinkin' that too funny.\n\n<name> is my kind of <race>!\n\nYou still got my knife?" }
WordHunterWoW_QuestEN[12660] = { title = "Weapons of Destruction", description = "The Lich King's lackeys have dared to bring weapons of destruction into my domain.  I will not stand for this.\n\nGo to their outpost to the north and destroy the weapons they would use against the land.  We cannot let the Scourge taint another inch of these sacred lands.", objectives = "The Avatar of Freya wants you to go to the Death's Hand Encampment to the northwest and destroy 4 Unstable Explosives.", completion = "I thank you, <race>.  You're proving to be a worthy ally." }
WordHunterWoW_QuestEN[12661] = { title = "Infiltrating Voltarus", description = "By now you've probably guessed the details of my plan.\n\nWe're using the Scourge's interest in you against them. You're going undercover. I know it's likely a death sentence, but if we do nothing your death is a certainty.\n\nTravel northeast to Reliquary of Pain and stand on the platform while wearing your disguise. Once inside Voltarus, you must earn the trust of the Scourge commander.\n\nWhen you've completed your mission, blow this horn and I'll fly to your location to receive your report.", objectives = "Stefan wants you to use your Ensorcelled Choker to get into Voltarus and do whatever the Scourge leader there asks of you.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", completion = "Well, now... I must admit I'm more than a little surprised to see you, <name>.\n\nTell me what you've learned." }
WordHunterWoW_QuestEN[12662] = { title = "Bringing Down Heb'Jin", description = "<Dagoda looks at Ahunae and sighs.>\n\nYou want to really deal with Heb'Drakkar? Collecting scalps isn't going to get the job done. You have to take out their leader, Heb'Jin.\n\nThe problem is, he's up on the bat rookery goading his forces on.\n\nBang his drum and I guarantee that he'll fly down. That's when you kill him.\n\nYou can take this net we got from one of his headhunters. Use it to trap his bat when he lands. That way you won't have to fight both of them.\n", objectives = "Element-Tamer Dagoda at Zim'Torga wants you to kill Heb'Jin.", completion = "You did it!\n\n<Dagoda gives you a big kiss on the cheek.>\n\nYou have no idea how much of a relief that is to me! Defending against trolls on all sides is really putting a strain on us. Not to mention his incessant yelling.\n\nPlease, <name>, take your pick of what we have to offer." }
WordHunterWoW_QuestEN[12663] = { title = "Reunited", description = "{name}!\n\nYa musta received mah gift! Turn around, mon, lemme get a good look at ya... Ahh, ya make me proud.\n\nWe come such a long way, you and I, and now we be servin' da Lich King together.\n\nStick with me and big things be comin, mon. Big things... but first, we need to be gettin' ya caught up. So much been happenin' since I saw ya last.\n\nGo speak ta Gorebag for a tour of Zul'Drak. Listen for me and I'll tell ya all ya be needin' ta know. ", objectives = "Drakuru in Voltarus wants you to speak to Gorebag and take the tour of Zul'Drak.", completion = "So, now ya be seein' what we be up against, mon.\n\nGo down, take some time ta learn da land, prepare some strategy. \n\nI'll be havin' some tasks for ya soon." }
WordHunterWoW_QuestEN[12664] = { title = "Dark Horizon", description = "Ahh, another supplicant answerin' da Lich King's call.\n\n<Drakuru sniffs you.>\n\nFreshly scourged, eh? Ya still be reekin' of da living!\n\nLong be da line of dem who seek da Lich King's blessings. Ya must rise above da masses and prove yerself worthy of wieldin' true power.\n\nLookin' down over Zul'Drak, I sensed potential in ya. I ordered your - invitation.\n\nDa rest be up ta you....\n\nGo an' speak ta Gorebag for a tour of Zul'Drak. Dere be much ta do if you're to be of any worth to me.", objectives = "Drakuru in Voltarus wants you to speak to Gorebag and take the tour of Zul'Drak.", progress = "Have ya taken in da battlefield yet, mon?", completion = "So, now ya be seein' what we be up against, mon.\n\nI want ya ta go down, learn da land, mingle with yer bretheren. Prepare yourself...\n\nSoon, dere be much for ya to do. Don't ya be disappointin' me!" }
WordHunterWoW_QuestEN[12665] = { title = "I Sense a Disturbance", description = "There's something wrong with Quetz'lun, the wind serpent goddess. What it is exactly I cannot sense, but I do know that her altar has been overrun with powerful creatures.\n\nI'm going to send you there on the back of one of my children, which you saved. The two of you will move swiftly and with great stealth to uncover what has become of Quetz'lun.\n\nMy child will see you safely back to me. Just keep your eyes open.\n\nWhen you are ready, ask and I will call one of my kittens for you.", objectives = "Har'koa has asked you to determine what has happened to Quetz'lun. Speak to her to be able to ride one of her children stealthily into the Altar of Quetz'lun.\n\nReturn to her at the Altar of Har'koa once you have done so.", completion = "Thank you for bringing my kitten back safely.\n\nDeep down I knew it. I wanted to deny it, but your eyes have revealed the truth.\n\nNevertheless, I sense something else. All is not as it seems." }
WordHunterWoW_QuestEN[12666] = { title = "Preparations for the Underworld", description = "Quetz'lun may be dead, but I can still feel her spirit lingering in the underworld at the altar. We have to find a way to get you to her.\n\nLuckily for us, I just happen to have a supply of former supplicants at hand who are no longer in need of their sacred adornments. Both my subduers and claws are likely to still be wearing them.\n\nBring the adornments to me and I'll draw upon their energy to enable you to cross over into Quetz'lun's underworld nightmare.", objectives = "Har'koa wants you to collect 8 Sacred Adornments. Deliver them to her at the Altar of Har'koa.", progress = "I never imagined that it would come to this. The Drakkari are truly lost.", completion = "<The leopard goddess looks saddened at the collection of holy symbols that you have brought before her.>\n\nThere was a time when these meant something. Let's see if we can put them to better use." }
WordHunterWoW_QuestEN[12667] = { title = "Seek the Wind Serpent Goddess", description = "You are prepared, but I'm not certain that you're ready for what is to come.\n\nWhen you cross back over into Quetz'lun's altar area, you will enter the realm of the dead. From what I can feel of it, it's not going to be pleasant.\n\nTry not to be distracted by what you see in there. Simply head for the altar building and seek out Quetz'lun's Spirit.", objectives = "Seek Quetz'lun's Spirit at the Altar of Quetz'lun.", completion = "<race> worm. Tell me why I should not annihilate you where you stand?" }
WordHunterWoW_QuestEN[12668] = { title = "Foundation for Revenge", description = "I have something special planned for my favorite high priests. But first you get to prove yourself in laying the foundation for my revenge.\n\nYou do still want to live, yes?\n\nAs you have seen, my devotees are enjoying their stay here, but now it's time for them to make final restitution.\n\nDo me the smallest of favors if you would, {name}. Lure them near my soul fonts and then put an end to their existences.\n\nThey taste so delicious, and their sacrifice will not go in vain, I can assure you.", objectives = "Quetz'lun's Spirit has tasked you with the destruction of 12 trolls, either Quetz'lun Worshippers or Serpent-Touched Berserkers, near her Soul Fonts.\n\nOnly after you have accomplished this should you return to her at the Altar of Quetz'lun.", progress = "Why do you return when your task is not yet complete? Do you not realize that I can destroy you with but a thought?\n\nGo now, little <race>. Complete that which I commanded of you!", completion = "Exquisite. Perhaps you will be of some use after all." }
WordHunterWoW_QuestEN[12669] = { title = "So Far, So Bad", description = "Everything you've reported is consistent with what we know. Learning of Drakuru and earning his trust will lay the groundwork for your future missions.\n\nReturn to him and do as he says. Do whatever you must to appear sincere, {name}. A great deal is riding upon your performance.\n\nThis time I'm adding an additional assignment: While you're in the field, pour this additive into their blight cauldrons. It should neutralize the scourging agent and render the batch useless.", objectives = "Stefan at Ebon Watch wants you to return to Drakuru and complete any tasks he has for you.\n\nWhile at the Reliquary of Pain, you are to use the Diluting Additive on 5 Blight Cauldrons.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", completion = "Nice work, <name>!\n\nDiluting those cauldrons will not only save lives, it will slow the growth of the Scourge in this region.\n\nNow come, tell me what you've learned of Drakuru's strategy in Zul'Drak." }
WordHunterWoW_QuestEN[12670] = { title = "The Scarlet Harvest", description = "Below Acherus stands Death's Breach, the staging point for our assault upon the Scarlet Crusade. You are to ride one of my Scourge gryphons, located on either side of this platform, and report to Prince Valanar. Do as he says and you may live to see these lands fall before us.", objectives = "Report to Prince Valanar at Death's Breach.", completion = "Do you smell it?\n\n<Valanar sniffs at the air.>\n\nFresh meat... The scent of Scarlet Crusader wafts through the air.\n\n<Valanar salivates.>\n\nApologies, <class>, I'm sure you're not interested in my choice of fine cuisine. You are here to work! To lead the charge! Yes... I know. The Lich King has told me all that I need to know about you, <name>.\n\nThe time for bloodshed is now." }
WordHunterWoW_QuestEN[12671] = { title = "Reconnaissance Flight", description = "It's about time we had planes up and running in this place.  The professor's been asking me to check out a strange weather pattern coming from the northeast.\n\nThing is, I'm going to need a co-pilot if we're going into uncharted territory.  No way in hell I'm heading out there alone.\n\nWhat do you say, tough-guy?  You might learn a thing or two.  And once you learn to deal with the northern winds... you can pretty much fly anywhere.", objectives = "Help Pilot Vic complete the Reconnaissance Flight.", completion = "You saved my life up there, buddy.  Nice flying!" }
WordHunterWoW_QuestEN[12672] = { title = "Setting the Stage", description = "I will give you a chance at continued existence.\n\nThere are fragments of the power that fueled my curse scattered about the altar grounds. It is my desire that you collect some of them for me. Not so many that the curse will be lifted, but enough that I will be able to eventually make use of them to exact revenge upon my prophet.\n\nGo, insect. Run and do my bidding before I change my mind about letting you live.", objectives = "Quetz'lun's Spirit has demanded that you collect 10 Underworld Power Fragments. Return to her at the Altar of Quetz'lun only when you have done so.", progress = "What a shame that Har'koa didn't send you along sooner. Then again, she and I never did get along.\n\nShe probably held back your help just long enough for this to happen.", completion = "They'll do. Likely I won't even need them.\n\nBut it was fun watching you run around at my command." }
WordHunterWoW_QuestEN[12673] = { title = "It Rolls Downhill", description = "If ya ever gonna be worthy of da Lich King's gifts, ya must learn ta be a great leader - one who be commandin' respect!\n\nI got a task dat gonna refine your command skills, mon....\n\nSumma my minions be trained ta harvest blight crystals from da land below, but dey be lazy and slow. You gonna be in charge o' dem, mon.\n\nTake dis scepter and teach 'em how to get da job done. When dey be under your control, make 'em harvest dem crystals!", objectives = "Overlord Drakuru in Voltarus wants you to use the Scepter of Suggestion on the Blight Geists and then order them to harvest 7 Blight Crystals.", progress = "Ya got my underlings whipped into shape, <name>?", completion = "Da crystals be pilin' up like never before!\n\nYou keep up da good work, <name>. I got more tasks for ya real soon." }
WordHunterWoW_QuestEN[12674] = { title = "Hell Hath a Fury", description = "It is now time for you to punish my three high priests: Mu'funu, Tua-Tua, and Hawinni. You'll find them spread around the altar grounds.\n\nTake this hexxing stick. I've empowered it with my rage and indignation. I'm sure that it will prove potent.\n\nJust use it and proceed to destroy them. The hex will take care of the rest.\n\n<Quetz'lun displays a toothy grin.>\n\nSucceed and I may let you go. Fail and die.", objectives = "Quetz'lun's Spirit at the Altar of Quetz'lun wants you to use Quetz'lun's Hexxing Stick upon High Priest Mu'funu, High Priestess Tua-Tua, and High Priest Hawinni. Once you have done this, slay them.", progress = "DO YOU THINK THAT I'M A FOOL?\n\nTHEY'RE NOT DEAD!", completion = "<The terrible spirit before you lets loose a blood-chilling cackle.>\n\nThey had it coming. And I'll give them more of the same again and again and again...." }
WordHunterWoW_QuestEN[12675] = { title = "One Last Thing", description = "There is one last thing that is needed to enact the final revenge against my prophet. The power fragments you collected must be imbued with a portion of a living gods' spirit. You're going to need to beseech Har'koa for some of hers.\n\nOnce you've done that, when you return here, you will not come to the underworld. Instead, you will return to the physical world of my altar. My children and guardians will no longer attack you, and you'll be able to get to my prophet without having to worry about them.", objectives = "Deliver the Underworld Power Fragments to Har'koa and beseech her for a portion of her spirit. You will still find her at the Altar of Har'koa.", progress = "You've returned, <name>.", completion = "A portion of my spirit?\n\n<The snow leopard goddess pauses a moment to consider.>\n\nThat's quite an expensive gift considering that this is for revenge and I'm already greatly weakened by the actions of my subduers.\n\nStill, I may know a way." }
WordHunterWoW_QuestEN[12676] = { title = "Sabotage", description = "While we're working to discover the purpose of these crystals, we need you back in Voltarus doing Drakuru's bidding.\n\nEvery task you perform successfully gets you closer to him, and brings us that much nearer to knowing his mind.\n\nWhile you're there, I have another mission for you. Drakuru's Scourgewagons pose a significant threat. We need them destroyed. \n\nMake your way to the wagons and activate these charges. Once they're set, get clear! The explosion will expose you if you're too close.", objectives = "Stefan at Ebon Watch wants you to perform another task for Drakuru.\n\nAdditionally, you are to use the Explosive Charges on 5 Scourgewagons at the  Reliquary of Pain.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", completion = "Excellent!\n\nYour undercover work has truly paid off, <name>.\n\nNow let's have a look at that scepter...." }
WordHunterWoW_QuestEN[12677] = { title = "Hazardous Materials", description = "Blight crystals?! What could this scumbag Drakuru be up to? Clearly, he's working on something significant.\n\nContinue to do his bidding and perhaps once he's more familiar with you he'll reveal his plans. In the meantime, we need to have a look at these crystals.\n\nWhile you're in Voltarus, try to get some samples of the harvested crystals when no one's looking.\n\nBe alert! Handling those crystals can trigger your disguise to fail.", objectives = "Stefan at Ebon Watch wants you to go to Voltarus and complete any tasks Drakuru has for you. While there, you are to steal 5 Harvested Blight Crystals.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", progress = "Welcome back, <name>.\n\nWere you able to steal any samples of Drakuru's crystals?", completion = "Fascinating!\n\nWe'll look into the properties of these crystals right away.\n\nNow tell me, <name>, what is the latest with this Drakuru fellow?" }
WordHunterWoW_QuestEN[12678] = { title = "If Chaos Drives, Let Suffering Hold The Reins", description = "They make their stand now, outside of Death's Breach, futilely attempting to push us back in hopes of saving their horses, mines, lumber and citizens.\n\nThis will be your first lesson in Scourge warfare: TERROR!\n\nGo to the front lines, south of here, and destroy Scarlet Crusaders. Leave their corpses so that we may utilize them for the death march.\n\nBut most importantly: kill the fleeing villagers. Soldiers dying are an affordance, but villagers? That is what strikes fear into the hearts of man.", objectives = "Prince Valanar at Death's Breach commands you to slay 10 Scarlet Crusaders or Scarlet Peasants and 10 Citizens of Havenshire.", completion = "Do you feel it, <name>? That sensation is raw power coursing through your body. Such a thing cannot exist for mortals.\n\nThe front lines are now dismantled. The geist will finish the job and prepare the grounds for Razuvious. We turn our attention now to more tactical targets." }
WordHunterWoW_QuestEN[12679] = { title = "Tonight We Dine In Havenshire", description = "The Sky Darkeners are mindless constructs with one purpose: KILL! Specifically, they are aiming to kill any man or woman that they see fleeing Havenshire for the safety of New Avalon. We certainly can't allow those cowards to make it to safety and then take up arms against us!\n\nThere is one slight problem. They use saronite arrows for maximum range and damage. Saronite, however, is a metal only found in Northrend, so supplies are limited! Retrieve those arrows for me and I will reward you handsomely.", objectives = "Orithos the Sky Darkener at Death's Breach wants you to recover 15 Saronite Arrows.", progress = "The trajectories they are firing at would have most of the arrows land at or near the Havenshire Farm, south of us.", completion = "Well done, <class>! You feed the Scourge war machine with your deeds!\n\nAh yes, your reward - as promised." }
WordHunterWoW_QuestEN[12680] = { title = "Grand Theft Palomino", description = "How fortuitous it is that the Crusade has a stable full of horses a mere stone's throw from this post. Though they guard it tenaciously, an enterprising young death knight could break through their defenses and take what is rightfully his!\n\nOnce you acquire a horse from the Havenshire Stables, return it to me and I will see what can be done about transforming it into a proper deathcharger.\n\nRemember, {name}, it's only stealing if you're caught. Watch out for that deranged stable master, Kitrik!", objectives = "Salanar the Horseman asks that you steal a horse from the Havenshire Stables and return it to him at Death's Breach.", progress = "You don't want to walk forever, do you?", completion = "Now for the true test. Can you show mastery over an unbound charger and brutally overtake the thing that you desire most?" }
WordHunterWoW_QuestEN[12681] = { title = "Reagent Agent", description = "That Archmage Pentarus, back in Dalaran, will be expecting us to return with all kinds of reagents and talismans. It seems the locals are fond of animal parts. Twisted claws from the goretalon rocs are among their favorite.\n\nIt's not my place to say whether the rumors are true or not, but I've a feeling there's something here.\n\nThe rocs live in the Bonefields off to the northeast, where they feed on the corpses of old mammoths. Will you help me gather talons for the archmage's research?", objectives = "Bring 5 Twisted Roc Claws to Colvin Norrington at Dorian's Outpost.", progress = "Were you able to find any of the twisted talons?", completion = "<Colvin looks admiringly at the talons you've brought back.>\n\nThese will more than suffice. The gorlocs have a saying that the more gnarled the talon, the more power it holds. I'm sure the archmage will get his money's worth from this expedition." }
WordHunterWoW_QuestEN[12682] = { title = "Uncharted Territory (DEPRECATED)", description = "Not all of us in this expedition are here to hunt the biggest and rarest game.  Some of us actually have serious work to do.\n\nThe mere existence of this place boggles the mind -- a tropical paradise in the middle of Northrend.  I wouldn't be a scholar worthy of the name if I didn't put some effort into trying to understand this place.\n\nTake theseYou will receive:\n\nUpon completion of this quest you will gain:", objectives = "Not all of us in this expedition are here to hunt the biggest and rarest game. Some of us actually have serious work to do.\n\nThe mere existence of this place boggles the mind -- a tropical paradise in the middle of Northrend. I wouldn't be a scholar worthy of the name if I didn't put some effort into trying to understand this place.\n\nTake theseYou will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[12683] = { title = "Burning to Help", description = "There's no more caustic material in all of the basin than bittertide hydra sputum. I've got special containers to collect just such a thing for Archmage Pentarus' studies. Now all I need is a brave, um... collector.\n\nYou look like a hardy, adventurous {class}. How'd you like to make a bit of money and aid Dalaran's cause at the same time?\n\nAll you need to do is take this container with you to Bittertide Lake, to the southwest. Engage the hydra and use the container to sample the sputum they shower you with.", objectives = "Colvin Norrington at Dorian's Outpost wants you to take 5 Hydra Sputum Samples and kill 5 Bittertide Hydra.", progress = "Did you get those samples?", completion = "Wonderful! Here's your payment, as agreed. And, uh, a bit of advice: you might want to enjoy long, hot baths the next few days if that 'burning sensation' persists." }
WordHunterWoW_QuestEN[12684] = { title = "Blood of a Dead God", description = "Mam'toth, the god of the mammoths, destroyed himself, and took much of his temple with him, rather than allowing his trolls to gain his power.\n\nIf I'm to sacrifice a portion of my spirit, I will need something with which to bolster myself.\n\nMam'toth left behind an enormous crater to the northeast, just north of the Altar of Quetz'lun. Within the crater his blood yet lives.\n\nBring it to me.", objectives = "Har'koa has asked you to collect 7 Blood of Mam'toth. Return them to her at the Altar of Har'koa.", progress = "I wish that there were something that we could do to bring Mam'toth back to life, but there isn't.\n\nWe can honor him and his sacrifice by continuing the fight against the Drakkari.", completion = "Very well. Let us see if this works...." }
WordHunterWoW_QuestEN[12685] = { title = "You Reap What You Sow", description = "This is what it has come down to... revenge.\n\n<Har'koa sighs.>\n\nTake this ritual kit and enact it near Quetz'lun's corpse upon her altar. If everything works properly, her spirit should be drawn into the material world where she will be able to reclaim her power from the prophet.\n\nThe rest will be up to you, {name}. You must slay the prophet in his drained state.", objectives = "Slay the Drained Prophet of Quetz'lun and then inform Witch Doctor Khufu at Zim'Torga.", completion = "<The witch doctor shakes his head in disbelief.>\n\nIt sounds like you barely escaped Quetz'lun's underworld alive.\n\nI'm glad that it's you out there. I don't know if I would have had the courage to deal with that situation!" }
WordHunterWoW_QuestEN[12686] = { title = "Zero Tolerance", description = "Ignorance! Dis be intolerable, mon! My entire batch of blight be useless!\n\nDat mongrel, Darmuk! He be responsible for watchin over da blight. He failed me, mon!\n\nDis be a good lesson for ya, {name}. Failure be like a disease dat spreads. Ya gotta catch it and kill it early, before it be killin' you!\n\nTake dis scepter. It make my scourged trolls stronger. Use dem ta kill Darmuk. He be lurkin' down below just to da south.\n\nLet dat be an example to all, mon. Don't be failin' Drakuru!", objectives = "Drakuru in Voltarus wants you to go to the Reliquary of Pain and use the Scepter of Empowerment on a Servant of Drakuru. You are then to use its abilities to defeat Darmuk.", progress = "Has Darmuk paid for his failure, <name>?", completion = "Ya done good, <name>. You be learnin' faster than I had hoped.\n\nGo now, get ya some rest. Soon I be givin' ya an even greater test!" }
WordHunterWoW_QuestEN[12687] = { title = "Into the Realm of Shadows", description = "The horse you stole has been taken to the Realm of Shadows. It is there that my dark rider will slay the beast and raise it as a deathcharger. Do you think yourself brave enough to enter the Realm of Shadows in pursuit of the deathcharger?\n\nIf you accept, I will transport you to the shadow world. Once there, seek out a dark rider in the open fields south of us. To emerge victorious you must slay him, overtake his deathcharger and return it to Death's Breach. Issue the Horseman's Call should you succeed.", objectives = "Salanar the Horseman at Death's Breach has challenged you to slay the Dark Rider of Acherus and take his Acherus Deathcharger.\n\nShould you succeed, return the Acherus Deathcharger to Death's Breach and use the Horseman's Call to summon Salanar.", progress = "You must take the deathcharger by force, <class>!", completion = "You have succeeded where most initiates fail, <name>. For that you will be rewarded handsomely." }
WordHunterWoW_QuestEN[12688] = { title = "Engineering a Disaster", description = "These goblin goons and their minions have decided that they own this pillar and its crystals. I came here to explore the crystals and take samples, but they overpowered me and won't let me return to the camp.\n\nIf you'll help me fight our way out of here, we can teach these thugs a lesson they'll never forget!", objectives = "Help Engineer Helice escape from Swindlegrin's Dig, then speak with Hemet Nesingwary at the Nesingwary Base Camp.", completion = "Thank you for freeing Helice and seeing to her safe return. We all started to get worried when she didn't return from her crystal hunting trip." }
WordHunterWoW_QuestEN[12689] = { title = "Hand of the Oracles", description = "", objectives = "Hi! Really glad see you again!\n\nI knew we friends. I knew it! You good friend. Not just for us, but for all Oracles. Thank you for saving us! Thank you, thank you!\n\nI saw you bonk that puppy-man good! Undead thing said he your friend before? I not know that. You done with puppy-men though, yeah? Just Oracle friend now?\n\nStop! No agree without thinking - you sure you not want to be friends with puppy-men anymore?" }
WordHunterWoW_QuestEN[12690] = { title = "Fuel for the Fire", description = "It be time we start our march to Gundrak, mon. It be time for me ta turn ya loose on dem trolls!\n\nDey breached our wall and put a whole army just north of us.\n\nHahaha!\n\nDey be fuel for da fire, mon! We gunna take da chieftiains an' kill da rest! It all be part of my master plan....\n\nYou take dis scepter and go command my abominations. Bring 'em to da Drakkari army and kill em all! When da chieftains come, my pet Shalewing gunna snatch 'em up and bring 'em here to me.", objectives = "Drakuru in Voltarus wants you to use the Scepter of Command on Bloated Abominations and then use their abilities at the Frigid Breach to kill 60 Drakkari Skullcrushers and lure out 3 Drakkari Chieftains.\n\nChieftains will appear when enough Skullcrushers have been slain.", progress = "Did ya smash da trolls, <name>?", completion = "We done it, mon!\n\nI got da chieftains all caged up and you led my abominations to victory over their armies.\n\nIt be time ta celebrate, mon!" }
WordHunterWoW_QuestEN[12691] = { title = "A Timeworn Coffer", description = "The stone coffer appears to be locked.  It appears that a key fits inside a large stone keyhole.\n\nPerhaps one of the guardians in the vicinity has this key in its possession.", objectives = "Obtain a Huge Stone Key from the nearby Sholazar Guardians and bring it to the Timeworn Coffer at the Maker's Overlook.", progress = "The stone coffer does not budge.", completion = "The huge stone key turns with a deep grunt as the coffer lid opens up to reveal hidden treasure inside." }
WordHunterWoW_QuestEN[12692] = { title = "Return of the Lich Hunter", description = "Okay, I going back to Frenzyheart Hill to make sure all Frenzyheart know what you done for wolvar and for Zepik. You great hunter and they dumb to think you not.\n\nGo back to hill and talk to Elder Harkek... I make sure he knows you not traitor before any other Frenzyheart.\n\nThank you, Lich Hunter.", objectives = "Return to Frenzyheart Hill and speak to Elder Harkek.", completion = "It good to see you again. I knew you not a traitor, I glad Zepik prove me right.\n\nI hear you Lich Hunter now - that pretty good! You make Harkek proud." }
WordHunterWoW_QuestEN[12693] = { title = "Wolvar Faction Choice Tracker", description = "", objectives = "" }
WordHunterWoW_QuestEN[12694] = { title = "Oracle Faction Choice Tracker", description = "", objectives = "" }
WordHunterWoW_QuestEN[12695] = { title = "Return of the Friendly Dryskin", description = "Yay! Soo-say probably worrying about us! Maybe you go back to town and tell him everything okay? Yeah, go tell Soo-say.\n\nI going grab shiny ball thing from dead lich guy - I meet you there! Go go! I meet you there!", objectives = "Return to Rainspeaker Canopy and speak to High-Oracle Soo-say.", completion = "Good to see you again! We worried when you not come back right away.\n\nJaloot beat you back - lot of energy in Jaloot, he pretty fast. He told me how you save him from lich thing. Moodle told me how you save mosswalkers too. You really nice.\n\nI hope you stay with us for while. Always something need doing." }
WordHunterWoW_QuestEN[12696] = { title = "Aerial Surveillance", description = "You did a good job helping Wes with getting that flying machine back up and running.\n\nIf you'd like to help us further, there is an unusual weather pattern coming in from the northeast.  I have a pilot ready to work for me, but I'm afraid he needs a copilot.\n\nIf you think you're up to it, you can take the flight to Lakeside Landing.  Tell Vic I sent you.", objectives = "Professor Calvert wants you to take the flight to Lakeside Landing and speak with Pilot Vic there.", completion = "The professor sent you my way?  All right." }
WordHunterWoW_QuestEN[12697] = { title = "Gothik the Harvester", description = "CHAOS, {name}! The Crusade is in a frenzy. They have diverted all forces outside of New Avalon to set up a blockade at Light's Point, east of here. They are desperately trying to strip the Havenshire Mine of all resources and load the cargo aboard the frigates they have docked on the coast.\n\nLet's stir things up a bit, shall we? Gothik the Harvester, grand necromancer of the Lich King, has graced us with his presence. He has a gift he'd like to bestow upon the Scarlet Crusade. Seek him out.", objectives = "Speak with Gothik the Harvester at Death's Breach.", completion = "You have fought hard to invade the realm of the harvester... Wait.\n\n<Gothik looks at his notes.>\n\nMy apologies, <race>. Old habits die hard.\n\nValanar sent you, then? I trust you are somewhat competent.\n\nI do have a gift for the Scarlet dogs. One that is sure to speed up their work in the mines." }
WordHunterWoW_QuestEN[12698] = { title = "The Gift That Keeps On Giving", description = "I have come from the frozen heart of Naxxramas to feast on souls and deliver a vicious thrashing upon our sworn enemies - and I'm all out of souls.\n\nThis device I am about to give to you is a portable plague spreader. Take it east, to the Havenshire Mines, and unleash it near the Scarlet miners working inside. Use it to turn the miners into ghouls and return to me when you have a small army at your side. I have saved a special place for them in the vacuum cleaner of souls!", objectives = "Gothik the Harvester at Death's Breach has given you the Gift of the Harvester to use on Scarlet Miners. Create 5 Scarlet Ghouls with the device and return the ghouls to Gothik.", progress = "One small note: miners don't always become ghouls. Sometimes they turn into enraged spirits, hell-bent on killing you.", completion = "They now know that the mines are no longer safe. They will double their efforts in retreating, leaving their backs open to us!" }
WordHunterWoW_QuestEN[12699] = { title = "An Embarrassing Incident", description = "There's one little problem we have to solve before we head out.  You see, I can't seem to find the keys to my flying machine.\n\nI've looked pretty much everywhere for them... maybe you can give me a hand.  Only place I haven't looked yet is inside the lake.\n\nI'll even give you my very own air tank.  It's almost empty, but it's got a couple of hits left.", objectives = "Look for Vic's Keys inside the lake at River's Heart.", progress = "You find anything yet, <name>?", completion = "Excellent!" }
WordHunterWoW_QuestEN[12700] = { title = "An Attack Of Opportunity", description = "Only the Scarlet forces at New Avalon and Light's Point challenge us! The time to attack the Scarlet fleet at Light's Point has come.\n\nThe diversion at the mine has caused chaos amidst their ranks. They are frantically working to clear the area and return to their ships.\n\nThe time is ripe! Prince Valanar is seizing this opportunity to finish off the Scarlet fleet. Report to him at once!", objectives = "Speak with Prince Valanar at Death's Breach.", completion = "You have served us well, <class>. Few of your brethren have survived our initial attack upon the Scarlet interlopers. You remain as one of the strongest.\n\n\n\nEast of us, past the Havenshire Mine, is the coast - called Light's Point by the Scarlet Crusade. A thousand soldiers stand between us and their ships. Insurmountable? Hardly the point..." }
WordHunterWoW_QuestEN[12701] = { title = "Massacre At Light's Point", description = "In their haste the Crusade will make one fatal error: forgetting to check the mine cars.\n\nYou are to return to Havenshire Mine, east of here, and locate the mine car that my minions have planted near the outhouse. Climb inside the mine car and a Scarlet miner will unwittingly see to it that you are placed safely behind enemy lines.\n\nOnce aboard one of their ships, use the cannons against them! SLAUGHTER THEM ALL!\n\nCall the Scourge gryphon from the cannon when you are ready to return.", objectives = "Prince Valanar at Death's Breach has commanded you to slaughter 100 Scarlet Defenders.", progress = "Death knights know no fear!", completion = "The entire Scarlet fleet wiped out in a matter of minutes! I will receive a commendation from the Lich King for this! All that remains of the Scarlet Crusade now are the denizens of New Avalon.\n\nI'll set the fire starters and necromancers upon Havenshire immediately. You will carry my report to the Highlord!" }
WordHunterWoW_QuestEN[12702] = { title = "Chicken Party!", description = "I bet you not guess what happen again.\n\nNope, not Goregek or chickens.\n\nOkay, I lie. Goregek let chickens out again. Dumb Goregek and rumbly belly.\n\nLet me know if you need help from any of the hunters... they around here somewhere.", objectives = "Capture 12 Chicken Escapees for Elder Harkek at Frenzyheart Hill.", progress = "Chickens not get far usually... if wasps not eat them, maybe we just let them stay on field next time.", completion = "You good at this.\n\nMaybe someday we just dump Goregek in river so you not have to do this no more." }
WordHunterWoW_QuestEN[12703] = { title = "Kartak's Rampage", description = "You the great Lich Hunter, eh? Good to have such strong Frenzyheart ally for battle. Maybe you strong enough to call Kartak even.\n\nBig battle at Kartak's Hold to southwest.  Go kill spark big-tongues until you get good bit of Oracle Blood. Bring blood to altar in Kartak's Hold to call Kartak for delicious feast of big-tongue.\n\nKartak take your body if you worthy... with Kartak's powers, you slaughter more big-tongues than even best dreams.\n\nGo kill lots, hunter!", objectives = "Bring a pure sample of Oracle Blood to the Altar of Kartak to summon Kartak. With the aid of Kartak's shared powers, slaughter 50 of the nearby Sparktouched Gorlocs for Shaman Jakjek in Kartak's Hold.", completion = "Ritual went so easy for you!\n\nYou come back later for more killing someday, okay?" }
WordHunterWoW_QuestEN[12704] = { title = "Appeasing the Great Rain Stone", description = "Since mosswalker been attacked I worried maybe we not good to Great Rain Stone... we maybe too greedy. We need more treasures to offer!\n\nYou good at finding shinies last time... maybe you go look more around village for shinies? You maybe need one of good Rainspeakers for help. Just tell us who.", objectives = "High-Oracle Soo-say in Rainspeaker Canopy wants you to take a companion to dig up and collect 6 Shiny Treasures.\n\nBe sure to speak to High-Oracle Soo-say in Rainspeaker Canopy about securing the aid of one of your previous companions.", progress = "Never enough shinies... Great Rain Stone good to us, we need be good to Great Rain Stone.", completion = "So many good shinies! You good at this.\n\nCome back for more again later, yes?" }
WordHunterWoW_QuestEN[12705] = { title = "Will of the Titans", description = "Puppy-men been attacking Sparktouched... we need fight or they just attack other Oracles too.\n\nYou been good friend to us, so maybe we allow you special honor. Great Ones left protector long time ago for shrines... it here still, but it not know something wrong til shrines messed with.\n\nPuppy-men down there have bad crystals for making trouble... bring a bad crystal to Lightning Shrine so Soo-holu know to help.\n\nDon't be scared if Soo-holu take your body... he very powerful, so he keep you safe.", objectives = "Obtain a Tainted Crystal from the wolvar near Sparktouched Haven and bring it to the Great Lightning Stone to call Soo-holu. With the aid of Soo-holu's shared powers, kill 50 of the nearby Frenzyheart wolvar, then return to Lightningcaller Soo-met near the Great Lightning Stone.", progress = "Thank you for help dryskin. You very good to us.", completion = "Soo-holu strong, huh? I very glad he accept you to share his body for fight.\n\nHe more trusting of people he met before, so maybe come back another time to help more, yes?" }
WordHunterWoW_QuestEN[12706] = { title = "Victory At Death's Breach!", description = "<Prince Valanar hands you a sealed scroll.>\n\nThis is the full report of our victory at Death's Breach. You are to deliver this to Highlord Mograine - inside Acherus. I have made sure to include your heroics in the report. Mograine will undoubtedly reward you greatly for this victory, {name}.\n\nGo now!", objectives = "Deliver Prince Valanar's Report to Highlord Darion Mograine in Acherus: The Ebon Hold.", progress = "I was certain you wouldn't make it back here in one piece, <class>. Perhaps there is more to you than I first surmised.", completion = "<Highlord Mograine reads over the report.>\n\nThe ENTIRE Scarlet fleet?\n\n<Highlord Mograine nods.>\n\nSuch power, <name>... I have not seen such a display of domination in years... Since my father wielded...\n\n\n\nIt's not important...\n\nYes, your commendation, lest I forget." }
WordHunterWoW_QuestEN[12707] = { title = "Wooly Justice", description = "Ahunae hear about your trip to Mam'toth Crater, mon. The children of Mam'toth are enraged and cry out for justice!\n\nFollow the avenue northeast up the steps to the next tier of Zul'Drak. On your right you will find what's left of the Altar of Mam'toth.\n\nWhen you get there, flash this Medallion of Mam'toth in front of the eyes of one of the enraged mammoths. It'll calm down for a little while, letting you hop on its back.\n\nRide it around, trampling all of the Mam'toth disciples that you can find!", objectives = "Scalper Ahunae at Zim'Torga wants you to use the Medallion of Mam'toth to calm and ride an Enraged Mammoth. You are then to trample 12 Mam'toth Disciples to death.", completion = "Score one for the victims, mon!" }
WordHunterWoW_QuestEN[12708] = { title = "Enchanted Tiki Warriors", description = "I know that you're headed up to the Zol'Maz Stronghold to the northeast, {class}. While you're there, I need you to deal with the warlord's special guardians.\n\nThe enchanted tiki warriors, as they're called, represent a very real threat. If the Drakkari were to mass produce them, we'd quickly be overrun.\n\nLet's you and I demonstrate that they're not worth the effort to create, shall we?", objectives = "Element-Tamer Dagoda at Zim'Torga has asked you to destroy 12 Enchanted Tiki Warriors.", completion = "That should make them think twice about making more of those things. I shudder to think what it would be like to have to fight an army of those things.\n\n<The element-tamer is thoughtful for a moment.>\n\nI guess it would be just like fighting the endless waves of the Scourge." }
WordHunterWoW_QuestEN[12709] = { title = "Hexed Caches", description = "Pardon me, {name}. I'm given to understand that you might be heading northeast up to the Zol'Maz Stronghold. Such a trip presents a great opportunity for us to conclude our Drakkari goods gathering.\n\nAs I have come to know, the Drakkari warlord is extremely paranoid. He's had all of his caches at the stronghold hexed with dire magic. Rumor has it that his tiki warriors carry the cure, but who can say?\n\nIf you could find the time to acquire some of those goods, I would be most appreciative.", objectives = "Chronicler To'kini at Zim'Torga has asked you to acquire 12 Zol'Maz Stronghold Caches.", progress = "Perhaps you carry the caches within your pack even as we speak?", completion = "Just look at all of that!\n\nSee here, <name>. This piece you recovered vividly illustrates that the Drakkari became aware of the weakening of the land that the Scourge caused by their presence.\n\nThe warlord felt compelled to take the opportunity this presented. He pushed the prophets to kill their gods in an effort to control the power and fight back against the Lich King's forces.\n\nEither way they were doomed. They inadvertently chose to be the instrument of their own destruction!" }
WordHunterWoW_QuestEN[12710] = { title = "Disclosure", description = "Ya doin' well, {name}.\n\nYou be provin' dat I got an eye for talent! Now ya see why da Lich King gave me his blessing....\n\nDa time has come for me to reveal my master plan to ya, mon.\n\nNow you be seein' how we gunna sweep through da swarms of Drakkari trolls to take our rightful place in da great palace of Gundrak.\n\nTake dis scepter, mon. It be a token of my trust in ya. With it, you be able ta access my upper chamber and witness for yourself our secret weapons.", objectives = "Drakuru in Voltarus wants you to take the teleporter to his upper chamber.", progress = "Have ya gone ta witness my creations, <name>?", completion = "So, there ya have it, mon.\n\nWe be makin' da ultimate scourge army ta serve da Lich King. He gunna be most pleased!\n\nYou keep da scepter, <name>. You gunna be needin' it ta command my army in battle....\n\nSoon!" }
WordHunterWoW_QuestEN[12711] = { title = "Abandoned Mail", description = "", objectives = "Atop the mailbox are several illegible letters and scrolls. Useless...\n\nPerhaps you should check inside?" }
WordHunterWoW_QuestEN[12712] = { title = "The Key of Warlord Zol'Maz", description = "{name}, we need a key to unlock the chains of the rhino god, Akali. Even now he is being prepared for the slaughter.\n\nThe Drakkari warlord, Zol'Maz, carries the key. Hearing of your exploits, he has secluded himself and his family at their stronghold up the steps to the northeast.\n\nThe warlord is strong and you will need help. If you were to combine the tiki, sword and incantation of his family members, you would be able to summon such help as you challenge him before his home's gate.", objectives = "Har'koa at Zim'Torga has asked you to acquire the Key of Warlord Zol'Maz.", progress = "I cannot stress how important it is that you acquire the warlord's key no matter the cost.", completion = "It might have been better if I hadn't asked you to bring it back here instead of heading directly to Gundrak.\n\nHowever, I think that it's best that you hear what else I have to say first." }
WordHunterWoW_QuestEN[12713] = { title = "Betrayal", description = "The time has come to end this charade, {name}.\n\nAs valuable as your information has been, we must bring Drakuru down and bring his project to an end before his freaks are unleashed.\n\nWe've modified your scepter for the job. When the time is right, you will be able to use it on Drakuru's Blightbloods and turn them against him. It's your only hope of defeating him.\n\nFight well.", objectives = "Stefan in Ebon Watch wants you to defeat Drakuru.\n\nIf you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", progress = "Have you faced Drakuru in battle, <name>?", completion = "So, it is done.\n\nWe still have much to do, but our work here will be much more manageable thanks to your efforts.\n\nPlease accept this as a token of our gratitude." }
WordHunterWoW_QuestEN[12714] = { title = "The Will Of The Lich King", description = "It is the will of the Lich King that drives us onward, {name}. None are more aware of this than death knights. Our very existence is intrinsically tied to his consciousness. Surely you have heard him speak to you - invading your thoughts...\n\nCan you hear him now? Perhaps it is too early for you.\n\n<Mograine closes his eyes and nods to an unseen host.>\n\nYes, my lord. It will be done.\n\n{name}, you are to return to Death's Breach and report to Prince Valanar. The Lich King commands it!", objectives = "Return to Death's Breach and report to Prince Valanar.", completion = "Havenshire is ours! A thousand corpses litter the ground, patiently awaiting rebirth. We strike now at our enemy with the awakened strength of the Scourge!\n\nThe ghouls have already begun their assault upon New Avalon. Our forces have moved in behind them and taken the Crypt of Remembrance." }
WordHunterWoW_QuestEN[12715] = { title = "The Crypt of Remembrance", description = "The attacks upon the gates of the last Scarlet bastion have begun. Our ghouls are wearing the Crusade's front lines down while we labor to fortify our new forward base, the Crypt of Remembrance.\n\nVenture south to the crypt, which borders New Avalon, and report to my dear brother, Prince Keleseth.\n\nHe will be expecting you.\n\nPrepare yourself, {name}, for you are about to witness the next stage of Scourge warfare: DOMINATION!\n\nRide now, death knight!", objectives = "Report to Prince Keleseth at the Crypt of Remembrance.", completion = "Hail, <class>. I am the blood lord, Keleseth, ruler of the southeastern reaches of Northrend. The Lich King has sought to utilize my talents in ending this mortal affront to the Scourge. As with all things the Lich King asks of me, I am happy to oblige. Of course, a sea of endless souls to sate my thirst certainly sweetened the deal, don't you think?" }
WordHunterWoW_QuestEN[12716] = { title = "The Plaguebringer's Request", description = "Look at this pumpkin patch! Notice anything missing? Of course you don't, because you're a moron! Your brain was probably the first thing to die.\n\n<Noth sighs.>\n\nI have been commanded to put together a plague cauldron. You will help me.\n\nDirectly inside the gate of New Avalon is the inn. Enter the inn and steal an empty cauldron. Then go to the forge, also near the gate, and steal some iron chains. Bring those back to me along with 10 Crusader skulls. Do I need to tell you where to get those too?", objectives = "Noth the Plaguebringer has requested that you bring him 1 Empty Cauldron, 1 Iron Chain and 10 Crusader Skulls.", progress = "Have you gathered the materials I requested?", completion = "Perfect! Now give me a moment to get things set up." }
WordHunterWoW_QuestEN[12717] = { title = "Noth's Special Brew", description = "The cauldron is ready to begin spewing its foul corruption across the land!\n\nNow, death knight, a brief lesson in plague cauldrons. The gas that the cauldron emits is deadly to the living, but empowers Scourge. As with all Scourge creations, it feeds off of death and grows stronger the longer it feeds.\n\nTake these Crusader skulls and drop them in the cauldron. You will be quite happy with the results.", objectives = "Place the Pile of Crusader Skulls inside the Plague Cauldron.", progress = "The plague cauldron stands idle.", completion = "The plague cauldron jumps to life when the skulls are placed inside.\n\nAfter a few seconds some vials of dark liquid float to the top." }
WordHunterWoW_QuestEN[12718] = { title = "More Skulls For Brew", description = "", objectives = "The plague cauldron bubbles and churns its toxic brew, spewing a thick gas all around.\n\nDo you have more Crusader skulls to place inside?", progress = "The plague cauldron bubbles and churns its toxic brew, spewing a thick gas all around.\n\nDo you have more Crusader skulls to place inside?", completion = "The plague cauldron jumps to life when the skulls are placed inside.\n\nAfter a few seconds, the plague cauldron grants you the dark and frothy splendor of Noth's Special Brew." }
WordHunterWoW_QuestEN[12719] = { title = "Nowhere To Run And Nowhere To Hide", description = "Nothing less than total annihilation will suffice, {name}. To that end, a few hundred mindless ghouls assaulting the front gate of New Avalon will not do. We must infiltrate the inner sanctum and dispose of their officials. They must be shown that no one can escape the Scourge's grasp!\n\nMake your way to the New Avalon Town Hall, southwest of here, and assassinate the mayor. Search the building for the New Avalon registry and bring it to me.", objectives = "Prince Keleseth at the Crypt of Remembrance has ordered you to kill Mayor Quimby and recover the New Avalon Registry.", progress = "There is nowhere to run!", completion = "The registry will tell us many things about the Scarlet insects.\n\n<Keleseth flips through the pages of the registry.>\n\nDeath rates, births, but most importantly, movement.\n\nLook here, <name>, they have already sent three vessels abroad. Let me see here... Where are they headed?\n\n\n\nWHAT? This is impossible. They sail to Northrend!\n\nBeside the coordinates are the words: \"Crimson Dawn.\"" }
WordHunterWoW_QuestEN[12720] = { title = "How To Win Friends And Influence Enemies", description = "In my travels across this world I have made several interesting discoveries. For instance, did you know that with the proper amount of encouragement one can extract all the truths that a man dares hide? As luck would have it, I happen to have some encouragement on hand.\n\n<Keleseth pulls something out of an ornately jeweled box.>\n\nThese are my \"persuaders.\" Equip them and take to the field, death knight. Apply the pointy ends to the soldiers of New Avalon. Discover the truth about this \"Crimson Dawn.\"", objectives = "Prince Keleseth at the Crypt of Remembrance has ordered you to discover the truth about the \"Crimson Dawn.\"\n\nRemove Keleseth's Persuaders from the Ornately Jeweled Box and use them to \"persuade\" the Scarlet Crusade into talking.", progress = "Use the persuaders on Scarlet Crusaders. One of them will eventually... crack.", completion = "An awakening? What nonsense do you speak, boy! What kind of fool would deliver their people into the very heart of the frozen wastes? Perhaps, though, this courier holds the answer." }
WordHunterWoW_QuestEN[12721] = { title = "Rampage", description = "{name}, there is no time left. You must take the key and use it to unlock Akali.\n\nHe is being held in the courtyard in front of Gundrak, the capital of Zul'Drak. Akali's chains are secured by four anchor points. You must unlock each of them to set the rhino god free.\n\nGundrak is teeming with ice trolls. However, I believe that if you're careful, you should be able to slip in without too much danger.\n\nOnce you're done, please inform the witch doctor.", objectives = "Har'koa at Zim'Torga has asked you to free Akali and then to inform Witch Doctor Khufu at Zim'Torga.", completion = "No!\n\nAnother god destroyed, its power stolen. And now the prophet of Akali has threatened us directly.\n\nWhen he comes, he will come for Har'koa. We cannot allow him to take her power too.\n\nWe must consult the gods once more, <name>. They will tell us what must be done." }
WordHunterWoW_QuestEN[12722] = { title = "Lambs To The Slaughter", description = "Most humans would have fled the moment a Scourge necropolis took up residence in their air space. Not the Scarlet Crusade!\n\nI must confess - I rather enjoy our exchanges with the Crusade. Through the years, Scourge battles against them have resulted in several of the most tragic events in human history. Yet here we stand - AGAIN - locked in battle!\n\nWe shan't deny them the pleasures of eternal servitude to the Lich King! Enter New Avalon and fulfill their death wish. Leave no survivors.", objectives = "Baron Rivendare at the Crypt of Remembrance has commanded you to slay 10 Scarlet Crusade Soldiers and 15 Citizens of New Avalon.", completion = "You are quite effective with that blade, <name>. Perhaps, Lich King permitting, you would be interested in becoming one of my minions? Stratholme is looking for a new mayor." }
WordHunterWoW_QuestEN[12723] = { title = "Behind Scarlet Lines", description = "I have sent Orbaz, Thassarian and Koltira behind enemy lines to search for the courier. They have set up a base of operations at the Scarlet Tavern, located at the southern end of New Avalon. The tavern is tucked away behind the two orchards, adjacent to the Chapel of the Crimson Flame. You are to make your way to the tavern and report to Orbaz Bloodbane. He will update you on their situation.\n", objectives = "Report to Orbaz Bloodbane at the Scarlet Tavern in New Avalon.", completion = "Looks like we'll let anyone into the dark order these days. When I was given the gift, things were different. Much different!\n\nAs to this courier..." }
WordHunterWoW_QuestEN[12724] = { title = "The Path Of The Righteous Crusader", description = "We haven't got a damned clue about when or where this courier is supposed to show up. None of these humans had an answer either.\n\n<Orbaz points to the Scarlet corpses strewn across the floor.>\n\nI did manage to beat something useful out of the last one. Inside Scarlet Hold they keep a schedule of all patrol routes. I want you to break into the hold and steal the schedule.\n\nThe hold is the largest building in New Avalon - northeast of here. ", objectives = "Orbaz Bloodbane at the Scarlet Tavern in New Avalon has ordered you to steal the New Avalon Patrol Schedule from the Scarlet Hold.", progress = "Tear the hold apart! The schedule is there!", completion = "<Orbaz flips through the schedule.>\n\nThese worthless cretins have been busy! Northern patrol routes, southern patrol routes, western patrol routes, eastern patrol routes, but nothing about their couriers' routes. Wait a minute. What's this? It looks like a western patrol route, coming out of Western Plaguelands? This patrol will path through here today! I'm going to need time to plan." }
WordHunterWoW_QuestEN[12725] = { title = "Brothers In Death", description = "Breaking through the Scarlet lines was no easy task. We suffered many casualties during the assault and lost one of our best death knights, Koltira Deathweaver. I don't know whether he's dead or alive, but I'll be damned if we don't search for him.\n\nI last saw him being bound in irons and dragged away to the Scarlet Hold, northeast of here. Tear that keep asunder, death knight. Find Koltira!", objectives = "Search for Koltira Deathweaver in the Scarlet Hold.", completion = "You were foolish in coming after me. I failed. I should have been left for dead - now two of us might be killed.\n\n<Koltira shakes his head.>\n\nWe are death knights of the Scourge. This flies in the face of the dark brotherhood's covenants.\n\nThassarian, you blasted fool!" }
WordHunterWoW_QuestEN[12726] = { title = "Song of Wind and Water", description = "Listen to storm, yes?  The Stormwright's Shelf echoes with ancient song.... the Song of Wind and Water.\n\nThe great tempest devours the sons of typhoons and storms.  Take this drum and play his song... play Haiphoon's song.\n\nHelp him feed on wind and water so tempest can continue. ", objectives = "Soo-nee wants you to use the Tempest Drums at the Stormwright's Shelf and help Haiphoon devour 3 Storm Revenants and 3 Aqueous Spirits.", completion = "I thank you, <name>.  The great tempest will look upon us favorably thanks to you." }
WordHunterWoW_QuestEN[12727] = { title = "Bloody Breakout", description = "The alarms have been sounded. The High Inquisitor and his acolytes will be here soon. I'm too badly injured to be of much use, but I'll do what little I can to help.\n\nSlay the High Inquisitor and his cronies. Tear off his head and return with it to Thassarian. Vengeance will soothe his savage soul.\n\nOne more thing, {name}. If you do manage to survive and make it back to Thassarian, tell him that they're executing prisoners at the chapel. Perhaps he'll send you there to play the hero once more.", objectives = "Slay High Inquisitor Valroth and take Valroth's Head to Thassarian at the Scarlet Tavern in New Avalon.", progress = "What of Koltira?", completion = "I'll feed this monster's head to the ghouls!\n\n<Thassarian tosses the head into the back room.>\n\nDid Koltira make it out?\n\n<Thassarian pauses.>\n\nI'm certain he did. Those walls can't hold him.\n\nTime for some payback." }
WordHunterWoW_QuestEN[12728] = { title = "Monitoring the Rift: Winterfin Cavern", description = "I need to compile my notes and prepare a presentation for my colleagues in Dalaran.\n\nWhile I do, I must ask that you visit the Winterfin Cavern to the north. You must use the Arcanometer while standing in the mouth of the cavern.\n\nReturn to me at once when you have the data. My documentation will be incomplete without it.", objectives = "Librarian Garren at Amber Ledge wants you to use the Arcanometer at Winterfin Caverns.", progress = "Have you collected the data from Winterfin Caverns yet, <name>?", completion = "Excellent, this completes my report.\n\nI'll be sure to mention your kindness to the council, <name>." }
WordHunterWoW_QuestEN[12729] = { title = "The Gods Have Spoken", description = "The gods have spoken and we must heed their wisdom.\n\nTravel north to Zim'Rhuk to destroy guardians there until they yield the unblemished heart. Travel east to the Altar of Quetz'lun and disrupt the altar wardens until you recover their gusty essence.\n\nDeliver both to Har'koa and she will combine them into that which will compel late Akali's prophet to appear.", objectives = "Deliver the Unblemished Heart of the Guardian and the Gusty Essence of the Warden to Har'koa at Zim'Torga.", progress = "Do you have that which is required, <name>?", completion = "Your bravery seems boundless, <name>.\n\nPlease hand me the heart and the essence, and I will fashion them into that which will compel the prophet to appear before you." }
WordHunterWoW_QuestEN[12730] = { title = "Convocation at Zol'Heb", description = "You must take this instrument of convocation--of summoning--to Zol'Heb just south of Gundrak.\n\nTherein you will find a circle of power. Use the convocation to force the prophet of Akali to appear.\n\nMy heart goes out to you, {name}. We have been through much together, and you have done all that you can to not only save my life, but those of the other gods the Drakkari have destroyed.\n\nBut I fear this time we may not see each other again until the afterlife.", objectives = "Har'koa at Zim'Torga has asked you to slay the Prophet of Akali.", progress = "I can only offer you the warmth of my words and the encouragement that comes with them.\n\nTake what time you need to steel and prepare yourself, but I implore you not to take too long or the prophet will surely descend upon us.", completion = "You did it! <name>, you are the champion of Zul'Drak!\n\nWe will never be able to repay the debt that we owe to you, but the Zandalari have given into my trust a number of objects they believe you might have an interest in.\n\nPlease, I want you to have a token of our appreciation, but hurry. I sense another issue of urgency!" }
WordHunterWoW_QuestEN[12732] = { title = "The Heartblood's Strength", description = "One day, Rejek will be mighty warrior. Blood and skyfire will make Rejek strong. You see soon.\n\nRejek give you vial, you take to very top of Suntouched Pillar, far to west. Put waters there in vial.\n\nThen go to north edge of basin, to ledge north of Bonefields. You find and kill goretalon matriarch. Take heartblood.\n\nYou combine heartblood and water, bring to Rejek. Rejek drink, make strong.", objectives = "Bring a vial of Suntouched Heartblood to Rejek at Frenzyheart Hill.", progress = "Du bringst Rejek Geschenk?", completion = "Rejek dankt dir. Rejek trinkt, wird stark, nie vergisst mächtiges Geschenk von <name>." }
WordHunterWoW_QuestEN[12733] = { title = "Death's Challenge", description = "Born of the Lich King's victory over Illidan Stormrage in the heart of the frozen wastes, Death's Challenge is a rite of passage that all death knights must undergo.\n\nSeek out other death knights of Acherus and challenge them to a duel. They must accept and fight until a victor emerges!\n\nGo now, {name}! Victory for the Scourge! Glory to the Lich King!\n", objectives = "Olrun the Battlecaller has ordered you to win 5 duels against other death knights.\n\nYou may choose to battle death knight initiates or players.", progress = "Have you completed Death's Challenge?", completion = "To the victor goes the glory, <class>! Well done! The Lich King looks favorably upon you on this day." }
WordHunterWoW_QuestEN[12734] = { title = "Rejek: First Blood", description = "Rejek just became youngest warrior in all of Frenzyheart tribe. Father gave Rejek a mighty sword to defeat Frenzyheart enemies, but old tradition say sword need to be blooded first. Older warrior usually do that. You do this honor for Rejek?\n\nTake blade, put in corpses of all Frenzyheart foes: wasps and hardknuckles to southwest, and the big-tongues. Maybe blood blade on Mistwhispers, far to northwest near Bittertide Lake.", objectives = "Blood Rejek's Blade on the corpses of a Sapphire Hive Wasp, a Hardknuckle Charger, and 3 members of the Mistwhisper Tribe. You may blood the sword on either Mistwhisper Oracles or Mistwhisper Warriors. Return to Rejek at Frenzyheart Hill when your task is complete.", progress = "You blood Rejek's blade?", completion = "Rejek sees the stains of the blood of his enemies on the blade. Now Rejek has a mighty weapon for the mighty warrior he will be!" }
WordHunterWoW_QuestEN[12735] = { title = "A Cleansing Song", description = "Earth in Sholazar is pure.  The pillars have protected the land for centuries.\n\nWater, not as pure, it comes from outside Sholazar.... from oceans, from lakes, from rivers.  Water sometimes bring bad spirits - need to be cleansed.\n\nYou take this chime and play at Bittertide Lake, Wintergrasp River and River's Heart.  It make bad spirit angry... and then you must kill it.", objectives = "Soo-nee, at the Rainspeaker Canopy, wants you to play the Cleansing Chime at Bittertide Lake, Wintergrasp River and River's Heart and slay the evil spirits that plague the waters there.", completion = "Waters... cleansed.  Yes.  All is well.\n\nYou understand our way, <name>." }
WordHunterWoW_QuestEN[12736] = { title = "Song of Reflection", description = "Of course you not as smart as gorloc!  You just simple {race}.\n\nYou not without hope, though!  You show you can learn.  Maybe crystals make you smart like crystals make us smart!\n\nI teach you to play song to clear your mind.  You play song by crystals then crystals make your mind better... not as good as gorloc's but better than you have now.  Lifeblood Pillar is broken, but other pillars still good!", objectives = "Soo-nee at Rainspeaker Canopy wants you to use the Didgeridoo of Contemplation at the top of the Glimmering Pillar, the Suntouched Pillar, the Mosslight Pillar and the Skyreach Pillar.", completion = "You see?  I can tell you smarter already.  And if not smarter... then... happier!" }
WordHunterWoW_QuestEN[12737] = { title = "Song of Fecundity", description = "The storm is a destructive force.  Storm burns trees.  Storm floods houses.\n\nBut storm can also be life force if you know right song.  In Stormwright Shelf, above Maker's Perch, you can find small dirt mounds.  They very fertile -- they carry inside a strong seed.  All they wait for is the right song.\n\nYou take this horn and play song for them.", objectives = "Soo-nee at Rainspeaker Canopy wants you to go to the Stormwright's Shelf, northwest of the Maker's Perch, and play the Horn of Fecundity near 8 piles Soaked Fertile Dirt.", completion = "You learn fast, <name>.  You learn that song well.  Maybe next time I teach you different song." }
WordHunterWoW_QuestEN[12738] = { title = "A Cry For Vengeance!", description = "The cry for vengeance must be heard, {name}. Commander Plaguefist and a company of death knights are on their way to raze the Chapel of the Crimson Flame. If there are any death knights imprisoned at the chapel, Plaguefist will get them out.\n\nYou can still catch up to them if you hurry. The chapel is due west of here. ", objectives = "Report to Knight Commander Plaguefist at the Chapel of the Crimson Flame.", completion = "They're only flesh and bone - no match for the Scourge.\n\nWe didn't find any of our brothers, but we did stumble upon something special." }
WordHunterWoW_QuestEN[12739] = { title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty tauren in there that I think you'll take great pleasure in executing.", objectives = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Malar Bravehorn, an Argent Dawn prisoner inside the nearby prison house.", completion = "Felt good, didn't it? You're not one of them anymore, <name>. You're Scourge. You're one of us. Forever..." }
WordHunterWoW_QuestEN[12740] = { title = "Parachutes for the Argent Crusade", description = "Those sky terrors are destroying my men and women! Dying from falling is a horrible way to go.\n\n{class}, you have to get these parachutes out to them! At least then they'll have a fighting chance to survive.", objectives = "Commander Falstaav at The Argent Stand has asked you to equip 10 Argent Crusaders or Argent Shieldmen out in the courtyard with parachutes.", completion = "You're a good man, <name>. We're fortunate that you happened to stop by.\n\nStick around a while. I'm sure that we have much that a capable <class> such as yourself can do." }
WordHunterWoW_QuestEN[12741] = { title = "Strength of the Tempest", description = "Silly big-tongues think singing to the clouds give them power. Rejek show big-tongues how to get power by taking it!\n\nFar to northwest, there is large, flat area the big-tongues call 'Stormwright's Shelf.' Rejek is sure you can only get there by flying like bird.\n\nOn this shelf, Rejek has heard of mighty forces of wind and water. Kill them for their badness, then take it to the big-tongue 'Shrine of the Tempest' at shelf's western side. Rejek will await your return with ultimate power.", objectives = "Gather 3 Essences of the Monsoon and 3 Essences of the Storm and take them to the Shrine of the Tempest. Return to Rejek at Frenzyheart Hill with the True Power of the Tempest.", progress = "You bring Rejek true power of elements?", completion = "Now Rejek show cowardly big-tongues how to really use elements!" }
WordHunterWoW_QuestEN[12742] = { title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty human in there that I think you'll take great pleasure in executing.", objectives = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Ellen Stanbridge, an Argent Dawn prisoner inside the nearby prison house.", progress = "How does it feel?", completion = "Felt good, didn't it? You're not one of them anymore, <name>. You're Scourge. You're one of us. Forever..." }
WordHunterWoW_QuestEN[12743] = { title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty night elf in there that I think you'll take great pleasure in executing.", objectives = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Yazmina Oakenthorn, an Argent Dawn prisoner inside the nearby prison house.", completion = "Felt good, didn't it? You're not one of them anymore, <name>. You're Scourge. You're one of us. Forever..." }
WordHunterWoW_QuestEN[12744] = { title = "A Special Surprise", description = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, {name}. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing.\n\nI was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty dwarf in there that I think you'll take great pleasure in executing.", objectives = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Donovan Pulfrost, an Argent Dawn prisoner inside the nearby prison house.", completion = "Felt good, didn't it? You're not one of them anymore, <name>. You're Scourge. You're one of us. Forever..." }
